def _utc_now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def _sha256(path: Path) -> str:
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _read_json(path: Path) -> Any:
    return json.loads(Path(path).read_text(encoding="utf-8"))


def _read_jsonl(path: Path) -> list[dict[str, Any]]:
    return [
        json.loads(line)
        for line in Path(path).read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]


def _auc_in_gt_oos(in_scope: list[float], oos: list[float]) -> float | None:
    if not in_scope or not oos:
        return None
    greater = sum(1 for a in in_scope for b in oos if a > b)
    ties = sum(1 for a in in_scope for b in oos if a == b)
    return round((greater + 0.5 * ties) / (len(in_scope) * len(oos)), 6)


def _mean(values: list[float]) -> float | None:
    return round(sum(values) / len(values), 6) if values else None


def _pearson(a: list[float], b: list[float]) -> float | None:
    if len(a) != len(b) or len(a) < 2:
        return None
    ma = sum(a) / len(a)
    mb = sum(b) / len(b)
    da = [x - ma for x in a]
    db = [y - mb for y in b]
    denom = math.sqrt(sum(x * x for x in da) * sum(y * y for y in db))
    if not denom:
        return None
    return round(sum(x * y for x, y in zip(da, db)) / denom, 6)


def _best_threshold_at_retention(
    rows: list[dict[str, Any]],
    score_fn: Callable[[dict[str, Any]], float],
    *,
    min_retain: float,
) -> dict[str, Any] | None:
    inscope = [r for r in rows if r["is_inscope"]]
    oos = [r for r in rows if r["is_oos"]]
    conf = [r for r in rows if r["is_confounded_predicted_geometry_oos"]]
    if not inscope or not oos:
        return None
    candidates = sorted({round(score_fn(r), 6) for r in rows})
    best = None
    for threshold in candidates:
        retain = sum(1 for r in inscope if score_fn(r) >= threshold) / len(inscope)
        if retain < min_retain:
            continue
        oos_abst = sum(1 for r in oos if score_fn(r) < threshold) / len(oos)
        conf_abst = (
            sum(1 for r in conf if score_fn(r) < threshold) / len(conf)
            if conf else None
        )
        item = {
            "threshold": threshold,
            "inscope_retain_recall": round(retain, 4),
            "oos_abstain_recall": round(oos_abst, 4),
            "confounded_abstain_recall": round(conf_abst, 4) if conf_abst is not None else None,
        }
        key = (item["oos_abstain_recall"], item["confounded_abstain_recall"] or 0.0)
        if best is None or key > best[0]:
            best = (key, item)
    return best[1] if best else None


def _fold_scores(row: dict[str, Any]) -> dict[str, float]:
    top3 = row.get("top3_retained_train_neighbors") or []
    primary_top3 = [
        float(n.get("prob") or 0.0)
        for n in top3
        if n.get("fingerprint_id")
    ]
    nearest_primary_prob = (
        float(row.get("nearest_foldseek_prob") or 0.0)
        if row.get("nearest_train_fingerprint_id")
        else 0.0
    )
    high_conf_primary_count = int(row.get("retained_high_confidence_primary_fingerprint_hit_count") or 0)
    return {
        "nearest_primary_foldseek_prob": nearest_primary_prob,
        "top3_primary_foldseek_prob": max(primary_top3) if primary_top3 else 0.0,
        "nearest_primary_indicator": 1.0 if row.get("nearest_train_fingerprint_id") else 0.0,
        "high_conf_primary_hit_indicator": 1.0 if high_conf_primary_count > 0 else 0.0,
        "log1p_high_conf_primary_hit_count": round(math.log1p(high_conf_primary_count), 6),
    }


def build_fold_level_novelty_signal(
    *,
    foldseek_metadata_path: Path,
    esm2_150m_path: Path,
    cofactor_sidecar_path: Path,
    predicted_geometry_audit_path: Path,
    novelty_eval_path: Path,
) -> dict[str, Any]:
    plm = load_plm_rows(esm2_150m_path)
    cofactor = load_cofactor_scores(cofactor_sidecar_path)
    geometry = load_geometry_role_scores(predicted_geometry_audit_path)
    novelty = _read_json(novelty_eval_path)
    eight_confounded = set(
        novelty["cofactor_augmented_result"]["stratified_by_cofactor_signature"][
            "cofactor_confounded_oos_entry_ids"
        ]
    )
    predicted_confounded = {
        entry_id
        for entry_id, row in plm.items()
        if (
            row.get("split_assignment") == "heldout"
            and not row.get("true_fingerprint_id")
            and entry_id in cofactor
            and entry_id in geometry
            and max(cofactor[entry_id].get(c, 0.0) for c in COFACTOR_CLASSES)
            >= COFACTOR_SIGNATURE_THRESHOLD
        )
    }

    scored_rows: list[dict[str, Any]] = []
    for raw in _read_jsonl(foldseek_metadata_path):
        entry_id = raw.get("row_id") or raw.get("entry_id")
        if entry_id not in plm:
            continue
        plm_row = plm[entry_id]
        if plm_row.get("split_assignment") != "heldout":
            continue
        scores = _fold_scores(raw)
        scored_rows.append({
            "entry_id": entry_id,
            "split_assignment": plm_row.get("split_assignment"),
            "true_fingerprint_id": plm_row.get("true_fingerprint_id"),
            "is_inscope": bool(plm_row.get("true_fingerprint_id")),
            "is_oos": not bool(plm_row.get("true_fingerprint_id")),
            "is_cofactor_confounded_oos_any_geometry": entry_id in eight_confounded,
            "is_confounded_predicted_geometry_oos": entry_id in predicted_confounded,
            "nearest_train_entry_id": raw.get("nearest_train_entry_id"),
            "nearest_train_label_group": raw.get("nearest_train_label_group"),
            "nearest_train_fingerprint_id": raw.get("nearest_train_fingerprint_id"),
            "nearest_foldseek_prob": raw.get("nearest_foldseek_prob"),
            "nearest_foldseek_bits": raw.get("nearest_foldseek_bits"),
            "nearest_foldseek_lddt_tm_proxy": raw.get("nearest_foldseek_lddt_tm_proxy"),
            "retained_high_confidence_primary_fingerprint_hit_count": (
                raw.get("retained_high_confidence_primary_fingerprint_hit_count")
            ),
            "structural_neighborhood_bin": raw.get("structural_neighborhood_bin"),
            "fold_signals": scores,
            "top3_retained_train_neighbors": raw.get("top3_retained_train_neighbors") or [],
        })

    inscope = [r for r in scored_rows if r["is_inscope"]]
    oos = [r for r in scored_rows if r["is_oos"]]
    conf_pred = [r for r in scored_rows if r["is_confounded_predicted_geometry_oos"]]
    conf_any = [r for r in scored_rows if r["is_cofactor_confounded_oos_any_geometry"]]

    signal_names = list(scored_rows[0]["fold_signals"]) if scored_rows else []
    signals: dict[str, Any] = {}
    for name in signal_names:
        fn = lambda row, n=name: float(row["fold_signals"][n])
        signals[name] = {
            "auc_in_gt_oos": _auc_in_gt_oos([fn(r) for r in inscope], [fn(r) for r in oos]),
            "auc_in_gt_predicted_geometry_confounded_oos": _auc_in_gt_oos(
                [fn(r) for r in inscope], [fn(r) for r in conf_pred]
            ),
            "auc_in_gt_any_geometry_confounded_oos": _auc_in_gt_oos(
                [fn(r) for r in inscope], [fn(r) for r in conf_any]
            ),
            "in_scope_mean": _mean([fn(r) for r in inscope]),
            "oos_mean": _mean([fn(r) for r in oos]),
            "predicted_geometry_confounded_mean": _mean([fn(r) for r in conf_pred]),
            "best_at_90pct_inscope_retention": _best_threshold_at_retention(
                scored_rows, fn, min_retain=0.90
            ),
            "best_at_85pct_inscope_retention": _best_threshold_at_retention(
                scored_rows, fn, min_retain=0.85
            ),
        }

    primary_signal = "nearest_primary_foldseek_prob"
    overlap = [
        r for r in scored_rows
        if r["entry_id"] in geometry and r["entry_id"] in cofactor
    ]
    fold_values = [r["fold_signals"][primary_signal] for r in overlap]
    geom_values = [float(geometry[r["entry_id"]]["score"]) for r in overlap]
    cofactor_values = [
        max(cofactor[r["entry_id"]].get(c, 0.0) for c in COFACTOR_CLASSES)
        for r in overlap
    ]

    return {
        "artifact_id": "v3_fold_level_novelty_signal_current702_20260601",
        "schema_version": SCHEMA_VERSION,
        "created_utc": _utc_now_iso(),
        "status": "computed_from_existing_selected_pdb_foldseek_proxy",
        "scope": (
            "Fold-level novelty diagnostic against the current702 heldout rows, "
            "using the frozen selected-PDB Foldseek/fast-3Di structural-neighborhood "
            "metadata already in the repo. This is a bounded fold proxy, not a new "
            "predicted-geometry Foldseek run."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "heldout_threshold_tuning_for_deployment": False,
            "m_csa_eval_only": True,
        },
        "counts": {
            "heldout_fold_rows_scored": len(scored_rows),
            "inscope": len(inscope),
            "oos": len(oos),
            "cofactor_confounded_oos_any_geometry": len(conf_any),
            "cofactor_confounded_oos_predicted_geometry_overlap": len(conf_pred),
            "channel_overlap_rows_for_correlation": len(overlap),
        },
        "confounded_entry_ids": {
            "any_geometry_from_novelty_eval": sorted(eight_confounded),
            "predicted_geometry_overlap_current_gate": sorted(predicted_confounded),
        },
        "signals": signals,
        "orthogonality_to_current_channels": {
            "primary_fold_signal": primary_signal,
            "pearson_fold_vs_predicted_geometry_top1": _pearson(fold_values, geom_values),
            "pearson_fold_vs_cofactor_max": _pearson(fold_values, cofactor_values),
            "pearson_predicted_geometry_top1_vs_cofactor_max": _pearson(geom_values, cofactor_values),
            "interpretation": (
                "The selected-PDB fold proxy is only weakly correlated with both "
                "current deployment channels on overlapping heldout rows, so it is "
                "partly orthogonal. It catches the confounded rows by fold novelty, "
                "but its standalone high-retention operating point remains weak."
            ),
        },
        "confounded_row_details": [
            r for r in scored_rows
            if r["is_confounded_predicted_geometry_oos"] or r["is_cofactor_confounded_oos_any_geometry"]
        ],
        "interpretation": {
            "does_fold_signal_catch_confounded_rows": (
                "yes_as_a_rank_signal; all predicted-geometry confounded rows have "
                "near-zero nearest-primary Foldseek support in the existing selected-PDB proxy"
            ),
            "operating_point_status": (
                "not_deployable_standalone; at >=85% or >=90% in-scope retention the "
                "nearest-primary Foldseek proxy cannot abstain many OOS rows, because "
                "many in-scope rows also lack strong primary structural-neighbor support"
            ),
            "deployment_gap": (
                "A real deployment fold channel still needs predicted-structure "
                "Foldseek/TM scoring against the in-distribution atlas; this artifact "
                "uses selected-PDB structure metadata already frozen in repo."
            ),
        },
        "source_artifacts": {
            "foldseek_metadata": {
                "path": str(foldseek_metadata_path),
                "sha256": _sha256(foldseek_metadata_path),
            },
            "esm2_150m_embeddings": {
                "path": str(esm2_150m_path),
                "sha256": _sha256(esm2_150m_path),
            },
            "cofactor_sidecar": {
                "path": str(cofactor_sidecar_path),
                "sha256": _sha256(cofactor_sidecar_path),
            },
            "predicted_geometry_audit": {
                "path": str(predicted_geometry_audit_path),
                "sha256": _sha256(predicted_geometry_audit_path),
            },
            "novelty_eval": {
                "path": str(novelty_eval_path),
                "sha256": _sha256(novelty_eval_path),
            },
        },
    }


def _render_fold_report(audit: dict[str, Any]) -> str:
    counts = audit["counts"]
    sig = audit["signals"]["nearest_primary_foldseek_prob"]
    ortho = audit["orthogonality_to_current_channels"]
    lines = [
        "# Fold-Level Novelty Signal - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Counts",
        "",
        f"- Heldout fold rows scored: {counts['heldout_fold_rows_scored']}",
        f"- In-scope: {counts['inscope']}",
        f"- OOS: {counts['oos']}",
        f"- Cofactor-confounded OOS from novelty eval: {counts['cofactor_confounded_oos_any_geometry']}",
        f"- Cofactor-confounded OOS overlapping predicted-geometry gate: {counts['cofactor_confounded_oos_predicted_geometry_overlap']}",
        "",
        "## Primary Signal",
        "",
        "`nearest_primary_foldseek_prob` is the top Foldseek probability only when the nearest training neighbor carries a primary fingerprint; otherwise it is 0. Higher means the row sits near the occupied primary atlas.",
        "",
        f"- AUC in-scope > all OOS: {sig['auc_in_gt_oos']}",
        f"- AUC in-scope > predicted-geometry confounded OOS: {sig['auc_in_gt_predicted_geometry_confounded_oos']}",
        f"- Mean in-scope: {sig['in_scope_mean']}; mean OOS: {sig['oos_mean']}; mean confounded: {sig['predicted_geometry_confounded_mean']}",
        f"- Best >=90% retention point: {sig['best_at_90pct_inscope_retention']}",
        f"- Best >=85% retention point: {sig['best_at_85pct_inscope_retention']}",
        "",
        "## Orthogonality",
        "",
        f"- Pearson fold vs predicted-geometry top1: {ortho['pearson_fold_vs_predicted_geometry_top1']}",
        f"- Pearson fold vs cofactor max: {ortho['pearson_fold_vs_cofactor_max']}",
        f"- Pearson predicted-geometry top1 vs cofactor max: {ortho['pearson_predicted_geometry_top1_vs_cofactor_max']}",
        "",
        ortho["interpretation"],
        "",
        "## Confounded Rows",
        "",
        "| Row | nearest primary prob | top3 primary prob | high-conf primary hits | nearest train label |",
        "| --- | ---: | ---: | ---: | --- |",
    ]
    for row in audit["confounded_row_details"]:
        fs = row["fold_signals"]
        lines.append(
            f"| {row['entry_id']} | {fs['nearest_primary_foldseek_prob']} | "
            f"{fs['top3_primary_foldseek_prob']} | "
            f"{row['retained_high_confidence_primary_fingerprint_hit_count']} | "
            f"{row['nearest_train_label_group']} |"
        )
    lines += [
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['does_fold_signal_catch_confounded_rows']}",
        f"- {audit['interpretation']['operating_point_status']}",
        f"- {audit['interpretation']['deployment_gap']}",
    ]
    return "\n".join(lines) + "\n"


def write_fold_level_novelty_signal(
    *,
    foldseek_metadata_path: Path,
    esm2_150m_path: Path,
    cofactor_sidecar_path: Path,
    predicted_geometry_audit_path: Path,
    novelty_eval_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_fold_level_novelty_signal(
        foldseek_metadata_path=foldseek_metadata_path,
        esm2_150m_path=esm2_150m_path,
        cofactor_sidecar_path=cofactor_sidecar_path,
        predicted_geometry_audit_path=predicted_geometry_audit_path,
        novelty_eval_path=novelty_eval_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(_render_fold_report(audit), encoding="utf-8")
    return audit


def _entry_id_sort_key(entry_id: str) -> tuple[str, int, str]:
    match = re.match(r"^m_csa:(\d+)$", str(entry_id))
    if match:
        return ("m_csa", int(match.group(1)), str(entry_id))
    return (str(entry_id), -1, str(entry_id))


def _foldseek_binary_info(binary: str) -> dict[str, Any]:
    resolved = shutil.which(binary)
    if resolved is None:
        path = Path(binary)
        if path.exists():
            resolved = str(path.resolve())
    version = None
    version_command = None
    error = None
    if resolved:
        version_command = shlex.join([resolved, "version"])
        try:
            proc = subprocess.run(
                [resolved, "version"],
                check=True,
                capture_output=True,
                text=True,
                timeout=10,
            )
            version = (proc.stdout or proc.stderr).strip() or None
        except (OSError, subprocess.SubprocessError) as exc:
            error = f"{type(exc).__name__}: {exc}"
    return {
        "requested": binary,
        "resolved": resolved,
        "available": bool(resolved and version and not error),
        "version": version,
        "version_command": version_command,
        "error": error,
    }


def _predicted_row_status(row: dict[str, Any]) -> str:
    return str(row.get("predicted_geometry_status") or row.get("status") or "unknown")


def _predicted_row_ok(row: dict[str, Any]) -> bool:
    return _predicted_row_status(row) == "ok"


def _predicted_model_parts(row: dict[str, Any]) -> tuple[str | None, int | None, str | None]:
    pdb_id = str(row.get("predicted_pdb_id") or row.get("pdb_id") or "")
    match = re.match(r"^AF-(?P<accession>.+)-F1-model_v(?P<version>\d+)$", pdb_id)
    accession = str(row.get("accession") or row.get("sequence_id") or "").strip() or None
    version = None
    if match:
        accession = match.group("accession") or accession
        version = int(match.group("version"))
    return accession, version, pdb_id or None


def _afdb_cif_url(accession: str, version: int | None) -> str:
    model_version = int(version or 6)
    return f"https://alphafold.ebi.ac.uk/files/AF-{accession}-F1-model_v{model_version}.cif"


def _safe_path_token(value: str) -> str:
    return re.sub(r"[^A-Za-z0-9_.-]+", "_", value).strip("_") or "unknown"


def _coordinate_requests(
    rows: list[dict[str, Any]],
    *,
    coordinate_root: Path,
    role: str,
    subdir: str,
) -> list[dict[str, Any]]:
    by_path: dict[str, dict[str, Any]] = {}
    for row in sorted(rows, key=lambda item: _entry_id_sort_key(str(item.get("entry_id")))):
        accession, version, predicted_pdb_id = _predicted_model_parts(row)
        entry_id = str(row.get("entry_id") or "")
        if not accession:
            key = f"missing_accession::{entry_id}"
            by_path[key] = {
                "role": role,
                "status": "missing_accession",
                "accession": None,
                "alphafold_version": version,
                "predicted_pdb_id": predicted_pdb_id,
                "url": None,
                "expected_local_path": None,
                "local_file_exists": False,
                "entry_ids": [entry_id],
                "rows": [
                    {
                        "entry_id": entry_id,
                        "split_assignment": row.get("split_assignment"),
                        "true_fingerprint_id": row.get("true_fingerprint_id"),
                        "benchmark_role": row.get("benchmark_role"),
                    }
                ],
            }
            continue
        token = _safe_path_token(f"{accession}_v{version or 6}")
        local_path = coordinate_root / subdir / f"afdb_{token}.cif"
        key = str(local_path)
        if key not in by_path:
            url = _afdb_cif_url(accession, version)
            by_path[key] = {
                "role": role,
                "status": "ready_to_materialize",
                "accession": accession,
                "alphafold_version": version or 6,
                "predicted_pdb_id": predicted_pdb_id,
                "url": url,
                "expected_local_path": str(local_path),
                "local_file_exists": local_path.exists(),
                "download_command": shlex.join(
                    ["curl", "-fL", "--retry", "3", url, "-o", str(local_path)]
                ),
                "entry_ids": [],
                "rows": [],
            }
        by_path[key]["entry_ids"].append(entry_id)
        by_path[key]["rows"].append(
            {
                "entry_id": entry_id,
                "split_assignment": row.get("split_assignment"),
                "true_fingerprint_id": row.get("true_fingerprint_id"),
                "benchmark_role": row.get("benchmark_role"),
                "top1_fingerprint_id": row.get("top1_fingerprint_id"),
            }
        )
    return sorted(
        by_path.values(),
        key=lambda item: (
            str(item.get("accession") or ""),
            _entry_id_sort_key(str((item.get("entry_ids") or [""])[0])),
        ),
    )


def _missing_coordinate_count(requests: list[dict[str, Any]]) -> int:
    return sum(1 for item in requests if not item.get("local_file_exists"))


def _foldseek_easy_search_command(
    *,
    binary: str,
    query_dir: Path,
    target_dir: Path,
    result_tsv: Path,
    tmp_dir: Path,
    threads: int,
) -> str:
    return shlex.join(
        [
            binary,
            "easy-search",
            str(query_dir),
            str(target_dir),
            str(result_tsv),
            str(tmp_dir),
            "--format-output",
            "query,target,qtmscore,ttmscore,alntmscore,prob,bits",
            "--exhaustive-search",
            "1",
            "--alignment-type",
            "1",
            "--tmalign-fast",
            "0",
            "--exact-tmscore",
            "1",
            "--threads",
            str(max(1, int(threads))),
            "-v",
            "1",
        ]
    )


def _request_aliases(request: dict[str, Any]) -> set[str]:
    path_value = request.get("expected_local_path")
    aliases = set()
    if path_value:
        path = Path(str(path_value))
        aliases.update({str(path), path.name, path.stem})
    accession = request.get("accession")
    version = request.get("alphafold_version")
    if accession:
        aliases.add(f"afdb_{_safe_path_token(f'{accession}_v{version or 6}')}")
        aliases.add(f"afdb_{_safe_path_token(f'{accession}_v{version or 6}')}.cif")
    predicted_pdb_id = request.get("predicted_pdb_id")
    if predicted_pdb_id:
        aliases.add(str(predicted_pdb_id))
    return aliases


def _alias_map(requests: list[dict[str, Any]]) -> tuple[dict[str, dict[str, Any]], list[str]]:
    alias_to_request: dict[str, dict[str, Any]] = {}
    collisions: set[str] = set()
    for request in requests:
        for alias in _request_aliases(request):
            if alias in alias_to_request and alias_to_request[alias] is not request:
                collisions.add(alias)
                continue
            alias_to_request[alias] = request
    for alias in collisions:
        alias_to_request.pop(alias, None)
    return alias_to_request, sorted(collisions)


def _parse_optional_float(value: str | None) -> float | None:
    if value in (None, ""):
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _parse_foldseek_tsv_hits(
    *,
    result_tsv: Path,
    query_requests: list[dict[str, Any]],
    target_requests: list[dict[str, Any]],
) -> dict[str, Any]:
    if not result_tsv.exists():
        return {
            "status": "result_tsv_missing",
            "path": str(result_tsv),
            "nearest_atlas_hits": [],
            "summary": {
                "mapped_pair_count": 0,
                "unmapped_pair_count": 0,
                "query_entry_count_with_hits": 0,
            },
        }
    query_aliases, query_collisions = _alias_map(query_requests)
    target_aliases, target_collisions = _alias_map(target_requests)
    nearest: dict[str, dict[str, Any]] = {}
    mapped_pair_count = 0
    unmapped_pair_count = 0
    unmapped_names: set[str] = set()
    for line in result_tsv.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line:
            continue
        parts = line.split("\t")
        if parts[0] == "query":
            continue
        if len(parts) < 5:
            unmapped_pair_count += 1
            continue
        raw_query, raw_target = parts[0], parts[1]
        query_request = query_aliases.get(raw_query)
        target_request = target_aliases.get(raw_target)
        if query_request is None or target_request is None:
            unmapped_pair_count += 1
            if query_request is None:
                unmapped_names.add(raw_query)
            if target_request is None:
                unmapped_names.add(raw_target)
            continue
        qtmscore = _parse_optional_float(parts[2])
        ttmscore = _parse_optional_float(parts[3])
        alntmscore = _parse_optional_float(parts[4])
        scores = [s for s in (qtmscore, ttmscore, alntmscore) if s is not None]
        if not scores:
            unmapped_pair_count += 1
            continue
        mapped_pair_count += 1
        tm_score = max(scores)
        prob = _parse_optional_float(parts[5]) if len(parts) > 5 else None
        bits = _parse_optional_float(parts[6]) if len(parts) > 6 else None
        target_row = (target_request.get("rows") or [{}])[0]
        for query_row in query_request.get("rows") or []:
            entry_id = str(query_row.get("entry_id"))
            candidate = {
                "query_entry_id": entry_id,
                "query_accession": query_request.get("accession"),
                "raw_query_name": raw_query,
                "nearest_atlas_entry_id": target_row.get("entry_id"),
                "nearest_atlas_accession": target_request.get("accession"),
                "nearest_atlas_true_fingerprint_id": target_row.get("true_fingerprint_id"),
                "raw_target_name": raw_target,
                "tm_score": round(tm_score, 6),
                "qtmscore": qtmscore,
                "ttmscore": ttmscore,
                "alntmscore": alntmscore,
                "prob": prob,
                "bits": bits,
            }
            previous = nearest.get(entry_id)
            if previous is None or candidate["tm_score"] > previous["tm_score"]:
                nearest[entry_id] = candidate
    hits = sorted(nearest.values(), key=lambda row: _entry_id_sort_key(row["query_entry_id"]))
    return {
        "status": "parsed" if hits else "parsed_no_mapped_hits",
        "path": str(result_tsv),
        "nearest_atlas_hits": hits,
        "summary": {
            "mapped_pair_count": mapped_pair_count,
            "unmapped_pair_count": unmapped_pair_count,
            "query_entry_count_with_hits": len(hits),
            "max_nearest_atlas_tm_score": (
                round(max(row["tm_score"] for row in hits), 6) if hits else None
            ),
            "min_nearest_atlas_tm_score": (
                round(min(row["tm_score"] for row in hits), 6) if hits else None
            ),
            "alias_collision_count": len(query_collisions) + len(target_collisions),
            "alias_collisions": query_collisions + target_collisions,
            "unmapped_names": sorted(unmapped_names),
        },
    }


def _fold_channel_signal_from_hits(
    *,
    hits: list[dict[str, Any]],
    query_requests: list[dict[str, Any]],
    confounded_ids: set[str],
) -> dict[str, Any] | None:
    row_context = {
        str(row.get("entry_id")): row
        for request in query_requests
        for row in request.get("rows") or []
        if row.get("entry_id")
    }
    scored_rows = []
    for hit in hits:
        entry_id = str(hit.get("query_entry_id"))
        context = row_context.get(entry_id, {})
        if not context:
            continue
        scored_rows.append(
            {
                "entry_id": entry_id,
                "true_fingerprint_id": context.get("true_fingerprint_id"),
                "is_inscope": bool(context.get("true_fingerprint_id")),
                "is_oos": not bool(context.get("true_fingerprint_id")),
                "is_confounded_predicted_geometry_oos": entry_id in confounded_ids,
                "fold_signals": {"nearest_atlas_tm_score": float(hit["tm_score"])},
                "nearest_atlas_entry_id": hit.get("nearest_atlas_entry_id"),
                "nearest_atlas_true_fingerprint_id": hit.get(
                    "nearest_atlas_true_fingerprint_id"
                ),
            }
        )
    if not scored_rows:
        return None
    inscope = [row for row in scored_rows if row["is_inscope"]]
    oos = [row for row in scored_rows if row["is_oos"]]
    conf = [row for row in oos if row["is_confounded_predicted_geometry_oos"]]
    agn = [row for row in oos if not row["is_confounded_predicted_geometry_oos"]]
    fn = lambda row: float(row["fold_signals"]["nearest_atlas_tm_score"])
    return {
        "signal_name": "nearest_atlas_tm_score",
        "direction": "higher_means_nearer_to_in_distribution_predicted_atlas",
        "counts": {
            "heldout_rows_scored": len(scored_rows),
            "inscope": len(inscope),
            "oos": len(oos),
            "confounded_oos": len(conf),
            "agnostic_oos": len(agn),
        },
        "auc_in_gt_oos_all": _auc_in_gt_oos([fn(row) for row in inscope], [fn(row) for row in oos]),
        "auc_in_gt_confounded_oos": _auc_in_gt_oos(
            [fn(row) for row in inscope], [fn(row) for row in conf]
        ),
        "auc_in_gt_agnostic_oos": _auc_in_gt_oos(
            [fn(row) for row in inscope], [fn(row) for row in agn]
        ),
        "in_scope_mean": _mean([fn(row) for row in inscope]),
        "oos_mean": _mean([fn(row) for row in oos]),
        "confounded_mean": _mean([fn(row) for row in conf]),
        "best_at_90pct_inscope_retention": _best_threshold_at_retention(
            scored_rows, fn, min_retain=0.90
        ),
        "best_at_85pct_inscope_retention": _best_threshold_at_retention(
            scored_rows, fn, min_retain=0.85
        ),
        "row_scores": scored_rows,
    }


def build_predicted_structure_fold_channel(
    *,
    predicted_geometry_atlas_path: Path,
    fold_level_signal_path: Path,
    coordinate_root: Path,
    foldseek_binary: str = DEFAULT_FOLDSEEK_BINARY,
    threads: int = 4,
    priority_result_tsv: Path | None = None,
    heldout_result_tsv: Path | None = None,
) -> dict[str, Any]:
    predicted_atlas = _read_json(predicted_geometry_atlas_path)
    fold_signal = _read_json(fold_level_signal_path)
    rows = [
        row
        for row in predicted_atlas.get("results", [])
        if isinstance(row, dict)
    ]
    atlas_rows = [
        row
        for row in rows
        if row.get("split_assignment") == "in_distribution" and _predicted_row_ok(row)
    ]
    heldout_ok_rows = [
        row
        for row in rows
        if row.get("split_assignment") == "heldout" and _predicted_row_ok(row)
    ]
    confounded_ids = set(
        fold_signal.get("confounded_entry_ids", {}).get(
            "predicted_geometry_overlap_current_gate", []
        )
    )
    priority_rows = [
        row for row in heldout_ok_rows if str(row.get("entry_id")) in confounded_ids
    ]
    missing_priority_ids = sorted(
        confounded_ids - {str(row.get("entry_id")) for row in priority_rows},
        key=_entry_id_sort_key,
    )

    coordinate_root = Path(coordinate_root)
    atlas_dir = coordinate_root / "atlas_in_distribution"
    priority_query_dir = coordinate_root / "queries_cofactor_confounded_oos"
    heldout_query_dir = coordinate_root / "queries_all_heldout"
    result_root = coordinate_root.parent / f"{coordinate_root.name}_foldseek_results"

    atlas_requests = _coordinate_requests(
        atlas_rows,
        coordinate_root=coordinate_root,
        role="atlas_in_distribution_target",
        subdir="atlas_in_distribution",
    )
    priority_requests = _coordinate_requests(
        priority_rows,
        coordinate_root=coordinate_root,
        role="priority_query_cofactor_confounded_oos",
        subdir="queries_cofactor_confounded_oos",
    )
    heldout_requests = _coordinate_requests(
        heldout_ok_rows,
        coordinate_root=coordinate_root,
        role="all_heldout_query_when_cheap",
        subdir="queries_all_heldout",
    )
    foldseek = _foldseek_binary_info(foldseek_binary)
    resolved_binary = str(foldseek.get("resolved") or foldseek_binary)

    priority_command = _foldseek_easy_search_command(
        binary=resolved_binary,
        query_dir=priority_query_dir,
        target_dir=atlas_dir,
        result_tsv=priority_result_tsv
        or result_root / "cofactor_confounded_oos_vs_atlas.tsv",
        tmp_dir=result_root / "tmp_confounded",
        threads=threads,
    )
    heldout_command = _foldseek_easy_search_command(
        binary=resolved_binary,
        query_dir=heldout_query_dir,
        target_dir=atlas_dir,
        result_tsv=heldout_result_tsv or result_root / "all_heldout_vs_atlas.tsv",
        tmp_dir=result_root / "tmp_all_heldout",
        threads=threads,
    )
    materialization_command = (
        "python - <<'PY'\n"
        "import json\n"
        "import urllib.request\n"
        "from pathlib import Path\n"
        f"artifact = json.loads(Path('artifacts/{PREDICTED_STRUCTURE_FOLD_CHANNEL_ID}.json').read_text())\n"
        "groups = artifact['foldseek_input_manifest']['coordinate_request_groups']\n"
        "for group in groups.values():\n"
        "    for item in group:\n"
        "        path = item.get('expected_local_path')\n"
        "        url = item.get('url')\n"
        "        if not path or not url:\n"
        "            continue\n"
        "        target = Path(path)\n"
        "        target.parent.mkdir(parents=True, exist_ok=True)\n"
        "        if target.exists():\n"
        "            continue\n"
        "        urllib.request.urlretrieve(url, target)\n"
        "PY"
    )

    priority_missing = _missing_coordinate_count(atlas_requests) + _missing_coordinate_count(
        priority_requests
    )
    heldout_missing = _missing_coordinate_count(atlas_requests) + _missing_coordinate_count(
        heldout_requests
    )
    blockers: list[str] = []
    if not foldseek["available"]:
        blockers.append("foldseek_runtime_unavailable")
    if priority_missing:
        blockers.append("predicted_coordinate_files_missing_for_priority_scope")
    if heldout_missing:
        blockers.append("predicted_coordinate_files_missing_for_all_heldout_scope")
    priority_result = _parse_foldseek_tsv_hits(
        result_tsv=priority_result_tsv
        or result_root / "cofactor_confounded_oos_vs_atlas.tsv",
        query_requests=priority_requests,
        target_requests=atlas_requests,
    )
    heldout_result = _parse_foldseek_tsv_hits(
        result_tsv=heldout_result_tsv or result_root / "all_heldout_vs_atlas.tsv",
        query_requests=heldout_requests,
        target_requests=atlas_requests,
    )
    if priority_result["status"] != "parsed":
        blockers.append("priority_foldseek_results_not_computed_or_parsed")
    if heldout_result["status"] != "parsed":
        blockers.append("all_heldout_foldseek_results_not_computed_or_parsed")
    all_heldout_signal = _fold_channel_signal_from_hits(
        hits=heldout_result.get("nearest_atlas_hits", []),
        query_requests=heldout_requests,
        confounded_ids=confounded_ids,
    )
    status = (
        "computed_all_heldout_foldseek_scores"
        if heldout_result["status"] == "parsed"
        else "computed_priority_foldseek_scores"
        if priority_result["status"] == "parsed"
        else (
            "ready_to_run_foldseek_priority_scope"
            if foldseek["available"] and priority_missing == 0
            else "manifest_staged_missing_predicted_coordinate_bundle"
        )
    )
    if heldout_result["status"] == "parsed":
        current_result = (
            "All-heldout Foldseek/TM scores were parsed from the configured result TSV; "
            "the fold channel now has a real nearest-atlas TM signal for every ok "
            "predicted-geometry heldout row."
        )
        next_action = (
            "Use the all-heldout fold-channel signal in the next abstention combiner "
            "diagnostic, or decide whether persistent predicted-CIF coordinate "
            "provenance should be committed."
        )
    elif priority_result["status"] == "parsed":
        current_result = (
            "Priority Foldseek/TM scores for the cofactor-confounded OOS rows were "
            "parsed from the configured result TSV; the full all-heldout sweep remains "
            "uncomputed."
        )
        next_action = (
            "Run the all-heldout Foldseek/TM sweep when cheap, or commit a dedicated "
            "predicted CIF bundle if persistent coordinate provenance is required."
        )
    else:
        current_result = (
            "No Foldseek/TM scores are claimed here because the current repo does not "
            "contain a dedicated predicted AlphaFold CIF bundle for these current702 "
            "atlas/query rows."
        )
        next_action = (
            "Materialize the exact AFDB v6 coordinate requests, run the priority "
            "Foldseek command, then rerun the parser to emit nearest-atlas TM scores "
            "for the six confounded rows before the all-heldout sweep."
        )

    return {
        "artifact_id": PREDICTED_STRUCTURE_FOLD_CHANNEL_ID,
        "schema_version": SCHEMA_VERSION,
        "created_utc": _utc_now_iso(),
        "status": status,
        "scope": (
            "Bounded manifest for a deployment-regime predicted-structure "
            "Foldseek/TM channel: AlphaFoldDB-predicted heldout rows scored "
            "against the current702 in-distribution predicted-structure atlas."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "heldout_threshold_tuning_for_deployment": False,
            "large_model_downloads_performed": False,
            "frozen_current702_inputs_only": True,
            "score_fabrication": False,
        },
        "counts": {
            "combined_predicted_retrieval_rows": len(rows),
            "atlas_in_distribution_rows_ok": len(atlas_rows),
            "heldout_rows_ok": len(heldout_ok_rows),
            "priority_cofactor_confounded_oos_rows": len(priority_rows),
            "priority_cofactor_confounded_oos_missing_ids": len(missing_priority_ids),
            "atlas_coordinate_requests": len(atlas_requests),
            "priority_query_coordinate_requests": len(priority_requests),
            "all_heldout_query_coordinate_requests": len(heldout_requests),
            "priority_scope_missing_coordinate_files": priority_missing,
            "all_heldout_scope_missing_coordinate_files": heldout_missing,
        },
        "target_rows": {
            "priority_cofactor_confounded_oos_entry_ids": [
                str(row.get("entry_id"))
                for row in sorted(priority_rows, key=lambda item: _entry_id_sort_key(str(item.get("entry_id"))))
            ],
            "priority_cofactor_confounded_oos_missing_ids": missing_priority_ids,
            "all_heldout_when_cheap_entry_count": len(heldout_ok_rows),
        },
        "runtime": {
            "foldseek": foldseek,
            "threads": max(1, int(threads)),
        },
        "blockers": blockers,
        "parsed_foldseek_results": {
            "priority_cofactor_confounded_oos_vs_atlas": priority_result,
            "all_heldout_vs_atlas": heldout_result,
        },
        "fold_channel_signal": {
            "nearest_atlas_tm_score": all_heldout_signal,
        },
        "foldseek_input_manifest": {
            "coordinate_root": str(coordinate_root),
            "atlas_database_dir": str(atlas_dir),
            "priority_query_dir": str(priority_query_dir),
            "all_heldout_query_dir": str(heldout_query_dir),
            "result_root": str(result_root),
            "coordinate_request_groups": {
                "atlas_in_distribution": atlas_requests,
                "priority_cofactor_confounded_oos_queries": priority_requests,
                "all_heldout_queries_when_cheap": heldout_requests,
            },
        },
        "commands": {
            "materialize_coordinate_bundle": materialization_command,
            "run_priority_cofactor_confounded_oos_vs_atlas": priority_command,
            "run_all_heldout_vs_atlas_when_cheap": heldout_command,
            "expected_foldseek_tsv_columns": [
                "query",
                "target",
                "qtmscore",
                "ttmscore",
                "alntmscore",
                "prob",
                "bits",
            ],
            "scoring_contract": (
                "Per query, score the nearest in-distribution atlas hit by "
                "max(qtmscore, ttmscore, alntmscore); lower nearest-atlas TM "
                "support is the fold-novelty direction."
            ),
        },
        "source_artifacts": {
            "predicted_geometry_atlas": {
                "path": str(predicted_geometry_atlas_path),
                "sha256": _sha256(predicted_geometry_atlas_path),
            },
            "fold_level_signal": {
                "path": str(fold_level_signal_path),
                "sha256": _sha256(fold_level_signal_path),
            },
        },
        "interpretation": {
            "current_result": current_result,
            "next_action": next_action,
        },
    }


def _render_predicted_structure_fold_channel_report(audit: dict[str, Any]) -> str:
    counts = audit["counts"]
    parsed = audit.get("parsed_foldseek_results", {})
    priority_parsed = parsed.get("priority_cofactor_confounded_oos_vs_atlas", {})
    heldout_parsed = parsed.get("all_heldout_vs_atlas", {})
    lines = [
        "# Predicted-Structure Fold Channel - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Foldseek available: {audit['runtime']['foldseek']['available']}",
        f"- Priority scope missing coordinate files: {counts['priority_scope_missing_coordinate_files']}",
        f"- All-heldout scope missing coordinate files: {counts['all_heldout_scope_missing_coordinate_files']}",
        f"- Priority Foldseek TSV parse status: {priority_parsed.get('status')}",
        f"- All-heldout Foldseek TSV parse status: {heldout_parsed.get('status')}",
        "",
        "## Scope Counts",
        "",
        f"- Atlas in-distribution rows with ok predicted geometry: {counts['atlas_in_distribution_rows_ok']}",
        f"- Heldout rows with ok predicted geometry: {counts['heldout_rows_ok']}",
        f"- Priority cofactor-confounded OOS rows: {counts['priority_cofactor_confounded_oos_rows']}",
        "",
        "## Priority Rows",
        "",
    ]
    for entry_id in audit["target_rows"]["priority_cofactor_confounded_oos_entry_ids"]:
        lines.append(f"- {entry_id}")
    lines += [
        "",
        "## Blockers",
        "",
    ]
    if audit["status"].startswith("computed_") and audit["blockers"]:
        lines += [
            "- The scored Foldseek TSVs below were parsed successfully; these blockers track "
            "missing persistent coordinate-file provenance for reproduction.",
        ]
    for blocker in audit["blockers"]:
        lines.append(f"- {blocker}")
    lines += [
        "",
        "## All-Heldout Fold Signal",
        "",
    ]
    fold_signal = (audit.get("fold_channel_signal") or {}).get("nearest_atlas_tm_score")
    if fold_signal:
        lines += [
            f"- AUC in-scope > all OOS: {fold_signal['auc_in_gt_oos_all']}",
            f"- AUC in-scope > confounded OOS: {fold_signal['auc_in_gt_confounded_oos']}",
            f"- Mean in-scope: {fold_signal['in_scope_mean']}; mean OOS: {fold_signal['oos_mean']}; mean confounded: {fold_signal['confounded_mean']}",
            f"- Best >=90% retention diagnostic: {fold_signal['best_at_90pct_inscope_retention']}",
            f"- Best >=85% retention diagnostic: {fold_signal['best_at_85pct_inscope_retention']}",
        ]
    else:
        lines.append("- All-heldout Foldseek/TM scores have not been parsed yet.")
    lines += [
        "",
        "## Priority Parsed Hits",
        "",
    ]
    priority_hits = priority_parsed.get("nearest_atlas_hits", [])
    if priority_hits:
        lines += [
            "| Query | nearest atlas | atlas fingerprint | TM score |",
            "| --- | --- | --- | ---: |",
        ]
        for hit in priority_hits:
            lines.append(
                f"| {hit['query_entry_id']} | {hit['nearest_atlas_entry_id']} | "
                f"{hit['nearest_atlas_true_fingerprint_id']} | {hit['tm_score']} |"
            )
    else:
        lines.append("- No priority Foldseek hits parsed yet.")
    lines += [
        "",
        "## Commands",
        "",
        "Materialize the exact predicted CIF bundle:",
        "",
        "```bash",
        audit["commands"]["materialize_coordinate_bundle"],
        "```",
        "",
        "Run the six-row priority Foldseek/TM pass:",
        "",
        "```bash",
        audit["commands"]["run_priority_cofactor_confounded_oos_vs_atlas"],
        "```",
        "",
        "Run all heldout rows when cheap:",
        "",
        "```bash",
        audit["commands"]["run_all_heldout_vs_atlas_when_cheap"],
        "```",
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['current_result']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_predicted_structure_fold_channel(
    *,
    predicted_geometry_atlas_path: Path,
    fold_level_signal_path: Path,
    coordinate_root: Path,
    out_path: Path,
    report_path: Path | None = None,
    foldseek_binary: str = DEFAULT_FOLDSEEK_BINARY,
    threads: int = 4,
    priority_result_tsv: Path | None = None,
    heldout_result_tsv: Path | None = None,
) -> dict[str, Any]:
    audit = build_predicted_structure_fold_channel(
        predicted_geometry_atlas_path=predicted_geometry_atlas_path,
        fold_level_signal_path=fold_level_signal_path,
        coordinate_root=coordinate_root,
        foldseek_binary=foldseek_binary,
        threads=threads,
        priority_result_tsv=priority_result_tsv,
        heldout_result_tsv=heldout_result_tsv,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_predicted_structure_fold_channel_report(audit),
            encoding="utf-8",
        )
    return audit


def _summarize_foldseek_result_path(parsed_result: dict[str, Any]) -> dict[str, Any]:
    path_value = parsed_result.get("path")
    path = Path(str(path_value)) if path_value else None
    exists = bool(path and path.is_file())
    line_count = None
    if exists:
        line_count = sum(
            1 for line in path.read_text(encoding="utf-8").splitlines() if line.strip()
        )
    return {
        "path": str(path) if path else None,
        "exists": exists,
        "sha256": _sha256(path) if exists else None,
        "nonempty_line_count": line_count,
        "parsed_status": parsed_result.get("status"),
        "mapped_pair_count": (
            (parsed_result.get("summary") or {}).get("mapped_pair_count")
        ),
        "query_entry_count_with_hits": (
            (parsed_result.get("summary") or {}).get("query_entry_count_with_hits")
        ),
    }


def _record_count_mismatch(
    mismatches: list[dict[str, Any]],
    *,
    key: str,
    expected: Any,
    actual: Any,
) -> None:
    if expected != actual:
        mismatches.append({"key": key, "expected": expected, "actual": actual})


def build_predicted_structure_fold_channel_contract_audit(
    *,
    predicted_structure_fold_channel_path: Path,
    predicted_geometry_atlas_path: Path,
    fold_level_signal_path: Path,
) -> dict[str, Any]:
    fold_channel = _read_json(predicted_structure_fold_channel_path)
    predicted_atlas = _read_json(predicted_geometry_atlas_path)
    fold_signal = _read_json(fold_level_signal_path)
    rows = [
        row
        for row in predicted_atlas.get("results", [])
        if isinstance(row, dict)
    ]
    atlas_rows = [
        row
        for row in rows
        if row.get("split_assignment") == "in_distribution" and _predicted_row_ok(row)
    ]
    heldout_rows = [
        row
        for row in rows
        if row.get("split_assignment") == "heldout" and _predicted_row_ok(row)
    ]
    heldout_ids = {
        str(row.get("entry_id"))
        for row in heldout_rows
        if row.get("entry_id")
    }
    confounded_ids = set(
        fold_signal.get("confounded_entry_ids", {}).get(
            "predicted_geometry_overlap_current_gate", []
        )
    )
    priority_ids = heldout_ids & confounded_ids
    priority_missing_ids = sorted(confounded_ids - heldout_ids, key=_entry_id_sort_key)

    parsed = fold_channel.get("parsed_foldseek_results") or {}
    all_parsed = parsed.get("all_heldout_vs_atlas") or {}
    priority_parsed = parsed.get("priority_cofactor_confounded_oos_vs_atlas") or {}
    all_hits = [
        hit for hit in all_parsed.get("nearest_atlas_hits", []) if isinstance(hit, dict)
    ]
    priority_hits = [
        hit
        for hit in priority_parsed.get("nearest_atlas_hits", [])
        if isinstance(hit, dict)
    ]
    all_hit_ids = [str(hit.get("query_entry_id")) for hit in all_hits]
    priority_hit_ids = [str(hit.get("query_entry_id")) for hit in priority_hits]
    all_hit_id_set = set(all_hit_ids)
    priority_hit_id_set = set(priority_hit_ids)
    row_scores = (
        (
            (fold_channel.get("fold_channel_signal") or {})
            .get("nearest_atlas_tm_score")
            or {}
        )
        .get("row_scores")
        or []
    )
    row_score_ids = [
        str(row.get("entry_id")) for row in row_scores if isinstance(row, dict)
    ]
    row_score_id_set = set(row_score_ids)

    count_mismatches: list[dict[str, Any]] = []
    counts = fold_channel.get("counts") or {}
    _record_count_mismatch(
        count_mismatches,
        key="combined_predicted_retrieval_rows",
        expected=len(rows),
        actual=counts.get("combined_predicted_retrieval_rows"),
    )
    _record_count_mismatch(
        count_mismatches,
        key="atlas_in_distribution_rows_ok",
        expected=len(atlas_rows),
        actual=counts.get("atlas_in_distribution_rows_ok"),
    )
    _record_count_mismatch(
        count_mismatches,
        key="heldout_rows_ok",
        expected=len(heldout_rows),
        actual=counts.get("heldout_rows_ok"),
    )
    _record_count_mismatch(
        count_mismatches,
        key="priority_cofactor_confounded_oos_rows",
        expected=len(priority_ids),
        actual=counts.get("priority_cofactor_confounded_oos_rows"),
    )
    _record_count_mismatch(
        count_mismatches,
        key="priority_cofactor_confounded_oos_missing_ids",
        expected=len(priority_missing_ids),
        actual=counts.get("priority_cofactor_confounded_oos_missing_ids"),
    )
    _record_count_mismatch(
        count_mismatches,
        key="all_heldout_nearest_hit_rows",
        expected=len(heldout_ids),
        actual=len(all_hit_id_set),
    )
    _record_count_mismatch(
        count_mismatches,
        key="priority_nearest_hit_rows",
        expected=len(priority_ids),
        actual=len(priority_hit_id_set),
    )
    _record_count_mismatch(
        count_mismatches,
        key="fold_signal_row_scores",
        expected=len(heldout_ids),
        actual=len(row_score_id_set),
    )

    duplicate_hit_ids = sorted(
        {
            entry_id
            for entry_id, count in Counter(all_hit_ids).items()
            if entry_id and count > 1
        },
        key=_entry_id_sort_key,
    )
    duplicate_priority_hit_ids = sorted(
        {
            entry_id
            for entry_id, count in Counter(priority_hit_ids).items()
            if entry_id and count > 1
        },
        key=_entry_id_sort_key,
    )
    missing_all_hit_ids = sorted(heldout_ids - all_hit_id_set, key=_entry_id_sort_key)
    extra_all_hit_ids = sorted(all_hit_id_set - heldout_ids, key=_entry_id_sort_key)
    missing_priority_hit_ids = sorted(
        priority_ids - priority_hit_id_set,
        key=_entry_id_sort_key,
    )
    extra_priority_hit_ids = sorted(
        priority_hit_id_set - priority_ids,
        key=_entry_id_sort_key,
    )
    missing_row_score_ids = sorted(heldout_ids - row_score_id_set, key=_entry_id_sort_key)
    extra_row_score_ids = sorted(row_score_id_set - heldout_ids, key=_entry_id_sort_key)

    score_range_violations = []
    for row in row_scores:
        if not isinstance(row, dict):
            continue
        score = ((row.get("fold_signals") or {}).get("nearest_atlas_tm_score"))
        if not isinstance(score, (int, float)) or not 0.0 <= float(score) <= 1.0:
            score_range_violations.append(
                {"entry_id": row.get("entry_id"), "nearest_atlas_tm_score": score}
            )

    source_mismatches = []
    expected_sources = {
        "predicted_geometry_atlas": predicted_geometry_atlas_path,
        "fold_level_signal": fold_level_signal_path,
    }
    for key, path in expected_sources.items():
        record = (fold_channel.get("source_artifacts") or {}).get(key) or {}
        if record.get("path") != str(path):
            source_mismatches.append(
                {
                    "source": key,
                    "field": "path",
                    "expected": str(path),
                    "actual": record.get("path"),
                }
            )
        if not path.exists():
            source_mismatches.append(
                {
                    "source": key,
                    "field": "exists",
                    "expected": True,
                    "actual": False,
                }
            )
        elif record.get("sha256") != _sha256(path):
            source_mismatches.append(
                {
                    "source": key,
                    "field": "sha256",
                    "expected": _sha256(path),
                    "actual": record.get("sha256"),
                }
            )

    required_guardrails = {
        "labels_registries_ontologies_changed": False,
        "imports_or_promotions_performed": False,
        "production_thresholds_changed": False,
        "heldout_threshold_tuning_for_deployment": False,
        "large_model_downloads_performed": False,
        "frozen_current702_inputs_only": True,
        "score_fabrication": False,
    }
    guardrails = fold_channel.get("guardrails") or {}
    guardrail_mismatches = [
        {"key": key, "expected": expected, "actual": guardrails.get(key)}
        for key, expected in required_guardrails.items()
        if guardrails.get(key) != expected
    ]

    expected_status = "computed_all_heldout_foldseek_scores"
    status_violations = []
    if fold_channel.get("artifact_id") != PREDICTED_STRUCTURE_FOLD_CHANNEL_ID:
        status_violations.append(
            {
                "field": "artifact_id",
                "expected": PREDICTED_STRUCTURE_FOLD_CHANNEL_ID,
                "actual": fold_channel.get("artifact_id"),
            }
        )
    if fold_channel.get("status") != expected_status:
        status_violations.append(
            {
                "field": "status",
                "expected": expected_status,
                "actual": fold_channel.get("status"),
            }
        )
    for name, parsed_result in (
        ("all_heldout_vs_atlas", all_parsed),
        ("priority_cofactor_confounded_oos_vs_atlas", priority_parsed),
    ):
        if parsed_result.get("status") != "parsed":
            status_violations.append(
                {
                    "field": f"{name}.status",
                    "expected": "parsed",
                    "actual": parsed_result.get("status"),
                }
            )

    allowed_computed_blockers = {
        "predicted_coordinate_files_missing_for_priority_scope",
        "predicted_coordinate_files_missing_for_all_heldout_scope",
    }
    blockers = set(fold_channel.get("blockers") or [])
    blocker_violations = sorted(blockers - allowed_computed_blockers)

    command_violations = []
    commands = fold_channel.get("commands") or {}
    for key in (
        "run_priority_cofactor_confounded_oos_vs_atlas",
        "run_all_heldout_vs_atlas_when_cheap",
    ):
        command = str(commands.get(key) or "")
        for token in (
            "--exact-tmscore",
            "--exhaustive-search 1",
            "query,target,qtmscore,ttmscore,alntmscore,prob,bits",
        ):
            if token not in command:
                command_violations.append(
                    {"command": key, "missing_token": token}
                )

    foldseek_result_files = {
        "all_heldout_vs_atlas": _summarize_foldseek_result_path(all_parsed),
        "priority_cofactor_confounded_oos_vs_atlas": _summarize_foldseek_result_path(
            priority_parsed
        ),
    }
    missing_result_files = [
        {"name": name, "path": summary["path"]}
        for name, summary in foldseek_result_files.items()
        if not summary["exists"]
    ]

    critical_counts = {
        "status_violations": len(status_violations),
        "count_mismatches": len(count_mismatches),
        "duplicate_all_heldout_hit_ids": len(duplicate_hit_ids),
        "duplicate_priority_hit_ids": len(duplicate_priority_hit_ids),
        "missing_all_heldout_hit_ids": len(missing_all_hit_ids),
        "extra_all_heldout_hit_ids": len(extra_all_hit_ids),
        "missing_priority_hit_ids": len(missing_priority_hit_ids),
        "extra_priority_hit_ids": len(extra_priority_hit_ids),
        "missing_fold_signal_row_score_ids": len(missing_row_score_ids),
        "extra_fold_signal_row_score_ids": len(extra_row_score_ids),
        "score_range_violations": len(score_range_violations),
        "source_mismatches": len(source_mismatches),
        "guardrail_mismatches": len(guardrail_mismatches),
        "unexpected_blockers": len(blocker_violations),
        "command_violations": len(command_violations),
        "missing_result_files": len(missing_result_files),
    }
    passed = all(count == 0 for count in critical_counts.values())
    blocker_clause = (
        "with no computed blockers remaining."
        if not blockers
        else "with only allowed coordinate-file provenance blockers present."
    )
    contract_next_action = (
        "Use this as the validation layer for downstream fold-augmented "
        "gate work; the scored channel and coordinate bundle are now "
        "byte-reproducible under the companion provenance audit."
        if not blockers
        else (
            "Use this as the validation layer for downstream fold-augmented "
            "gate work; persistent CIF provenance remains optional research "
            "infrastructure, not a scoring blocker."
        )
    )
    return {
        "artifact_id": PREDICTED_STRUCTURE_FOLD_CHANNEL_CONTRACT_AUDIT_ID,
        "schema_version": SCHEMA_VERSION,
        "created_utc": _utc_now_iso(),
        "status": (
            "fold_channel_contract_passed_current702"
            if passed
            else "fold_channel_contract_failed_current702"
        ),
        "scope": (
            "Strict contract audit for the existing AlphaFoldDB-predicted "
            "Foldseek/TM channel: verify that the scored all-heldout and "
            "priority cofactor-confounded rows match frozen current702 inputs."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "heldout_threshold_tuning_for_deployment": False,
            "scored_fold_channel_mutated": False,
            "validation_only": True,
        },
        "contract": {
            "expected_fold_channel_status": expected_status,
            "allowed_computed_blockers": sorted(allowed_computed_blockers),
            "required_guardrails": required_guardrails,
            "required_foldseek_command_tokens": [
                "--exact-tmscore",
                "--exhaustive-search 1",
                "query,target,qtmscore,ttmscore,alntmscore,prob,bits",
            ],
        },
        "counts": {
            "predicted_atlas_rows": len(rows),
            "atlas_in_distribution_rows_ok": len(atlas_rows),
            "heldout_rows_ok": len(heldout_rows),
            "priority_cofactor_confounded_oos_rows": len(priority_ids),
            "priority_cofactor_confounded_oos_missing_ids": len(priority_missing_ids),
            "all_heldout_nearest_hits": len(all_hits),
            "priority_nearest_hits": len(priority_hits),
            "fold_signal_row_scores": len(row_scores),
            "critical_counts": critical_counts,
        },
        "foldseek_result_files": foldseek_result_files,
        "violations": {
            "status_violations": status_violations,
            "count_mismatches": count_mismatches,
            "duplicate_all_heldout_hit_ids": duplicate_hit_ids[:50],
            "duplicate_priority_hit_ids": duplicate_priority_hit_ids[:50],
            "missing_all_heldout_hit_ids": missing_all_hit_ids[:50],
            "extra_all_heldout_hit_ids": extra_all_hit_ids[:50],
            "missing_priority_hit_ids": missing_priority_hit_ids[:50],
            "extra_priority_hit_ids": extra_priority_hit_ids[:50],
            "missing_fold_signal_row_score_ids": missing_row_score_ids[:50],
            "extra_fold_signal_row_score_ids": extra_row_score_ids[:50],
            "score_range_violations": score_range_violations[:50],
            "source_mismatches": source_mismatches[:50],
            "guardrail_mismatches": guardrail_mismatches[:50],
            "unexpected_blockers": blocker_violations[:50],
            "command_violations": command_violations[:50],
            "missing_result_files": missing_result_files[:50],
        },
        "interpretation": {
            "result": (
                "The real predicted-structure fold channel satisfies the strict "
                "current702 scoring contract: all ok heldout rows and all six "
                "priority cofactor-confounded OOS rows have parsed nearest-atlas "
                f"Foldseek/TM hits, {blocker_clause}"
                if passed
                else "The fold channel contract has critical mismatches; treat the scored channel as blocked until repaired."
            ),
            "next_action": (
                contract_next_action
                if passed
                else "Repair the listed violations, rerun the fold-channel builder, then rerun this audit."
            ),
        },
        "source_artifacts": {
            "predicted_structure_fold_channel": {
                "path": str(predicted_structure_fold_channel_path),
                "sha256": _sha256(predicted_structure_fold_channel_path),
            },
            "predicted_geometry_atlas": {
                "path": str(predicted_geometry_atlas_path),
                "sha256": _sha256(predicted_geometry_atlas_path),
            },
            "fold_level_signal": {
                "path": str(fold_level_signal_path),
                "sha256": _sha256(fold_level_signal_path),
            },
        },
    }


def _render_predicted_structure_fold_channel_contract_audit_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    lines = [
        "# Predicted-Structure Fold Channel Contract Audit - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Heldout ok rows: {counts['heldout_rows_ok']}",
        f"- All-heldout nearest hits: {counts['all_heldout_nearest_hits']}",
        f"- Priority confounded rows: {counts['priority_cofactor_confounded_oos_rows']}",
        f"- Priority nearest hits: {counts['priority_nearest_hits']}",
        f"- Critical violation counts: {counts['critical_counts']}",
        "",
        "## Foldseek Result Files",
        "",
    ]
    for name, summary in audit["foldseek_result_files"].items():
        lines.append(
            f"- {name}: exists={summary['exists']}, "
            f"lines={summary['nonempty_line_count']}, "
            f"hits={summary['query_entry_count_with_hits']}"
        )
    lines += [
        "",
        "## Contract",
        "",
        f"- Expected fold-channel status: {audit['contract']['expected_fold_channel_status']}",
        f"- Allowed computed blockers: {', '.join(audit['contract']['allowed_computed_blockers'])}",
        "- This audit validates the scored artifact without changing labels, registries, thresholds, or imports.",
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['result']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_predicted_structure_fold_channel_contract_audit(
    *,
    predicted_structure_fold_channel_path: Path,
    predicted_geometry_atlas_path: Path,
    fold_level_signal_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_predicted_structure_fold_channel_contract_audit(
        predicted_structure_fold_channel_path=predicted_structure_fold_channel_path,
        predicted_geometry_atlas_path=predicted_geometry_atlas_path,
        fold_level_signal_path=fold_level_signal_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_predicted_structure_fold_channel_contract_audit_report(audit),
            encoding="utf-8",
        )
    return audit


def _nested_key_paths_with_tokens(
    value: Any,
    *,
    tokens: tuple[str, ...],
    prefix: str = "",
) -> list[str]:
    paths: list[str] = []
    if isinstance(value, dict):
        for key, nested in value.items():
            key_text = str(key)
            path = f"{prefix}.{key_text}" if prefix else key_text
            lowered = key_text.lower()
            if any(token in lowered for token in tokens):
                paths.append(path)
            paths.extend(
                _nested_key_paths_with_tokens(nested, tokens=tokens, prefix=path)
            )
    elif isinstance(value, list):
        for index, nested in enumerate(value):
            path = f"{prefix}[{index}]" if prefix else f"[{index}]"
            paths.extend(
                _nested_key_paths_with_tokens(nested, tokens=tokens, prefix=path)
            )
    return paths


def build_predicted_structure_fold_channel_deployment_input_audit(
    *,
    predicted_structure_fold_channel_path: Path,
) -> dict[str, Any]:
    fold_channel = _read_json(predicted_structure_fold_channel_path)
    coordinate_groups = (
        (fold_channel.get("foldseek_input_manifest") or {}).get(
            "coordinate_request_groups"
        )
        or {}
    )
    coordinate_requests: list[dict[str, Any]] = []
    for group_name, group_rows in coordinate_groups.items():
        if not isinstance(group_rows, list):
            continue
        for row in group_rows:
            if not isinstance(row, dict):
                continue
            record = dict(row)
            record["coordinate_group"] = str(group_name)
            coordinate_requests.append(record)

    coordinate_violations = []
    afdb_url_requests = 0
    afdb_local_path_requests = 0
    forbidden_coordinate_key_paths = []
    for index, request in enumerate(coordinate_requests):
        url = str(request.get("url") or "")
        local_path = str(request.get("expected_local_path") or "")
        if url.startswith("https://alphafold.ebi.ac.uk/files/AF-") and url.endswith(
            "-F1-model_v6.cif"
        ):
            afdb_url_requests += 1
        else:
            coordinate_violations.append(
                {
                    "index": index,
                    "entry_id": request.get("entry_id"),
                    "violation": "coordinate_request_url_not_afdb_v6_cif",
                    "url": url,
                }
            )
        if "/afdb_" in local_path and local_path.endswith("_v6.cif"):
            afdb_local_path_requests += 1
        else:
            coordinate_violations.append(
                {
                    "index": index,
                    "entry_id": request.get("entry_id"),
                    "violation": "coordinate_request_local_path_not_afdb_v6_cif",
                    "expected_local_path": local_path,
                }
            )
        forbidden_coordinate_key_paths.extend(
            [
                f"coordinate_requests[{index}].{path}"
                for path in _nested_key_paths_with_tokens(
                    request,
                    tokens=("selected_pdb", "experimental_pdb"),
                )
            ]
        )

    row_scores = (
        (
            (fold_channel.get("fold_channel_signal") or {})
            .get("nearest_atlas_tm_score")
            or {}
        )
        .get("row_scores")
        or []
    )
    row_score_records = [row for row in row_scores if isinstance(row, dict)]
    row_score_forbidden_paths = []
    row_scores_with_fold_signal = 0
    unexpected_fold_signal_keys = []
    evaluation_label_rows = 0
    for index, row in enumerate(row_score_records):
        row_score_forbidden_paths.extend(
            [
                f"row_scores[{index}].{path}"
                for path in _nested_key_paths_with_tokens(
                    row,
                    tokens=("selected_pdb", "experimental_pdb"),
                )
            ]
        )
        fold_signals = row.get("fold_signals") or {}
        if fold_signals.get("nearest_atlas_tm_score") is not None:
            row_scores_with_fold_signal += 1
        extra_signal_keys = sorted(set(fold_signals) - {"nearest_atlas_tm_score"})
        for key in extra_signal_keys:
            unexpected_fold_signal_keys.append(
                {"entry_id": row.get("entry_id"), "fold_signal_key": key}
            )
        if (
            row.get("true_fingerprint_id") is not None
            or row.get("nearest_atlas_true_fingerprint_id") is not None
        ):
            evaluation_label_rows += 1

    critical_counts = {
        "coordinate_request_url_not_afdb_v6_cif": len(
            [
                row
                for row in coordinate_violations
                if row["violation"] == "coordinate_request_url_not_afdb_v6_cif"
            ]
        ),
        "coordinate_request_local_path_not_afdb_v6_cif": len(
            [
                row
                for row in coordinate_violations
                if row["violation"]
                == "coordinate_request_local_path_not_afdb_v6_cif"
            ]
        ),
        "coordinate_requests_with_experimental_pdb_metadata_keys": len(
            forbidden_coordinate_key_paths
        ),
        "row_scores_with_experimental_pdb_metadata_keys": len(
            row_score_forbidden_paths
        ),
        "unexpected_fold_signal_keys": len(unexpected_fold_signal_keys),
    }
    critical_violation_total = sum(critical_counts.values())
    return {
        "artifact_id": PREDICTED_STRUCTURE_FOLD_CHANNEL_DEPLOYMENT_INPUT_AUDIT_ID,
        "schema_version": (
            f"{SCHEMA_VERSION}.predicted_structure_fold_channel_deployment_input_audit"
        ),
        "created_utc": _utc_now_iso(),
        "status": (
            "predicted_structure_fold_channel_deployment_inputs_predicted_only"
            if critical_violation_total == 0
            else "predicted_structure_fold_channel_deployment_inputs_blocked"
        ),
        "scope": (
            "Validation-only audit that the current fold channel is a "
            "predicted-structure-vs-atlas signal. It checks coordinate request "
            "provenance and scored row payload fields without rerunning "
            "Foldseek/TM, changing thresholds, or editing labels."
        ),
        "deployment_validity": {
            "predicted_structure_vs_atlas_only": critical_violation_total == 0,
            "coordinate_source": "AlphaFoldDB v6 CIF requests",
            "fold_signal_fields": ["nearest_atlas_tm_score"],
            "evaluation_label_fields_present_but_not_fold_signals": (
                evaluation_label_rows
            ),
        },
        "counts": {
            "coordinate_request_rows": len(coordinate_requests),
            "coordinate_request_groups": len(coordinate_groups),
            "afdb_url_requests": afdb_url_requests,
            "afdb_local_path_requests": afdb_local_path_requests,
            "row_score_rows": len(row_score_records),
            "row_scores_with_nearest_atlas_tm_score": row_scores_with_fold_signal,
            "evaluation_label_rows": evaluation_label_rows,
            "critical_counts": critical_counts,
            "critical_violation_total": critical_violation_total,
        },
        "violations": {
            "coordinate_violations": coordinate_violations,
            "coordinate_forbidden_metadata_key_paths": sorted(
                forbidden_coordinate_key_paths
            ),
            "row_score_forbidden_metadata_key_paths": sorted(
                row_score_forbidden_paths
            ),
            "unexpected_fold_signal_keys": unexpected_fold_signal_keys,
        },
        "guardrails": {
            "validation_only": True,
            "foldseek_or_tm_rerun_performed": False,
            "experimental_pdb_metadata_used_as_channel_input": False,
            "heldout_rows_used_for_training_or_threshold_tuning": False,
            "threshold_selected_or_tuned": False,
            "production_thresholds_changed": False,
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
        },
        "decision": {
            "deployment_input_contract_passed": critical_violation_total == 0,
            "apply_or_change_threshold_now": False,
            "next_gate": (
                "Use this audit with the confounded readiness artifact: the "
                "fold channel input surface is predicted-only, while deployment "
                "closure still depends on the composed production-blocker and "
                "coordinate-provenance gates."
            ),
        },
        "source_artifacts": {
            "predicted_structure_fold_channel": _source_path_record(
                predicted_structure_fold_channel_path
            )
        },
        "interpretation": {
            "result": (
                "The current fold channel coordinate requests and scored row "
                "signals are predicted-structure-vs-atlas inputs; experimental "
                "PDB metadata does not appear in the checked channel fields."
                if critical_violation_total == 0
                else "The current fold channel has deployment-input provenance violations."
            ),
            "next_action": (
                "Keep using the fixed operating point; clear production "
                "blockers and verify the composed coordinate-provenance gate "
                "before deployment-closed claims."
            ),
        },
    }


def _render_predicted_structure_fold_channel_deployment_input_audit_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    critical = counts["critical_counts"]
    lines = [
        "# Predicted-Structure Fold Channel Deployment Input Audit - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Coordinate request rows: {counts['coordinate_request_rows']}",
        f"- AFDB URL requests: {counts['afdb_url_requests']}",
        f"- AFDB local path requests: {counts['afdb_local_path_requests']}",
        f"- Row-score rows: {counts['row_score_rows']}",
        "- Row scores with nearest-atlas TM score: "
        f"{counts['row_scores_with_nearest_atlas_tm_score']}",
        f"- Critical violations: {counts['critical_violation_total']}",
        "",
        "## Critical Counts",
        "",
    ]
    for key, value in sorted(critical.items()):
        lines.append(f"- {key}: {value}")
    lines += [
        "",
        "## Decision",
        "",
        "- Deployment input contract passed: "
        f"{audit['decision']['deployment_input_contract_passed']}",
        f"- Next gate: {audit['decision']['next_gate']}",
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['result']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_predicted_structure_fold_channel_deployment_input_audit(
    *,
    predicted_structure_fold_channel_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_predicted_structure_fold_channel_deployment_input_audit(
        predicted_structure_fold_channel_path=predicted_structure_fold_channel_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(
        json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_predicted_structure_fold_channel_deployment_input_audit_report(
                audit
            ),
            encoding="utf-8",
        )
    return audit


def _coordinate_request_record(item: dict[str, Any]) -> dict[str, Any]:
    expected_path_value = str(item.get("expected_local_path") or "")
    expected_path = Path(expected_path_value) if expected_path_value else None
    exists = bool(expected_path is not None and expected_path.is_file())
    return {
        "accession": item.get("accession"),
        "predicted_pdb_id": item.get("predicted_pdb_id"),
        "entry_ids": list(item.get("entry_ids") or []),
        "role": item.get("role"),
        "expected_local_path": str(expected_path) if expected_path is not None else None,
        "url": item.get("url"),
        "download_command": item.get("download_command"),
        "local_file_exists_reported": item.get("local_file_exists"),
        "local_file_exists_observed": exists,
        "sha256": _sha256(expected_path) if expected_path is not None and exists else None,
    }


def build_predicted_structure_fold_channel_coordinate_provenance_audit(
    *,
    predicted_structure_fold_channel_path: Path,
    contract_audit_path: Path | None = None,
) -> dict[str, Any]:
    fold_channel = _read_json(predicted_structure_fold_channel_path)
    request_groups = (
        (fold_channel.get("foldseek_input_manifest") or {}).get(
            "coordinate_request_groups"
        )
        or {}
    )

    group_summaries: dict[str, dict[str, Any]] = {}
    missing_coordinate_requests: dict[str, list[dict[str, Any]]] = {}
    observed_coordinate_requests: dict[str, list[dict[str, Any]]] = {}
    path_to_records: dict[str, list[dict[str, Any]]] = defaultdict(list)
    reported_observed_mismatches: list[dict[str, Any]] = []
    malformed_requests: list[dict[str, Any]] = []
    accession_to_records: dict[str, list[dict[str, Any]]] = defaultdict(list)

    for group_name, raw_items in sorted(request_groups.items()):
        records = []
        if not isinstance(raw_items, list):
            malformed_requests.append(
                {"group": group_name, "reason": "coordinate_group_not_list"}
            )
            raw_items = []
        for raw_item in raw_items:
            if not isinstance(raw_item, dict):
                malformed_requests.append(
                    {"group": group_name, "reason": "coordinate_request_not_object"}
                )
                continue
            record = _coordinate_request_record(raw_item)
            records.append(record)
            expected_path = record["expected_local_path"]
            if expected_path:
                path_to_records[expected_path].append(
                    {
                        "group": group_name,
                        "accession": record["accession"],
                        "entry_ids": record["entry_ids"],
                        "url": record["url"],
                        "local_file_exists_observed": record[
                            "local_file_exists_observed"
                        ],
                    }
                )
            if record["accession"]:
                accession_to_records[str(record["accession"])].append(
                    {
                        "group": group_name,
                        "expected_local_path": expected_path,
                        "entry_ids": record["entry_ids"],
                        "url": record["url"],
                        "local_file_exists_observed": record[
                            "local_file_exists_observed"
                        ],
                    }
                )
            if record["local_file_exists_reported"] != record[
                "local_file_exists_observed"
            ]:
                reported_observed_mismatches.append(
                    {
                        "group": group_name,
                        "expected_local_path": expected_path,
                        "reported": record["local_file_exists_reported"],
                        "observed": record["local_file_exists_observed"],
                    }
                )
        missing = [
            record
            for record in records
            if not record["local_file_exists_observed"]
        ]
        observed = [
            record
            for record in records
            if record["local_file_exists_observed"]
        ]
        missing_coordinate_requests[group_name] = missing
        observed_coordinate_requests[group_name] = observed
        group_summaries[group_name] = {
            "request_count": len(records),
            "observed_file_count": len(observed),
            "missing_file_count": len(missing),
            "unique_expected_path_count": len(
                {
                    record["expected_local_path"]
                    for record in records
                    if record["expected_local_path"]
                }
            ),
            "unique_accession_count": len(
                {
                    record["accession"]
                    for record in records
                    if record["accession"]
                }
            ),
        }

    unique_coordinate_records = []
    duplicate_coordinate_requests = []
    for path, records in sorted(path_to_records.items()):
        exists = Path(path).is_file()
        accessions = sorted(
            {str(record["accession"]) for record in records if record["accession"]}
        )
        entry_ids = sorted(
            {
                str(entry_id)
                for record in records
                for entry_id in record.get("entry_ids", [])
            },
            key=_entry_id_sort_key,
        )
        groups = sorted({str(record["group"]) for record in records})
        unique_record = {
            "expected_local_path": path,
            "accessions": accessions,
            "entry_ids": entry_ids,
            "groups": groups,
            "url": next((record["url"] for record in records if record["url"]), None),
            "local_file_exists_observed": exists,
            "sha256": _sha256(Path(path)) if exists else None,
        }
        unique_coordinate_records.append(unique_record)
        if len(groups) > 1:
            duplicate_coordinate_requests.append(unique_record)

    unique_accession_records = []
    duplicate_accession_requests = []
    for accession, records in sorted(accession_to_records.items()):
        expected_paths = sorted(
            {
                str(record["expected_local_path"])
                for record in records
                if record["expected_local_path"]
            }
        )
        entry_ids = sorted(
            {
                str(entry_id)
                for record in records
                for entry_id in record.get("entry_ids", [])
            },
            key=_entry_id_sort_key,
        )
        groups = sorted({str(record["group"]) for record in records})
        accession_record = {
            "accession": accession,
            "expected_local_paths": expected_paths,
            "entry_ids": entry_ids,
            "groups": groups,
            "urls": sorted(
                {str(record["url"]) for record in records if record["url"]}
            ),
            "any_local_file_exists_observed": any(
                record["local_file_exists_observed"] for record in records
            ),
            "all_local_files_exist_observed": all(
                record["local_file_exists_observed"] for record in records
            ),
        }
        unique_accession_records.append(accession_record)
        if len(expected_paths) > 1 or len(groups) > 1:
            duplicate_accession_requests.append(accession_record)

    result_files = {
        name: _summarize_foldseek_result_path(parsed_result)
        for name, parsed_result in (
            (fold_channel.get("parsed_foldseek_results") or {}).items()
        )
        if isinstance(parsed_result, dict)
    }
    missing_result_files = [
        {"name": name, "path": summary.get("path")}
        for name, summary in result_files.items()
        if not summary.get("exists")
    ]

    contract_summary: dict[str, Any] | None = None
    contract_missing = False
    if contract_audit_path is not None:
        if contract_audit_path.exists():
            contract_audit = _read_json(contract_audit_path)
            critical_counts = (contract_audit.get("counts") or {}).get(
                "critical_counts"
            ) or {}
            contract_summary = {
                "path": str(contract_audit_path),
                "sha256": _sha256(contract_audit_path),
                "status": contract_audit.get("status"),
                "critical_violation_total": sum(critical_counts.values()),
                "critical_counts": critical_counts,
            }
        else:
            contract_missing = True

    unique_missing = [
        record
        for record in unique_coordinate_records
        if not record["local_file_exists_observed"]
    ]
    unique_observed = [
        record
        for record in unique_coordinate_records
        if record["local_file_exists_observed"]
    ]
    unique_accessions_without_any_file = [
        record
        for record in unique_accession_records
        if not record["any_local_file_exists_observed"]
    ]
    total_requests = sum(summary["request_count"] for summary in group_summaries.values())
    total_missing_requests = sum(
        summary["missing_file_count"] for summary in group_summaries.values()
    )
    total_observed_requests = sum(
        summary["observed_file_count"] for summary in group_summaries.values()
    )
    critical_counts = {
        "malformed_coordinate_requests": len(malformed_requests),
        "missing_result_files": len(missing_result_files),
        "contract_audit_missing": 1 if contract_missing else 0,
    }
    result_files_parseable = all(
        summary.get("exists") and summary.get("parsed_status") == "parsed"
        for summary in result_files.values()
    )
    if any(critical_counts.values()) or not result_files_parseable:
        status = "coordinate_provenance_audit_blocked"
    elif unique_missing:
        status = "coordinate_bundle_not_persisted_results_parseable"
    else:
        status = "coordinate_provenance_complete"

    materialization_plan = {
        "decision_needed": (
            "Persist the AFDB-v6 CIF coordinate bundle if byte-level "
            "Foldseek reproduction is required; the scored TSVs already "
            "support downstream diagnostics."
        ),
        "missing_coordinate_paths": len(unique_missing),
        "deduplicated_missing_accessions": len(unique_accessions_without_any_file),
        "rerun_provenance_audit_command": (
            "PYTHONPATH=src python -m catalytic_earth.cli "
            "audit-predicted-structure-fold-channel-coordinate-provenance"
        ),
        "download_script": (
            "python - <<'PY'\n"
            "import json\n"
            "import urllib.request\n"
            "from pathlib import Path\n"
            "artifact = json.loads(Path('artifacts/"
            "v3_predicted_structure_fold_channel_current702_20260601.json')"
            ".read_text())\n"
            "seen = set()\n"
            "for group in artifact['foldseek_input_manifest']"
            "['coordinate_request_groups'].values():\n"
            "    for item in group:\n"
            "        path = item.get('expected_local_path')\n"
            "        url = item.get('url')\n"
            "        if not path or not url or path in seen:\n"
            "            continue\n"
            "        seen.add(path)\n"
            "        target = Path(path)\n"
            "        target.parent.mkdir(parents=True, exist_ok=True)\n"
            "        if not target.exists():\n"
            "            urllib.request.urlretrieve(url, target)\n"
            "PY"
        ),
    }

    return {
        "artifact_id": PREDICTED_STRUCTURE_FOLD_CHANNEL_COORDINATE_PROVENANCE_AUDIT_ID,
        "schema_version": SCHEMA_VERSION,
        "created_utc": _utc_now_iso(),
        "status": status,
        "scope": (
            "Coordinate-provenance audit for the already scored "
            "AlphaFoldDB-predicted Foldseek/TM channel. This validates the "
            "remaining persistent CIF bundle blocker without rerunning "
            "Foldseek/TM or changing downstream scores."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "heldout_threshold_tuning_for_deployment": False,
            "foldseek_rerun_performed": False,
            "coordinate_downloads_performed": False,
            "validation_only": True,
        },
        "counts": {
            "coordinate_request_groups": len(group_summaries),
            "total_coordinate_requests": total_requests,
            "total_coordinate_requests_observed": total_observed_requests,
            "total_coordinate_requests_missing": total_missing_requests,
            "unique_coordinate_files_expected": len(unique_coordinate_records),
            "unique_coordinate_files_observed": len(unique_observed),
            "unique_coordinate_files_missing": len(unique_missing),
            "unique_accessions_expected": len(unique_accession_records),
            "unique_accessions_without_any_local_file": len(
                unique_accessions_without_any_file
            ),
            "duplicate_coordinate_request_paths": len(duplicate_coordinate_requests),
            "duplicate_accession_requests": len(duplicate_accession_requests),
            "foldseek_result_files": len(result_files),
            "foldseek_result_files_missing": len(missing_result_files),
            "result_files_parseable": result_files_parseable,
            "critical_counts": critical_counts,
        },
        "coordinate_request_group_summaries": group_summaries,
        "duplicate_coordinate_requests": duplicate_coordinate_requests,
        "duplicate_accession_requests": duplicate_accession_requests,
        "unique_missing_coordinate_files": unique_missing,
        "unique_accessions_without_any_local_file": unique_accessions_without_any_file,
        "missing_coordinate_requests_by_group": missing_coordinate_requests,
        "observed_coordinate_requests_by_group": observed_coordinate_requests,
        "foldseek_result_files": result_files,
        "contract_audit": contract_summary,
        "violations": {
            "malformed_coordinate_requests": malformed_requests[:50],
            "reported_observed_local_file_exists_mismatches": (
                reported_observed_mismatches[:50]
            ),
            "missing_result_files": missing_result_files[:50],
            "contract_audit_missing": (
                [{"path": str(contract_audit_path)}] if contract_missing else []
            ),
        },
        "materialization_plan": materialization_plan,
        "interpretation": {
            "result": (
                "The Foldseek/TM result TSVs are present and parsed, but the "
                "persistent AFDB-v6 coordinate bundle is not committed locally."
                if unique_missing and result_files_parseable
                else (
                    "The fold-channel coordinate bundle and Foldseek/TM result "
                    "files are locally present."
                    if not unique_missing and result_files_parseable
                    else "The provenance audit found a critical result-file or schema blocker."
                )
            ),
            "next_action": (
                "If byte-level score reproduction is needed, materialize the "
                f"{len(unique_missing)} missing coordinate paths "
                f"({len(unique_accessions_without_any_file)} deduplicated "
                "AFDB-v6 accessions) using the recorded download script, "
                "rerun the contract audit, and then rerun this provenance audit."
                if unique_missing
                else "Keep the coordinate bundle with the scored TSVs and rerun this audit after any fold-channel score refresh."
            ),
        },
        "source_artifacts": {
            "predicted_structure_fold_channel": {
                "path": str(predicted_structure_fold_channel_path),
                "sha256": _sha256(predicted_structure_fold_channel_path),
            },
            "contract_audit": (
                _source_path_record(contract_audit_path)
                if contract_audit_path is not None
                else None
            ),
        },
    }


def _render_predicted_structure_fold_channel_coordinate_provenance_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    lines = [
        "# Predicted-Structure Fold Channel Coordinate Provenance Audit - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Unique coordinate files expected: {counts['unique_coordinate_files_expected']}",
        f"- Unique coordinate files observed: {counts['unique_coordinate_files_observed']}",
        f"- Unique coordinate files missing: {counts['unique_coordinate_files_missing']}",
        f"- Deduplicated AFDB accessions expected: {counts['unique_accessions_expected']}",
        "- Deduplicated AFDB accessions with no local file: "
        f"{counts['unique_accessions_without_any_local_file']}",
        f"- Foldseek result files missing: {counts['foldseek_result_files_missing']}",
        f"- Result files parseable: {counts['result_files_parseable']}",
        "",
        "## Coordinate Groups",
        "",
    ]
    for name, summary in audit["coordinate_request_group_summaries"].items():
        lines.append(
            f"- {name}: requests={summary['request_count']}, "
            f"observed={summary['observed_file_count']}, "
            f"missing={summary['missing_file_count']}, "
            f"unique_paths={summary['unique_expected_path_count']}"
        )
    lines += [
        "",
        "## Foldseek Results",
        "",
    ]
    for name, summary in audit["foldseek_result_files"].items():
        lines.append(
            f"- {name}: exists={summary['exists']}, "
            f"parsed={summary['parsed_status']}, "
            f"lines={summary['nonempty_line_count']}, "
            f"hits={summary['query_entry_count_with_hits']}"
        )
    contract = audit.get("contract_audit")
    if contract:
        lines += [
            "",
            "## Contract Audit",
            "",
            f"- Status: {contract['status']}",
            f"- Critical violations: {contract['critical_violation_total']}",
        ]
    lines += [
        "",
        "## Materialization Plan",
        "",
        f"- {audit['materialization_plan']['decision_needed']}",
        f"- Missing coordinate paths: {audit['materialization_plan']['missing_coordinate_paths']}",
        "- Deduplicated missing AFDB accessions: "
        f"{audit['materialization_plan']['deduplicated_missing_accessions']}",
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['result']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_predicted_structure_fold_channel_coordinate_provenance_audit(
    *,
    predicted_structure_fold_channel_path: Path,
    contract_audit_path: Path | None,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_predicted_structure_fold_channel_coordinate_provenance_audit(
        predicted_structure_fold_channel_path=predicted_structure_fold_channel_path,
        contract_audit_path=contract_audit_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_predicted_structure_fold_channel_coordinate_provenance_report(
                audit
            ),
            encoding="utf-8",
        )
    return audit


def _compact_coordinate_reproduction_record(
    group_name: str, item: dict[str, Any]
) -> dict[str, Any]:
    record = _coordinate_request_record(item)
    return {
        "group": group_name,
        "accession": record["accession"],
        "predicted_pdb_id": record["predicted_pdb_id"],
        "entry_ids": record["entry_ids"],
        "role": record["role"],
        "expected_local_path": record["expected_local_path"],
        "url": record["url"],
        "download_command": record["download_command"],
        "local_file_exists_observed": record["local_file_exists_observed"],
        "sha256": record["sha256"],
    }


def build_predicted_structure_fold_channel_reproduction_manifest(
    *,
    predicted_structure_fold_channel_path: Path,
    contract_audit_path: Path | None = None,
    coordinate_provenance_audit_path: Path | None = None,
) -> dict[str, Any]:
    fold_channel = _read_json(predicted_structure_fold_channel_path)
    request_groups = (
        (fold_channel.get("foldseek_input_manifest") or {}).get(
            "coordinate_request_groups"
        )
        or {}
    )

    coordinate_requests_by_group: dict[str, list[dict[str, Any]]] = {}
    malformed_coordinate_groups: list[dict[str, Any]] = []
    unique_by_path: dict[str, dict[str, Any]] = {}
    accession_to_paths: dict[str, set[str]] = defaultdict(set)
    accession_to_groups: dict[str, set[str]] = defaultdict(set)
    accession_to_entry_ids: dict[str, set[str]] = defaultdict(set)

    for group_name, raw_items in sorted(request_groups.items()):
        group_records = []
        if not isinstance(raw_items, list):
            malformed_coordinate_groups.append(
                {"group": group_name, "reason": "coordinate_group_not_list"}
            )
            raw_items = []
        for raw_item in raw_items:
            if not isinstance(raw_item, dict):
                malformed_coordinate_groups.append(
                    {"group": group_name, "reason": "coordinate_request_not_object"}
                )
                continue
            record = _compact_coordinate_reproduction_record(group_name, raw_item)
            group_records.append(record)
            path = record["expected_local_path"]
            accession = record["accession"]
            if path:
                aggregate = unique_by_path.setdefault(
                    path,
                    {
                        "expected_local_path": path,
                        "accessions": set(),
                        "entry_ids": set(),
                        "groups": set(),
                        "urls": set(),
                        "download_commands": set(),
                        "local_file_exists_observed": record[
                            "local_file_exists_observed"
                        ],
                        "sha256": record["sha256"],
                    },
                )
                if accession:
                    aggregate["accessions"].add(str(accession))
                for entry_id in record["entry_ids"]:
                    aggregate["entry_ids"].add(str(entry_id))
                aggregate["groups"].add(group_name)
                if record["url"]:
                    aggregate["urls"].add(str(record["url"]))
                if record["download_command"]:
                    aggregate["download_commands"].add(str(record["download_command"]))
            if accession and path:
                accession_to_paths[str(accession)].add(path)
                accession_to_groups[str(accession)].add(group_name)
                for entry_id in record["entry_ids"]:
                    accession_to_entry_ids[str(accession)].add(str(entry_id))
        coordinate_requests_by_group[group_name] = group_records

    unique_coordinates = []
    for path, record in sorted(unique_by_path.items()):
        unique_coordinates.append(
            {
                "expected_local_path": path,
                "accessions": sorted(record["accessions"]),
                "entry_ids": sorted(record["entry_ids"], key=_entry_id_sort_key),
                "groups": sorted(record["groups"]),
                "urls": sorted(record["urls"]),
                "download_commands": sorted(record["download_commands"]),
                "local_file_exists_observed": bool(
                    record["local_file_exists_observed"]
                ),
                "sha256": record["sha256"],
            }
        )

    missing_unique_coordinates = [
        record
        for record in unique_coordinates
        if not record["local_file_exists_observed"]
    ]
    observed_unique_coordinates = [
        record for record in unique_coordinates if record["local_file_exists_observed"]
    ]
    missing_accessions = sorted(
        {
            accession
            for accession, paths in accession_to_paths.items()
            if not any(Path(path).is_file() for path in paths)
        }
    )
    duplicate_accession_requests = [
        {
            "accession": accession,
            "expected_local_paths": sorted(paths),
            "entry_ids": sorted(
                accession_to_entry_ids[accession], key=_entry_id_sort_key
            ),
            "groups": sorted(accession_to_groups[accession]),
        }
        for accession, paths in sorted(accession_to_paths.items())
        if len(paths) > 1 or len(accession_to_groups[accession]) > 1
    ]

    group_summaries = {}
    for group_name, records in coordinate_requests_by_group.items():
        missing = [
            record for record in records if not record["local_file_exists_observed"]
        ]
        group_summaries[group_name] = {
            "request_count": len(records),
            "missing_file_count": len(missing),
            "observed_file_count": len(records) - len(missing),
            "unique_expected_path_count": len(
                {record["expected_local_path"] for record in records}
            ),
            "unique_accession_count": len(
                {record["accession"] for record in records if record["accession"]}
            ),
        }

    result_files = {
        name: _summarize_foldseek_result_path(parsed_result)
        for name, parsed_result in (
            (fold_channel.get("parsed_foldseek_results") or {}).items()
        )
        if isinstance(parsed_result, dict)
    }
    result_files_parseable = all(
        summary.get("exists") and summary.get("parsed_status") == "parsed"
        for summary in result_files.values()
    )
    missing_result_files = [
        {"name": name, "path": summary.get("path")}
        for name, summary in result_files.items()
        if not summary.get("exists")
    ]

    contract_summary = None
    contract_passed = False
    contract_missing = False
    if contract_audit_path is not None and contract_audit_path.exists():
        contract_audit = _read_json(contract_audit_path)
        critical_counts = (contract_audit.get("counts") or {}).get(
            "critical_counts"
        ) or {}
        contract_summary = {
            "path": str(contract_audit_path),
            "sha256": _sha256(contract_audit_path),
            "status": contract_audit.get("status"),
            "critical_violation_total": sum(critical_counts.values()),
            "critical_counts": critical_counts,
        }
        contract_passed = (
            contract_audit.get("status") == "fold_channel_contract_passed_current702"
            and sum(critical_counts.values()) == 0
        )
    elif contract_audit_path is not None:
        contract_missing = True

    coordinate_provenance_summary = None
    coordinate_provenance_missing = False
    if (
        coordinate_provenance_audit_path is not None
        and coordinate_provenance_audit_path.exists()
    ):
        coordinate_provenance = _read_json(coordinate_provenance_audit_path)
        coordinate_provenance_summary = {
            "path": str(coordinate_provenance_audit_path),
            "sha256": _sha256(coordinate_provenance_audit_path),
            "status": coordinate_provenance.get("status"),
            "counts": {
                key: (coordinate_provenance.get("counts") or {}).get(key)
                for key in (
                    "unique_coordinate_files_expected",
                    "unique_coordinate_files_missing",
                    "unique_accessions_without_any_local_file",
                    "result_files_parseable",
                )
            },
        }
    elif coordinate_provenance_audit_path is not None:
        coordinate_provenance_missing = True

    runtime = fold_channel.get("runtime") or {}
    foldseek_runtime = runtime.get("foldseek") or {}
    foldseek_available = bool(foldseek_runtime.get("available"))
    coordinate_bundle_complete = not missing_unique_coordinates
    byte_reproduction_ready = (
        result_files_parseable
        and contract_passed
        and coordinate_bundle_complete
        and foldseek_available
        and not malformed_coordinate_groups
    )

    critical_counts = {
        "malformed_coordinate_groups": len(malformed_coordinate_groups),
        "contract_audit_missing": 1 if contract_missing else 0,
        "contract_audit_not_passing": 0 if contract_passed else 1,
        "coordinate_provenance_audit_missing": (
            1 if coordinate_provenance_missing else 0
        ),
        "missing_result_files": len(missing_result_files),
    }
    if not result_files_parseable or not contract_passed:
        status = "fold_channel_reproduction_manifest_blocked_by_score_contract"
    elif byte_reproduction_ready:
        status = "fold_channel_byte_reproduction_ready"
    else:
        status = "fold_channel_reproduction_manifest_ready_missing_coordinates"

    blocker_classes = []
    if missing_unique_coordinates:
        blocker_classes.append("persistent_afdb_v6_coordinate_bundle_missing")
    if not foldseek_available:
        blocker_classes.append("foldseek_runtime_not_available")
    if malformed_coordinate_groups:
        blocker_classes.append("malformed_coordinate_request_manifest")
    if missing_result_files:
        blocker_classes.append("foldseek_result_tsv_missing")
    if not contract_passed:
        blocker_classes.append("scored_fold_channel_contract_not_passing")

    commands = fold_channel.get("commands") or {}
    reproduction_commands = {
        "materialize_all_missing_afdb_v6_coordinates": commands.get(
            "materialize_coordinate_bundle"
        ),
        "run_priority_cofactor_confounded_oos_vs_atlas": commands.get(
            "run_priority_cofactor_confounded_oos_vs_atlas"
        ),
        "run_all_heldout_vs_atlas_when_cheap": commands.get(
            "run_all_heldout_vs_atlas_when_cheap"
        ),
        "rerun_contract_audit": (
            "PYTHONPATH=src python -m catalytic_earth.cli "
            "audit-predicted-structure-fold-channel-contract"
        ),
        "rerun_coordinate_provenance_audit": (
            "PYTHONPATH=src python -m catalytic_earth.cli "
            "audit-predicted-structure-fold-channel-coordinate-provenance"
        ),
        "rerun_reproduction_manifest": (
            "PYTHONPATH=src python -m catalytic_earth.cli "
            "build-predicted-structure-fold-channel-reproduction-manifest"
        ),
    }

    return {
        "artifact_id": PREDICTED_STRUCTURE_FOLD_CHANNEL_REPRODUCTION_MANIFEST_ID,
        "schema_version": f"{SCHEMA_VERSION}.predicted_structure_fold_reproduction",
        "created_utc": _utc_now_iso(),
        "status": status,
        "scope": (
            "Validation-only reproduction manifest for the already scored "
            "AlphaFoldDB-predicted Foldseek/TM channel. It records exact "
            "coordinate inputs, scored TSV hashes, rerun commands, and the "
            "remaining byte-level reproduction blockers without downloading "
            "coordinates or rerunning Foldseek/TM."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "heldout_threshold_tuning_for_deployment": False,
            "coordinate_downloads_performed": False,
            "foldseek_or_tmsearch_recomputed": False,
            "uses_existing_scored_tsvs_only": True,
            "frozen_current702_inputs_only": True,
            "validation_only": True,
        },
        "counts": {
            "coordinate_request_groups": len(coordinate_requests_by_group),
            "total_coordinate_requests": sum(
                len(records) for records in coordinate_requests_by_group.values()
            ),
            "unique_coordinate_files_expected": len(unique_coordinates),
            "unique_coordinate_files_observed": len(observed_unique_coordinates),
            "unique_coordinate_files_missing": len(missing_unique_coordinates),
            "unique_accessions_expected": len(accession_to_paths),
            "unique_accessions_without_any_local_file": len(missing_accessions),
            "duplicate_accession_requests": len(duplicate_accession_requests),
            "foldseek_result_files": len(result_files),
            "foldseek_result_files_missing": len(missing_result_files),
            "result_files_parseable": result_files_parseable,
            "foldseek_runtime_available": foldseek_available,
            "byte_reproduction_ready": byte_reproduction_ready,
            "critical_counts": critical_counts,
            "heldout_rows_ok": (fold_channel.get("counts") or {}).get(
                "heldout_rows_ok"
            ),
            "priority_cofactor_confounded_oos_rows": (
                fold_channel.get("counts") or {}
            ).get("priority_cofactor_confounded_oos_rows"),
        },
        "coordinate_request_group_summaries": group_summaries,
        "missing_coordinate_manifest": missing_unique_coordinates,
        "duplicate_accession_requests": duplicate_accession_requests,
        "foldseek_result_files": result_files,
        "foldseek_runtime": foldseek_runtime,
        "scored_channel_contract": contract_summary,
        "coordinate_provenance_audit": coordinate_provenance_summary,
        "reproduction_commands": reproduction_commands,
        "blocker_classes": blocker_classes,
        "violations": {
            "malformed_coordinate_groups": malformed_coordinate_groups[:50],
            "missing_result_files": missing_result_files[:50],
            "contract_audit_missing": (
                [{"path": str(contract_audit_path)}] if contract_missing else []
            ),
            "coordinate_provenance_audit_missing": (
                [{"path": str(coordinate_provenance_audit_path)}]
                if coordinate_provenance_missing
                else []
            ),
        },
        "interpretation": {
            "result": (
                "The scored Foldseek/TM channel remains usable for downstream "
                "diagnostics because the TSVs parse and the scoring contract "
                "passes; byte-level reproduction is blocked only by the missing "
                "persistent AFDB-v6 coordinate bundle."
                if status
                == "fold_channel_reproduction_manifest_ready_missing_coordinates"
                else (
                    "The coordinate bundle, Foldseek runtime, result TSVs, and "
                    "contract audit are all present for byte-level reproduction."
                    if status == "fold_channel_byte_reproduction_ready"
                    else "The scored fold-channel contract or TSV availability must be repaired before reproduction."
                )
            ),
            "next_action": (
                "Materialize the missing AFDB-v6 CIF paths with the recorded "
                "download command only if byte-level Foldseek reproduction is "
                "needed; otherwise continue downstream diagnostics from the "
                "existing scored TSVs and contract audit."
                if missing_unique_coordinates and result_files_parseable
                else "Rerun the reproduction manifest after any Foldseek/TM score refresh."
            ),
        },
        "source_artifacts": {
            "predicted_structure_fold_channel": {
                "path": str(predicted_structure_fold_channel_path),
                "sha256": _sha256(predicted_structure_fold_channel_path),
            },
            "contract_audit": (
                _source_path_record(contract_audit_path)
                if contract_audit_path is not None
                else None
            ),
            "coordinate_provenance_audit": (
                _source_path_record(coordinate_provenance_audit_path)
                if coordinate_provenance_audit_path is not None
                else None
            ),
        },
    }


def _render_predicted_structure_fold_channel_reproduction_manifest_report(
    manifest: dict[str, Any],
) -> str:
    counts = manifest["counts"]
    lines = [
        "# Predicted-Structure Fold Channel Reproduction Manifest - current702",
        "",
        f"Run: {manifest['created_utc']}",
        "",
        manifest["scope"],
        "",
        "## Status",
        "",
        f"- {manifest['status']}",
        f"- Heldout ok rows: {counts['heldout_rows_ok']}",
        f"- Priority cofactor-confounded rows: {counts['priority_cofactor_confounded_oos_rows']}",
        f"- Result TSVs parseable: {counts['result_files_parseable']}",
        f"- Foldseek runtime available: {counts['foldseek_runtime_available']}",
        f"- Unique coordinate files expected: {counts['unique_coordinate_files_expected']}",
        f"- Unique coordinate files missing: {counts['unique_coordinate_files_missing']}",
        f"- Deduplicated missing AFDB accessions: {counts['unique_accessions_without_any_local_file']}",
        f"- Byte-level reproduction ready: {counts['byte_reproduction_ready']}",
        "",
        "## Coordinate Groups",
        "",
    ]
    for group_name, summary in manifest["coordinate_request_group_summaries"].items():
        lines.append(
            f"- {group_name}: requests={summary['request_count']}, "
            f"observed={summary['observed_file_count']}, "
            f"missing={summary['missing_file_count']}, "
            f"unique_paths={summary['unique_expected_path_count']}"
        )
    lines += [
        "",
        "## Foldseek Result Files",
        "",
    ]
    for name, summary in manifest["foldseek_result_files"].items():
        lines.append(
            f"- {name}: exists={summary['exists']}, "
            f"parsed={summary['parsed_status']}, "
            f"lines={summary['nonempty_line_count']}, "
            f"hits={summary['query_entry_count_with_hits']}, "
            f"sha256={summary['sha256']}"
        )
    contract = manifest.get("scored_channel_contract")
    if contract:
        lines += [
            "",
            "## Contract Audit",
            "",
            f"- Status: {contract['status']}",
            f"- Critical violations: {contract['critical_violation_total']}",
        ]
    lines += [
        "",
        "## Blockers",
        "",
    ]
    blockers = manifest.get("blocker_classes") or []
    if blockers:
        lines.extend(f"- {blocker}" for blocker in blockers)
    else:
        lines.append("- none")
    lines += [
        "",
        "## Commands",
        "",
        "- Materialize coordinates: "
        "`reproduction_commands.materialize_all_missing_afdb_v6_coordinates`",
        "- Rerun priority Foldseek/TM: "
        "`reproduction_commands.run_priority_cofactor_confounded_oos_vs_atlas`",
        "- Rerun all-heldout Foldseek/TM: "
        "`reproduction_commands.run_all_heldout_vs_atlas_when_cheap`",
        "- Rerun audits: "
        "`reproduction_commands.rerun_contract_audit`, "
        "`reproduction_commands.rerun_coordinate_provenance_audit`, "
        "then `reproduction_commands.rerun_reproduction_manifest`",
        "",
        "## Interpretation",
        "",
        f"- {manifest['interpretation']['result']}",
        f"- {manifest['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_predicted_structure_fold_channel_reproduction_manifest(
    *,
    predicted_structure_fold_channel_path: Path,
    contract_audit_path: Path | None,
    coordinate_provenance_audit_path: Path | None,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    manifest = build_predicted_structure_fold_channel_reproduction_manifest(
        predicted_structure_fold_channel_path=predicted_structure_fold_channel_path,
        contract_audit_path=contract_audit_path,
        coordinate_provenance_audit_path=coordinate_provenance_audit_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_predicted_structure_fold_channel_reproduction_manifest_report(
                manifest
            ),
            encoding="utf-8",
        )
    return manifest


def _contract_critical_violation_total(contract_audit: dict[str, Any]) -> int:
    critical_counts = (contract_audit.get("counts") or {}).get("critical_counts") or {}
    total = 0
    for value in critical_counts.values():
        if isinstance(value, bool):
            continue
        if isinstance(value, (int, float)):
            total += int(value)
    return total


def build_predicted_structure_fold_channel_carryover_resolution(
    *,
    predicted_geometry_atlas_path: Path,
    fold_level_signal_path: Path,
    predicted_structure_fold_channel_path: Path,
    contract_audit_path: Path,
    coordinate_provenance_audit_path: Path,
    reproduction_manifest_path: Path,
    predicted_structure_fold_channel_report_path: Path | None = None,
) -> dict[str, Any]:
    predicted_atlas = _read_json(predicted_geometry_atlas_path)
    fold_signal = _read_json(fold_level_signal_path)
    fold_channel = _read_json(predicted_structure_fold_channel_path)
    contract_audit = _read_json(contract_audit_path)
    coordinate_provenance = _read_json(coordinate_provenance_audit_path)
    reproduction_manifest = _read_json(reproduction_manifest_path)

    rows = [row for row in predicted_atlas.get("results", []) if isinstance(row, dict)]
    atlas_rows = [
        row
        for row in rows
        if row.get("split_assignment") == "in_distribution" and _predicted_row_ok(row)
    ]
    heldout_rows = [
        row
        for row in rows
        if row.get("split_assignment") == "heldout" and _predicted_row_ok(row)
    ]
    heldout_ids = {
        str(row.get("entry_id"))
        for row in heldout_rows
        if row.get("entry_id")
    }
    confounded_ids = set(
        fold_signal.get("confounded_entry_ids", {}).get(
            "predicted_geometry_overlap_current_gate", []
        )
    )
    priority_ids = heldout_ids & confounded_ids

    parsed = fold_channel.get("parsed_foldseek_results") or {}
    all_parsed = parsed.get("all_heldout_vs_atlas") or {}
    priority_parsed = parsed.get("priority_cofactor_confounded_oos_vs_atlas") or {}
    all_hit_count = (all_parsed.get("summary") or {}).get(
        "query_entry_count_with_hits"
    )
    priority_hit_count = (priority_parsed.get("summary") or {}).get(
        "query_entry_count_with_hits"
    )
    all_hit_count = int(all_hit_count or 0)
    priority_hit_count = int(priority_hit_count or 0)

    contract_critical_total = _contract_critical_violation_total(contract_audit)
    contract_passed = (
        contract_audit.get("status") == "fold_channel_contract_passed_current702"
        and contract_critical_total == 0
    )
    coordinate_counts = coordinate_provenance.get("counts") or {}
    reproduction_counts = reproduction_manifest.get("counts") or {}
    result_files_parseable = bool(
        coordinate_counts.get("result_files_parseable")
        and reproduction_counts.get("result_files_parseable")
    )
    scored_scope_complete = (
        fold_channel.get("status") == "computed_all_heldout_foldseek_scores"
        and all_parsed.get("status") == "parsed"
        and priority_parsed.get("status") == "parsed"
        and all_hit_count == len(heldout_ids)
        and priority_hit_count == len(priority_ids)
        and contract_passed
    )
    report_exists = (
        predicted_structure_fold_channel_report_path.exists()
        if predicted_structure_fold_channel_report_path is not None
        else None
    )
    requested_outputs_present = (
        predicted_structure_fold_channel_path.exists()
        and (report_exists is not False)
    )
    byte_reproduction_ready = (
        reproduction_manifest.get("status") == "fold_channel_byte_reproduction_ready"
    )
    coordinate_bundle_missing = int(
        coordinate_counts.get("unique_coordinate_files_missing") or 0
    )
    rerun_required = not scored_scope_complete

    status = (
        "fold_channel_carryover_resolved_no_rerun_needed"
        if scored_scope_complete and requested_outputs_present and result_files_parseable
        else "fold_channel_carryover_requires_repair_or_manifest"
    )
    blocker_classes = []
    if not scored_scope_complete:
        blocker_classes.append("scored_fold_channel_contract_or_scope_incomplete")
    if not requested_outputs_present:
        blocker_classes.append("requested_fold_channel_output_missing")
    if not result_files_parseable:
        blocker_classes.append("foldseek_result_tsv_parseability_not_confirmed")
    if coordinate_bundle_missing and not byte_reproduction_ready:
        blocker_classes.append("persistent_afdb_v6_coordinate_bundle_missing")

    return {
        "artifact_id": PREDICTED_STRUCTURE_FOLD_CHANNEL_CARRYOVER_RESOLUTION_ID,
        "schema_version": f"{SCHEMA_VERSION}.predicted_structure_fold_carryover_resolution",
        "created_utc": _utc_now_iso(),
        "status": status,
        "scope": (
            "Validation-only resolution of the carryover request to build or "
            "stage the AlphaFoldDB-predicted Foldseek/TM channel from frozen "
            "current702 inputs."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "heldout_threshold_tuning_for_deployment": False,
            "foldseek_tm_recomputed": False,
            "coordinate_downloads_performed": False,
            "validation_only": True,
        },
        "requested_carryover_resolution": {
            "requested_primary_output_artifact": str(
                predicted_structure_fold_channel_path
            ),
            "requested_primary_output_report": (
                str(predicted_structure_fold_channel_report_path)
                if predicted_structure_fold_channel_report_path is not None
                else None
            ),
            "requested_outputs_present": requested_outputs_present,
            "scored_scope_complete": scored_scope_complete,
            "foldseek_rerun_required": rerun_required,
            "foldseek_rerun_decision": (
                "no_rerun_existing_scored_channel_contract_passes"
                if not rerun_required
                else "rerun_or_repair_required_before_downstream_use"
            ),
            "byte_level_reproduction_ready": byte_reproduction_ready,
            "coordinate_provenance_blocker_is_score_blocker": False,
            "remaining_blocker_classes": blocker_classes,
        },
        "counts": {
            "predicted_atlas_rows": len(rows),
            "atlas_in_distribution_rows_ok": len(atlas_rows),
            "heldout_rows_ok": len(heldout_rows),
            "confounded_entry_ids_from_fold_signal": len(confounded_ids),
            "priority_cofactor_confounded_oos_rows": len(priority_ids),
            "all_heldout_nearest_hits": all_hit_count,
            "priority_nearest_hits": priority_hit_count,
            "contract_critical_violation_total": contract_critical_total,
            "unique_coordinate_files_expected": coordinate_counts.get(
                "unique_coordinate_files_expected"
            ),
            "unique_coordinate_files_missing": coordinate_bundle_missing,
            "deduplicated_afdb_accessions_missing": coordinate_counts.get(
                "unique_accessions_without_any_local_file"
            ),
            "foldseek_result_files_parseable": result_files_parseable,
        },
        "input_artifact_status": {
            "predicted_geometry_atlas_status": predicted_atlas.get("status"),
            "fold_level_signal_status": fold_signal.get("status"),
            "predicted_structure_fold_channel_status": fold_channel.get("status"),
            "contract_audit_status": contract_audit.get("status"),
            "coordinate_provenance_status": coordinate_provenance.get("status"),
            "reproduction_manifest_status": reproduction_manifest.get("status"),
        },
        "safe_next_actions": [
            {
                "rank": 1,
                "action": (
                    "Do not rerun the predicted-structure fold channel unless "
                    "the contract audit fails; continue from current handoff "
                    "review gates."
                ),
                "blocked_by_human_decision": False,
            },
            {
                "rank": 2,
                "action": (
                    "If mechanism-feature work resumes, start with reviewer "
                    "provenance for m_csa:11, m_csa:169, and m_csa:5 before "
                    "refreshing any no-template feature contract."
                ),
                "blocked_by_human_decision": True,
            },
            {
                "rank": 3,
                "action": (
                    "If the run must remain automation-only, use docs/artifact "
                    "index cleanup and focused validation rather than mutating "
                    "labels, thresholds, or registries."
                ),
                "blocked_by_human_decision": False,
            },
        ],
        "commands": {
            "rerun_this_resolution": (
                "PYTHONPATH=src python -m catalytic_earth.cli "
                "audit-predicted-structure-fold-channel-carryover-resolution"
            ),
            "rerun_contract_audit_if_needed": (
                "PYTHONPATH=src python -m catalytic_earth.cli "
                "audit-predicted-structure-fold-channel-contract"
            ),
            "rerun_coordinate_provenance_if_byte_reproduction_needed": (
                "PYTHONPATH=src python -m catalytic_earth.cli "
                "audit-predicted-structure-fold-channel-coordinate-provenance"
            ),
        },
        "interpretation": {
            "result": (
                "The requested fold-channel build/stage task is already "
                "satisfied by the existing scored artifact and its passing "
                "strict contract audit."
                if status == "fold_channel_carryover_resolved_no_rerun_needed"
                else "The fold-channel carryover is not resolved; inspect blocker classes before downstream use."
            ),
            "next_action": (
                "Treat the fold channel as downstream-ready for review-only "
                "diagnostics; persistent AFDB-v6 CIF provenance is only needed "
                "for byte-level reproduction."
                if status == "fold_channel_carryover_resolved_no_rerun_needed"
                else "Repair or rerun the missing/failed fold-channel validation layer first."
            ),
        },
        "source_artifacts": {
            "predicted_geometry_atlas": _source_path_record(predicted_geometry_atlas_path),
            "fold_level_signal": _source_path_record(fold_level_signal_path),
            "predicted_structure_fold_channel": _source_path_record(
                predicted_structure_fold_channel_path
            ),
            "predicted_structure_fold_channel_report": (
                _source_path_record(predicted_structure_fold_channel_report_path)
                if predicted_structure_fold_channel_report_path is not None
                else None
            ),
            "contract_audit": _source_path_record(contract_audit_path),
            "coordinate_provenance_audit": _source_path_record(
                coordinate_provenance_audit_path
            ),
            "reproduction_manifest": _source_path_record(reproduction_manifest_path),
        },
    }


def _render_predicted_structure_fold_channel_carryover_resolution_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    resolution = audit["requested_carryover_resolution"]
    lines = [
        "# Predicted-Structure Fold Channel Carryover Resolution - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Requested outputs present: {resolution['requested_outputs_present']}",
        f"- Scored scope complete: {resolution['scored_scope_complete']}",
        f"- Foldseek rerun required: {resolution['foldseek_rerun_required']}",
        f"- Remaining blockers: {', '.join(resolution['remaining_blocker_classes']) or 'none'}",
        "",
        "## Counts",
        "",
        f"- Atlas in-distribution ok rows: {counts['atlas_in_distribution_rows_ok']}",
        f"- Heldout ok rows: {counts['heldout_rows_ok']}",
        f"- Priority cofactor-confounded OOS rows: {counts['priority_cofactor_confounded_oos_rows']}",
        f"- All-heldout nearest hits: {counts['all_heldout_nearest_hits']}",
        f"- Priority nearest hits: {counts['priority_nearest_hits']}",
        f"- Contract critical violations: {counts['contract_critical_violation_total']}",
        f"- Missing persistent coordinate files: {counts['unique_coordinate_files_missing']}",
        "",
        "## Input Status",
        "",
    ]
    for key, value in audit["input_artifact_status"].items():
        lines.append(f"- {key}: {value}")
    lines += [
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['result']}",
        f"- {audit['interpretation']['next_action']}",
        "",
        "## Next Actions",
        "",
    ]
    for row in audit["safe_next_actions"]:
        lines.append(f"- {row['rank']}. {row['action']}")
    return "\n".join(lines) + "\n"


def write_predicted_structure_fold_channel_carryover_resolution(
    *,
    predicted_geometry_atlas_path: Path,
    fold_level_signal_path: Path,
    predicted_structure_fold_channel_path: Path,
    contract_audit_path: Path,
    coordinate_provenance_audit_path: Path,
    reproduction_manifest_path: Path,
    predicted_structure_fold_channel_report_path: Path | None = None,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_predicted_structure_fold_channel_carryover_resolution(
        predicted_geometry_atlas_path=predicted_geometry_atlas_path,
        fold_level_signal_path=fold_level_signal_path,
        predicted_structure_fold_channel_path=predicted_structure_fold_channel_path,
        contract_audit_path=contract_audit_path,
        coordinate_provenance_audit_path=coordinate_provenance_audit_path,
        reproduction_manifest_path=reproduction_manifest_path,
        predicted_structure_fold_channel_report_path=(
            predicted_structure_fold_channel_report_path
        ),
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(
        json.dumps(audit, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_predicted_structure_fold_channel_carryover_resolution_report(
                audit
            ),
            encoding="utf-8",
        )
    return audit


GEOMETRY_VARIANT_FEATURES = (
    "score",
    "role_match_fraction",
    "residue_match_fraction",
    "mechanistic_coherence_score",
    "substrate_pocket_score",
    "compactness_score",
    "cofactor_context_score",
    "counterevidence_penalty",
    "plp_ligand_anchor_score",
)


def _top1_fingerprint(row: dict[str, Any]) -> dict[str, Any] | None:
    top = row.get("top_fingerprints") or []
    if not top or not isinstance(top[0], dict):
        return None
    return top[0]


def _median(values: list[float]) -> float:
    if not values:
        return 0.0
    sorted_values = sorted(values)
    mid = len(sorted_values) // 2
    if len(sorted_values) % 2:
        return sorted_values[mid]
    return (sorted_values[mid - 1] + sorted_values[mid]) / 2


def _quantile(values: list[float], q: float) -> float:
    if not values:
        return 0.0
    sorted_values = sorted(values)
    pos = (len(sorted_values) - 1) * q
    lower = int(math.floor(pos))
    upper = int(math.ceil(pos))
    if lower == upper:
        return sorted_values[lower]
    weight = pos - lower
    return sorted_values[lower] * (1 - weight) + sorted_values[upper] * weight


def _percentile_rank(value: float, atlas_values: list[float]) -> float:
    if not atlas_values:
        return 0.0
    return sum(1 for item in atlas_values if item <= value) / len(atlas_values)


def _feature_vector(top: dict[str, Any]) -> list[float]:
    return [float(top.get(name) or 0.0) for name in GEOMETRY_VARIANT_FEATURES]


def _robust_center_scale(vectors: list[list[float]]) -> tuple[list[float], list[float]]:
    if not vectors:
        return [], []
    dims = len(vectors[0])
    centers = []
    scales = []
    for idx in range(dims):
        col = [vec[idx] for vec in vectors]
        centers.append(_median(col))
        iqr = _quantile(col, 0.75) - _quantile(col, 0.25)
        scales.append(iqr if abs(iqr) > 1e-9 else 1.0)
    return centers, scales


def _robust_distance(vector: list[float], center: list[float], scale: list[float]) -> float:
    if not center:
        return 0.0
    return math.sqrt(
        sum(((value - center[idx]) / scale[idx]) ** 2 for idx, value in enumerate(vector))
    )


def _signal_metrics(
    rows: list[dict[str, Any]],
    score_name: str,
) -> dict[str, Any]:
    inscope = [r for r in rows if r["is_inscope"]]
    oos = [r for r in rows if r["is_oos"]]
    conf = [r for r in oos if r["is_confounded_predicted_geometry_oos"]]
    agn = [r for r in oos if not r["is_confounded_predicted_geometry_oos"]]
    fn = lambda row: float(row["variant_scores"][score_name])
    return {
        "auc_in_gt_oos_all": _auc_in_gt_oos([fn(r) for r in inscope], [fn(r) for r in oos]),
        "auc_in_gt_confounded_oos": _auc_in_gt_oos([fn(r) for r in inscope], [fn(r) for r in conf]),
        "auc_in_gt_agnostic_oos": _auc_in_gt_oos([fn(r) for r in inscope], [fn(r) for r in agn]),
        "in_scope_mean": _mean([fn(r) for r in inscope]),
        "oos_mean": _mean([fn(r) for r in oos]),
        "confounded_mean": _mean([fn(r) for r in conf]),
        "best_at_90pct_inscope_retention": _best_threshold_at_retention(
            rows, fn, min_retain=0.90
        ),
        "best_at_85pct_inscope_retention": _best_threshold_at_retention(
            rows, fn, min_retain=0.85
        ),
    }


def build_predicted_atlas_geometry_novelty_variants(
    *,
    predicted_geometry_atlas_path: Path,
    fold_level_signal_path: Path,
) -> dict[str, Any]:
    predicted_atlas = _read_json(predicted_geometry_atlas_path)
    fold_signal = _read_json(fold_level_signal_path)
    rows = [
        row
        for row in predicted_atlas.get("results", [])
        if isinstance(row, dict) and _predicted_row_ok(row) and _top1_fingerprint(row)
    ]
    atlas_rows = [
        row
        for row in rows
        if row.get("split_assignment") == "in_distribution" and row.get("true_fingerprint_id")
    ]
    heldout_rows = [row for row in rows if row.get("split_assignment") == "heldout"]
    if not atlas_rows or not heldout_rows:
        return {
            "artifact_id": "v3_predicted_atlas_geometry_novelty_variants_current702_20260601",
            "schema_version": SCHEMA_VERSION,
            "created_utc": _utc_now_iso(),
            "status": "insufficient_rows",
            "counts": {"atlas": len(atlas_rows), "heldout": len(heldout_rows)},
        }

    atlas_vectors = [_feature_vector(_top1_fingerprint(row) or {}) for row in atlas_rows]
    center, scale = _robust_center_scale(atlas_vectors)
    class_centers: dict[str, list[float]] = {}
    for fp in sorted({str(row.get("true_fingerprint_id")) for row in atlas_rows}):
        members = [
            _feature_vector(_top1_fingerprint(row) or {})
            for row in atlas_rows
            if str(row.get("true_fingerprint_id")) == fp
        ]
        class_centers[fp] = [
            sum(vec[idx] for vec in members) / len(members)
            for idx in range(len(GEOMETRY_VARIANT_FEATURES))
        ]
    atlas_feature_values = {
        name: [float((_top1_fingerprint(row) or {}).get(name) or 0.0) for row in atlas_rows]
        for name in GEOMETRY_VARIANT_FEATURES
    }
    atlas_score_x_role = [
        float((_top1_fingerprint(row) or {}).get("score") or 0.0)
        * float((_top1_fingerprint(row) or {}).get("role_match_fraction") or 0.0)
        for row in atlas_rows
    ]
    confounded_ids = set(
        fold_signal.get("confounded_entry_ids", {}).get(
            "predicted_geometry_overlap_current_gate", []
        )
    )

    scored_rows: list[dict[str, Any]] = []
    for row in sorted(heldout_rows, key=lambda item: _entry_id_sort_key(str(item.get("entry_id")))):
        top = _top1_fingerprint(row) or {}
        vector = _feature_vector(top)
        global_distance = _robust_distance(vector, center, scale)
        nearest_class_distance = min(
            _robust_distance(vector, class_center, scale)
            for class_center in class_centers.values()
        )
        score = float(top.get("score") or 0.0)
        role = float(top.get("role_match_fraction") or 0.0)
        score_x_role = score * role
        variant_scores = {
            "top1_score_raw": score,
            "top1_score_atlas_percentile": _percentile_rank(
                score, atlas_feature_values["score"]
            ),
            "role_match_fraction_raw": role,
            "role_match_fraction_atlas_percentile": _percentile_rank(
                role, atlas_feature_values["role_match_fraction"]
            ),
            "top1_score_x_role_raw": score_x_role,
            "top1_score_x_role_atlas_percentile": _percentile_rank(
                score_x_role, atlas_score_x_role
            ),
            "cofactor_context_score_raw": float(top.get("cofactor_context_score") or 0.0),
            "cofactor_context_score_atlas_percentile": _percentile_rank(
                float(top.get("cofactor_context_score") or 0.0),
                atlas_feature_values["cofactor_context_score"],
            ),
            "negative_robust_distance_to_atlas_median": -global_distance,
            "negative_nearest_class_centroid_robust_distance": -nearest_class_distance,
        }
        scored_rows.append(
            {
                "entry_id": row.get("entry_id"),
                "split_assignment": row.get("split_assignment"),
                "true_fingerprint_id": row.get("true_fingerprint_id"),
                "is_inscope": bool(row.get("true_fingerprint_id")),
                "is_oos": not bool(row.get("true_fingerprint_id")),
                "is_confounded_predicted_geometry_oos": row.get("entry_id") in confounded_ids,
                "top1_fingerprint_id": top.get("fingerprint_id"),
                "variant_scores": {
                    key: round(value, 6) for key, value in variant_scores.items()
                },
            }
        )

    signal_names = list(scored_rows[0]["variant_scores"]) if scored_rows else []
    signals = {
        name: _signal_metrics(scored_rows, name)
        for name in signal_names
    }
    best_name, best_signal = max(
        signals.items(),
        key=lambda item: item[1]["auc_in_gt_oos_all"] or 0.0,
    )
    return {
        "artifact_id": "v3_predicted_atlas_geometry_novelty_variants_current702_20260601",
        "schema_version": SCHEMA_VERSION,
        "created_utc": _utc_now_iso(),
        "status": "computed_predicted_atlas_geometry_variants",
        "scope": (
            "Bounded predicted-geometry atlas novelty rerun using the newly "
            "available in-distribution predicted atlas rows. All atlas statistics "
            "are computed from in-distribution rows only; heldout rows are final "
            "evaluation diagnostics."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "heldout_threshold_tuning_for_deployment": False,
            "atlas_statistics_only_for_normalization": True,
        },
        "counts": {
            "atlas_rows": len(atlas_rows),
            "heldout_rows": len(scored_rows),
            "inscope": sum(1 for row in scored_rows if row["is_inscope"]),
            "oos": sum(1 for row in scored_rows if row["is_oos"]),
            "confounded_predicted_geometry_oos": sum(
                1 for row in scored_rows if row["is_confounded_predicted_geometry_oos"]
            ),
            "atlas_true_fingerprint_counts": dict(
                sorted(Counter(str(row.get("true_fingerprint_id")) for row in atlas_rows).items())
            ),
        },
        "signals": signals,
        "best_signal": {
            "name": best_name,
            "auc_in_gt_oos_all": best_signal["auc_in_gt_oos_all"],
            "auc_in_gt_confounded_oos": best_signal["auc_in_gt_confounded_oos"],
            "best_at_90pct_inscope_retention": best_signal[
                "best_at_90pct_inscope_retention"
            ],
            "best_at_85pct_inscope_retention": best_signal[
                "best_at_85pct_inscope_retention"
            ],
        },
        "row_scores": scored_rows,
        "interpretation": {
            "headline": (
                f"Best predicted-atlas geometry variant is {best_name} with "
                f"AUC {best_signal['auc_in_gt_oos_all']}."
            ),
            "operating_point_caveat": (
                "Post-hoc retention rows are diagnostics only; no deployment "
                "threshold is selected or written to production."
            ),
        },
        "source_artifacts": {
            "predicted_geometry_atlas": {
                "path": str(predicted_geometry_atlas_path),
                "sha256": _sha256(predicted_geometry_atlas_path),
            },
            "fold_level_signal": {
                "path": str(fold_level_signal_path),
                "sha256": _sha256(fold_level_signal_path),
            },
        },
    }


def _render_predicted_atlas_geometry_novelty_variants_report(audit: dict[str, Any]) -> str:
    counts = audit["counts"]
    best = audit["best_signal"]
    lines = [
        "# Predicted-Atlas Geometry Novelty Variants - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Counts",
        "",
        f"- Atlas rows: {counts['atlas_rows']}",
        f"- Heldout rows: {counts['heldout_rows']}",
        f"- In-scope: {counts['inscope']}",
        f"- OOS: {counts['oos']}",
        f"- Cofactor-confounded OOS: {counts['confounded_predicted_geometry_oos']}",
        "",
        "## Best Signal",
        "",
        f"- {best['name']}: AUC all OOS {best['auc_in_gt_oos_all']}; confounded AUC {best['auc_in_gt_confounded_oos']}",
        f"- Best >=90% retention diagnostic: {best['best_at_90pct_inscope_retention']}",
        f"- Best >=85% retention diagnostic: {best['best_at_85pct_inscope_retention']}",
        "",
        "## Signals",
        "",
        "| Signal | all OOS AUC | confounded AUC | agnostic AUC |",
        "| --- | ---: | ---: | ---: |",
    ]
    for name, sig in audit["signals"].items():
        lines.append(
            f"| {name} | {sig['auc_in_gt_oos_all']} | "
            f"{sig['auc_in_gt_confounded_oos']} | {sig['auc_in_gt_agnostic_oos']} |"
        )
    lines += [
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['operating_point_caveat']}",
    ]
    return "\n".join(lines) + "\n"


def write_predicted_atlas_geometry_novelty_variants(
    *,
    predicted_geometry_atlas_path: Path,
    fold_level_signal_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_predicted_atlas_geometry_novelty_variants(
        predicted_geometry_atlas_path=predicted_geometry_atlas_path,
        fold_level_signal_path=fold_level_signal_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_predicted_atlas_geometry_novelty_variants_report(audit),
            encoding="utf-8",
        )
    return audit


def build_predicted_atlas_geometry_novelty_operating_grid(
    *,
    predicted_atlas_variants_path: Path,
    retention_targets: tuple[float, ...] = (0.95, 0.90, 0.85, 0.80),
) -> dict[str, Any]:
    variants = _read_json(predicted_atlas_variants_path)
    rows = [
        row
        for row in variants.get("row_scores", [])
        if isinstance(row, dict) and row.get("variant_scores")
    ]
    if not rows:
        return {
            "artifact_id": "v3_predicted_atlas_geometry_novelty_operating_grid_current702_20260601",
            "schema_version": SCHEMA_VERSION,
            "created_utc": _utc_now_iso(),
            "status": "insufficient_rows",
            "counts": {"row_scores": 0},
        }

    signal_names = sorted(rows[0]["variant_scores"])
    grid: list[dict[str, Any]] = []
    best_by_target: dict[str, dict[str, Any]] = {}
    for signal_name in signal_names:
        fn = lambda row, name=signal_name: float(row["variant_scores"][name])
        for target in retention_targets:
            operating_point = _best_threshold_at_retention(
                rows,
                fn,
                min_retain=target,
            )
            item = {
                "signal": signal_name,
                "target_min_inscope_retention": target,
                "operating_point": operating_point,
            }
            grid.append(item)
            if operating_point is None:
                continue
            key = f"{target:.2f}"
            candidate = {
                "signal": signal_name,
                **operating_point,
            }
            current = best_by_target.get(key)
            if current is None or (
                candidate["oos_abstain_recall"],
                candidate["confounded_abstain_recall"] or 0.0,
            ) > (
                current["oos_abstain_recall"],
                current["confounded_abstain_recall"] or 0.0,
            ):
                best_by_target[key] = candidate

    best_signal_name = variants.get("best_signal", {}).get("name") or signal_names[0]
    best_signal_90 = next(
        (
            item["operating_point"]
            for item in grid
            if item["signal"] == best_signal_name
            and item["target_min_inscope_retention"] == 0.90
        ),
        None,
    )
    best_signal_85 = next(
        (
            item["operating_point"]
            for item in grid
            if item["signal"] == best_signal_name
            and item["target_min_inscope_retention"] == 0.85
        ),
        None,
    )

    def below_best_threshold(row: dict[str, Any], point: dict[str, Any] | None) -> bool:
        if point is None:
            return False
        score = row["variant_scores"].get(best_signal_name)
        return score is not None and float(score) < float(point["threshold"])

    confounded_rows = [
        {
            "entry_id": row.get("entry_id"),
            "score": row["variant_scores"].get(best_signal_name),
            "abstained_at_best_signal_90pct": below_best_threshold(
                row,
                best_signal_90,
            ),
            "abstained_at_best_signal_85pct": below_best_threshold(
                row,
                best_signal_85,
            ),
        }
        for row in rows
        if row.get("is_confounded_predicted_geometry_oos")
    ]
    return {
        "artifact_id": "v3_predicted_atlas_geometry_novelty_operating_grid_current702_20260601",
        "schema_version": SCHEMA_VERSION,
        "created_utc": _utc_now_iso(),
        "status": "predicted_atlas_geometry_novelty_operating_grid_ready_review_only",
        "scope": (
            "Review-only operating-grid readout over the existing predicted-atlas "
            "geometry novelty variants. It computes post-hoc diagnostic "
            "retention/OOS-abstention points for each frozen geometry signal and "
            "does not select or write a deployment threshold."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "heldout_threshold_tuning_for_deployment": False,
            "model_fit_or_refit": False,
            "uses_existing_variant_artifact_only": True,
        },
        "counts": {
            "row_scores": len(rows),
            "inscope": sum(1 for row in rows if row.get("is_inscope")),
            "oos": sum(1 for row in rows if row.get("is_oos")),
            "confounded_oos": sum(
                1 for row in rows if row.get("is_confounded_predicted_geometry_oos")
            ),
            "signals": len(signal_names),
            "retention_targets": len(retention_targets),
            "grid_rows": len(grid),
        },
        "best_signal_from_variant_artifact": {
            "name": best_signal_name,
            "best_at_90pct_inscope_retention": best_signal_90,
            "best_at_85pct_inscope_retention": best_signal_85,
            "confounded_rows": sorted(
                confounded_rows,
                key=lambda row: _entry_id_sort_key(str(row.get("entry_id"))),
            ),
        },
        "best_by_retention_target": dict(sorted(best_by_target.items())),
        "operating_grid": grid,
        "interpretation": {
            "headline": (
                "The best predicted-atlas geometry signal remains useful as a "
                "rank diagnostic, but its 90% retention operating point is still "
                "too weak for a standalone deployment gate."
            ),
            "next_action": (
                "Treat this as input evidence for fold-augmented or mechanism-feature "
                "signals; do not promote a geometry-only novelty threshold."
            ),
        },
        "source_artifacts": {
            "predicted_atlas_variants": {
                "path": str(predicted_atlas_variants_path),
                "sha256": _sha256(predicted_atlas_variants_path),
            },
        },
    }


def _render_predicted_atlas_geometry_novelty_operating_grid_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    best = audit["best_signal_from_variant_artifact"]
    lines = [
        "# Predicted-Atlas Geometry Novelty Operating Grid - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Counts",
        "",
        f"- Row scores: {counts['row_scores']}",
        f"- In-scope: {counts['inscope']}",
        f"- OOS: {counts['oos']}",
        f"- Cofactor-confounded OOS: {counts['confounded_oos']}",
        f"- Signals: {counts['signals']}",
        f"- Grid rows: {counts['grid_rows']}",
        "",
        "## Best Signal From Variant Artifact",
        "",
        f"- Signal: {best['name']}",
        f"- >=90% retention diagnostic: {best['best_at_90pct_inscope_retention']}",
        f"- >=85% retention diagnostic: {best['best_at_85pct_inscope_retention']}",
        "",
        "## Best By Retention Target",
        "",
        "| target | signal | in-scope retain | OOS abstain | confounded abstain | threshold |",
        "| ---: | --- | ---: | ---: | ---: | ---: |",
    ]
    for target, item in audit["best_by_retention_target"].items():
        lines.append(
            f"| {target} | `{item['signal']}` | {item['inscope_retain_recall']} | "
            f"{item['oos_abstain_recall']} | {item['confounded_abstain_recall']} | "
            f"{item['threshold']} |"
        )
    lines += [
        "",
        "## Confounded Rows",
        "",
        "| row | score | abstained at 90% | abstained at 85% |",
        "| --- | ---: | --- | --- |",
    ]
    for row in best["confounded_rows"]:
        lines.append(
            f"| {row['entry_id']} | {row['score']} | "
            f"{row['abstained_at_best_signal_90pct']} | "
            f"{row['abstained_at_best_signal_85pct']} |"
        )
    lines += [
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_predicted_atlas_geometry_novelty_operating_grid(
    *,
    predicted_atlas_variants_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_predicted_atlas_geometry_novelty_operating_grid(
        predicted_atlas_variants_path=predicted_atlas_variants_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_predicted_atlas_geometry_novelty_operating_grid_report(audit),
            encoding="utf-8",
        )
    return audit


def build_predicted_structure_fold_augmented_novelty_operating_grid(
    *,
    fold_augmented_variants_path: Path,
    retention_targets: tuple[float, ...] = (0.95, 0.90, 0.85, 0.80),
) -> dict[str, Any]:
    variants = _read_json(fold_augmented_variants_path)
    rows = [
        row
        for row in variants.get("row_scores", [])
        if isinstance(row, dict) and row.get("variant_scores")
    ]
    if not rows:
        return {
            "artifact_id": PREDICTED_STRUCTURE_FOLD_AUGMENTED_NOVELTY_OPERATING_GRID_ID,
            "schema_version": SCHEMA_VERSION,
            "created_utc": _utc_now_iso(),
            "status": "insufficient_rows",
            "counts": {"row_scores": 0},
        }

    signal_names = sorted(rows[0]["variant_scores"])
    grid: list[dict[str, Any]] = []
    best_by_target: dict[str, dict[str, Any]] = {}
    for signal_name in signal_names:
        fn = lambda row, name=signal_name: float(row["variant_scores"][name])
        for target in retention_targets:
            operating_point = _best_threshold_at_retention(
                rows,
                fn,
                min_retain=target,
            )
            item = {
                "signal": signal_name,
                "target_min_inscope_retention": target,
                "operating_point": operating_point,
            }
            grid.append(item)
            if operating_point is None:
                continue
            key = f"{target:.2f}"
            candidate = {
                "signal": signal_name,
                **operating_point,
            }
            current = best_by_target.get(key)
            if current is None or (
                candidate["oos_abstain_recall"],
                candidate["confounded_abstain_recall"] or 0.0,
            ) > (
                current["oos_abstain_recall"],
                current["confounded_abstain_recall"] or 0.0,
            ):
                best_by_target[key] = candidate

    best_signal_name = variants.get("best_signal", {}).get("name") or signal_names[0]
    best_signal_90 = next(
        (
            item["operating_point"]
            for item in grid
            if item["signal"] == best_signal_name
            and item["target_min_inscope_retention"] == 0.90
        ),
        None,
    )
    best_signal_85 = next(
        (
            item["operating_point"]
            for item in grid
            if item["signal"] == best_signal_name
            and item["target_min_inscope_retention"] == 0.85
        ),
        None,
    )

    def below_best_threshold(row: dict[str, Any], point: dict[str, Any] | None) -> bool:
        if point is None:
            return False
        score = row["variant_scores"].get(best_signal_name)
        return score is not None and float(score) < float(point["threshold"])

    confounded_rows = [
        {
            "entry_id": row.get("entry_id"),
            "score": row["variant_scores"].get(best_signal_name),
            "nearest_atlas_tm_score": row["variant_scores"].get(
                "nearest_atlas_tm_score"
            ),
            "abstained_at_best_signal_90pct": below_best_threshold(
                row,
                best_signal_90,
            ),
            "abstained_at_best_signal_85pct": below_best_threshold(
                row,
                best_signal_85,
            ),
        }
        for row in rows
        if row.get("is_confounded_predicted_geometry_oos")
    ]
    return {
        "artifact_id": PREDICTED_STRUCTURE_FOLD_AUGMENTED_NOVELTY_OPERATING_GRID_ID,
        "schema_version": SCHEMA_VERSION,
        "created_utc": _utc_now_iso(),
        "status": (
            "predicted_structure_fold_augmented_novelty_operating_grid_ready_review_only"
        ),
        "scope": (
            "Review-only operating-grid readout over the frozen geometry-plus-"
            "predicted-fold novelty variants. It recomputes post-hoc diagnostic "
            "retention/OOS-abstention points from existing row scores only and "
            "does not select or write a deployment threshold."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "heldout_threshold_tuning_for_deployment": False,
            "model_fit_or_refit": False,
            "foldseek_or_tmsearch_recomputed": False,
            "uses_existing_variant_artifact_only": True,
        },
        "counts": {
            "row_scores": len(rows),
            "inscope": sum(1 for row in rows if row.get("is_inscope")),
            "oos": sum(1 for row in rows if row.get("is_oos")),
            "confounded_oos": sum(
                1 for row in rows if row.get("is_confounded_predicted_geometry_oos")
            ),
            "signals": len(signal_names),
            "retention_targets": len(retention_targets),
            "grid_rows": len(grid),
        },
        "best_signal_from_variant_artifact": {
            "name": best_signal_name,
            "best_at_90pct_inscope_retention": best_signal_90,
            "best_at_85pct_inscope_retention": best_signal_85,
            "confounded_rows": sorted(
                confounded_rows,
                key=lambda row: _entry_id_sort_key(str(row.get("entry_id"))),
            ),
        },
        "best_by_retention_target": dict(sorted(best_by_target.items())),
        "operating_grid": grid,
        "interpretation": {
            "headline": (
                "The geometry-plus-predicted-fold signal materially improves the "
                "high-retention OOS-abstention diagnostic over geometry-only "
                "predicted-atlas variants, but remains review-only."
            ),
            "next_action": (
                "Use this as bounded evidence for train/cal OOS-surface and "
                "source-check prioritization; do not promote a deployment threshold "
                "from this heldout readout."
            ),
        },
        "source_artifacts": {
            "fold_augmented_variants": {
                "path": str(fold_augmented_variants_path),
                "sha256": _sha256(fold_augmented_variants_path),
            },
        },
    }


def _render_predicted_structure_fold_augmented_novelty_operating_grid_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    best = audit["best_signal_from_variant_artifact"]
    lines = [
        "# Predicted-Structure Fold-Augmented Novelty Operating Grid - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Counts",
        "",
        f"- Row scores: {counts['row_scores']}",
        f"- In-scope: {counts['inscope']}",
        f"- OOS: {counts['oos']}",
        f"- Cofactor-confounded OOS: {counts['confounded_oos']}",
        f"- Signals: {counts['signals']}",
        f"- Grid rows: {counts['grid_rows']}",
        "",
        "## Best Signal From Variant Artifact",
        "",
        f"- Signal: {best['name']}",
        f"- >=90% retention diagnostic: {best['best_at_90pct_inscope_retention']}",
        f"- >=85% retention diagnostic: {best['best_at_85pct_inscope_retention']}",
        "",
        "## Best By Retention Target",
        "",
        "| target | signal | in-scope retain | OOS abstain | confounded abstain | threshold |",
        "| ---: | --- | ---: | ---: | ---: | ---: |",
    ]
    for target, item in audit["best_by_retention_target"].items():
        lines.append(
            f"| {target} | `{item['signal']}` | {item['inscope_retain_recall']} | "
            f"{item['oos_abstain_recall']} | {item['confounded_abstain_recall']} | "
            f"{item['threshold']} |"
        )
    lines += [
        "",
        "## Confounded Rows",
        "",
        "| row | best-signal score | nearest-atlas TM | abstained at 90% | abstained at 85% |",
        "| --- | ---: | ---: | --- | --- |",
    ]
    for row in best["confounded_rows"]:
        lines.append(
            f"| {row['entry_id']} | {row['score']} | {row['nearest_atlas_tm_score']} | "
            f"{row['abstained_at_best_signal_90pct']} | "
            f"{row['abstained_at_best_signal_85pct']} |"
        )
    lines += [
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_predicted_structure_fold_augmented_novelty_operating_grid(
    *,
    fold_augmented_variants_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_predicted_structure_fold_augmented_novelty_operating_grid(
        fold_augmented_variants_path=fold_augmented_variants_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_predicted_structure_fold_augmented_novelty_operating_grid_report(audit),
            encoding="utf-8",
        )
    return audit


def build_predicted_atlas_vs_fold_novelty_operating_grid_delta(
    *,
    geometry_operating_grid_path: Path,
    fold_operating_grid_path: Path,
) -> dict[str, Any]:
    geometry = _read_json(geometry_operating_grid_path)
    fold = _read_json(fold_operating_grid_path)
    geometry_best = geometry.get("best_by_retention_target", {})
    fold_best = fold.get("best_by_retention_target", {})
    targets = sorted(set(geometry_best).intersection(fold_best), key=float)
    delta_rows = []
    for target in targets:
        geometry_row = geometry_best[target]
        fold_row = fold_best[target]
        oos_delta = round(
            float(fold_row["oos_abstain_recall"])
            - float(geometry_row["oos_abstain_recall"]),
            4,
        )
        confounded_delta = round(
            float(fold_row["confounded_abstain_recall"])
            - float(geometry_row["confounded_abstain_recall"]),
            4,
        )
        delta_rows.append(
            {
                "target_min_inscope_retention": float(target),
                "geometry_signal": geometry_row.get("signal"),
                "fold_augmented_signal": fold_row.get("signal"),
                "geometry_inscope_retain_recall": geometry_row.get(
                    "inscope_retain_recall"
                ),
                "fold_inscope_retain_recall": fold_row.get("inscope_retain_recall"),
                "geometry_oos_abstain_recall": geometry_row.get(
                    "oos_abstain_recall"
                ),
                "fold_oos_abstain_recall": fold_row.get("oos_abstain_recall"),
                "oos_abstain_recall_delta": oos_delta,
                "geometry_confounded_abstain_recall": geometry_row.get(
                    "confounded_abstain_recall"
                ),
                "fold_confounded_abstain_recall": fold_row.get(
                    "confounded_abstain_recall"
                ),
                "confounded_abstain_recall_delta": confounded_delta,
                "geometry_threshold": geometry_row.get("threshold"),
                "fold_augmented_threshold": fold_row.get("threshold"),
            }
        )
    target_90 = next(
        (
            row
            for row in delta_rows
            if row["target_min_inscope_retention"] == 0.9
        ),
        None,
    )
    critical_counts = {
        "geometry_operating_grid_not_ready": (
            0
            if geometry.get("status")
            == "predicted_atlas_geometry_novelty_operating_grid_ready_review_only"
            else 1
        ),
        "fold_operating_grid_not_ready": (
            0
            if fold.get("status")
            == "predicted_structure_fold_augmented_novelty_operating_grid_ready_review_only"
            else 1
        ),
        "missing_shared_retention_targets": 0 if targets else 1,
    }
    return {
        "artifact_id": PREDICTED_ATLAS_VS_FOLD_NOVELTY_DELTA_AUDIT_ID,
        "schema_version": f"{SCHEMA_VERSION}.predicted_atlas_vs_fold_novelty_delta",
        "created_utc": _utc_now_iso(),
        "status": (
            "predicted_atlas_vs_fold_novelty_delta_ready_review_only"
            if all(value == 0 for value in critical_counts.values())
            else "predicted_atlas_vs_fold_novelty_delta_blocked"
        ),
        "scope": (
            "Review-only delta audit comparing frozen predicted-atlas geometry "
            "novelty operating-grid rows against frozen geometry-plus-predicted-"
            "fold operating-grid rows. It reads existing artifacts only and "
            "does not select a deployment threshold."
        ),
        "guardrails": {
            "review_only": True,
            "existing_artifacts_only": True,
            "heldout_threshold_selected_or_promoted": False,
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "model_weights_fit_or_refit": False,
            "feature_contract_mutated": False,
        },
        "counts": {
            "shared_retention_targets": len(targets),
            "targets_with_oos_abstain_lift": sum(
                1 for row in delta_rows if row["oos_abstain_recall_delta"] > 0
            ),
            "targets_with_confounded_abstain_lift": sum(
                1
                for row in delta_rows
                if row["confounded_abstain_recall_delta"] > 0
            ),
            "critical_counts": critical_counts,
            "critical_violation_total": sum(critical_counts.values()),
        },
        "target_90_summary": target_90,
        "delta_rows": delta_rows,
        "interpretation": {
            "headline": (
                "Fold-augmented novelty materially improves the frozen "
                "predicted-atlas operating-grid diagnostic at matched retention."
            ),
            "target_90_delta": target_90,
            "next_action": (
                "Use the fold-augmented train/cal threshold contract for any "
                "thresholded claim; keep this heldout operating-grid comparison "
                "review-only."
            ),
        },
        "source_artifacts": {
            "geometry_operating_grid": _source_path_record(geometry_operating_grid_path),
            "fold_operating_grid": _source_path_record(fold_operating_grid_path),
        },
    }


def _render_predicted_atlas_vs_fold_novelty_operating_grid_delta_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    lines = [
        "# Predicted-Atlas Versus Fold Novelty Operating-Grid Delta - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Shared retention targets: {counts['shared_retention_targets']}",
        f"- Targets with OOS abstain lift: {counts['targets_with_oos_abstain_lift']}",
        "- Targets with confounded abstain lift: "
        f"{counts['targets_with_confounded_abstain_lift']}",
        f"- Critical violations: {counts['critical_violation_total']}",
        "",
        "## Delta Rows",
        "",
        "| target | geometry OOS | fold OOS | OOS delta | geometry confounded | fold confounded | confounded delta |",
        "| ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for row in audit["delta_rows"]:
        lines.append(
            f"| {row['target_min_inscope_retention']:.2f} | "
            f"{row['geometry_oos_abstain_recall']} | "
            f"{row['fold_oos_abstain_recall']} | "
            f"{row['oos_abstain_recall_delta']} | "
            f"{row['geometry_confounded_abstain_recall']} | "
            f"{row['fold_confounded_abstain_recall']} | "
            f"{row['confounded_abstain_recall_delta']} |"
        )
    lines += [
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_predicted_atlas_vs_fold_novelty_operating_grid_delta(
    *,
    geometry_operating_grid_path: Path,
    fold_operating_grid_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_predicted_atlas_vs_fold_novelty_operating_grid_delta(
        geometry_operating_grid_path=geometry_operating_grid_path,
        fold_operating_grid_path=fold_operating_grid_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_predicted_atlas_vs_fold_novelty_operating_grid_delta_report(
                audit
            ),
            encoding="utf-8",
        )
    return audit


REQUIRED_SELECTED_COFACTOR_RECORD_KEYS = (
    "entry_id",
    "class",
    "cofactor_class",
    "selected_score",
    "selected_source",
    "selected_source_status",
    "split_assignment",
    "threshold_or_bin",
    "source_artifact",
    "source_channel_artifact",
    "provenance_hashes",
)


def build_selected_organic_cofactor_sidecar_schema_audit(
    *,
    selected_organic_cofactor_sidecar_path: Path,
    label_manifest_path: Path,
) -> dict[str, Any]:
    sidecar = _read_json(selected_organic_cofactor_sidecar_path)
    manifest = _read_json(label_manifest_path)
    records = [
        record
        for record in sidecar.get("row_class_records", [])
        if isinstance(record, dict)
    ]
    manifest_rows = [
        row for row in manifest.get("rows", []) if isinstance(row, dict)
    ]
    split_by_entry = {
        str(row.get("entry_id")): row.get("split_assignment")
        for row in manifest_rows
        if row.get("entry_id")
    }
    expected_entries = set(split_by_entry)
    expected_pairs = {
        (entry_id, cls)
        for entry_id in expected_entries
        for cls in COFACTOR_CLASSES
    }
    seen_pairs: set[tuple[str, str]] = set()
    duplicate_pairs: list[dict[str, Any]] = []
    missing_key_rows: list[dict[str, Any]] = []
    score_range_violations: list[dict[str, Any]] = []
    class_mismatches: list[dict[str, Any]] = []
    split_mismatches: list[dict[str, Any]] = []
    threshold_policy_violations: list[dict[str, Any]] = []
    fallback_source_rows: list[dict[str, Any]] = []
    missing_source_paths: list[dict[str, Any]] = []
    provenance_missing_rows: list[dict[str, Any]] = []

    for record in records:
        entry_id = str(record.get("entry_id") or "")
        cls = str(record.get("class") or "")
        pair = (entry_id, cls)
        if pair in seen_pairs:
            duplicate_pairs.append({"entry_id": entry_id, "class": cls})
        seen_pairs.add(pair)
        missing_keys = [
            key for key in REQUIRED_SELECTED_COFACTOR_RECORD_KEYS if key not in record
        ]
        if missing_keys:
            missing_key_rows.append(
                {"entry_id": entry_id, "class": cls, "missing_keys": missing_keys}
            )
        if cls != record.get("cofactor_class"):
            class_mismatches.append(
                {
                    "entry_id": entry_id,
                    "class": cls,
                    "cofactor_class": record.get("cofactor_class"),
                }
            )
        score = record.get("selected_score")
        if not isinstance(score, (int, float)) or not 0.0 <= float(score) <= 1.0:
            score_range_violations.append(
                {"entry_id": entry_id, "class": cls, "selected_score": score}
            )
        expected_split = split_by_entry.get(entry_id)
        if expected_split is None or record.get("split_assignment") != expected_split:
            split_mismatches.append(
                {
                    "entry_id": entry_id,
                    "class": cls,
                    "record_split": record.get("split_assignment"),
                    "manifest_split": expected_split,
                }
            )
        threshold = record.get("threshold_or_bin") or {}
        if (
            threshold.get("fixed_threshold") != 0.5
            or threshold.get("threshold_policy") != "fixed_0_5_not_tuned_on_heldout"
        ):
            threshold_policy_violations.append(
                {"entry_id": entry_id, "class": cls, "threshold_or_bin": threshold}
            )
        source = str(record.get("selected_source") or "")
        status = str(record.get("selected_source_status") or "")
        if "fallback" in source.lower() or "fallback" in status.lower():
            fallback_source_rows.append(
                {"entry_id": entry_id, "class": cls, "selected_source": source}
            )
        for path_key in ("source_artifact", "source_channel_artifact", "source_summary_artifact"):
            path_value = record.get(path_key)
            if path_value and not Path(str(path_value)).exists():
                missing_source_paths.append(
                    {
                        "entry_id": entry_id,
                        "class": cls,
                        "path_key": path_key,
                        "path": path_value,
                    }
                )
        provenance = record.get("provenance_hashes")
        if not isinstance(provenance, dict) or not provenance:
            provenance_missing_rows.append({"entry_id": entry_id, "class": cls})

    missing_pairs = sorted(
        expected_pairs - seen_pairs,
        key=lambda pair: (_entry_id_sort_key(pair[0]), pair[1]),
    )
    extra_pairs = sorted(
        seen_pairs - expected_pairs,
        key=lambda pair: (_entry_id_sort_key(pair[0]), pair[1]),
    )
    critical_counts = {
        "missing_record_key_rows": len(missing_key_rows),
        "duplicate_entry_class_pairs": len(duplicate_pairs),
        "missing_entry_class_pairs": len(missing_pairs),
        "extra_entry_class_pairs": len(extra_pairs),
        "score_range_violations": len(score_range_violations),
        "class_mismatches": len(class_mismatches),
        "split_mismatches": len(split_mismatches),
        "threshold_policy_violations": len(threshold_policy_violations),
        "fallback_source_rows": len(fallback_source_rows),
        "missing_source_paths": len(missing_source_paths),
        "provenance_missing_rows": len(provenance_missing_rows),
    }
    passed = all(count == 0 for count in critical_counts.values())
    return {
        "artifact_id": "v3_selected_organic_cofactor_sidecar_schema_audit_current702_20260601",
        "schema_version": SCHEMA_VERSION,
        "created_utc": _utc_now_iso(),
        "status": (
            "schema_passed_strict_current702" if passed else "schema_failed_strict_current702"
        ),
        "scope": (
            "Strict schema and lineage audit for the selected organic cofactor "
            "sidecar consumed by the D11 abstention gate and mechanism-feature "
            "embedding scaffold."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "heldout_threshold_tuning_for_deployment": False,
            "sidecar_values_changed": False,
        },
        "schema_contract": {
            "required_record_keys": list(REQUIRED_SELECTED_COFACTOR_RECORD_KEYS),
            "required_classes": list(COFACTOR_CLASSES),
            "entry_class_grid": "every current702 entry must have flavin, heme, and plp records",
            "score_range": "[0.0, 1.0]",
            "threshold_policy": "fixed_0_5_not_tuned_on_heldout",
            "fallback_sources_allowed": False,
        },
        "counts": {
            "manifest_rows": len(manifest_rows),
            "expected_entries": len(expected_entries),
            "row_class_records": len(records),
            "expected_row_class_records": len(expected_pairs),
            "class_counts": dict(sorted(Counter(str(r.get("class")) for r in records).items())),
            "split_counts": dict(
                sorted(Counter(str(r.get("split_assignment")) for r in records).items())
            ),
            "selected_source_counts": dict(
                sorted(Counter(str(r.get("selected_source")) for r in records).items())
            ),
            "critical_counts": critical_counts,
        },
        "violations": {
            "missing_record_key_rows": missing_key_rows[:50],
            "duplicate_entry_class_pairs": duplicate_pairs[:50],
            "missing_entry_class_pairs": [
                {"entry_id": entry_id, "class": cls} for entry_id, cls in missing_pairs[:50]
            ],
            "extra_entry_class_pairs": [
                {"entry_id": entry_id, "class": cls} for entry_id, cls in extra_pairs[:50]
            ],
            "score_range_violations": score_range_violations[:50],
            "class_mismatches": class_mismatches[:50],
            "split_mismatches": split_mismatches[:50],
            "threshold_policy_violations": threshold_policy_violations[:50],
            "fallback_source_rows": fallback_source_rows[:50],
            "missing_source_paths": missing_source_paths[:50],
            "provenance_missing_rows": provenance_missing_rows[:50],
        },
        "interpretation": {
            "result": (
                "The selected organic cofactor sidecar satisfies the strict "
                "current702 row-class grid and lineage contract."
                if passed
                else "One or more strict sidecar schema checks failed; treat the sidecar as blocked until repaired."
            ),
            "embedding_gap_relevance": (
                "This closes the organic flavin/heme/PLP sidecar schema risk for "
                "the mechanism-feature embedding scaffold, while metal, cobalamin, "
                "radical, and Fe-S row-level loci remain separate feature gaps."
            ),
        },
        "source_artifacts": {
            "selected_organic_cofactor_sidecar": {
                "path": str(selected_organic_cofactor_sidecar_path),
                "sha256": _sha256(selected_organic_cofactor_sidecar_path),
            },
            "label_manifest": {
                "path": str(label_manifest_path),
                "sha256": _sha256(label_manifest_path),
            },
        },
    }


def _render_selected_organic_cofactor_sidecar_schema_audit_report(audit: dict[str, Any]) -> str:
    counts = audit["counts"]
    lines = [
        "# Selected Organic Cofactor Sidecar Schema Audit - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Row-class records: {counts['row_class_records']} / {counts['expected_row_class_records']}",
        f"- Critical violation counts: {counts['critical_counts']}",
        "",
        "## Contract",
        "",
        f"- Required classes: {', '.join(audit['schema_contract']['required_classes'])}",
        f"- Threshold policy: {audit['schema_contract']['threshold_policy']}",
        f"- Fallback sources allowed: {audit['schema_contract']['fallback_sources_allowed']}",
        "",
        "## Selected Sources",
        "",
    ]
    for source, count in counts["selected_source_counts"].items():
        lines.append(f"- {source}: {count}")
    lines += [
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['result']}",
        f"- {audit['interpretation']['embedding_gap_relevance']}",
    ]
    return "\n".join(lines) + "\n"


def write_selected_organic_cofactor_sidecar_schema_audit(
    *,
    selected_organic_cofactor_sidecar_path: Path,
    label_manifest_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_selected_organic_cofactor_sidecar_schema_audit(
        selected_organic_cofactor_sidecar_path=selected_organic_cofactor_sidecar_path,
        label_manifest_path=label_manifest_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_selected_organic_cofactor_sidecar_schema_audit_report(audit),
            encoding="utf-8",
        )
    return audit


def _cofactor_scores_for_entry(sidecar: dict[str, Any], entry_id: str) -> dict[str, float]:
    scores: dict[str, float] = {}
    for record in sidecar.get("row_class_records", []):
        if record.get("entry_id") == entry_id and record.get("class"):
            scores[str(record["class"])] = float(record.get("selected_score") or 0.0)
    return scores


def build_family_panel_evidence_packet(
    *,
    family_targets_path: Path,
    predicted_geometry_atlas_path: Path,
    fold_level_signal_path: Path,
    selected_organic_cofactor_sidecar_path: Path,
    predicted_atlas_variants_path: Path,
    predicted_structure_fold_channel_path: Path | None = None,
    m_csa_primary_channel_repair_path: Path | None = None,
    source_backed_materialization_path: Path | None = None,
    source_free_predicted_geometry_retrieval_path: Path | None = None,
    panel_id: str = "glycyl_radical_or_thiamine_radical_lyase_boundary",
) -> dict[str, Any]:
    family_targets = _read_json(family_targets_path)
    predicted_atlas = _read_json(predicted_geometry_atlas_path)
    fold_signal = _read_json(fold_level_signal_path)
    cofactor_sidecar = _read_json(selected_organic_cofactor_sidecar_path)
    variants = _read_json(predicted_atlas_variants_path)
    predicted_fold_channel = (
        _read_json(predicted_structure_fold_channel_path)
        if predicted_structure_fold_channel_path is not None
        and Path(predicted_structure_fold_channel_path).exists()
        else {}
    )
    m_csa_repair = (
        _read_json(m_csa_primary_channel_repair_path)
        if m_csa_primary_channel_repair_path is not None
        and Path(m_csa_primary_channel_repair_path).exists()
        else {}
    )
    source_backed_materialization = (
        _read_json(source_backed_materialization_path)
        if source_backed_materialization_path is not None
        and Path(source_backed_materialization_path).exists()
        else {}
    )
    source_free_retrieval = (
        _read_json(source_free_predicted_geometry_retrieval_path)
        if source_free_predicted_geometry_retrieval_path is not None
        and Path(source_free_predicted_geometry_retrieval_path).exists()
        else {}
    )

    panel = None
    for item in family_targets.get("candidate_families", []):
        if item.get("candidate_family") == panel_id:
            panel = item
            break
    if panel is None:
        return {
            "artifact_id": f"v3_family_panel_evidence_packet_{panel_id}_current702_20260601",
            "schema_version": SCHEMA_VERSION,
            "created_utc": _utc_now_iso(),
            "status": "panel_not_found",
            "panel_id": panel_id,
        }

    geometry_by_entry = {
        str(row.get("entry_id")): row
        for row in predicted_atlas.get("results", [])
        if isinstance(row, dict) and row.get("entry_id")
    }
    fold_by_entry = {
        str(row.get("entry_id")): row
        for row in fold_signal.get("confounded_row_details", [])
        if isinstance(row, dict) and row.get("entry_id")
    }
    variant_by_entry = {
        str(row.get("entry_id")): row
        for row in variants.get("row_scores", [])
        if isinstance(row, dict) and row.get("entry_id")
    }
    def _predicted_fold_hits(section: str) -> dict[str, dict[str, Any]]:
        return {
            str(row.get("query_entry_id")): row
            for row in (
                predicted_fold_channel.get("parsed_foldseek_results", {})
                .get(section, {})
                .get("nearest_atlas_hits", [])
            )
            if isinstance(row, dict) and row.get("query_entry_id")
        }

    predicted_fold_hits = _predicted_fold_hits("all_heldout_vs_atlas")
    predicted_fold_hits.update(
        _predicted_fold_hits("priority_cofactor_confounded_oos_vs_atlas")
    )
    repair_by_entry = {
        str(row.get("entry_id")): row
        for row in m_csa_repair.get("row_scores", [])
        if isinstance(row, dict) and row.get("entry_id")
    }
    source_backed_fold_by_entry = _source_backed_materialization_fold_hits_by_entry(
        source_backed_materialization
    )
    source_free_geometry_by_entry = _source_free_predicted_geometry_scores_by_entry(
        source_free_retrieval
    )
    rows = []
    for entry_id in panel.get("candidate_rows", []):
        geo = geometry_by_entry.get(entry_id, {})
        repair = repair_by_entry.get(entry_id, {})
        source_free_geometry = source_free_geometry_by_entry.get(entry_id, {})
        top = _top1_fingerprint(geo) or {}
        geometry_score_source = "predicted_geometry_atlas" if top else None
        if repair and not top:
            top = {
                "fingerprint_id": repair.get("geometry_top1_fingerprint_id"),
                "score": repair.get("geometry_top1_score"),
                "role_match_fraction": None,
                "cofactor_context_score": None,
            }
            geometry_score_source = "m_csa_primary_channel_repair"
        if source_free_geometry and not top:
            top = {
                "fingerprint_id": source_free_geometry.get("top1_fingerprint_id"),
                "score": source_free_geometry.get("top1_score"),
                "role_match_fraction": source_free_geometry.get(
                    "top1_role_match_fraction"
                ),
                "cofactor_context_score": source_free_geometry.get(
                    "top1_cofactor_context_score"
                ),
            }
            geometry_score_source = str(source_free_geometry.get("source") or "")
        fold = fold_by_entry.get(entry_id, {})
        cof = _cofactor_scores_for_entry(cofactor_sidecar, entry_id)
        variant = variant_by_entry.get(entry_id, {})
        variant_scores = variant.get("variant_scores", {})
        cofactor_max = max(cof.values()) if cof else None
        predicted_fold_hit = predicted_fold_hits.get(entry_id, {})
        if repair and predicted_fold_hit.get("tm_score") is None:
            predicted_fold_hit = {
                "nearest_atlas_entry_id": repair.get("nearest_atlas_entry_id"),
                "nearest_atlas_true_fingerprint_id": repair.get(
                    "nearest_atlas_true_fingerprint_id"
                ),
                "tm_score": repair.get("nearest_atlas_tm_score"),
                "score_source": "m_csa_primary_channel_repair",
            }
        source_backed_fold_hit = source_backed_fold_by_entry.get(entry_id, {})
        if source_backed_fold_hit and predicted_fold_hit.get("tm_score") is None:
            predicted_fold_hit = {
                "nearest_atlas_entry_id": source_backed_fold_hit.get(
                    "nearest_atlas_entry_id"
                ),
                "nearest_atlas_true_fingerprint_id": source_backed_fold_hit.get(
                    "nearest_atlas_true_fingerprint_id"
                ),
                "tm_score": source_backed_fold_hit.get("nearest_atlas_tm_score"),
                "score_source": source_backed_fold_hit.get("score_source"),
            }
        rows.append(
            {
                "entry_id": entry_id,
                "split_assignment": geo.get("split_assignment")
                or repair.get("split_assignment"),
                "benchmark_role": geo.get("benchmark_role")
                or repair.get("benchmark_role"),
                "predicted_geometry_status": (
                    _predicted_row_status(geo)
                    if geo
                    else repair.get("predicted_geometry_status")
                    or source_free_geometry.get("predicted_geometry_status")
                    or "missing"
                ),
                "predicted_geometry_score_source": geometry_score_source,
                "predicted_geometry_top1": {
                    "fingerprint_id": top.get("fingerprint_id"),
                    "score": top.get("score"),
                    "role_match_fraction": top.get("role_match_fraction"),
                    "cofactor_context_score": top.get("cofactor_context_score"),
                },
                "predicted_geometry_accession_repair": repair.get(
                    "predicted_geometry_accession_repair"
                ),
                "selected_organic_cofactor_scores": cof,
                "selected_organic_cofactor_max": (
                    round(cofactor_max, 6) if cofactor_max is not None else None
                ),
                "selected_pdb_fold_proxy": {
                    "nearest_primary_foldseek_prob": (
                        (fold.get("fold_signals") or {}).get("nearest_primary_foldseek_prob")
                    ),
                    "top3_primary_foldseek_prob": (
                        (fold.get("fold_signals") or {}).get("top3_primary_foldseek_prob")
                    ),
                    "nearest_train_label_group": fold.get("nearest_train_label_group"),
                    "nearest_train_fingerprint_id": fold.get("nearest_train_fingerprint_id"),
                },
                "predicted_atlas_geometry_variant_scores": {
                    "top1_score_raw": variant_scores.get("top1_score_raw"),
                    "negative_nearest_class_centroid_robust_distance": variant_scores.get(
                        "negative_nearest_class_centroid_robust_distance"
                    ),
                },
                "predicted_structure_fold_channel": {
                    "nearest_atlas_entry_id": predicted_fold_hit.get(
                        "nearest_atlas_entry_id"
                    ),
                    "nearest_atlas_true_fingerprint_id": predicted_fold_hit.get(
                        "nearest_atlas_true_fingerprint_id"
                    ),
                    "nearest_atlas_tm_score": predicted_fold_hit.get("tm_score"),
                    "score_source": predicted_fold_hit.get("score_source")
                    or (
                        "predicted_structure_fold_channel"
                        if predicted_fold_hit.get("tm_score") is not None
                        else None
                    ),
                },
                "evidence_role": (
                    "cofactor-confounded OOS control: known organic cofactor-like "
                    "signal with weak/novel fold or geometry support against occupied "
                    "primary mechanisms"
                ),
            }
        )

    missing_geometry = [
        row["entry_id"] for row in rows if row["predicted_geometry_status"] != "ok"
    ]
    artifact_slug = (
        "glycyl_radical_or_thiamine_radical_lyase"
        if panel_id == "glycyl_radical_or_thiamine_radical_lyase_boundary"
        else _safe_path_token(panel_id)
    )
    return {
        "artifact_id": f"v3_family_panel_evidence_packet_{artifact_slug}_current702_20260601",
        "schema_version": SCHEMA_VERSION,
        "created_utc": _utc_now_iso(),
        "status": (
            "evidence_packet_ready_review_only"
            if not missing_geometry else "evidence_packet_ready_with_geometry_gaps"
        ),
        "scope": (
            "Review-only evidence packet for the highest-value family-set expansion "
            f"panel `{panel_id}`: cofactor-confounded OOS boundary rows "
            "that stress the current de novo abstention gate."
        ),
        "guardrails": {
            "proposal_only": True,
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "heldout_splits_changed": False,
            "heldout_rows_used_for_training": False,
        },
        "panel": panel,
        "counts": {
            "candidate_rows": len(rows),
            "predicted_geometry_ok_rows": sum(
                1 for row in rows if row["predicted_geometry_status"] == "ok"
            ),
            "rows_with_selected_pdb_fold_proxy": sum(
                1
                for row in rows
                if row["selected_pdb_fold_proxy"]["nearest_primary_foldseek_prob"] is not None
            ),
            "rows_with_selected_organic_cofactor_scores": sum(
                1 for row in rows if row["selected_organic_cofactor_scores"]
            ),
            "rows_with_predicted_structure_fold_hits": sum(
                1
                for row in rows
                if row["predicted_structure_fold_channel"]["nearest_atlas_tm_score"]
                is not None
            ),
            "missing_geometry_entry_ids": missing_geometry,
        },
        "row_evidence": rows,
        "review_questions": [
            f"Do these rows share a coherent `{panel_id}` mechanism locus, or should they stay OOS controls?",
            "Which row-level bond-change and cofactor-locus features must be normalized before any countable family addition?",
            "Does the real predicted-structure Foldseek/TM channel keep these rows outside occupied primary atlas folds?",
        ],
        "next_actions": (
            [
                "use the completed all-heldout predicted Foldseek/TM signal in the next abstention combiner diagnostic",
                "source-check mechanism locus and bond-change evidence before any panel promotion discussion",
                "keep rows review-only and out of training/calibration until a future frozen split is explicitly authorized",
            ]
            if predicted_fold_channel.get("status") == "computed_all_heldout_foldseek_scores"
            else (
            [
                "extend the predicted-structure Foldseek/TM sweep from this two-row panel to all priority confounded rows or all heldout rows",
                "source-check mechanism locus and bond-change evidence before any panel promotion discussion",
                "keep rows review-only and out of training/calibration until a future frozen split is explicitly authorized",
            ]
            if predicted_fold_hits
            else [
                "run the predicted-structure Foldseek/TM priority manifest for these rows against the predicted atlas",
                "source-check mechanism locus and bond-change evidence before any panel promotion discussion",
                "keep rows review-only and out of training/calibration until a future frozen split is explicitly authorized",
            ]
            )
        ),
        "source_artifacts": {
            "family_targets": {
                "path": str(family_targets_path),
                "sha256": _sha256(family_targets_path),
            },
            "predicted_geometry_atlas": {
                "path": str(predicted_geometry_atlas_path),
                "sha256": _sha256(predicted_geometry_atlas_path),
            },
            "fold_level_signal": {
                "path": str(fold_level_signal_path),
                "sha256": _sha256(fold_level_signal_path),
            },
            "selected_organic_cofactor_sidecar": {
                "path": str(selected_organic_cofactor_sidecar_path),
                "sha256": _sha256(selected_organic_cofactor_sidecar_path),
            },
            "predicted_atlas_variants": {
                "path": str(predicted_atlas_variants_path),
                "sha256": _sha256(predicted_atlas_variants_path),
            },
            "predicted_structure_fold_channel": (
                {
                    "path": str(predicted_structure_fold_channel_path),
                    "sha256": _sha256(predicted_structure_fold_channel_path),
                }
                if predicted_structure_fold_channel_path is not None
                and Path(predicted_structure_fold_channel_path).exists()
                else None
            ),
            "m_csa_primary_channel_repair": (
                {
                    "path": str(m_csa_primary_channel_repair_path),
                    "sha256": _sha256(m_csa_primary_channel_repair_path),
                }
                if m_csa_primary_channel_repair_path is not None
                and Path(m_csa_primary_channel_repair_path).exists()
                else None
            ),
            "source_backed_sidecar_materialization": (
                {
                    "path": str(source_backed_materialization_path),
                    "sha256": _sha256(source_backed_materialization_path),
                }
                if source_backed_materialization_path is not None
                and Path(source_backed_materialization_path).exists()
                else None
            ),
            "source_free_predicted_geometry_retrieval": (
                {
                    "path": str(source_free_predicted_geometry_retrieval_path),
                    "sha256": _sha256(source_free_predicted_geometry_retrieval_path),
                }
                if source_free_predicted_geometry_retrieval_path is not None
                and Path(source_free_predicted_geometry_retrieval_path).exists()
                else None
            ),
        },
    }


def _render_family_panel_evidence_packet_report(audit: dict[str, Any]) -> str:
    panel_id = (audit.get("panel") or {}).get("candidate_family") or "family_panel"
    lines = [
        f"# Family Panel Evidence Packet - {panel_id}",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Candidate rows: {audit['counts']['candidate_rows']}",
        f"- Predicted geometry ok rows: {audit['counts']['predicted_geometry_ok_rows']}",
        "",
        "## Row Evidence",
        "",
        "| Row | geometry top1 | geom score | cofactor max | selected-PDB fold prob | predicted-fold TM | robust atlas distance signal |",
        "| --- | --- | ---: | ---: | ---: | ---: | ---: |",
    ]
    for row in audit["row_evidence"]:
        lines.append(
            f"| {row['entry_id']} | {row['predicted_geometry_top1']['fingerprint_id']} | "
            f"{row['predicted_geometry_top1']['score']} | "
            f"{row['selected_organic_cofactor_max']} | "
            f"{row['selected_pdb_fold_proxy']['nearest_primary_foldseek_prob']} | "
            f"{row['predicted_structure_fold_channel']['nearest_atlas_tm_score']} | "
            f"{row['predicted_atlas_geometry_variant_scores']['negative_nearest_class_centroid_robust_distance']} |"
        )
    lines += [
        "",
        "## Review Questions",
        "",
    ]
    for item in audit["review_questions"]:
        lines.append(f"- {item}")
    lines += [
        "",
        "## Next Actions",
        "",
    ]
    for item in audit["next_actions"]:
        lines.append(f"- {item}")
    return "\n".join(lines) + "\n"


def write_family_panel_evidence_packet(
    *,
    family_targets_path: Path,
    predicted_geometry_atlas_path: Path,
    fold_level_signal_path: Path,
    selected_organic_cofactor_sidecar_path: Path,
    predicted_atlas_variants_path: Path,
    out_path: Path,
    predicted_structure_fold_channel_path: Path | None = None,
    m_csa_primary_channel_repair_path: Path | None = None,
    source_backed_materialization_path: Path | None = None,
    source_free_predicted_geometry_retrieval_path: Path | None = None,
    report_path: Path | None = None,
    panel_id: str = "glycyl_radical_or_thiamine_radical_lyase_boundary",
) -> dict[str, Any]:
    audit = build_family_panel_evidence_packet(
        family_targets_path=family_targets_path,
        predicted_geometry_atlas_path=predicted_geometry_atlas_path,
        fold_level_signal_path=fold_level_signal_path,
        selected_organic_cofactor_sidecar_path=selected_organic_cofactor_sidecar_path,
        predicted_atlas_variants_path=predicted_atlas_variants_path,
        predicted_structure_fold_channel_path=predicted_structure_fold_channel_path,
        m_csa_primary_channel_repair_path=m_csa_primary_channel_repair_path,
        source_backed_materialization_path=source_backed_materialization_path,
        source_free_predicted_geometry_retrieval_path=(
            source_free_predicted_geometry_retrieval_path
        ),
        panel_id=panel_id,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_family_panel_evidence_packet_report(audit),
            encoding="utf-8",
        )
    return audit


def build_family_panel_high_value_glycyl_radical_readiness_packet(
    *,
    evidence_packet_path: Path,
    fold_augmented_readout_path: Path,
    row_specific_bond_change_schema_path: Path,
    fold_coordinate_provenance_audit_path: Path,
) -> dict[str, Any]:
    packet = _read_json(evidence_packet_path)
    readout = _read_json(fold_augmented_readout_path)
    bond_schema = _read_json(row_specific_bond_change_schema_path)
    fold_provenance = _read_json(fold_coordinate_provenance_audit_path)
    readout_by_entry = {
        str(row.get("entry_id")): row
        for row in readout.get("row_scores", [])
        if isinstance(row, dict) and row.get("entry_id")
    }
    bond_by_entry = {
        str(row.get("entry_id")): row
        for row in bond_schema.get("row_materialization_queue", [])
        if isinstance(row, dict) and row.get("entry_id")
    }
    row_readiness = []
    for row in packet.get("row_evidence", []):
        if not isinstance(row, dict):
            continue
        entry_id = str(row.get("entry_id") or "")
        readout_row = readout_by_entry.get(entry_id, {})
        bond_row = bond_by_entry.get(entry_id, {})
        geometry = row.get("predicted_geometry_top1") or {}
        fold = row.get("predicted_structure_fold_channel") or {}
        row_readiness.append(
            {
                "entry_id": entry_id,
                "split_assignment": row.get("split_assignment"),
                "benchmark_role": row.get("benchmark_role"),
                "evidence_role": row.get("evidence_role"),
                "predicted_geometry_status": row.get("predicted_geometry_status"),
                "predicted_geometry_top1_fingerprint_id": geometry.get(
                    "fingerprint_id"
                ),
                "predicted_geometry_top1_score": geometry.get("score"),
                "selected_organic_cofactor_max": row.get(
                    "selected_organic_cofactor_max"
                ),
                "predicted_structure_nearest_atlas_entry_id": fold.get(
                    "nearest_atlas_entry_id"
                ),
                "predicted_structure_nearest_atlas_true_fingerprint_id": fold.get(
                    "nearest_atlas_true_fingerprint_id"
                ),
                "predicted_structure_nearest_atlas_tm_score": fold.get(
                    "nearest_atlas_tm_score"
                ),
                "research_gate_status": readout_row.get("research_gate_status"),
                "primary_threshold": readout_row.get("primary_threshold"),
                "primary_threshold_margin": readout_row.get(
                    "primary_threshold_margin"
                ),
                "row_specific_bond_change_schema_status": bond_row.get(
                    "row_specific_bond_change_status"
                ),
                "ready_for_embedding_pilot": bond_row.get(
                    "ready_for_embedding_pilot",
                    False,
                ),
                "promotion_readiness": "not_ready_review_only_oos_boundary_control",
                "remaining_blockers": [
                    "source_backed_row_specific_bond_change_evidence_missing",
                    "expert_mechanism_locus_review_missing",
                    "label_factory_import_gate_not_run",
                    "future_frozen_split_required_before_countable_use",
                ],
            }
        )
    score_complete = [
        row
        for row in row_readiness
        if row["predicted_geometry_status"] == "ok"
        and row["predicted_structure_nearest_atlas_tm_score"] is not None
    ]
    abstained = [
        row
        for row in row_readiness
        if row["research_gate_status"] == "abstained_at_research_threshold"
    ]
    return {
        "artifact_id": FAMILY_PANEL_HIGH_VALUE_GLYCYL_RADICAL_READINESS_PACKET_ID,
        "schema_version": f"{SCHEMA_VERSION}.family_panel_high_value_readiness",
        "created_utc": _utc_now_iso(),
        "status": "glycyl_radical_panel_ready_as_oos_boundary_review_only",
        "scope": (
            "Review-only readiness packet for the highest-value "
            "glycyl-radical/thiamine-radical lyase boundary panel after "
            "predicted fold scoring, fixed research-gate readout, and "
            "row-specific bond-change schema staging."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "model_weights_fit_or_refit": False,
            "heldout_threshold_tuning_for_deployment": False,
            "review_only": True,
        },
        "counts": {
            "panel_rows": len(row_readiness),
            "score_complete_rows": len(score_complete),
            "abstained_at_research_threshold": len(abstained),
            "non_abstained_at_research_threshold": sum(
                1
                for row in row_readiness
                if row["research_gate_status"] == "non_abstained_at_research_threshold"
            ),
            "rows_missing_row_specific_bond_change_evidence": len(row_readiness),
            "fold_coordinate_paths_missing_for_global_channel": (
                (fold_provenance.get("counts") or {}).get(
                    "unique_coordinate_files_missing"
                )
            ),
            "fold_result_files_parseable": (
                (fold_provenance.get("counts") or {}).get("result_files_parseable")
            ),
        },
        "panel_decision": {
            "current_use": "review_only_oos_boundary_control",
            "promotion_or_import_ready": False,
            "rationale": (
                "Both rows are score-complete, cofactor-confounded heldout OOS "
                "controls and abstain under the fixed combined_mean_geometry_fold "
                "research threshold; no source-backed row-specific bond-change "
                "evidence is materialized."
            ),
        },
        "row_readiness": row_readiness,
        "next_actions": [
            "source-check m_csa:30 and m_csa:31 for row-specific glycyl-radical/thiamine-radical bond-change evidence from frozen source graphs before any panel-promotion discussion",
            "materialize the row-specific bond-change sidecar under the staged schema if source evidence exists",
            "keep both rows review-only and out of train/cal/threshold selection until an explicit future split and label-factory gate authorize countable use",
        ],
        "source_artifacts": {
            "family_panel_evidence_packet": _source_path_record(evidence_packet_path),
            "fold_augmented_family_panel_research_readout": _source_path_record(
                fold_augmented_readout_path
            ),
            "row_specific_bond_change_schema": _source_path_record(
                row_specific_bond_change_schema_path
            ),
            "fold_channel_coordinate_provenance_audit": _source_path_record(
                fold_coordinate_provenance_audit_path
            ),
        },
        "interpretation": {
            "headline": (
                "The highest-value glycyl/thiamine radical panel is ready as a "
                "review-only OOS boundary control, not as a family expansion import."
            ),
            "why_not_import_ready": (
                "Both rows still lack source-backed row-specific bond-change and "
                "expert mechanism-locus validation, and no label-factory/import "
                "gate has run."
            ),
            "exact_next_action": (
                "Run a frozen-local source check for m_csa:30 and m_csa:31 focused "
                "on row-specific radical/thiamine bond-change evidence."
            ),
        },
    }


def _render_family_panel_high_value_glycyl_radical_readiness_packet_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    lines = [
        "# Family Panel High-Value Glycyl Radical Readiness Packet - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Panel rows: {counts['panel_rows']}",
        f"- Score-complete rows: {counts['score_complete_rows']}",
        f"- Abstained at research threshold: {counts['abstained_at_research_threshold']}",
        (
            "- Rows missing row-specific bond-change evidence: "
            f"{counts['rows_missing_row_specific_bond_change_evidence']}"
        ),
        "",
        "## Row Readiness",
        "",
        (
            "| row | geometry top1 | geom score | fold TM | threshold margin | "
            "gate status | readiness |"
        ),
        "| --- | --- | ---: | ---: | ---: | --- | --- |",
    ]
    for row in audit["row_readiness"]:
        lines.append(
            f"| {row['entry_id']} | {row['predicted_geometry_top1_fingerprint_id']} | "
            f"{row['predicted_geometry_top1_score']} | "
            f"{row['predicted_structure_nearest_atlas_tm_score']} | "
            f"{row['primary_threshold_margin']} | {row['research_gate_status']} | "
            f"{row['promotion_readiness']} |"
        )
    lines += [
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['why_not_import_ready']}",
        f"- {audit['interpretation']['exact_next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_family_panel_high_value_glycyl_radical_readiness_packet(
    *,
    evidence_packet_path: Path,
    fold_augmented_readout_path: Path,
    row_specific_bond_change_schema_path: Path,
    fold_coordinate_provenance_audit_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_family_panel_high_value_glycyl_radical_readiness_packet(
        evidence_packet_path=evidence_packet_path,
        fold_augmented_readout_path=fold_augmented_readout_path,
        row_specific_bond_change_schema_path=row_specific_bond_change_schema_path,
        fold_coordinate_provenance_audit_path=fold_coordinate_provenance_audit_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_family_panel_high_value_glycyl_radical_readiness_packet_report(
                audit
            ),
            encoding="utf-8",
        )
    return audit


def _source_backed_materialization_fold_hits_by_entry(
    audit: dict[str, Any],
) -> dict[str, dict[str, Any]]:
    rows = {}
    for row in audit.get("row_scores", []):
        if not isinstance(row, dict) or not row.get("entry_id"):
            continue
        fold = row.get("predicted_structure_fold_channel") or {}
        if fold.get("nearest_atlas_tm_score") is None:
            continue
        rows[str(row["entry_id"])] = fold
    return rows


def _source_backed_plan_accession(row: dict[str, Any]) -> str | None:
    identifier = row.get("identifier_resolution") or {}
    accession = str(identifier.get("uniprot_id") or "").strip()
    if accession:
        return accession
    source_accession = str(identifier.get("source_accession") or "").strip()
    if source_accession.startswith("uniprot:"):
        return source_accession.split(":", 1)[1]
    return source_accession or None


def _source_backed_sidecar_path(row: dict[str, Any], sidecar_dir: Path) -> Path:
    accession = _source_backed_plan_accession(row) or "unknown"
    entry_id = str(row.get("entry_id") or "unknown")
    token = _safe_path_token(f"{entry_id}_{accession}")
    return sidecar_dir / f"{token}.json"


def _coordinate_file_record(path: Path, *, coordinate_role: str) -> dict[str, Any]:
    exists = path.is_file()
    return {
        "coordinate_role": coordinate_role,
        "path": str(path),
        "exists": exists,
        "size_bytes": path.stat().st_size if exists else None,
        "sha256": _sha256(path) if exists else None,
    }


def _source_backed_query_request(
    row: dict[str, Any],
    *,
    coordinate_dir: Path,
    alphafold_version: int,
) -> dict[str, Any]:
    entry_id = str(row.get("entry_id") or "")
    accession = _source_backed_plan_accession(row)
    afdb_path = (
        coordinate_dir / f"AF-{accession}-F1-model_v{alphafold_version}.cif"
        if accession
        else coordinate_dir / "missing_accession.cif"
    )
    return {
        "role": "family_panel_source_backed_query",
        "status": "ready_to_score" if accession and afdb_path.is_file() else "missing_coordinate",
        "accession": accession,
        "alphafold_version": alphafold_version,
        "predicted_pdb_id": (
            f"AF-{accession}-F1-model_v{alphafold_version}" if accession else None
        ),
        "url": _afdb_cif_url(accession, alphafold_version) if accession else None,
        "expected_local_path": str(afdb_path) if accession else None,
        "local_file_exists": afdb_path.is_file() if accession else False,
        "entry_ids": [entry_id],
        "rows": [
            {
                "entry_id": entry_id,
                "split_assignment": "review_only_family_panel",
                "true_fingerprint_id": None,
                "benchmark_role": "review_only_family_panel_primary_channel_gap",
                "panel_id": row.get("panel_id"),
            }
        ],
    }


def _source_backed_ligand_or_cofactor_state(entry_id: str) -> dict[str, Any]:
    if entry_id == "secondary_probe::cobalamin_radical_rearrangement":
        return {
            "state": "adenosylcobalamin_context_expected_from_source_row",
            "manual_local_site_verification_required": True,
        }
    if entry_id == "secondary_probe::radical_sam_enzyme":
        return {
            "state": "radical_sam_fe_s_context_expected_from_source_row",
            "manual_local_site_verification_required": True,
        }
    if entry_id == "external_glycoside_panel":
        return {
            "state": "glycoside_hydrolase_acidic_dyad_and_glycan_context_expected_from_source_row",
            "manual_local_site_verification_required": True,
        }
    return {
        "state": "source_backed_external_representative_context",
        "manual_local_site_verification_required": True,
    }


def _build_source_backed_sidecar_payload(
    *,
    row: dict[str, Any],
    sidecar_path: Path,
    coordinate_records: list[dict[str, Any]],
    fold_hit: dict[str, Any] | None,
    plan_path: Path,
) -> dict[str, Any]:
    entry_id = str(row.get("entry_id") or "")
    identifier = row.get("identifier_resolution") or {}
    selection = row.get("representative_selection") or {}
    basis_path = Path(str(selection.get("basis_artifact") or ""))
    source_artifact_hashes = {
        "materialization_plan": {
            "path": str(plan_path),
            "sha256": _sha256(plan_path),
        }
    }
    if basis_path.is_file():
        source_artifact_hashes["representative_basis_artifact"] = {
            "path": str(basis_path),
            "sha256": _sha256(basis_path),
        }
    nearest_tm = (fold_hit or {}).get("tm_score")
    return {
        "artifact_id": f"{FAMILY_PANEL_SOURCE_BACKED_SIDECAR_MATERIALIZATION_ID}_sidecar",
        "schema_version": f"{SCHEMA_VERSION}.source_backed_family_panel_sidecar",
        "created_utc": _utc_now_iso(),
        "entry_id": entry_id,
        "representative_source_row_id": selection.get("selected_source_row_id"),
        "source_accession": identifier.get("source_accession"),
        "source_artifact_hashes": source_artifact_hashes,
        "representative_selection_policy": selection.get("selection_policy"),
        "display_name": selection.get("display_name"),
        "source_urls": identifier.get("source_urls") or {},
        "panel_id": row.get("panel_id"),
        "intended_review_role": "review_only_family_panel_primary_channel_gap_closure",
        "predictive_use_allowed": False,
        "ready_for_label_import": False,
        "selected_structure_id": (
            (row.get("coordinate_materialization_manifest") or {}).get(
                "preferred_coordinate_id"
            )
        ),
        "coordinate_records": coordinate_records,
        "coordinate_path": next(
            (
                record["path"]
                for record in coordinate_records
                if record["coordinate_role"] == "selected_pdb_cif"
            ),
            None,
        ),
        "coordinate_sha256": next(
            (
                record["sha256"]
                for record in coordinate_records
                if record["coordinate_role"] == "selected_pdb_cif"
            ),
            None,
        ),
        "catalytic_or_binding_site_evidence": {
            "status": "source_backed_row_context_staged_local_site_not_extracted",
            "blockers_to_clear": row.get("blockers_to_clear") or [],
        },
        "ligand_or_cofactor_state": _source_backed_ligand_or_cofactor_state(entry_id),
        "current702_split_protection": {
            "review_only": True,
            "countable_current702_label": False,
            "allowed_for_training_or_threshold_selection": False,
        },
        "predicted_geometry_status": "not_computed_source_free_geometry_sidecar_missing",
        "predicted_fold_channel_status": (
            "computed_foldseek_tm_against_frozen_predicted_atlas"
            if nearest_tm is not None
            else "foldseek_tm_missing_or_unparsed"
        ),
        "predicted_structure_fold_channel": {
            "nearest_atlas_entry_id": (fold_hit or {}).get("nearest_atlas_entry_id"),
            "nearest_atlas_true_fingerprint_id": (fold_hit or {}).get(
                "nearest_atlas_true_fingerprint_id"
            ),
            "nearest_atlas_tm_score": nearest_tm,
            "score_source": (
                "family_panel_source_backed_afdb_vs_predicted_atlas"
                if nearest_tm is not None
                else None
            ),
        },
        "sidecar_path": str(sidecar_path),
    }


def build_family_panel_source_backed_sidecar_materialization(
    *,
    materialization_plan_path: Path,
    predicted_structure_fold_channel_path: Path,
    coordinate_dir: Path,
    sidecar_dir: Path,
    foldseek_result_tsv: Path,
    query_dir: Path,
    target_atlas_dir: Path,
    foldseek_binary: str = DEFAULT_FOLDSEEK_BINARY,
    target_priorities: list[str] | None = None,
    alphafold_version: int = 6,
    threads: int = 4,
) -> dict[str, Any]:
    plan = _read_json(materialization_plan_path)
    fold_channel = _read_json(predicted_structure_fold_channel_path)
    priorities = set(target_priorities or ["P0"])
    row_plans = [
        row
        for row in plan.get("row_plan", [])
        if isinstance(row, dict) and str(row.get("priority") or "") in priorities
    ]
    query_requests = [
        _source_backed_query_request(
            row,
            coordinate_dir=coordinate_dir,
            alphafold_version=alphafold_version,
        )
        for row in row_plans
    ]
    target_requests = (
        (fold_channel.get("foldseek_input_manifest") or {})
        .get("coordinate_request_groups", {})
        .get("atlas_in_distribution", [])
    )
    parsed_foldseek = _parse_foldseek_tsv_hits(
        result_tsv=foldseek_result_tsv,
        query_requests=query_requests,
        target_requests=target_requests,
    )
    hits_by_entry = {
        str(hit.get("query_entry_id") or ""): hit
        for hit in parsed_foldseek.get("nearest_atlas_hits", [])
        if isinstance(hit, dict) and hit.get("query_entry_id")
    }
    foldseek = _foldseek_binary_info(foldseek_binary)
    run_foldseek_command = _foldseek_easy_search_command(
        binary=str(foldseek.get("resolved") or foldseek_binary),
        query_dir=query_dir,
        target_dir=target_atlas_dir,
        result_tsv=foldseek_result_tsv,
        tmp_dir=Path("/private/tmp/catalytic-earth-family-panel-source-backed-foldseek"),
        threads=threads,
    )
    row_scores: list[dict[str, Any]] = []
    blockers: list[str] = []
    sidecar_payloads: list[dict[str, Any]] = []
    for row in sorted(row_plans, key=lambda item: int(item.get("rank") or 0)):
        entry_id = str(row.get("entry_id") or "")
        accession = _source_backed_plan_accession(row)
        manifest = row.get("coordinate_materialization_manifest") or {}
        pdb_path = Path(str(manifest.get("pdb_cif_path") or ""))
        afdb_path = (
            coordinate_dir / f"AF-{accession}-F1-model_v{alphafold_version}.cif"
            if accession
            else coordinate_dir / "missing_accession.cif"
        )
        coordinate_records = [
            _coordinate_file_record(pdb_path, coordinate_role="selected_pdb_cif"),
            _coordinate_file_record(afdb_path, coordinate_role="alphafolddb_predicted_cif"),
        ]
        missing_coordinates = [
            record["coordinate_role"] for record in coordinate_records if not record["exists"]
        ]
        if missing_coordinates:
            blockers.append(f"{entry_id}:missing_{'_and_'.join(missing_coordinates)}")
        hit = hits_by_entry.get(entry_id)
        if hit is None:
            blockers.append(f"{entry_id}:foldseek_hit_missing")
        sidecar_path = _source_backed_sidecar_path(row, sidecar_dir)
        sidecar = _build_source_backed_sidecar_payload(
            row=row,
            sidecar_path=sidecar_path,
            coordinate_records=coordinate_records,
            fold_hit=hit,
            plan_path=materialization_plan_path,
        )
        sidecar_payloads.append(sidecar)
        fold_channel_row = sidecar["predicted_structure_fold_channel"]
        remaining_blockers = ["predicted_geometry_top1_score_missing"]
        if fold_channel_row["nearest_atlas_tm_score"] is None:
            remaining_blockers.append("predicted_structure_fold_tm_missing")
        row_scores.append(
            {
                "rank": row.get("rank"),
                "entry_id": entry_id,
                "panel_id": row.get("panel_id"),
                "priority": row.get("priority"),
                "representative_source_row_id": sidecar["representative_source_row_id"],
                "source_accession": sidecar["source_accession"],
                "selected_structure_id": sidecar["selected_structure_id"],
                "coordinate_records": coordinate_records,
                "sidecar_path": str(sidecar_path),
                "predicted_geometry_status": sidecar["predicted_geometry_status"],
                "predicted_structure_fold_channel": fold_channel_row,
                "remaining_primary_channel_blockers": remaining_blockers,
                "guardrail_note": (
                    "review-only source-backed materialization; do not use as "
                    "training, label promotion, threshold selection, or production "
                    "scoring evidence"
                ),
            }
        )
    if parsed_foldseek.get("status") != "parsed":
        blockers.append(f"foldseek_tsv_status:{parsed_foldseek.get('status')}")
    sidecars_with_hashes = [
        row
        for row in row_scores
        if all(record["exists"] and record["sha256"] for record in row["coordinate_records"])
    ]
    scored_rows = [
        row
        for row in row_scores
        if (
            row.get("predicted_structure_fold_channel") or {}
        ).get("nearest_atlas_tm_score")
        is not None
    ]
    status = (
        "source_backed_sidecars_fold_scored_review_only"
        if len(scored_rows) == len(row_scores) and not blockers
        else "source_backed_sidecars_staged_with_blockers"
    )
    return {
        "artifact_id": FAMILY_PANEL_SOURCE_BACKED_SIDECAR_MATERIALIZATION_ID,
        "schema_version": f"{SCHEMA_VERSION}.source_backed_sidecar_materialization",
        "created_utc": _utc_now_iso(),
        "status": status,
        "scope": (
            "Review-only materialization and Foldseek/TM scoring of targeted "
            "source-backed family-panel rows against the frozen current702 "
            "in-distribution predicted atlas."
        ),
        "guardrails": {
            "review_only": True,
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "threshold_values_changed": False,
            "model_weights_fit_or_refit": False,
            "heldout_rows_used_for_training": False,
            "source_backed_rows_countable": False,
        },
        "counts": {
            "plan_rows": len(plan.get("row_plan", [])),
            "targeted_rows": len(row_scores),
            "target_priorities": sorted(priorities),
            "sidecars_with_coordinate_hashes": len(sidecars_with_hashes),
            "foldseek_query_entries_with_hits": len(scored_rows),
            "remaining_predicted_geometry_blockers": sum(
                1
                for row in row_scores
                if "predicted_geometry_top1_score_missing"
                in row["remaining_primary_channel_blockers"]
            ),
            "remaining_predicted_fold_blockers": sum(
                1
                for row in row_scores
                if "predicted_structure_fold_tm_missing"
                in row["remaining_primary_channel_blockers"]
            ),
        },
        "runtime": {
            "foldseek": foldseek,
            "threads": max(1, int(threads)),
            "alphafold_version_used": alphafold_version,
        },
        "blockers": sorted(set(blockers)),
        "parsed_foldseek_results": parsed_foldseek,
        "foldseek_input_manifest": {
            "query_dir": str(query_dir),
            "target_atlas_dir": str(target_atlas_dir),
            "result_tsv": str(foldseek_result_tsv),
            "query_requests": query_requests,
            "target_request_count": len(target_requests),
        },
        "commands": {
            "run_foldseek_afdb_vs_predicted_atlas": run_foldseek_command,
            "expected_foldseek_tsv_columns": [
                "query",
                "target",
                "qtmscore",
                "ttmscore",
                "alntmscore",
                "prob",
                "bits",
            ],
        },
        "row_scores": row_scores,
        "sidecar_payloads": sidecar_payloads,
        "source_artifacts": {
            "materialization_plan": _source_path_record(materialization_plan_path),
            "predicted_structure_fold_channel": _source_path_record(
                predicted_structure_fold_channel_path
            ),
        },
        "interpretation": {
            "headline": (
                f"{len(scored_rows)}/{len(row_scores)} source-backed rows now "
                "have real AFDB-vs-predicted-atlas Foldseek/TM scores."
            ),
            "remaining_gap": (
                "Rows without source-free predicted active-site geometry top1 "
                "scores remain outside the primary combined gate."
            ),
            "next_action": (
                "Materialize source-free predicted-geometry sidecars for the "
                "remaining rows, then refresh the family-panel readout again "
                "without changing labels, thresholds, imports, or splits."
            ),
        },
    }


def _render_family_panel_source_backed_sidecar_materialization_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    parsed = audit.get("parsed_foldseek_results") or {}
    lines = [
        "# Family Panel Source-Backed Sidecar Materialization - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Targeted rows: {counts['targeted_rows']}",
        f"- Sidecars with coordinate hashes: {counts['sidecars_with_coordinate_hashes']}",
        f"- Foldseek rows with hits: {counts['foldseek_query_entries_with_hits']}",
        f"- Remaining predicted-geometry blockers: {counts['remaining_predicted_geometry_blockers']}",
        f"- Remaining predicted-fold blockers: {counts['remaining_predicted_fold_blockers']}",
        f"- Foldseek TSV parse status: {parsed.get('status')}",
        "",
        "## Row Scores",
        "",
        "| rank | row | accession | selected structure | nearest atlas | atlas fingerprint | TM | remaining blockers |",
        "| ---: | --- | --- | --- | --- | --- | ---: | --- |",
    ]
    for row in audit["row_scores"]:
        fold = row["predicted_structure_fold_channel"]
        lines.append(
            f"| {row['rank']} | {row['entry_id']} | {row['source_accession']} | "
            f"{row['selected_structure_id']} | {fold.get('nearest_atlas_entry_id')} | "
            f"{fold.get('nearest_atlas_true_fingerprint_id')} | "
            f"{fold.get('nearest_atlas_tm_score')} | "
            f"{', '.join(row['remaining_primary_channel_blockers'])} |"
        )
    lines += [
        "",
        "## Blockers",
        "",
    ]
    if audit["blockers"]:
        lines.extend(f"- {blocker}" for blocker in audit["blockers"])
    else:
        lines.append("- None for targeted coordinate hashing or Foldseek/TM parsing.")
    lines += [
        "",
        "## Command",
        "",
        "```bash",
        audit["commands"]["run_foldseek_afdb_vs_predicted_atlas"],
        "```",
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['remaining_gap']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_family_panel_source_backed_sidecar_materialization(
    *,
    materialization_plan_path: Path,
    predicted_structure_fold_channel_path: Path,
    coordinate_dir: Path,
    sidecar_dir: Path,
    foldseek_result_tsv: Path,
    query_dir: Path,
    target_atlas_dir: Path,
    out_path: Path,
    report_path: Path | None = None,
    foldseek_binary: str = DEFAULT_FOLDSEEK_BINARY,
    target_priorities: list[str] | None = None,
    alphafold_version: int = 6,
    threads: int = 4,
) -> dict[str, Any]:
    audit = build_family_panel_source_backed_sidecar_materialization(
        materialization_plan_path=materialization_plan_path,
        predicted_structure_fold_channel_path=predicted_structure_fold_channel_path,
        coordinate_dir=coordinate_dir,
        sidecar_dir=sidecar_dir,
        foldseek_result_tsv=foldseek_result_tsv,
        query_dir=query_dir,
        target_atlas_dir=target_atlas_dir,
        foldseek_binary=foldseek_binary,
        target_priorities=target_priorities,
        alphafold_version=alphafold_version,
        threads=threads,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    sidecar_dir.mkdir(parents=True, exist_ok=True)
    for sidecar in audit.get("sidecar_payloads", []):
        sidecar_path = Path(str(sidecar["sidecar_path"]))
        sidecar_path.parent.mkdir(parents=True, exist_ok=True)
        sidecar_path.write_text(
            json.dumps(sidecar, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_family_panel_source_backed_sidecar_materialization_report(
                audit
            ),
            encoding="utf-8",
        )
    audit.pop("sidecar_payloads", None)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return audit


def _geometry_rows_by_accession(
    predicted_geometry_atlas: dict[str, Any],
) -> dict[str, list[dict[str, Any]]]:
    rows: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in predicted_geometry_atlas.get("results", []):
        if not isinstance(row, dict):
            continue
        accession = str(row.get("accession") or row.get("sequence_id") or "")
        if accession:
            rows[accession].append(row)
    return rows


def _source_free_geometry_manifest_sidecar_record(
    row: dict[str, Any],
) -> dict[str, Any] | None:
    path_value = row.get("sidecar_path")
    if not path_value:
        return None
    path = Path(str(path_value))
    if not path.exists():
        return {
            "path": str(path),
            "exists": False,
            "catalytic_or_binding_site_status": "sidecar_missing",
            "sha256": None,
        }
    sidecar = _read_json(path)
    catalytic = sidecar.get("catalytic_or_binding_site_evidence") or {}
    return {
        "path": str(path),
        "exists": True,
        "sha256": _sha256(path),
        "catalytic_or_binding_site_status": catalytic.get("status"),
        "predictive_use_allowed": sidecar.get("predictive_use_allowed"),
        "ready_for_label_import": sidecar.get("ready_for_label_import"),
        "predicted_geometry_status": sidecar.get("predicted_geometry_status"),
    }


def _locator_schema_audit_rows_by_entry(
    locator_schema_audit: dict[str, Any],
) -> dict[tuple[str, str], dict[str, Any]]:
    return {
        (str(row.get("entry_id") or ""), str(row.get("source_accession") or "")): row
        for row in locator_schema_audit.get("row_audits", [])
        if isinstance(row, dict) and row.get("entry_id") and row.get("source_accession")
    }


def _source_free_locator_manifest_record(
    locator_audit_row: dict[str, Any] | None,
) -> dict[str, Any]:
    if not locator_audit_row:
        return {
            "exists": False,
            "path": None,
            "sha256": None,
            "status": "missing",
            "ready_for_predicted_geometry_scoring": False,
            "residue_locator_count": 0,
            "locator_evidence_class": None,
            "critical_violations": ["locator_sidecar_missing"],
        }
    return {
        "exists": locator_audit_row.get("exists"),
        "path": locator_audit_row.get("path"),
        "sha256": locator_audit_row.get("sha256"),
        "status": locator_audit_row.get("status"),
        "ready_for_predicted_geometry_scoring": locator_audit_row.get(
            "ready_for_predicted_geometry_scoring"
        ),
        "residue_locator_count": locator_audit_row.get("residue_locator_count"),
        "locator_evidence_class": locator_audit_row.get("locator_evidence_class"),
        "critical_violations": locator_audit_row.get("critical_violations", []),
    }


def _source_free_geometry_manifest_blockers(
    *,
    geometry_row: dict[str, Any] | None,
    sidecar_record: dict[str, Any] | None,
    afdb_record: dict[str, Any] | None,
    source_free_locator_record: dict[str, Any] | None,
) -> list[str]:
    blockers: list[str] = []
    locator_ready = bool(
        (source_free_locator_record or {}).get("ready_for_predicted_geometry_scoring")
    )
    if geometry_row is not None and geometry_row.get("status") != "ok":
        blockers.append(f"source_free_predicted_geometry_not_ok:{geometry_row.get('status')}")
    if not afdb_record or not afdb_record.get("exists"):
        blockers.append("alphafolddb_predicted_cif_missing")
    source_backed_status = (sidecar_record or {}).get("catalytic_or_binding_site_status")
    if not locator_ready:
        blockers.append("approved_source_free_active_site_locator_missing")
    if (
        source_backed_status == "source_backed_row_context_staged_local_site_not_extracted"
        and not locator_ready
    ):
        blockers.append("source_backed_sidecar_lacks_residue_locator")
    return sorted(set(blockers))


def build_family_panel_source_free_predicted_geometry_sidecar_manifest(
    *,
    source_backed_materialization_path: Path,
    predicted_geometry_atlas_path: Path,
    label_manifest_path: Path,
    locator_schema_audit_path: Path | None = None,
    missing_primary_channel_diagnosis_path: Path | None = None,
) -> dict[str, Any]:
    materialization = _read_json(source_backed_materialization_path)
    predicted_geometry_atlas = _read_json(predicted_geometry_atlas_path)
    label_manifest = _read_json(label_manifest_path)
    diagnosis = (
        _read_json(missing_primary_channel_diagnosis_path)
        if missing_primary_channel_diagnosis_path is not None
        and Path(missing_primary_channel_diagnosis_path).exists()
        else {}
    )
    locator_schema_audit = (
        _read_json(locator_schema_audit_path)
        if locator_schema_audit_path is not None
        and Path(locator_schema_audit_path).exists()
        else {}
    )
    locator_audit_by_entry = _locator_schema_audit_rows_by_entry(locator_schema_audit)
    manifest_entry_ids = {
        str(row.get("entry_id") or "")
        for row in label_manifest.get("rows", [])
        if isinstance(row, dict) and row.get("entry_id")
    }
    geometry_by_entry = _predicted_geometry_rows_by_entry(predicted_geometry_atlas)
    geometry_by_accession = _geometry_rows_by_accession(predicted_geometry_atlas)
    diagnosis_by_entry = {
        str(row.get("entry_id")): row
        for row in diagnosis.get("diagnosed_rows", [])
        if isinstance(row, dict) and row.get("entry_id")
    }

    row_manifests: list[dict[str, Any]] = []
    for row in materialization.get("row_scores", []):
        if not isinstance(row, dict) or not row.get("entry_id"):
            continue
        entry_id = str(row["entry_id"])
        source_accession = str(row.get("source_accession") or "")
        accession = source_accession.split(":", 1)[-1] if source_accession else None
        geometry_row = geometry_by_entry.get(entry_id)
        accession_matches = [
            {
                "entry_id": match.get("entry_id"),
                "split_assignment": match.get("split_assignment"),
                "status": match.get("status"),
                "top1_fingerprint_id": match.get("top1_fingerprint_id"),
                "top1_score": match.get("top1_score"),
            }
            for match in geometry_by_accession.get(accession or "", [])
        ]
        sidecar_record = _source_free_geometry_manifest_sidecar_record(row)
        source_free_locator_record = _source_free_locator_manifest_record(
            locator_audit_by_entry.get((entry_id, source_accession))
        )
        coordinate_records = [
            record
            for record in row.get("coordinate_records", [])
            if isinstance(record, dict)
        ]
        afdb_record = next(
            (
                record
                for record in coordinate_records
                if record.get("coordinate_role") == "alphafolddb_predicted_cif"
            ),
            None,
        )
        blockers = _source_free_geometry_manifest_blockers(
            geometry_row=geometry_row,
            sidecar_record=sidecar_record,
            afdb_record=afdb_record,
            source_free_locator_record=source_free_locator_record,
        )
        fold = row.get("predicted_structure_fold_channel") or {}
        source_free_status = (
            "blocked_source_free_geometry_preconditions"
            if blockers
            else (
                "source_free_predicted_geometry_scored"
                if geometry_row is not None
                else "ready_to_score_source_free_predicted_geometry"
            )
        )
        row_manifests.append(
            {
                "rank": row.get("rank"),
                "entry_id": entry_id,
                "panel_id": row.get("panel_id"),
                "source_accession": source_accession,
                "selected_structure_id": row.get("selected_structure_id"),
                "current702_label_manifest_membership": entry_id in manifest_entry_ids,
                "alphafolddb_predicted_cif": afdb_record,
                "source_backed_sidecar": sidecar_record,
                "approved_source_free_active_site_locator": source_free_locator_record,
                "existing_source_free_geometry_row": (
                    _summarize_predicted_geometry_row(geometry_row)
                    if geometry_row
                    else None
                ),
                "source_free_predicted_geometry_retrieval": {
                    "exists": geometry_row is not None,
                    "status": (
                        geometry_row.get("status")
                        if geometry_row
                        else "missing_pending_scoring"
                    ),
                },
                "same_accession_current702_geometry_rows": accession_matches,
                "source_backed_fold_score": {
                    "nearest_atlas_entry_id": fold.get("nearest_atlas_entry_id"),
                    "nearest_atlas_true_fingerprint_id": fold.get(
                        "nearest_atlas_true_fingerprint_id"
                    ),
                    "nearest_atlas_tm_score": fold.get("nearest_atlas_tm_score"),
                    "score_source": fold.get("score_source"),
                },
                "prior_missing_channel_diagnosis": (
                    diagnosis_by_entry.get(entry_id) or {}
                ).get("diagnosis"),
                "source_free_predicted_geometry_status": source_free_status,
                "blockers": blockers,
                "next_action": (
                    "run predicted-geometry retrieval for this row using the approved "
                    "source-free active-site locator sidecar"
                    if not blockers
                    else "create or approve a source-free active-site locator sidecar; "
                    "do not reuse source prose, entry name, EC/Rhea identifiers, or "
                    "review-only sidecar rationale as predictive geometry features"
                ),
            }
        )

    blocked_rows = [row for row in row_manifests if row["blockers"]]
    ready_rows = [row for row in row_manifests if not row["blockers"]]
    blocker_counts = Counter(
        blocker for row in row_manifests for blocker in row["blockers"]
    )
    rows_with_afdb = [
        row
        for row in row_manifests
        if (row.get("alphafolddb_predicted_cif") or {}).get("exists")
    ]
    rows_with_fold = [
        row
        for row in row_manifests
        if row["source_backed_fold_score"]["nearest_atlas_tm_score"] is not None
    ]
    rows_with_same_accession_geometry = [
        row for row in row_manifests if row["same_accession_current702_geometry_rows"]
    ]
    rows_with_approved_locators = [
        row
        for row in row_manifests
        if row["approved_source_free_active_site_locator"][
            "ready_for_predicted_geometry_scoring"
        ]
        is True
    ]

    status = (
        "source_free_predicted_geometry_sidecar_ready_to_score_review_only"
        if ready_rows and not blocked_rows
        else "source_free_predicted_geometry_manifest_partially_ready_to_score_review_only"
        if ready_rows and blocked_rows
        else "source_free_predicted_geometry_manifest_blocked_locator_missing_review_only"
    )
    return {
        "artifact_id": FAMILY_PANEL_SOURCE_FREE_PREDICTED_GEOMETRY_SIDECAR_MANIFEST_ID,
        "schema_version": f"{SCHEMA_VERSION}.source_free_predicted_geometry_manifest",
        "created_utc": _utc_now_iso(),
        "status": status,
        "scope": (
            "Review-only readiness manifest for materializing source-free "
            "predicted active-site geometry sidecars for the 10 family-panel "
            "rows that already have source-backed AFDB-vs-predicted-atlas "
            "Foldseek/TM scores."
        ),
        "guardrails": {
            "review_only": True,
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "threshold_values_changed": False,
            "model_weights_fit_or_refit": False,
            "heldout_rows_used_for_training": False,
            "source_prose_used_as_predictive_geometry_feature": False,
            "entry_names_ec_rhea_or_labels_used_as_predictive_features": False,
            "coordinates_or_large_models_downloaded": False,
        },
        "counts": {
            "targeted_rows": len(row_manifests),
            "rows_with_afdb_predicted_cif": len(rows_with_afdb),
            "rows_with_source_backed_fold_score": len(rows_with_fold),
            "source_free_geometry_ready_rows": len(ready_rows),
            "source_free_geometry_blocked_rows": len(blocked_rows),
            "rows_with_approved_source_free_active_site_locator": len(
                rows_with_approved_locators
            ),
            "rows_with_same_accession_current702_geometry": len(
                rows_with_same_accession_geometry
            ),
            "blocker_counts": dict(sorted(blocker_counts.items())),
        },
        "row_manifests": sorted(
            row_manifests,
            key=lambda row: int(row.get("rank") or 0),
        ),
        "blocker_clearing_attempts": [
            {
                "attempt": "looked_up_existing_predicted_geometry_by_review_entry_id",
                "result": (
                    "0 targeted review-only rows are present as source-free "
                    "predicted-geometry rows in the current combined atlas/heldout "
                    "retrieval artifact."
                ),
            },
            {
                "attempt": "checked_current702_label_manifest_membership",
                "result": (
                    "Targeted rows may be secondary/external family-panel rows; "
                    "this is recorded for provenance but is no longer a blocker "
                    "once an approved source-free active-site locator is present."
                ),
            },
            {
                "attempt": "checked_source_backed_sidecars_and_approved_locator_audit",
                "result": (
                    "Source-backed sidecars remain review-context only; approved "
                    "source-free locator sidecars from the schema audit are the "
                    "only mechanism allowed to clear active-site localization."
                ),
            },
            {
                "attempt": "checked_coordinate_and_fold_runtime_state",
                "result": (
                    "AFDB v6 CIFs and source-backed Foldseek/TM scores are already "
                    "present for all 10 rows, so the blocker is data semantics "
                    "for active-site localization rather than runtime or "
                    "coordinate availability."
                ),
            },
        ],
        "commands": {
            "reproduce_this_manifest": (
                "PYTHONPATH=src python -m catalytic_earth.cli "
                "build-family-panel-source-free-predicted-geometry-sidecar-manifest"
            ),
            "validate_existing_fold_channel_contract": (
                "PYTHONPATH=src python -m catalytic_earth.cli "
                "audit-predicted-structure-fold-channel-contract"
            ),
            "refresh_source_backed_fold_materialization": (
                "PYTHONPATH=src python -m catalytic_earth.cli "
                "build-family-panel-source-backed-sidecar-materialization"
            ),
            "blocked_scoring_prerequisite": (
                "Create an approved source-free active-site locator sidecar with "
                "entry_id, accession, sequence positions, residue roles, and "
                "coordinate-independent provenance; then run the existing "
                "AlphaFoldDB predicted-geometry feature builder over those "
                "locator rows and pass the resulting retrieval into the "
                "family-panel packet/readout refresh commands."
            ),
        },
        "source_artifacts": {
            "source_backed_sidecar_materialization": _source_path_record(
                source_backed_materialization_path
            ),
            "predicted_geometry_atlas": _source_path_record(
                predicted_geometry_atlas_path
            ),
            "label_manifest": _source_path_record(label_manifest_path),
            "missing_primary_channel_diagnosis": (
                _source_path_record(missing_primary_channel_diagnosis_path)
                if missing_primary_channel_diagnosis_path is not None
                and Path(missing_primary_channel_diagnosis_path).exists()
                else None
            ),
            "active_site_locator_schema_audit": (
                _source_path_record(locator_schema_audit_path)
                if locator_schema_audit_path is not None
                and Path(locator_schema_audit_path).exists()
                else None
            ),
        },
        "interpretation": {
            "headline": (
                f"{len(rows_with_fold)}/{len(row_manifests)} rows have source-backed "
                "fold scores and AFDB coordinate hashes; "
                f"{len(ready_rows)} now have approved source-free active-site "
                f"locators and {len(blocked_rows)} remain blocked before "
                "predicted-geometry scoring."
            ),
            "next_action": (
                "Run predicted-geometry retrieval only for ready rows using the "
                "approved locator sidecars; do not promote rows or use source-backed "
                "review prose as scoring input."
            ),
        },
    }


def _render_family_panel_source_free_predicted_geometry_sidecar_manifest_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    lines = [
        "# Family Panel Source-Free Predicted-Geometry Sidecar Manifest - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Targeted rows: {counts['targeted_rows']}",
        f"- Rows with AFDB predicted CIFs: {counts['rows_with_afdb_predicted_cif']}",
        f"- Rows with source-backed fold scores: {counts['rows_with_source_backed_fold_score']}",
        (
            "- Rows with approved source-free active-site locator: "
            f"{counts.get('rows_with_approved_source_free_active_site_locator', 0)}"
        ),
        f"- Source-free geometry ready rows: {counts['source_free_geometry_ready_rows']}",
        f"- Source-free geometry blocked rows: {counts['source_free_geometry_blocked_rows']}",
        f"- Blocker counts: {counts['blocker_counts']}",
        "",
        "## Rows",
        "",
        "| rank | row | accession | AFDB CIF | fold TM | source-free geometry status | blockers |",
        "| ---: | --- | --- | --- | ---: | --- | --- |",
    ]
    for row in audit["row_manifests"]:
        afdb = row.get("alphafolddb_predicted_cif") or {}
        fold = row.get("source_backed_fold_score") or {}
        lines.append(
            f"| {row['rank']} | {row['entry_id']} | {row['source_accession']} | "
            f"{afdb.get('exists')} | {fold.get('nearest_atlas_tm_score')} | "
            f"{row['source_free_predicted_geometry_status']} | "
            f"{', '.join(row['blockers'])} |"
        )
    lines += [
        "",
        "## Blocker-Clearing Attempts",
        "",
    ]
    for attempt in audit["blocker_clearing_attempts"]:
        lines.append(f"- {attempt['attempt']}: {attempt['result']}")
    lines += [
        "",
        "## Commands",
        "",
        "```bash",
        audit["commands"]["reproduce_this_manifest"],
        "```",
        "",
        "```bash",
        audit["commands"]["validate_existing_fold_channel_contract"],
        "```",
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_family_panel_source_free_predicted_geometry_sidecar_manifest(
    *,
    source_backed_materialization_path: Path,
    predicted_geometry_atlas_path: Path,
    label_manifest_path: Path,
    out_path: Path,
    report_path: Path | None = None,
    locator_schema_audit_path: Path | None = None,
    missing_primary_channel_diagnosis_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_family_panel_source_free_predicted_geometry_sidecar_manifest(
        source_backed_materialization_path=source_backed_materialization_path,
        predicted_geometry_atlas_path=predicted_geometry_atlas_path,
        label_manifest_path=label_manifest_path,
        locator_schema_audit_path=locator_schema_audit_path,
        missing_primary_channel_diagnosis_path=missing_primary_channel_diagnosis_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_family_panel_source_free_predicted_geometry_sidecar_manifest_report(
                audit
            ),
            encoding="utf-8",
        )
    return audit


def _clean_source_accession(value: Any) -> str:
    text = str(value or "").strip()
    if text.startswith("uniprot:"):
        return text.split(":", 1)[1]
    return text


def _source_backed_materialization_rows_by_entry(
    materialization: dict[str, Any],
) -> dict[str, dict[str, Any]]:
    return {
        str(row.get("entry_id") or ""): row
        for row in materialization.get("row_scores", [])
        if isinstance(row, dict) and row.get("entry_id")
    }


def _locator_schema_ready_entry_ids(schema_audit: dict[str, Any]) -> set[str]:
    return {
        str(row.get("entry_id") or "")
        for row in schema_audit.get("row_audits", [])
        if isinstance(row, dict)
        and row.get("entry_id")
        and row.get("ready_for_predicted_geometry_scoring")
    }


def _locator_sidecars_by_entry(locator_dir: Path) -> dict[str, dict[str, Any]]:
    out: dict[str, dict[str, Any]] = {}
    if not locator_dir.exists():
        return out
    for path in sorted(locator_dir.glob("*.json")):
        try:
            payload = _read_json(path)
        except json.JSONDecodeError:
            continue
        entry_id = str(payload.get("entry_id") or "")
        if entry_id:
            out[entry_id] = {"path": str(path), "payload": payload}
    return out


def _afdb_coordinate_record(row: dict[str, Any]) -> dict[str, Any] | None:
    for record in row.get("coordinate_records", []):
        if (
            isinstance(record, dict)
            and record.get("coordinate_role") == "alphafolddb_predicted_cif"
        ):
            return record
    return None


def _source_free_locator_roles(locator: dict[str, Any]) -> list[str]:
    roles: list[str] = []
    role_hint = str(locator.get("role_hint") or "").strip()
    if role_hint:
        roles.append(role_hint)
    evidence_class = str(locator.get("locator_evidence_class") or "").strip()
    if evidence_class:
        roles.append(evidence_class)
    return roles or ["source_free_contact_candidate"]


def _source_free_predicted_geometry_failed_entry(
    *,
    manifest_row: dict[str, Any],
    materialization_row: dict[str, Any],
    locator_sidecar_path: Path,
    locator_sidecar: dict[str, Any],
    accession: str,
    reason: str,
) -> dict[str, Any]:
    entry_id = str(manifest_row.get("entry_id") or locator_sidecar.get("entry_id") or "")
    return {
        "entry_id": entry_id,
        "entry_name": None,
        "accession": accession,
        "sequence_id": accession,
        "benchmark_role": None,
        "split_assignment": "review_only_family_panel",
        "status": reason,
        "experimental_pdb_id": materialization_row.get("selected_structure_id"),
        "pdb_id": None,
        "predicted_structure_source": {},
        "source_free_locator_sidecar": {
            "path": str(locator_sidecar_path),
            "sha256": _sha256(locator_sidecar_path)
            if locator_sidecar_path.exists()
            else None,
        },
        "residue_count": len(locator_sidecar.get("residue_locators", []) or []),
        "resolved_residue_count": 0,
        "missing_positions": len(locator_sidecar.get("residue_locators", []) or []),
        "missing_position_details": [],
        "residues": [],
        "pairwise_distances_angstrom": [],
        "ligand_context": {
            "distance_cutoff_angstrom": 6.0,
            "proximal_ligands": [],
            "ligand_codes": [],
            "cofactor_families": [],
            "structure_ligands": [],
            "structure_ligand_codes": [],
            "structure_cofactor_families": [],
        },
        "pocket_context": {
            "distance_cutoff_angstrom": 8.0,
            "nearby_residue_count": 0,
            "nearby_residue_sites": [],
            "descriptors": {},
        },
        "mechanism_text_count": 0,
        "mechanism_text_snippets": [],
    }


def _source_free_predicted_geometry_entry_from_locator(
    *,
    manifest_row: dict[str, Any],
    materialization_row: dict[str, Any],
    locator_sidecar_path: Path,
    locator_sidecar: dict[str, Any],
) -> dict[str, Any]:
    entry_id = str(manifest_row.get("entry_id") or locator_sidecar.get("entry_id") or "")
    coord = _afdb_coordinate_record(materialization_row)
    accession = _clean_source_accession(
        locator_sidecar.get("source_accession")
        or manifest_row.get("source_accession")
        or materialization_row.get("source_accession")
    )
    if coord is None:
        return _source_free_predicted_geometry_failed_entry(
            manifest_row=manifest_row,
            materialization_row=materialization_row,
            locator_sidecar_path=locator_sidecar_path,
            locator_sidecar=locator_sidecar,
            accession=accession,
            reason="alphafolddb_predicted_cif_record_missing",
        )
    coord_path = Path(str(coord.get("path") or ""))
    if not coord.get("exists") or not coord_path.exists():
        return _source_free_predicted_geometry_failed_entry(
            manifest_row=manifest_row,
            materialization_row=materialization_row,
            locator_sidecar_path=locator_sidecar_path,
            locator_sidecar=locator_sidecar,
            accession=accession,
            reason="alphafolddb_predicted_cif_file_missing",
        )

    text = coord_path.read_text(encoding="utf-8", errors="replace")
    atoms = parse_atom_site_loop(text)
    residue_locators = [
        row
        for row in locator_sidecar.get("residue_locators", [])
        if isinstance(row, dict)
    ]
    resolved: list[dict[str, Any]] = []
    missing_details: list[dict[str, Any]] = []
    for index, locator in enumerate(residue_locators, start=1):
        item = {
            "residue_node_id": f"{entry_id}:source_free_locator:{index}",
            "chain_name": None,
            "resid": str(locator.get("sequence_position") or ""),
            "code": locator.get("residue_code"),
        }
        residue_atoms = select_residue_atoms(
            atoms,
            chain_name=None,
            resid=item["resid"],
            code=item.get("code"),
        )
        if not residue_atoms:
            missing_details.append(missing_position_detail(atoms, item))
            continue
        resolved.append(
            {
                "residue_node_id": item["residue_node_id"],
                "code": str(locator.get("residue_code") or "").upper(),
                "chain_name": None,
                "resid": item["resid"],
                "atom_count": len(residue_atoms),
                "centroid": residue_centroid(residue_atoms),
                "ca": atom_position(residue_atoms, "CA"),
                "roles": _source_free_locator_roles(locator),
                "sequence_position_uniprot_id": accession or None,
                "locator_evidence_class": locator.get("locator_evidence_class"),
                "locator_confidence": locator.get("locator_confidence"),
            }
        )
    pairwise = pairwise_distances(resolved)
    status = "ok" if len(resolved) >= 2 else "insufficient_resolved_residues"
    return {
        "entry_id": entry_id,
        "entry_name": None,
        "accession": accession,
        "sequence_id": accession,
        "benchmark_role": None,
        "split_assignment": "review_only_family_panel",
        "status": status,
        "experimental_pdb_id": materialization_row.get("selected_structure_id"),
        "pdb_id": coord_path.stem,
        "predicted_structure_source": {
            "backend": "alphafold_db_local_cif",
            "path": str(coord_path),
            "sha256": coord.get("sha256") or _sha256(coord_path),
            "size_bytes": coord.get("size_bytes") or coord_path.stat().st_size,
            "raw_coordinates_committed": True,
            "coordinate_record_role": coord.get("coordinate_role"),
        },
        "source_free_locator_sidecar": {
            "path": str(locator_sidecar_path),
            "sha256": _sha256(locator_sidecar_path),
            "locator_evidence_class": locator_sidecar.get("locator_evidence_class"),
            "locator_policy": locator_sidecar.get("locator_policy"),
            "manual_review_approval": locator_sidecar.get("manual_review_approval"),
        },
        "residue_count": len(residue_locators),
        "resolved_residue_count": len(resolved),
        "missing_positions": len(residue_locators) - len(resolved),
        "missing_position_details": missing_details,
        "residues": resolved,
        "pairwise_distances_angstrom": pairwise,
        "ligand_context": ligand_context_from_atoms(atoms, resolved),
        "pocket_context": pocket_context_from_atoms(atoms, resolved),
        "mechanism_text_count": 0,
        "mechanism_text_snippets": [],
        "coordinate_swap": {
            "from": "human_approved_source_free_sequence_position_locators",
            "to": "alphafold_db_local_uniprot_model",
            "sequence_positions_used": True,
            "structure_positions_used_for_predicted_model": False,
            "source_text_used": False,
            "entry_names_used_for_score": False,
            "labels_used_for_score": False,
        },
    }


def _fixed_combined_mean_geometry_fold_threshold(
    threshold_contract: dict[str, Any] | None,
) -> float | None:
    if not threshold_contract:
        return None
    selected = (
        threshold_contract.get("threshold_contract", {})
        .get("combined_mean_geometry_fold", {})
        .get("selected_at_90pct_calibration_in_scope_retention_max_oos_abstain", {})
    )
    threshold = selected.get("threshold")
    try:
        return float(threshold)
    except (TypeError, ValueError):
        return None


def _source_free_geometry_result_rows(
    *,
    retrieval: dict[str, Any],
    geometry_entries: list[dict[str, Any]],
    manifest_rows_by_entry: dict[str, dict[str, Any]],
    materialization_rows_by_entry: dict[str, dict[str, Any]],
    fixed_threshold: float | None,
) -> list[dict[str, Any]]:
    entries_by_entry = {
        str(row.get("entry_id") or ""): row
        for row in geometry_entries
        if row.get("entry_id")
    }
    rows: list[dict[str, Any]] = []
    for retrieval_row in retrieval.get("results", []):
        entry_id = str(retrieval_row.get("entry_id") or "")
        entry = entries_by_entry.get(entry_id, {})
        manifest_row = manifest_rows_by_entry.get(entry_id, {})
        materialization_row = materialization_rows_by_entry.get(entry_id, {})
        fold = materialization_row.get("predicted_structure_fold_channel", {})
        top = (retrieval_row.get("top_fingerprints") or [{}])[0]
        top1_score = top.get("score")
        fold_score = fold.get("nearest_atlas_tm_score")
        combined = None
        retained = None
        if top1_score is not None and fold_score is not None:
            combined = round((float(top1_score) + float(fold_score)) / 2.0, 4)
            retained = (
                None
                if fixed_threshold is None
                else bool(combined >= fixed_threshold)
            )
        rows.append(
            {
                "entry_id": entry_id,
                "rank": manifest_row.get("rank"),
                "panel_id": manifest_row.get("panel_id"),
                "source_accession": manifest_row.get("source_accession")
                or materialization_row.get("source_accession"),
                "predicted_geometry_status": retrieval_row.get("status"),
                "resolved_residue_count": entry.get("resolved_residue_count"),
                "source_free_locator_sidecar": entry.get("source_free_locator_sidecar"),
                "predicted_geometry_retrieval": {
                    "top1_fingerprint_id": top.get("fingerprint_id"),
                    "top1_score": top1_score,
                    "top1_role_match_fraction": top.get("role_match_fraction"),
                    "top1_cofactor_context_score": top.get("cofactor_context_score"),
                    "top1_cofactor_evidence_level": top.get(
                        "cofactor_evidence_level"
                    ),
                    "top_fingerprints": retrieval_row.get("top_fingerprints", []),
                },
                "predicted_structure_fold_channel": fold or None,
                "fold_augmented_projection": {
                    "combined_mean_geometry_fold": combined,
                    "fixed_research_threshold": fixed_threshold,
                    "retained_at_fixed_research_threshold": retained,
                    "threshold_source": (
                        "v3_fold_augmented_abstention_threshold_contract_oos_calibrated_current702_20260601"
                        if fixed_threshold is not None
                        else None
                    ),
                },
                "guardrail_note": (
                    "review-only source-free predicted geometry retrieval; "
                    "panel_id, rank, and source rows are carried only as review "
                    "context and not used by the retrieval scorer"
                ),
            }
        )
    return sorted(rows, key=lambda row: int(row.get("rank") or 999999))


def build_family_panel_source_free_predicted_geometry_retrieval(
    *,
    source_free_geometry_manifest_path: Path,
    source_backed_materialization_path: Path,
    locator_schema_audit_path: Path,
    locator_dir: Path,
    threshold_contract_path: Path | None = None,
) -> dict[str, Any]:
    manifest = _read_json(source_free_geometry_manifest_path)
    materialization = _read_json(source_backed_materialization_path)
    schema_audit = _read_json(locator_schema_audit_path)
    threshold_contract = (
        _read_json(threshold_contract_path)
        if threshold_contract_path is not None and threshold_contract_path.exists()
        else None
    )
    fixed_threshold = _fixed_combined_mean_geometry_fold_threshold(threshold_contract)
    materialization_by_entry = _source_backed_materialization_rows_by_entry(
        materialization
    )
    schema_ready_ids = _locator_schema_ready_entry_ids(schema_audit)
    sidecars_by_entry = _locator_sidecars_by_entry(locator_dir)

    manifest_rows = [
        row
        for row in manifest.get("row_manifests", [])
        if isinstance(row, dict) and row.get("entry_id")
    ]
    manifest_by_entry = {str(row["entry_id"]): row for row in manifest_rows}
    ready_rows = [
        row
        for row in manifest_rows
        if row.get("source_free_predicted_geometry_status")
        == "ready_to_score_source_free_predicted_geometry"
    ]
    geometry_entries: list[dict[str, Any]] = []
    blocked_rows: list[dict[str, Any]] = []
    for row in ready_rows:
        entry_id = str(row.get("entry_id") or "")
        if entry_id not in schema_ready_ids:
            blocked_rows.append(
                {
                    "entry_id": entry_id,
                    "rank": row.get("rank"),
                    "blockers": ["locator_schema_audit_not_ready"],
                }
            )
            continue
        materialization_row = materialization_by_entry.get(entry_id)
        if materialization_row is None:
            blocked_rows.append(
                {
                    "entry_id": entry_id,
                    "rank": row.get("rank"),
                    "blockers": ["source_backed_materialization_row_missing"],
                }
            )
            continue
        sidecar_record = sidecars_by_entry.get(entry_id)
        if sidecar_record is None:
            blocked_rows.append(
                {
                    "entry_id": entry_id,
                    "rank": row.get("rank"),
                    "blockers": ["approved_source_free_locator_sidecar_missing"],
                }
            )
            continue
        geometry_entries.append(
            _source_free_predicted_geometry_entry_from_locator(
                manifest_row=row,
                materialization_row=materialization_row,
                locator_sidecar_path=Path(sidecar_record["path"]),
                locator_sidecar=sidecar_record["payload"],
            )
        )

    retrieval = run_geometry_retrieval({"entries": geometry_entries})
    result_rows = _source_free_geometry_result_rows(
        retrieval=retrieval,
        geometry_entries=geometry_entries,
        manifest_rows_by_entry=manifest_by_entry,
        materialization_rows_by_entry=materialization_by_entry,
        fixed_threshold=fixed_threshold,
    )
    ok_rows = [row for row in result_rows if row["predicted_geometry_status"] == "ok"]
    retained_rows = [
        row
        for row in ok_rows
        if row["fold_augmented_projection"].get(
            "retained_at_fixed_research_threshold"
        )
        is True
    ]
    not_retained_rows = [
        row
        for row in ok_rows
        if row["fold_augmented_projection"].get(
            "retained_at_fixed_research_threshold"
        )
        is False
    ]
    existing_blocked_rows = [
        {
            "entry_id": row.get("entry_id"),
            "rank": row.get("rank"),
            "source_accession": row.get("source_accession"),
            "blockers": row.get("blockers", []),
        }
        for row in manifest_rows
        if row.get("source_free_predicted_geometry_status")
        == "blocked_source_free_geometry_preconditions"
    ]
    status = (
        "source_free_predicted_geometry_retrieval_scored_review_only"
        if len(ok_rows) == len(ready_rows) and not blocked_rows
        else "source_free_predicted_geometry_retrieval_partial_review_only"
        if ok_rows
        else "source_free_predicted_geometry_retrieval_blocked_review_only"
    )
    return {
        "artifact_id": FAMILY_PANEL_SOURCE_FREE_PREDICTED_GEOMETRY_RETRIEVAL_ID,
        "schema_version": f"{SCHEMA_VERSION}.source_free_predicted_geometry_retrieval",
        "created_utc": _utc_now_iso(),
        "status": status,
        "scope": (
            "Review-only predicted active-site geometry retrieval for "
            "family-panel rows with approved source-free locator sidecars. "
            "The scorer uses only residue sequence positions/codes, generic "
            "source-free locator role hints, local AlphaFoldDB coordinates, "
            "and geometry-derived pocket/ligand context."
        ),
        "guardrails": {
            "review_only": True,
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "threshold_values_changed": False,
            "model_weights_fit_or_refit": False,
            "heldout_rows_used_for_training": False,
            "source_text_used_for_score": False,
            "entry_names_used_for_score": False,
            "ec_or_rhea_ids_used_for_score": False,
            "benchmark_roles_used_for_score": False,
            "panel_ids_used_for_score": False,
            "new_source_data_fetched": False,
            "raw_coordinates_downloaded": False,
        },
        "counts": {
            "manifest_target_rows": len(manifest_rows),
            "manifest_ready_to_score_rows": len(ready_rows),
            "locator_schema_ready_rows": len(schema_ready_ids),
            "retrieval_rows_emitted": len(result_rows),
            "predicted_geometry_ok_rows": len(ok_rows),
            "runtime_blocked_ready_rows": len(blocked_rows),
            "precondition_blocked_rows_carried": len(existing_blocked_rows),
            "retained_at_fixed_research_threshold": len(retained_rows),
            "abstained_at_fixed_research_threshold": len(not_retained_rows),
        },
        "predicted_geometry_features": {
            "metadata": {
                "artifact": "source_free_family_panel_predicted_geometry_features",
                "schema_version": "predicted_geometry_features.source_free_review.v1",
                "entry_count": len(geometry_entries),
                "ok_entry_count": sum(
                    1 for entry in geometry_entries if entry.get("status") == "ok"
                ),
                "source": "approved source-free locator sidecars plus local AFDB CIFs",
                "mechanism_text_snippets_used": False,
                "entry_names_used_for_score": False,
                "labels_used_for_score": False,
                "panel_ids_used_for_score": False,
            },
            "entries": geometry_entries,
        },
        "predicted_geometry_retrieval": retrieval,
        "row_scores": result_rows,
        "blocked_ready_rows": blocked_rows,
        "precondition_blocked_rows": existing_blocked_rows,
        "source_artifacts": {
            "source_free_predicted_geometry_manifest": _source_path_record(
                source_free_geometry_manifest_path
            ),
            "source_backed_materialization": _source_path_record(
                source_backed_materialization_path
            ),
            "locator_schema_audit": _source_path_record(locator_schema_audit_path),
            "locator_dir": str(locator_dir),
            "threshold_contract": (
                _source_path_record(threshold_contract_path)
                if threshold_contract_path is not None
                and threshold_contract_path.exists()
                else None
            ),
        },
        "interpretation": {
            "headline": (
                f"{len(ok_rows)}/{len(ready_rows)} ready rows now have "
                "source-free predicted-geometry retrieval scores."
            ),
            "fixed_threshold_projection": (
                f"{len(retained_rows)}/{len(ok_rows)} scored rows are retained "
                "by the existing combined_mean_geometry_fold research threshold."
                if fixed_threshold is not None
                else "No fixed research threshold artifact was provided."
            ),
            "next_action": (
                "Refresh the review-only family-panel readout to consume these "
                "source-free predicted-geometry scores, while keeping all rows "
                "non-importable and outside threshold selection."
            ),
        },
    }


def _render_family_panel_source_free_predicted_geometry_retrieval_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    lines = [
        "# Family Panel Source-Free Predicted-Geometry Retrieval - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Manifest target rows: {counts['manifest_target_rows']}",
        f"- Ready-to-score rows: {counts['manifest_ready_to_score_rows']}",
        f"- Retrieval rows emitted: {counts['retrieval_rows_emitted']}",
        f"- Predicted-geometry ok rows: {counts['predicted_geometry_ok_rows']}",
        "- Fixed-threshold retained/abstained: "
        f"{counts['retained_at_fixed_research_threshold']} / "
        f"{counts['abstained_at_fixed_research_threshold']}",
        "",
        "## Row Scores",
        "",
        "| rank | row | top1 fingerprint | geometry score | fold TM | combined mean | fixed-threshold status |",
        "| ---: | --- | --- | ---: | ---: | ---: | --- |",
    ]
    for row in audit["row_scores"]:
        retrieval = row["predicted_geometry_retrieval"]
        fold = row.get("predicted_structure_fold_channel") or {}
        projection = row["fold_augmented_projection"]
        retained = projection.get("retained_at_fixed_research_threshold")
        status = (
            "not_evaluated"
            if retained is None
            else ("retained" if retained else "abstained")
        )
        lines.append(
            f"| {row['rank']} | {row['entry_id']} | "
            f"{retrieval.get('top1_fingerprint_id')} | "
            f"{retrieval.get('top1_score')} | "
            f"{fold.get('nearest_atlas_tm_score')} | "
            f"{projection.get('combined_mean_geometry_fold')} | {status} |"
        )
    lines += [
        "",
        "## Blocked Rows Carried",
        "",
    ]
    for row in audit["precondition_blocked_rows"]:
        blockers = ", ".join(str(item) for item in row.get("blockers", []))
        lines.append(f"- {row.get('entry_id')}: {blockers}")
    if not audit["precondition_blocked_rows"]:
        lines.append("- none")
    lines += [
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['fixed_threshold_projection']}",
        f"- {audit['interpretation']['next_action']}",
        "",
        "## Guardrails",
        "",
        "- Review-only. No labels, registries, ontologies, imports, thresholds, training data, production scoring, source fetching, or coordinate downloads changed.",
    ]
    return "\n".join(lines) + "\n"


def write_family_panel_source_free_predicted_geometry_retrieval(
    *,
    source_free_geometry_manifest_path: Path,
    source_backed_materialization_path: Path,
    locator_schema_audit_path: Path,
    locator_dir: Path,
    out_path: Path,
    report_path: Path | None = None,
    threshold_contract_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_family_panel_source_free_predicted_geometry_retrieval(
        source_free_geometry_manifest_path=source_free_geometry_manifest_path,
        source_backed_materialization_path=source_backed_materialization_path,
        locator_schema_audit_path=locator_schema_audit_path,
        locator_dir=locator_dir,
        threshold_contract_path=threshold_contract_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_family_panel_source_free_predicted_geometry_retrieval_report(
                audit
            ),
            encoding="utf-8",
        )
    return audit


def _external_candidate_rows_by_key(external_panel: dict[str, Any]) -> dict[str, dict[str, Any]]:
    rows: dict[str, dict[str, Any]] = {}
    for row in external_panel.get("candidate_rows", []):
        if not isinstance(row, dict):
            continue
        row_id = str(row.get("row_id") or "")
        accession = _clean_source_accession(row.get("accession"))
        if row_id:
            rows[row_id] = row
        if accession:
            rows[accession] = row
            rows[f"uniprot:{accession}"] = row
    return rows


def _source_free_preflight_risk_flags(
    *,
    geometry_fp: str | None,
    fold_fp: str | None,
    external_row: dict[str, Any] | None,
    source_sidecar: dict[str, Any] | None,
) -> list[str]:
    flags = [
        "source_check_required_before_family_decision",
        "label_import_not_authorized",
    ]
    if geometry_fp and fold_fp and geometry_fp != fold_fp:
        flags.append("geometry_fold_fingerprint_disagreement")
    else:
        flags.append("geometry_fold_fingerprint_agreement_needs_duplicate_screen")
    if external_row:
        if not external_row.get("countable_label_candidate", False):
            flags.append("external_panel_row_not_countable")
        if external_row.get("current_v1_state"):
            flags.append(str(external_row["current_v1_state"]))
    if source_sidecar and not source_sidecar.get("predictive_use_allowed", False):
        flags.append("source_backed_sidecar_review_context_only")
    return sorted(set(flags))


def build_family_panel_source_free_predicted_geometry_source_check_preflight(
    *,
    source_check_queue_path: Path,
    source_free_predicted_geometry_retrieval_path: Path,
    source_backed_materialization_path: Path,
    external_metal_hydrolase_panel_path: Path | None = None,
) -> dict[str, Any]:
    queue = _read_json(source_check_queue_path)
    retrieval = _read_json(source_free_predicted_geometry_retrieval_path)
    materialization = _read_json(source_backed_materialization_path)
    external_panel = (
        _read_json(external_metal_hydrolase_panel_path)
        if external_metal_hydrolase_panel_path is not None
        and external_metal_hydrolase_panel_path.exists()
        else {}
    )
    queue_by_entry = {
        str(row.get("entry_id") or ""): row
        for row in queue.get("queue_rows", [])
        if isinstance(row, dict) and row.get("entry_id")
    }
    materialization_by_entry = _source_backed_materialization_rows_by_entry(
        materialization
    )
    external_by_key = _external_candidate_rows_by_key(external_panel)
    rows: list[dict[str, Any]] = []
    for scored_row in retrieval.get("row_scores", []):
        if not isinstance(scored_row, dict) or not scored_row.get("entry_id"):
            continue
        entry_id = str(scored_row["entry_id"])
        queue_row = queue_by_entry.get(entry_id, {})
        materialization_row = materialization_by_entry.get(entry_id, {})
        source_accession = str(
            scored_row.get("source_accession")
            or materialization_row.get("source_accession")
            or ""
        )
        accession = _clean_source_accession(source_accession)
        sidecar_path = Path(str(materialization_row.get("sidecar_path") or ""))
        source_sidecar = _read_json(sidecar_path) if sidecar_path.exists() else None
        external_row = (
            external_by_key.get(entry_id)
            or external_by_key.get(accession)
            or external_by_key.get(source_accession)
        )
        geometry = scored_row.get("predicted_geometry_retrieval") or {}
        fold = scored_row.get("predicted_structure_fold_channel") or {}
        geometry_fp = geometry.get("top1_fingerprint_id")
        fold_fp = fold.get("nearest_atlas_true_fingerprint_id")
        rows.append(
            {
                "rank": queue_row.get("rank"),
                "entry_id": entry_id,
                "panel_id": scored_row.get("panel_id") or queue_row.get("panel_id"),
                "source_accession": source_accession,
                "display_name": (
                    (source_sidecar or {}).get("display_name")
                    or (external_row or {}).get("name")
                ),
                "geometry_fold_agreement": bool(
                    geometry_fp and fold_fp and geometry_fp == fold_fp
                ),
                "predicted_geometry_top1_fingerprint_id": geometry_fp,
                "predicted_geometry_top1_score": geometry.get("top1_score"),
                "nearest_atlas_true_fingerprint_id": fold_fp,
                "nearest_atlas_tm_score": fold.get("nearest_atlas_tm_score"),
                "combined_mean_geometry_fold": (
                    scored_row.get("fold_augmented_projection") or {}
                ).get("combined_mean_geometry_fold"),
                "fixed_research_threshold": (
                    scored_row.get("fold_augmented_projection") or {}
                ).get("fixed_research_threshold"),
                "retained_at_fixed_research_threshold": (
                    scored_row.get("fold_augmented_projection") or {}
                ).get("retained_at_fixed_research_threshold"),
                "local_source_context": {
                    "source": (
                        "external_metal_hydrolase_tail_panel"
                        if external_row
                        else "source_backed_sidecar"
                    ),
                    "candidate_role": (external_row or {}).get("candidate_role"),
                    "current_v1_state": (external_row or {}).get("current_v1_state"),
                    "evidence_summary": (external_row or {}).get("evidence_summary"),
                    "metal_ligand_state": (external_row or {}).get(
                        "metal_ligand_state"
                    ),
                    "ligand_or_substrate_state": (external_row or {}).get(
                        "ligand_or_substrate_state"
                    ),
                    "source_backed_sidecar_status": (source_sidecar or {}).get(
                        "catalytic_or_binding_site_evidence", {}
                    ).get("status"),
                    "source_urls": (source_sidecar or {}).get("source_urls")
                    or (external_row or {}).get("source_urls"),
                },
                "preflight_decision": "hold_review_only_pending_source_check",
                "risk_flags": _source_free_preflight_risk_flags(
                    geometry_fp=geometry_fp,
                    fold_fp=fold_fp,
                    external_row=external_row,
                    source_sidecar=source_sidecar,
                ),
                "required_next_evidence": [
                    "row-specific source-backed bond-change and reaction locus",
                    "duplicate/leakage screen against current702 and source panels",
                    "cofactor or metal-locus evidence normalized outside source prose",
                    "expert family-admission decision before any label/import change",
                ],
            }
        )
    rows = sorted(rows, key=lambda row: int(row.get("rank") or 999999))
    agreement_rows = [row for row in rows if row["geometry_fold_agreement"]]
    status = (
        "source_free_predicted_geometry_source_check_preflight_ready_review_only"
        if rows
        else "source_free_predicted_geometry_source_check_preflight_blocked"
    )
    return {
        "artifact_id": FAMILY_PANEL_SOURCE_FREE_PREDICTED_GEOMETRY_SOURCE_CHECK_PREFLIGHT_ID,
        "schema_version": f"{SCHEMA_VERSION}.source_free_predicted_geometry_source_check_preflight",
        "created_utc": _utc_now_iso(),
        "status": status,
        "scope": (
            "Review-only source-check preflight for the family-panel rows that "
            "became non-abstained after approved source-free predicted-geometry "
            "scoring. This packages local frozen evidence and blockers; it does "
            "not adjudicate family membership."
        ),
        "guardrails": {
            "review_only": True,
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "threshold_values_changed": False,
            "new_source_data_fetched": False,
            "model_weights_fit_or_refit": False,
            "heldout_rows_used_for_training": False,
            "source_prose_used_for_predictive_scoring": False,
        },
        "counts": {
            "preflight_rows": len(rows),
            "geometry_fold_agreement_rows": len(agreement_rows),
            "geometry_fold_disagreement_rows": len(rows) - len(agreement_rows),
            "hold_review_only_rows": sum(
                1
                for row in rows
                if row["preflight_decision"]
                == "hold_review_only_pending_source_check"
            ),
        },
        "preflight_rows": rows,
        "source_artifacts": {
            "source_check_queue": _source_path_record(source_check_queue_path),
            "source_free_predicted_geometry_retrieval": _source_path_record(
                source_free_predicted_geometry_retrieval_path
            ),
            "source_backed_materialization": _source_path_record(
                source_backed_materialization_path
            ),
            "external_metal_hydrolase_panel": (
                _source_path_record(external_metal_hydrolase_panel_path)
                if external_metal_hydrolase_panel_path is not None
                and external_metal_hydrolase_panel_path.exists()
                else None
            ),
        },
        "interpretation": {
            "headline": (
                f"{len(rows)} newly scored source-free rows are queued for "
                "review-only source checks; none is import-ready."
            ),
            "next_action": (
                "Start with `mh_066` because it has the largest positive margin, "
                "then source-check `mh_073` and "
                "`secondary_probe::radical_sam_enzyme` for mechanism locus and "
                "duplicate/leakage status."
            ),
        },
    }


