def write_fold_augmented_oos_calibrated_threshold_contract(
    *,
    threshold_contract_path: Path,
    train_cal_oos_surface_path: Path,
    fold_augmented_gate_path: Path,
    out_path: Path,
    report_path: Path | None = None,
    artifact_id: str = FOLD_AUGMENTED_OOS_CALIBRATED_THRESHOLD_CONTRACT_ID,
) -> dict[str, Any]:
    audit = build_fold_augmented_oos_calibrated_threshold_contract(
        threshold_contract_path=threshold_contract_path,
        train_cal_oos_surface_path=train_cal_oos_surface_path,
        fold_augmented_gate_path=fold_augmented_gate_path,
        artifact_id=artifact_id,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_fold_augmented_oos_calibrated_threshold_contract_report(audit),
            encoding="utf-8",
        )
    return audit


def _cofactor_proxy_score(row: dict[str, Any]) -> float | None:
    channel_scores = row.get("channel_scores") or {}
    score = channel_scores.get("cofactor_max_score")
    if score is None:
        score = row.get("selected_organic_cofactor_max_score")
    if score is None:
        return None
    try:
        return float(score)
    except (TypeError, ValueError):
        return None


def _fixed_threshold_row_readout(
    rows: list[dict[str, Any]],
    *,
    channel_name: str,
    threshold: float,
) -> dict[str, Any]:
    scored_rows: list[dict[str, Any]] = []
    abstained = 0
    for row in rows:
        channel_scores = row.get("channel_scores") or {}
        if channel_name not in channel_scores:
            continue
        score = float(channel_scores[channel_name])
        abstains = score < threshold
        if abstains:
            abstained += 1
        fold = row.get("predicted_structure_fold_channel") or {}
        top1 = row.get("predicted_geometry_top1") or {}
        scored_rows.append(
            {
                "entry_id": row.get("entry_id"),
                "label_type": row.get("label_type"),
                "oos_tier": row.get("oos_tier"),
                "split_assignment": row.get("split_assignment"),
                "cofactor_proxy_score": _cofactor_proxy_score(row),
                channel_name: round(score, 6),
                "threshold_margin": round(score - threshold, 6),
                "abstains_at_fixed_threshold": abstains,
                "nearest_train_atlas_entry_id": fold.get("nearest_train_atlas_entry_id"),
                "nearest_train_atlas_true_fingerprint_id": fold.get(
                    "nearest_train_atlas_true_fingerprint_id"
                ),
                "predicted_geometry_top1_fingerprint_id": top1.get("fingerprint_id"),
            }
        )
    total = len(scored_rows)
    return {
        "threshold": round(threshold, 6),
        "row_count": total,
        "abstained": abstained,
        "retained": total - abstained,
        "abstain_recall": round(abstained / total, 4) if total else None,
        "retained_recall": round((total - abstained) / total, 4) if total else None,
        "rows": sorted(
            scored_rows,
            key=lambda row: (
                row["abstains_at_fixed_threshold"],
                row["threshold_margin"],
                str(row.get("entry_id")),
            ),
        ),
    }


def _selected_90pct_threshold_for_channel(
    threshold_contract: dict[str, Any],
    channel_name: str,
) -> float | None:
    channel = (threshold_contract.get("threshold_contract") or {}).get(channel_name) or {}
    selected = (
        channel.get("selected_at_90pct_calibration_in_scope_retention_max_oos_abstain")
        or {}
    )
    threshold = selected.get("threshold")
    if threshold is None:
        return None
    try:
        return float(threshold)
    except (TypeError, ValueError):
        return None


def build_fold_augmented_confounded_proxy_operating_point_audit(
    *,
    expanded_oos_calibrated_threshold_contract_path: Path,
    train_cal_oos_surface_path: Path,
    deployment_input_audit_path: Path,
    post_rerun_confounded_closure_path: Path,
    cofactor_proxy_threshold: float = COFACTOR_SIGNATURE_THRESHOLD,
    artifact_id: str = FOLD_AUGMENTED_CONFOUNDED_PROXY_OPERATING_POINT_AUDIT_ID,
) -> dict[str, Any]:
    threshold_contract = _read_json(expanded_oos_calibrated_threshold_contract_path)
    oos_surface = _read_json(train_cal_oos_surface_path)
    deployment_input = _read_json(deployment_input_audit_path)
    closure = _read_json(post_rerun_confounded_closure_path)

    primary = threshold_contract.get("primary_channel_readout") or {}
    selected = (
        primary.get("selected_at_90pct_calibration_in_scope_retention_max_oos_abstain")
        or {}
    )
    heldout = primary.get("heldout_final_eval_at_90pct_oos_calibrated_threshold") or {}
    channel_name = str(primary.get("channel") or "combined_mean_geometry_fold")
    fixed_threshold = selected.get("threshold") or heldout.get("threshold")
    blockers: list[str] = []
    if fixed_threshold is None:
        blockers.append("fixed_combined_mean_geometry_fold_threshold_missing")
        threshold_value = 0.0
    else:
        threshold_value = float(fixed_threshold)

    calibration_oos_rows = [
        row
        for row in oos_surface.get("candidate_row_scores", [])
        if isinstance(row, dict) and row.get("channel_scores")
    ]
    high_cofactor_rows = [
        row
        for row in calibration_oos_rows
        if (_cofactor_proxy_score(row) or 0.0) >= cofactor_proxy_threshold
    ]
    low_cofactor_rows = [
        row
        for row in calibration_oos_rows
        if (_cofactor_proxy_score(row) or 0.0) < cofactor_proxy_threshold
    ]
    fold_proxy_threshold = _selected_90pct_threshold_for_channel(
        threshold_contract, "fold_nearest_atlas_tm_score"
    )
    geometry_proxy_threshold = _selected_90pct_threshold_for_channel(
        threshold_contract, "geometry_top1_score"
    )
    structural_proxy_rows = []
    if fold_proxy_threshold is not None and geometry_proxy_threshold is not None:
        for row in calibration_oos_rows:
            channel_scores = row.get("channel_scores") or {}
            fold = channel_scores.get("fold_nearest_atlas_tm_score")
            geometry = channel_scores.get("geometry_top1_score")
            fold_channel = row.get("predicted_structure_fold_channel") or {}
            geometry_top1 = row.get("predicted_geometry_top1") or {}
            nearest_fp = fold_channel.get("nearest_train_atlas_true_fingerprint_id")
            top1_fp = geometry_top1.get("fingerprint_id")
            same_family = bool(nearest_fp and top1_fp and nearest_fp == top1_fp)
            if (
                same_family
                and fold is not None
                and geometry is not None
                and float(fold) >= fold_proxy_threshold
                and float(geometry) >= geometry_proxy_threshold
            ):
                structural_proxy_rows.append(row)
    if not calibration_oos_rows:
        blockers.append("no_calibration_oos_rows_available")
    if not high_cofactor_rows:
        blockers.append("no_high_cofactor_proxy_calibration_oos_rows_available")
    if fold_proxy_threshold is None or geometry_proxy_threshold is None:
        blockers.append("structural_proxy_component_thresholds_missing")
    if not structural_proxy_rows:
        blockers.append("no_same_family_structural_proxy_calibration_oos_rows_available")

    all_readout = _fixed_threshold_row_readout(
        calibration_oos_rows,
        channel_name=channel_name,
        threshold=threshold_value,
    )
    proxy_readout = _fixed_threshold_row_readout(
        high_cofactor_rows,
        channel_name=channel_name,
        threshold=threshold_value,
    )
    low_readout = _fixed_threshold_row_readout(
        low_cofactor_rows,
        channel_name=channel_name,
        threshold=threshold_value,
    )
    structural_readout = _fixed_threshold_row_readout(
        structural_proxy_rows,
        channel_name=channel_name,
        threshold=threshold_value,
    )
    deployment_counts = deployment_input.get("counts") or {}
    deployment_decision = deployment_input.get("decision") or {}
    deployment_validity = deployment_input.get("deployment_validity") or {}
    deployment_guardrails = deployment_input.get("guardrails") or {}
    deployment_input_passed = bool(
        deployment_input.get("status")
        == "predicted_structure_fold_channel_deployment_inputs_predicted_only"
        and deployment_decision.get("deployment_input_contract_passed")
        and int(deployment_counts.get("critical_violation_total") or 0) == 0
        and deployment_validity.get("predicted_structure_vs_atlas_only")
    )
    if not deployment_input_passed:
        blockers.append("deployment_input_contract_not_passing")

    closure_counts = closure.get("counts") or {}
    closure_decision = closure.get("decision") or {}
    heldout_confounded_ready = bool(
        closure_decision.get("confounded_subset_target_met_for_research")
    )
    in_scope_retention_ok = bool(
        closure_decision.get("in_scope_retention_ok_at_operating_point")
    )
    calibration_proxy_target_met = bool(
        proxy_readout["abstain_recall"] is not None
        and float(proxy_readout["abstain_recall"]) >= 0.80
    )
    if not calibration_proxy_target_met:
        blockers.append("calibration_high_cofactor_proxy_target_not_met")
    structural_proxy_target_met = bool(
        structural_readout["abstain_recall"] is not None
        and float(structural_readout["abstain_recall"]) >= 0.80
    )
    if not structural_proxy_target_met:
        blockers.append("calibration_same_family_structural_proxy_target_not_met")

    status = (
        "fold_augmented_confounded_proxy_operating_point_ready_with_proxy_caveat"
        if deployment_input_passed
        and heldout_confounded_ready
        and in_scope_retention_ok
        and fixed_threshold is not None
        else "fold_augmented_confounded_proxy_operating_point_blocked"
    )
    return {
        "artifact_id": artifact_id,
        "schema_version": (
            f"{SCHEMA_VERSION}.fold_augmented_confounded_proxy_operating_point_audit"
        ),
        "created_utc": _utc_now_iso(),
        "status": status,
        "scope": (
            "Leakage-safe Lever 3 audit for the fixed predicted-structure-vs-atlas "
            "fold operating point. It preserves the existing train/cal-selected "
            "combined_mean_geometry_fold threshold, stratifies only train/cal OOS "
            "negatives by the existing cofactor-signature proxy, and carries the "
            "already-frozen heldout confounded readout without selecting thresholds "
            "on heldout rows."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "model_weights_fit_or_refit": False,
            "threshold_selected_or_tuned": False,
            "threshold_values_changed": False,
            "threshold_selected_on_heldout": False,
            "heldout_rows_used_for_training_or_threshold_tuning": False,
            "heldout_metrics_read_from_existing_contract": True,
            "foldseek_or_tm_rerun_performed": False,
            "experimental_pdb_metadata_used_as_channel_input": bool(
                deployment_guardrails.get(
                    "experimental_pdb_metadata_used_as_channel_input"
                )
            ),
            "validation_only": True,
            "review_only": True,
        },
        "fixed_operating_point": {
            "channel": channel_name,
            "threshold": round(threshold_value, 6) if fixed_threshold is not None else None,
            "threshold_source": str(expanded_oos_calibrated_threshold_contract_path),
            "calibration_selection": selected,
            "heldout_final_readout": heldout,
        },
        "calibration_proxy_definition": {
            "cofactor_score_source": "channel_scores.cofactor_max_score or selected_organic_cofactor_max_score",
            "cofactor_proxy_threshold": cofactor_proxy_threshold,
            "proxy_rows_are_train_cal_oos_only": True,
            "proxy_rows_do_not_select_or_change_threshold": True,
            "target_for_flag_only": ">=0.80 abstain recall on high-cofactor train/cal OOS proxy rows",
        },
        "calibration_structural_proxy_definition": {
            "proxy": (
                "train/cal OOS rows whose predicted-geometry top1 fingerprint "
                "matches the nearest predicted-structure atlas fingerprint and "
                "whose geometry and fold component scores meet their existing "
                "90% calibration-retention thresholds"
            ),
            "geometry_top1_score_threshold": geometry_proxy_threshold,
            "fold_nearest_atlas_tm_score_threshold": fold_proxy_threshold,
            "proxy_rows_are_train_cal_oos_only": True,
            "proxy_rows_do_not_select_or_change_threshold": True,
            "target_for_flag_only": ">=0.80 abstain recall on same-family structural proxy rows",
        },
        "calibration_proxy_readout": {
            "all_calibration_oos": {
                key: value for key, value in all_readout.items() if key != "rows"
            },
            "high_cofactor_proxy_calibration_oos": {
                key: value for key, value in proxy_readout.items() if key != "rows"
            },
            "low_cofactor_calibration_oos": {
                key: value for key, value in low_readout.items() if key != "rows"
            },
            "same_family_structural_proxy_calibration_oos": {
                key: value for key, value in structural_readout.items() if key != "rows"
            },
            "high_cofactor_proxy_rows": proxy_readout["rows"],
            "same_family_structural_proxy_rows": structural_readout["rows"],
        },
        "deployment_input_contract": {
            "passed": deployment_input_passed,
            "status": deployment_input.get("status"),
            "critical_violation_total": deployment_counts.get("critical_violation_total"),
            "predicted_structure_vs_atlas_only": deployment_validity.get(
                "predicted_structure_vs_atlas_only"
            ),
            "row_score_rows": deployment_counts.get("row_score_rows"),
            "coordinate_request_rows": deployment_counts.get("coordinate_request_rows"),
        },
        "counts": {
            "calibration_oos_rows": len(calibration_oos_rows),
            "high_cofactor_proxy_calibration_oos_rows": len(high_cofactor_rows),
            "low_cofactor_calibration_oos_rows": len(low_cofactor_rows),
            "same_family_structural_proxy_calibration_oos_rows": len(
                structural_proxy_rows
            ),
            "high_cofactor_proxy_abstained_at_fixed_threshold": proxy_readout[
                "abstained"
            ],
            "same_family_structural_proxy_abstained_at_fixed_threshold": (
                structural_readout["abstained"]
            ),
            "all_calibration_oos_abstained_at_fixed_threshold": all_readout[
                "abstained"
            ],
            "heldout_confounded_oos_abstained": closure_counts.get(
                "heldout_confounded_oos_abstained"
            ),
            "heldout_confounded_oos_total": closure_counts.get(
                "heldout_confounded_oos_total"
            ),
            "heldout_in_scope_retained": heldout.get("heldout_in_scope_retained"),
            "heldout_in_scope_total": heldout.get("heldout_in_scope_total"),
            "remaining_combined_score_blocker_rows": closure_counts.get(
                "remaining_combined_score_blocker_rows"
            ),
            "critical_violation_total": len(blockers),
        },
        "blockers": blockers,
        "decision": {
            "fixed_threshold_preserved": True,
            "deployment_input_contract_passed": deployment_input_passed,
            "heldout_confounded_operating_point_met_from_existing_readout": (
                heldout_confounded_ready
            ),
            "in_scope_retention_ok_at_operating_point": in_scope_retention_ok,
            "calibration_high_cofactor_proxy_target_met": calibration_proxy_target_met,
            "calibration_same_family_structural_proxy_target_met": (
                structural_proxy_target_met
            ),
            "apply_or_change_threshold_now": False,
            "deployment_closed_now": False,
            "next_gate": (
                "Keep the fixed 0.44155 combined_mean_geometry_fold threshold "
                "unchanged. The heldout confounded operating point remains research-"
                "ready under predicted-only inputs, but the train/cal cofactor and "
                "same-family structural proxies do not by themselves meet a "
                "confounded-safe calibration target; "
                "deployment closure still needs the explicit P10746 caveat decision "
                "or an approved non-residue sidecar."
            ),
        },
        "source_artifacts": {
            "expanded_oos_calibrated_threshold_contract": _source_path_record(
                expanded_oos_calibrated_threshold_contract_path
            ),
            "train_cal_oos_surface": _source_path_record(train_cal_oos_surface_path),
            "deployment_input_audit": _source_path_record(deployment_input_audit_path),
            "post_rerun_confounded_closure": _source_path_record(
                post_rerun_confounded_closure_path
            ),
        },
        "interpretation": {
            "headline": (
                "The fixed fold operating point remains predicted-input-valid, "
                "but train/cal confounded-proxy abstention is weaker than the "
                "heldout confounded readout."
            ),
            "next_action": (
                "Do not tune on the six heldout confounded rows. Resolve the "
                "source-decision blocker for P10746, and if stronger deployable "
                "confounded calibration is required, add more reviewed train/cal "
                "confounded proxy rows rather than changing the threshold from heldout."
            ),
        },
    }


def _render_fold_augmented_confounded_proxy_operating_point_audit(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    fixed = audit["fixed_operating_point"]
    proxy = audit["calibration_proxy_readout"]
    decision = audit["decision"]
    lines = [
        "# Fold-Augmented Confounded Proxy Operating-Point Audit - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Blockers: {audit['blockers']}",
        f"- Fixed channel: {fixed['channel']}",
        f"- Fixed threshold: {fixed['threshold']}",
        "- Deployment input contract passed: "
        f"{decision['deployment_input_contract_passed']}",
        "- Heldout confounded operating point met: "
        f"{decision['heldout_confounded_operating_point_met_from_existing_readout']}",
        "- Calibration high-cofactor proxy target met: "
        f"{decision['calibration_high_cofactor_proxy_target_met']}",
        "- Calibration same-family structural proxy target met: "
        f"{decision['calibration_same_family_structural_proxy_target_met']}",
        "",
        "## Readout",
        "",
        "| subset | rows | abstained | abstain recall |",
        "| --- | ---: | ---: | ---: |",
    ]
    for name, readout in [
        ("all calibration OOS", proxy["all_calibration_oos"]),
        ("high-cofactor calibration OOS", proxy["high_cofactor_proxy_calibration_oos"]),
        ("low-cofactor calibration OOS", proxy["low_cofactor_calibration_oos"]),
        (
            "same-family structural proxy OOS",
            proxy["same_family_structural_proxy_calibration_oos"],
        ),
    ]:
        lines.append(
            f"| {name} | {readout['row_count']} | {readout['abstained']} | "
            f"{readout['abstain_recall']} |"
        )
    lines += [
        "",
        "## Heldout Carry-Through",
        "",
        "- Confounded OOS abstained: "
        f"{counts['heldout_confounded_oos_abstained']}/"
        f"{counts['heldout_confounded_oos_total']}",
        "- In-scope retained: "
        f"{counts['heldout_in_scope_retained']}/"
        f"{counts['heldout_in_scope_total']}",
        "",
        "## High-Cofactor Train/Cal Rows",
        "",
        "| entry | cofactor | score | margin | abstains | nearest atlas fingerprint | top1 geometry fingerprint |",
        "| --- | ---: | ---: | ---: | --- | --- | --- |",
    ]
    channel = fixed["channel"]
    for row in proxy["high_cofactor_proxy_rows"]:
        lines.append(
            f"| {row['entry_id']} | {row['cofactor_proxy_score']} | "
            f"{row[channel]} | {row['threshold_margin']} | "
            f"{row['abstains_at_fixed_threshold']} | "
            f"{row['nearest_train_atlas_true_fingerprint_id']} | "
            f"{row['predicted_geometry_top1_fingerprint_id']} |"
        )
    lines += [
        "",
        "## Same-Family Structural Train/Cal Rows",
        "",
        "| entry | cofactor | score | margin | abstains | nearest atlas fingerprint | top1 geometry fingerprint |",
        "| --- | ---: | ---: | ---: | --- | --- | --- |",
    ]
    for row in proxy["same_family_structural_proxy_rows"]:
        lines.append(
            f"| {row['entry_id']} | {row['cofactor_proxy_score']} | "
            f"{row[channel]} | {row['threshold_margin']} | "
            f"{row['abstains_at_fixed_threshold']} | "
            f"{row['nearest_train_atlas_true_fingerprint_id']} | "
            f"{row['predicted_geometry_top1_fingerprint_id']} |"
        )
    lines += [
        "",
        "## Decision",
        "",
        f"- Fixed threshold preserved: {decision['fixed_threshold_preserved']}",
        f"- Apply or change threshold now: {decision['apply_or_change_threshold_now']}",
        f"- Deployment closed now: {decision['deployment_closed_now']}",
        f"- Next gate: {decision['next_gate']}",
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_fold_augmented_confounded_proxy_operating_point_audit(
    *,
    expanded_oos_calibrated_threshold_contract_path: Path,
    train_cal_oos_surface_path: Path,
    deployment_input_audit_path: Path,
    post_rerun_confounded_closure_path: Path,
    out_path: Path,
    report_path: Path | None = None,
    cofactor_proxy_threshold: float = COFACTOR_SIGNATURE_THRESHOLD,
    artifact_id: str = FOLD_AUGMENTED_CONFOUNDED_PROXY_OPERATING_POINT_AUDIT_ID,
) -> dict[str, Any]:
    audit = build_fold_augmented_confounded_proxy_operating_point_audit(
        expanded_oos_calibrated_threshold_contract_path=(
            expanded_oos_calibrated_threshold_contract_path
        ),
        train_cal_oos_surface_path=train_cal_oos_surface_path,
        deployment_input_audit_path=deployment_input_audit_path,
        post_rerun_confounded_closure_path=post_rerun_confounded_closure_path,
        cofactor_proxy_threshold=cofactor_proxy_threshold,
        artifact_id=artifact_id,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_fold_augmented_confounded_proxy_operating_point_audit(audit),
            encoding="utf-8",
        )
    return audit


def _proxy_gap_priority(row: dict[str, Any]) -> str:
    margin = float(row.get("threshold_margin") or 0.0)
    proxy_membership = set(row.get("proxy_membership") or [])
    if "high_cofactor_signature_proxy" in proxy_membership:
        return "priority_1_high_cofactor_retained_proxy_gap"
    if margin >= 0.05:
        return "priority_2_hard_retained_structural_proxy_gap"
    return "priority_3_near_threshold_retained_structural_proxy_gap"


def build_fold_augmented_confounded_proxy_gap_targets(
    *,
    confounded_proxy_operating_point_audit_path: Path,
    artifact_id: str = FOLD_AUGMENTED_CONFOUNDED_PROXY_GAP_TARGETS_ID,
) -> dict[str, Any]:
    proxy_audit = _read_json(confounded_proxy_operating_point_audit_path)
    fixed = proxy_audit.get("fixed_operating_point") or {}
    readout = proxy_audit.get("calibration_proxy_readout") or {}
    high_cofactor_rows = [
        row
        for row in readout.get("high_cofactor_proxy_rows", [])
        if isinstance(row, dict)
    ]
    structural_rows = [
        row
        for row in readout.get("same_family_structural_proxy_rows", [])
        if isinstance(row, dict)
    ]
    by_entry: dict[str, dict[str, Any]] = {}
    for proxy_name, rows in [
        ("high_cofactor_signature_proxy", high_cofactor_rows),
        ("same_family_structural_proxy", structural_rows),
    ]:
        for row in rows:
            entry_id = str(row.get("entry_id") or "")
            if not entry_id or row.get("abstains_at_fixed_threshold"):
                continue
            item = by_entry.setdefault(
                entry_id,
                {
                    "entry_id": entry_id,
                    "cofactor_proxy_score": row.get("cofactor_proxy_score"),
                    "fixed_channel_score": row.get(fixed.get("channel")),
                    "threshold_margin": row.get("threshold_margin"),
                    "nearest_train_atlas_true_fingerprint_id": row.get(
                        "nearest_train_atlas_true_fingerprint_id"
                    ),
                    "predicted_geometry_top1_fingerprint_id": row.get(
                        "predicted_geometry_top1_fingerprint_id"
                    ),
                    "proxy_membership": [],
                },
            )
            if proxy_name not in item["proxy_membership"]:
                item["proxy_membership"].append(proxy_name)
    retained_rows = []
    for row in by_entry.values():
        row["priority"] = _proxy_gap_priority(row)
        retained_rows.append(row)
    retained_rows.sort(
        key=lambda row: (
            row["priority"],
            -float(row.get("threshold_margin") or 0.0),
            row["entry_id"],
        )
    )
    priority_counts = Counter(row["priority"] for row in retained_rows)
    family_counts = Counter(
        row.get("nearest_train_atlas_true_fingerprint_id") or "missing"
        for row in retained_rows
    )
    return {
        "artifact_id": artifact_id,
        "schema_version": (
            f"{SCHEMA_VERSION}.fold_augmented_confounded_proxy_gap_targets"
        ),
        "created_utc": _utc_now_iso(),
        "status": (
            "fold_augmented_confounded_proxy_gap_targets_ready"
            if retained_rows
            else "fold_augmented_confounded_proxy_gap_targets_empty"
        ),
        "scope": (
            "Review-only Lever 3 packet of train/cal confounded-proxy rows that "
            "are retained by the fixed predicted-structure-vs-atlas fold operating "
            "point. It is derived from the proxy audit and does not read heldout "
            "rows or select a threshold."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "model_weights_fit_or_refit": False,
            "threshold_selected_or_tuned": False,
            "threshold_values_changed": False,
            "heldout_rows_read_now": False,
            "heldout_rows_used_for_training_or_threshold_tuning": False,
            "foldseek_or_tm_rerun_performed": False,
            "validation_only": True,
            "review_only": True,
        },
        "fixed_operating_point": fixed,
        "counts": {
            "retained_proxy_gap_rows": len(retained_rows),
            "high_cofactor_retained_proxy_gap_rows": sum(
                1
                for row in retained_rows
                if "high_cofactor_signature_proxy" in row["proxy_membership"]
            ),
            "same_family_structural_retained_proxy_gap_rows": sum(
                1
                for row in retained_rows
                if "same_family_structural_proxy" in row["proxy_membership"]
            ),
            "priority_counts": dict(sorted(priority_counts.items())),
            "nearest_family_counts": dict(sorted(family_counts.items())),
        },
        "retained_proxy_gap_rows": retained_rows,
        "decision": {
            "apply_or_change_threshold_now": False,
            "deployment_closed_now": False,
            "gap_targets_are_train_cal_only": True,
            "next_gate": (
                "Use these retained train/cal proxy rows to design or review "
                "additional calibration-confounded proxy evidence. Do not adjust "
                "the fixed operating threshold from these rows without rerunning "
                "the full train/cal contract, and do not tune on heldout."
            ),
        },
        "source_artifacts": {
            "confounded_proxy_operating_point_audit": _source_path_record(
                confounded_proxy_operating_point_audit_path
            ),
        },
        "interpretation": {
            "headline": (
                f"{len(retained_rows)} train/cal confounded-proxy rows are retained "
                "at the fixed fold operating point and define the next calibration "
                "gap surface."
            ),
            "next_action": (
                "Prioritize high-cofactor retained gaps first, then hard retained "
                "same-family structural gaps with the largest positive margins."
            ),
        },
    }


def _render_fold_augmented_confounded_proxy_gap_targets(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    fixed = audit["fixed_operating_point"]
    lines = [
        "# Fold-Augmented Confounded Proxy Gap Targets - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Fixed channel: {fixed.get('channel')}",
        f"- Fixed threshold: {fixed.get('threshold')}",
        f"- Retained proxy gap rows: {counts['retained_proxy_gap_rows']}",
        "- High-cofactor retained proxy gaps: "
        f"{counts['high_cofactor_retained_proxy_gap_rows']}",
        "- Same-family structural retained proxy gaps: "
        f"{counts['same_family_structural_retained_proxy_gap_rows']}",
        "",
        "## Priority Counts",
        "",
    ]
    for key, value in counts["priority_counts"].items():
        lines.append(f"- {key}: {value}")
    lines += [
        "",
        "## Retained Gap Rows",
        "",
        "| priority | entry | margin | score | proxies | nearest fingerprint | top1 fingerprint |",
        "| --- | --- | ---: | ---: | --- | --- | --- |",
    ]
    for row in audit["retained_proxy_gap_rows"]:
        lines.append(
            f"| {row['priority']} | {row['entry_id']} | "
            f"{row['threshold_margin']} | {row['fixed_channel_score']} | "
            f"{', '.join(row['proxy_membership'])} | "
            f"{row['nearest_train_atlas_true_fingerprint_id']} | "
            f"{row['predicted_geometry_top1_fingerprint_id']} |"
        )
    lines += [
        "",
        "## Decision",
        "",
        f"- Apply or change threshold now: {audit['decision']['apply_or_change_threshold_now']}",
        f"- Deployment closed now: {audit['decision']['deployment_closed_now']}",
        f"- Next gate: {audit['decision']['next_gate']}",
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_fold_augmented_confounded_proxy_gap_targets(
    *,
    confounded_proxy_operating_point_audit_path: Path,
    out_path: Path,
    report_path: Path | None = None,
    artifact_id: str = FOLD_AUGMENTED_CONFOUNDED_PROXY_GAP_TARGETS_ID,
) -> dict[str, Any]:
    audit = build_fold_augmented_confounded_proxy_gap_targets(
        confounded_proxy_operating_point_audit_path=(
            confounded_proxy_operating_point_audit_path
        ),
        artifact_id=artifact_id,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_fold_augmented_confounded_proxy_gap_targets(audit),
            encoding="utf-8",
        )
    return audit


def _channel_scores_from_rows(rows: list[dict[str, Any]], channel_name: str) -> list[float]:
    scores: list[float] = []
    for row in rows:
        if channel_name in row:
            value = row.get(channel_name)
        else:
            value = (row.get("channel_scores") or {}).get(channel_name)
        if value is None:
            continue
        scores.append(float(value))
    return scores


def _threshold_stress_for_target(
    *,
    in_scope_scores: list[float],
    proxy_scores: list[float],
    target_abstain_recall: float,
) -> dict[str, Any] | None:
    if not in_scope_scores or not proxy_scores:
        return None
    candidates = sorted({round(score, 6) for score in in_scope_scores + proxy_scores})
    for threshold in candidates:
        proxy_abstained = sum(1 for score in proxy_scores if score < threshold)
        proxy_recall = proxy_abstained / len(proxy_scores)
        if proxy_recall < target_abstain_recall:
            continue
        retained = sum(1 for score in in_scope_scores if score >= threshold)
        retain_recall = retained / len(in_scope_scores)
        return {
            "threshold": threshold,
            "target_abstain_recall": target_abstain_recall,
            "proxy_abstain_recall": round(proxy_recall, 4),
            "proxy_abstained": proxy_abstained,
            "proxy_total": len(proxy_scores),
            "calibration_in_scope_retain_recall": round(retain_recall, 4),
            "calibration_in_scope_retained": retained,
            "calibration_in_scope_total": len(in_scope_scores),
        }
    return None


def build_fold_augmented_confounded_proxy_threshold_stress(
    *,
    train_cal_threshold_contract_path: Path,
    expanded_oos_calibrated_threshold_contract_path: Path,
    confounded_proxy_operating_point_audit_path: Path,
    artifact_id: str = FOLD_AUGMENTED_CONFOUNDED_PROXY_THRESHOLD_STRESS_ID,
) -> dict[str, Any]:
    train_cal = _read_json(train_cal_threshold_contract_path)
    expanded = _read_json(expanded_oos_calibrated_threshold_contract_path)
    proxy = _read_json(confounded_proxy_operating_point_audit_path)
    fixed = proxy.get("fixed_operating_point") or {}
    channel_name = str(fixed.get("channel") or "combined_mean_geometry_fold")
    fixed_threshold = fixed.get("threshold")
    calibration_in_scope_rows = [
        row
        for row in train_cal.get("calibration_row_scores", [])
        if isinstance(row, dict)
    ]
    in_scope_scores = _channel_scores_from_rows(calibration_in_scope_rows, channel_name)
    readout = proxy.get("calibration_proxy_readout") or {}
    proxy_sets = {
        "high_cofactor_signature_proxy": readout.get("high_cofactor_proxy_rows", []),
        "same_family_structural_proxy": readout.get(
            "same_family_structural_proxy_rows", []
        ),
        "all_expanded_calibration_oos": expanded.get(
            "calibration_oos_negative_row_scores", []
        ),
    }
    targets = [0.50, 0.80, 1.00]
    stress: dict[str, Any] = {}
    for name, rows in proxy_sets.items():
        row_list = [row for row in rows if isinstance(row, dict)]
        scores = _channel_scores_from_rows(row_list, channel_name)
        current_abstained = (
            sum(1 for score in scores if fixed_threshold is not None and score < float(fixed_threshold))
            if scores
            else 0
        )
        stress[name] = {
            "row_count": len(scores),
            "current_fixed_threshold": fixed_threshold,
            "current_fixed_threshold_abstained": current_abstained,
            "current_fixed_threshold_abstain_recall": (
                round(current_abstained / len(scores), 4) if scores else None
            ),
            "counterfactual_targets": {
                str(target): _threshold_stress_for_target(
                    in_scope_scores=in_scope_scores,
                    proxy_scores=scores,
                    target_abstain_recall=target,
                )
                for target in targets
            },
        }
    structural_80 = (
        stress.get("same_family_structural_proxy", {})
        .get("counterfactual_targets", {})
        .get("0.8")
    )
    high_80 = (
        stress.get("high_cofactor_signature_proxy", {})
        .get("counterfactual_targets", {})
        .get("0.8")
    )
    blockers = []
    if not in_scope_scores:
        blockers.append("no_calibration_in_scope_scores_available")
    if structural_80 and float(structural_80["calibration_in_scope_retain_recall"]) < 0.85:
        blockers.append("structural_proxy_80pct_abstain_breaks_85pct_in_scope_retention")
    if high_80 and float(high_80["calibration_in_scope_retain_recall"]) < 0.90:
        blockers.append("high_cofactor_proxy_80pct_abstain_breaks_90pct_in_scope_retention")
    return {
        "artifact_id": artifact_id,
        "schema_version": (
            f"{SCHEMA_VERSION}.fold_augmented_confounded_proxy_threshold_stress"
        ),
        "created_utc": _utc_now_iso(),
        "status": (
            "fold_augmented_confounded_proxy_threshold_stress_ready"
            if in_scope_scores
            else "fold_augmented_confounded_proxy_threshold_stress_blocked"
        ),
        "scope": (
            "Train/cal-only counterfactual threshold stress for Lever 3 confounded "
            "proxy rows. It reports the in-scope retention cost of forcing proxy "
            "abstention targets, without changing the fixed operating threshold "
            "or reading heldout rows."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "model_weights_fit_or_refit": False,
            "threshold_selected_or_tuned": False,
            "threshold_values_changed": False,
            "counterfactual_thresholds_computed_not_applied": True,
            "heldout_rows_read_now": False,
            "heldout_rows_used_for_training_or_threshold_tuning": False,
            "foldseek_or_tm_rerun_performed": False,
            "validation_only": True,
            "review_only": True,
        },
        "fixed_operating_point": fixed,
        "counts": {
            "calibration_in_scope_rows": len(in_scope_scores),
            "high_cofactor_proxy_rows": stress["high_cofactor_signature_proxy"][
                "row_count"
            ],
            "same_family_structural_proxy_rows": stress[
                "same_family_structural_proxy"
            ]["row_count"],
            "all_expanded_calibration_oos_rows": stress[
                "all_expanded_calibration_oos"
            ]["row_count"],
            "blockers": len(blockers),
        },
        "blockers": blockers,
        "threshold_stress": stress,
        "decision": {
            "apply_or_change_threshold_now": False,
            "deployment_closed_now": False,
            "structural_proxy_80pct_abstain_retention_ok": bool(
                structural_80
                and float(structural_80["calibration_in_scope_retain_recall"]) >= 0.85
            ),
            "high_cofactor_proxy_80pct_abstain_retention_ok": bool(
                high_80
                and float(high_80["calibration_in_scope_retain_recall"]) >= 0.90
            ),
            "next_gate": (
                "Do not raise the fixed threshold from heldout behavior. The "
                "train/cal stress shows whether proxy abstention targets can be "
                "met while preserving calibration in-scope retention; use it to "
                "decide whether more train/cal proxy evidence is needed."
            ),
        },
        "source_artifacts": {
            "train_cal_threshold_contract": _source_path_record(
                train_cal_threshold_contract_path
            ),
            "expanded_oos_calibrated_threshold_contract": _source_path_record(
                expanded_oos_calibrated_threshold_contract_path
            ),
            "confounded_proxy_operating_point_audit": _source_path_record(
                confounded_proxy_operating_point_audit_path
            ),
        },
        "interpretation": {
            "headline": (
                "Counterfactual proxy-abstention thresholds are not adopted; "
                "they expose the train/cal retention cost of stricter confounded "
                "proxy behavior."
            ),
            "next_action": (
                "If the retention cost is unacceptable, add or review more "
                "train/cal confounded proxy rows rather than changing the fixed "
                "operating point from heldout readout."
            ),
        },
    }


def _render_fold_augmented_confounded_proxy_threshold_stress(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    fixed = audit["fixed_operating_point"]
    lines = [
        "# Fold-Augmented Confounded Proxy Threshold Stress - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Blockers: {audit['blockers']}",
        f"- Fixed channel: {fixed.get('channel')}",
        f"- Fixed threshold: {fixed.get('threshold')}",
        f"- Calibration in-scope rows: {counts['calibration_in_scope_rows']}",
        "",
        "## Stress",
        "",
        "| subset | rows | fixed abstain | target | counterfactual threshold | proxy abstain | in-scope retain |",
        "| --- | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for name, stress in audit["threshold_stress"].items():
        for target, row in stress["counterfactual_targets"].items():
            row = row or {}
            lines.append(
                f"| {name} | {stress['row_count']} | "
                f"{stress['current_fixed_threshold_abstain_recall']} | "
                f"{target} | {row.get('threshold')} | "
                f"{row.get('proxy_abstain_recall')} | "
                f"{row.get('calibration_in_scope_retain_recall')} |"
            )
    lines += [
        "",
        "## Decision",
        "",
        f"- Apply or change threshold now: {audit['decision']['apply_or_change_threshold_now']}",
        "- Structural proxy 80% abstain retention ok: "
        f"{audit['decision']['structural_proxy_80pct_abstain_retention_ok']}",
        "- High-cofactor proxy 80% abstain retention ok: "
        f"{audit['decision']['high_cofactor_proxy_80pct_abstain_retention_ok']}",
        f"- Next gate: {audit['decision']['next_gate']}",
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_fold_augmented_confounded_proxy_threshold_stress(
    *,
    train_cal_threshold_contract_path: Path,
    expanded_oos_calibrated_threshold_contract_path: Path,
    confounded_proxy_operating_point_audit_path: Path,
    out_path: Path,
    report_path: Path | None = None,
    artifact_id: str = FOLD_AUGMENTED_CONFOUNDED_PROXY_THRESHOLD_STRESS_ID,
) -> dict[str, Any]:
    audit = build_fold_augmented_confounded_proxy_threshold_stress(
        train_cal_threshold_contract_path=train_cal_threshold_contract_path,
        expanded_oos_calibrated_threshold_contract_path=(
            expanded_oos_calibrated_threshold_contract_path
        ),
        confounded_proxy_operating_point_audit_path=(
            confounded_proxy_operating_point_audit_path
        ),
        artifact_id=artifact_id,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_fold_augmented_confounded_proxy_threshold_stress(audit),
            encoding="utf-8",
        )
    return audit


def _additional_abstained_rows_needed(
    *,
    row_count: int,
    abstained: int,
    target_recall: float,
) -> int | None:
    if target_recall < 0.0 or target_recall > 1.0:
        raise ValueError(f"target_recall must be between 0 and 1: {target_recall}")
    if row_count <= 0:
        return 0
    current = abstained / row_count
    if current >= target_recall:
        return 0
    if target_recall >= 1.0:
        return None
    needed = (target_recall * row_count - abstained) / (1.0 - target_recall)
    return max(0, int(math.ceil(needed - 1e-12)))


def _evidence_axis_for_confounded_proxy_gap(row: dict[str, Any]) -> dict[str, Any]:
    priority = str(row.get("priority") or "")
    proxies = set(row.get("proxy_membership") or [])
    if "high_cofactor_signature_proxy" in proxies or priority.startswith("priority_1"):
        return {
            "axis": "high_cofactor_confounded_proxy_extension",
            "recommended_action": (
                "Add or review train/cal OOS rows with source-free organic-cofactor "
                "locus evidence and rerun the proxy audit at the fixed threshold."
            ),
            "allowed_evidence": [
                "source-free cofactor locus sidecar",
                "approved non-residue interaction sidecar",
                "predicted-structure-vs-atlas channel scores",
            ],
        }
    if priority.startswith("priority_2"):
        return {
            "axis": "hard_same_family_structural_counteraxis",
            "recommended_action": (
                "Prioritize source-free active-site counteraxis review for hard "
                "metal-hydrolase-like structural mimics before any threshold rerun."
            ),
            "allowed_evidence": [
                "predicted-structure-vs-atlas channel scores",
                "source-free local metal or cofactor topology sidecar",
                "approved active-site non-residue interaction sidecar",
            ],
        }
    return {
        "axis": "near_threshold_same_family_structural_counteraxis",
        "recommended_action": (
            "Hold for secondary review after hard retained structural gaps unless "
            "the row is cheap to source-free annotate."
        ),
        "allowed_evidence": [
            "predicted-structure-vs-atlas channel scores",
            "source-free local topology sidecar",
        ],
    }


def _proxy_extension_requirement(
    *,
    name: str,
    readout: dict[str, Any],
    target_recalls: list[float],
) -> dict[str, Any]:
    row_count = int(readout.get("row_count") or 0)
    abstained = int(readout.get("abstained") or 0)
    return {
        "proxy": name,
        "row_count": row_count,
        "abstained_at_fixed_threshold": abstained,
        "current_abstain_recall": readout.get("abstain_recall"),
        "minimum_new_abstained_rows_if_all_new_rows_abstain": {
            str(target): _additional_abstained_rows_needed(
                row_count=row_count,
                abstained=abstained,
                target_recall=target,
            )
            for target in target_recalls
        },
        "assumption": (
            "Minimums assume every added train/cal proxy row abstains at the "
            "unchanged fixed threshold; mixed added rows require more evidence."
        ),
    }


def _confounded_proxy_current_surface_pool(
    *,
    train_cal_oos_surface: dict[str, Any],
    channel_name: str,
    fixed_threshold: float | None,
    cofactor_threshold: float,
    fold_threshold: float | None,
    geometry_threshold: float | None,
    high_proxy_rows: int,
    structural_proxy_rows: int,
) -> dict[str, Any]:
    rows = [
        row
        for row in train_cal_oos_surface.get("candidate_row_scores", [])
        if isinstance(row, dict) and isinstance(row.get("channel_scores"), dict)
    ]
    scored_rows = []
    for row in rows:
        channel_scores = row.get("channel_scores") or {}
        score = channel_scores.get(channel_name)
        if score is None:
            continue
        fold_score = channel_scores.get("fold_nearest_atlas_tm_score")
        geometry_score = channel_scores.get("geometry_top1_score")
        fold = row.get("predicted_structure_fold_channel") or {}
        geometry_top1 = row.get("predicted_geometry_top1") or {}
        nearest_fp = fold.get("nearest_train_atlas_true_fingerprint_id")
        top1_fp = geometry_top1.get("fingerprint_id")
        same_family = bool(nearest_fp and top1_fp and nearest_fp == top1_fp)
        strict_structural = bool(
            same_family
            and fold_threshold is not None
            and geometry_threshold is not None
            and fold_score is not None
            and geometry_score is not None
            and float(fold_score) >= fold_threshold
            and float(geometry_score) >= geometry_threshold
        )
        cofactor_score = _cofactor_proxy_score(row)
        high_cofactor = (cofactor_score or 0.0) >= cofactor_threshold
        abstained = (
            bool(float(score) < fixed_threshold) if fixed_threshold is not None else False
        )
        threshold_margin = (
            round(float(score) - fixed_threshold, 6)
            if fixed_threshold is not None
            else None
        )
        scored_rows.append(
            {
                "entry_id": row.get("entry_id"),
                "combined_score": round(float(score), 6),
                "threshold_margin": threshold_margin,
                "fold_nearest_atlas_tm_score": (
                    round(float(fold_score), 6) if fold_score is not None else None
                ),
                "geometry_top1_score": (
                    round(float(geometry_score), 6)
                    if geometry_score is not None
                    else None
                ),
                "cofactor_proxy_score": (
                    round(float(cofactor_score), 6)
                    if cofactor_score is not None
                    else None
                ),
                "nearest_train_atlas_true_fingerprint_id": nearest_fp,
                "predicted_geometry_top1_fingerprint_id": top1_fp,
                "same_family": same_family,
                "strict_structural": strict_structural,
                "high_cofactor": high_cofactor,
                "abstained": abstained,
            }
        )

    def _count(predicate: Callable[[dict[str, Any]], bool]) -> int:
        return sum(1 for row in scored_rows if predicate(row))

    high_rows = _count(lambda row: bool(row["high_cofactor"]))
    high_abstained = _count(
        lambda row: bool(row["high_cofactor"]) and bool(row["abstained"])
    )
    same_family_rows = _count(lambda row: bool(row["same_family"]))
    same_family_abstained = _count(
        lambda row: bool(row["same_family"]) and bool(row["abstained"])
    )
    strict_rows = _count(lambda row: bool(row["strict_structural"]))
    strict_abstained = _count(
        lambda row: bool(row["strict_structural"]) and bool(row["abstained"])
    )

    def _sort_pool_rows(pool_rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
        return sorted(
            pool_rows,
            key=lambda row: (
                not bool(row["abstained"]),
                -abs(float(row.get("threshold_margin") or 0.0)),
                str(row.get("entry_id") or ""),
            ),
        )

    return {
        "train_cal_oos_scored_rows": len(scored_rows),
        "fixed_threshold": fixed_threshold,
        "high_cofactor_rows_at_current_threshold": high_rows,
        "high_cofactor_abstained_at_fixed_threshold": high_abstained,
        "high_cofactor_rows": _sort_pool_rows(
            [row for row in scored_rows if row["high_cofactor"]]
        ),
        "unused_high_cofactor_rows_in_current_surface": max(
            0, high_rows - high_proxy_rows
        ),
        "same_family_rows_without_component_thresholds": same_family_rows,
        "same_family_abstained_without_component_thresholds": same_family_abstained,
        "same_family_abstain_recall_without_component_thresholds": (
            round(same_family_abstained / same_family_rows, 4)
            if same_family_rows
            else None
        ),
        "strict_same_family_structural_rows": strict_rows,
        "strict_same_family_structural_abstained": strict_abstained,
        "additional_same_family_rows_if_component_thresholds_loosened": max(
            0, same_family_rows - structural_proxy_rows
        ),
        "same_family_extra_rows_if_component_thresholds_loosened": _sort_pool_rows(
            [
                row
                for row in scored_rows
                if row["same_family"] and not row["strict_structural"]
            ]
        ),
        "current_surface_can_satisfy_high_cofactor_80pct_without_new_rows": (
            bool(high_rows and high_abstained / high_rows >= 0.8)
        ),
        "current_surface_can_satisfy_structural_80pct_by_loosened_membership": (
            bool(same_family_rows and same_family_abstained / same_family_rows >= 0.8)
        ),
    }


def build_fold_augmented_confounded_proxy_evidence_extension_plan(
    *,
    confounded_proxy_operating_point_audit_path: Path,
    confounded_proxy_gap_targets_path: Path,
    confounded_proxy_threshold_stress_path: Path,
    train_cal_oos_surface_path: Path | None = None,
    target_recalls: list[float] | None = None,
    artifact_id: str = FOLD_AUGMENTED_CONFOUNDED_PROXY_EVIDENCE_EXTENSION_PLAN_ID,
) -> dict[str, Any]:
    proxy = _read_json(confounded_proxy_operating_point_audit_path)
    gaps = _read_json(confounded_proxy_gap_targets_path)
    stress = _read_json(confounded_proxy_threshold_stress_path)
    train_cal_oos_surface = (
        _read_json(train_cal_oos_surface_path)
        if train_cal_oos_surface_path is not None
        and Path(train_cal_oos_surface_path).exists()
        else {}
    )
    targets = target_recalls or [0.50, 0.80]

    readout = proxy.get("calibration_proxy_readout") or {}
    requirements = {
        "high_cofactor_signature_proxy": _proxy_extension_requirement(
            name="high_cofactor_signature_proxy",
            readout=readout.get("high_cofactor_proxy_calibration_oos") or {},
            target_recalls=targets,
        ),
        "same_family_structural_proxy": _proxy_extension_requirement(
            name="same_family_structural_proxy",
            readout=(
                readout.get("same_family_structural_proxy_calibration_oos") or {}
            ),
            target_recalls=targets,
        ),
    }
    high_80_needed = requirements["high_cofactor_signature_proxy"][
        "minimum_new_abstained_rows_if_all_new_rows_abstain"
    ].get("0.8")
    structural_80_needed = requirements["same_family_structural_proxy"][
        "minimum_new_abstained_rows_if_all_new_rows_abstain"
    ].get("0.8")
    fixed = proxy.get("fixed_operating_point") or {}
    fixed_threshold = fixed.get("threshold")
    fixed_threshold_float = (
        float(fixed_threshold) if fixed_threshold is not None else None
    )
    cofactor_definition = proxy.get("calibration_proxy_definition") or {}
    structural_definition = proxy.get("calibration_structural_proxy_definition") or {}
    cofactor_threshold = float(
        cofactor_definition.get("cofactor_proxy_threshold")
        if cofactor_definition.get("cofactor_proxy_threshold") is not None
        else COFACTOR_SIGNATURE_THRESHOLD
    )
    fold_threshold = structural_definition.get("fold_nearest_atlas_tm_score_threshold")
    geometry_threshold = structural_definition.get("geometry_top1_score_threshold")
    current_surface_pool = (
        _confounded_proxy_current_surface_pool(
            train_cal_oos_surface=train_cal_oos_surface,
            channel_name=str(fixed.get("channel") or "combined_mean_geometry_fold"),
            fixed_threshold=fixed_threshold_float,
            cofactor_threshold=cofactor_threshold,
            fold_threshold=(
                float(fold_threshold) if fold_threshold is not None else None
            ),
            geometry_threshold=(
                float(geometry_threshold) if geometry_threshold is not None else None
            ),
            high_proxy_rows=requirements["high_cofactor_signature_proxy"]["row_count"],
            structural_proxy_rows=requirements["same_family_structural_proxy"][
                "row_count"
            ],
        )
        if train_cal_oos_surface
        else None
    )
    channel_name = str(fixed.get("channel") or "combined_mean_geometry_fold")
    current_surface_unscored_rows = []
    if train_cal_oos_surface:
        for row in train_cal_oos_surface.get("candidate_row_scores", []):
            if not isinstance(row, dict):
                continue
            channel_scores = row.get("channel_scores")
            if isinstance(channel_scores, dict) and channel_name in channel_scores:
                continue
            fold = row.get("predicted_structure_fold_channel") or {}
            current_surface_unscored_rows.append(
                {
                    "entry_id": row.get("entry_id"),
                    "accession": row.get("accession"),
                    "predicted_geometry_status": row.get(
                        "predicted_geometry_status"
                    ),
                    "nearest_train_atlas_entry_id": fold.get(
                        "nearest_train_atlas_entry_id"
                    ),
                    "nearest_train_atlas_tm_score": fold.get(
                        "nearest_train_atlas_tm_score"
                    ),
                    "nearest_train_atlas_true_fingerprint_id": fold.get(
                        "nearest_train_atlas_true_fingerprint_id"
                    ),
                }
            )

    retained_rows = [
        row
        for row in gaps.get("retained_proxy_gap_rows", [])
        if isinstance(row, dict)
    ]
    evidence_request_rows = []
    for row in retained_rows:
        axis = _evidence_axis_for_confounded_proxy_gap(row)
        evidence_request_rows.append(
            {
                "entry_id": row.get("entry_id"),
                "priority": row.get("priority"),
                "proxy_membership": row.get("proxy_membership") or [],
                "fixed_channel_score": row.get("fixed_channel_score"),
                "threshold_margin": row.get("threshold_margin"),
                "nearest_train_atlas_true_fingerprint_id": row.get(
                    "nearest_train_atlas_true_fingerprint_id"
                ),
                "predicted_geometry_top1_fingerprint_id": row.get(
                    "predicted_geometry_top1_fingerprint_id"
                ),
                **axis,
            }
        )
    priority_counts = Counter(str(row.get("priority") or "missing") for row in retained_rows)
    axis_counts = Counter(str(row.get("axis") or "missing") for row in evidence_request_rows)

    blockers = []
    if high_80_needed:
        blockers.append(
            "high_cofactor_proxy_needs_"
            f"{high_80_needed}_more_abstained_train_cal_rows_at_fixed_threshold"
        )
    if structural_80_needed:
        blockers.append(
            "same_family_structural_proxy_needs_"
            f"{structural_80_needed}_more_abstained_train_cal_rows_at_fixed_threshold"
        )
    for blocker in stress.get("blockers") or []:
        blockers.append(f"threshold_stress::{blocker}")
    if not retained_rows:
        blockers.append("no_retained_proxy_gap_rows_available")
    if current_surface_pool:
        if not current_surface_pool[
            "current_surface_can_satisfy_high_cofactor_80pct_without_new_rows"
        ]:
            blockers.append("current_train_cal_surface_lacks_high_cofactor_proxy_scale")
        if not current_surface_pool[
            "current_surface_can_satisfy_structural_80pct_by_loosened_membership"
        ]:
            blockers.append(
                "current_train_cal_surface_cannot_reach_structural_proxy_80pct_by_loosened_membership"
            )

    extension_ready = not blockers
    return {
        "artifact_id": artifact_id,
        "schema_version": (
            f"{SCHEMA_VERSION}.fold_augmented_confounded_proxy_evidence_extension_plan"
        ),
        "created_utc": _utc_now_iso(),
        "status": (
            "fold_augmented_confounded_proxy_evidence_extension_plan_ready"
            if retained_rows
            else "fold_augmented_confounded_proxy_evidence_extension_plan_blocked"
        ),
        "scope": (
            "Train/cal-only Lever 3 plan for extending confounded proxy evidence "
            "after the fixed predicted-structure-vs-atlas operating point failed "
            "to meet proxy calibration targets. It estimates how much additional "
            "proxy evidence would be needed at the unchanged threshold and maps "
            "retained proxy gaps to source-free evidence axes."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "model_weights_fit_or_refit": False,
            "threshold_selected_or_tuned": False,
            "threshold_values_changed": False,
            "heldout_rows_read_now": False,
            "heldout_rows_used_for_training_or_threshold_tuning": False,
            "mechanism_text_ec_rhea_source_ids_or_names_used_as_features": False,
            "experimental_pdb_metadata_used_as_channel_input": False,
            "train_cal_oos_surface_read_for_pool_scout": bool(current_surface_pool),
            "evidence_request_only": True,
            "review_only": True,
        },
        "fixed_operating_point": fixed,
        "extension_requirements": requirements,
        "current_surface_pool": current_surface_pool,
        "current_surface_unscored_candidate_rows": current_surface_unscored_rows,
        "evidence_request_rows": evidence_request_rows,
        "counts": {
            "retained_proxy_gap_rows": len(retained_rows),
            "evidence_request_rows": len(evidence_request_rows),
            "priority_counts": dict(sorted(priority_counts.items())),
            "axis_counts": dict(sorted(axis_counts.items())),
            "high_cofactor_min_new_abstained_rows_for_80pct": high_80_needed,
            "same_family_structural_min_new_abstained_rows_for_80pct": (
                structural_80_needed
            ),
            "threshold_stress_blockers": len(stress.get("blockers") or []),
            "current_surface_train_cal_oos_scored_rows": (
                current_surface_pool["train_cal_oos_scored_rows"]
                if current_surface_pool
                else 0
            ),
            "current_surface_unused_high_cofactor_rows": (
                current_surface_pool["unused_high_cofactor_rows_in_current_surface"]
                if current_surface_pool
                else 0
            ),
            "current_surface_additional_same_family_rows_if_loosened": (
                current_surface_pool[
                    "additional_same_family_rows_if_component_thresholds_loosened"
                ]
                if current_surface_pool
                else 0
            ),
            "current_surface_unscored_candidate_rows": len(
                current_surface_unscored_rows
            ),
            "blockers": len(blockers),
        },
        "blockers": blockers,
        "decision": {
            "apply_or_change_threshold_now": False,
            "deployment_closed_now": False,
            "evidence_extension_ready_for_threshold_rerun": extension_ready,
            "minimums_assume_all_new_proxy_rows_abstain": True,
            "next_gate": (
                "Do not raise the fixed threshold. Add or review train/cal "
                "confounded proxy rows beyond the currently scored surface on "
                "the evidence axes listed here, then rerun the proxy operating-"
                "point audit and threshold stress. Independently resolve the "
                "P10746 caveat or approved non-residue sidecar before claiming "
                "deployment closure."
            ),
        },
        "source_artifacts": {
            "confounded_proxy_operating_point_audit": _source_path_record(
                confounded_proxy_operating_point_audit_path
            ),
            "confounded_proxy_gap_targets": _source_path_record(
                confounded_proxy_gap_targets_path
            ),
            "confounded_proxy_threshold_stress": _source_path_record(
                confounded_proxy_threshold_stress_path
            ),
            "train_cal_oos_surface": (
                _source_path_record(train_cal_oos_surface_path)
                if train_cal_oos_surface_path is not None
                else {"path": None, "exists": False, "sha256": None}
            ),
        },
        "interpretation": {
            "headline": (
                "At the unchanged fixed threshold, proxy calibration needs more "
                "train/cal evidence rather than a higher deployment threshold."
            ),
            "next_action": (
                "Start with the one high-cofactor retained gap, then the hard "
                "same-family structural retained gaps; the current train/cal "
                "surface has no unused high-cofactor pool and loose same-family "
                "membership still misses the 80% target, so new proxy evidence "
                "is required before a rerun can close the calibration claim."
            ),
        },
    }


def _render_fold_augmented_confounded_proxy_evidence_extension_plan(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    fixed = audit["fixed_operating_point"]
    lines = [
        "# Fold-Augmented Confounded Proxy Evidence Extension Plan - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Blockers: {audit['blockers']}",
        f"- Fixed channel: {fixed.get('channel')}",
        f"- Fixed threshold: {fixed.get('threshold')}",
        "- Retained proxy gaps: "
        f"{counts['retained_proxy_gap_rows']}",
        "- High-cofactor minimum new abstained rows for 80%: "
        f"{counts['high_cofactor_min_new_abstained_rows_for_80pct']}",
        "- Same-family structural minimum new abstained rows for 80%: "
        f"{counts['same_family_structural_min_new_abstained_rows_for_80pct']}",
        "- Current-surface unused high-cofactor rows: "
        f"{counts.get('current_surface_unused_high_cofactor_rows')}",
        "- Current-surface additional same-family rows if loosened: "
        f"{counts.get('current_surface_additional_same_family_rows_if_loosened')}",
        "- Current-surface unscored candidate rows: "
        f"{counts.get('current_surface_unscored_candidate_rows')}",
        "",
        "## Extension Requirements",
        "",
        "| proxy | rows | fixed abstained | current recall | min new abstained @50% | min new abstained @80% |",
        "| --- | ---: | ---: | ---: | ---: | ---: |",
    ]
    for requirement in audit["extension_requirements"].values():
        additions = requirement["minimum_new_abstained_rows_if_all_new_rows_abstain"]
        lines.append(
            f"| {requirement['proxy']} | {requirement['row_count']} | "
            f"{requirement['abstained_at_fixed_threshold']} | "
            f"{requirement['current_abstain_recall']} | "
            f"{additions.get('0.5')} | {additions.get('0.8')} |"
        )
    pool = audit.get("current_surface_pool")
    if pool:
        lines += [
            "",
            "## Current Surface Pool",
            "",
            "| pool | rows | abstained | recall/capacity |",
            "| --- | ---: | ---: | ---: |",
            "| high-cofactor rows | "
            f"{pool['high_cofactor_rows_at_current_threshold']} | "
            f"{pool['high_cofactor_abstained_at_fixed_threshold']} | "
            f"{pool['current_surface_can_satisfy_high_cofactor_80pct_without_new_rows']} |",
            "| same-family loose rows | "
            f"{pool['same_family_rows_without_component_thresholds']} | "
            f"{pool['same_family_abstained_without_component_thresholds']} | "
            f"{pool['same_family_abstain_recall_without_component_thresholds']} |",
            "| strict same-family structural rows | "
            f"{pool['strict_same_family_structural_rows']} | "
            f"{pool['strict_same_family_structural_abstained']} | "
            f"{pool['additional_same_family_rows_if_component_thresholds_loosened']} |",
            "",
            "### Current Surface High-Cofactor Rows",
            "",
            "| entry | score | margin | abstains | nearest fingerprint | top1 fingerprint |",
            "| --- | ---: | ---: | --- | --- | --- |",
        ]
        for row in pool.get("high_cofactor_rows", []):
            lines.append(
                f"| {row['entry_id']} | {row['combined_score']} | "
                f"{row['threshold_margin']} | {row['abstained']} | "
                f"{row['nearest_train_atlas_true_fingerprint_id']} | "
                f"{row['predicted_geometry_top1_fingerprint_id']} |"
            )
        lines += [
            "",
            "### Current Surface Same-Family Extras If Loosened",
            "",
            "| entry | score | margin | abstains | fold | geometry | fingerprint |",
            "| --- | ---: | ---: | --- | ---: | ---: | --- |",
        ]
        for row in pool.get("same_family_extra_rows_if_component_thresholds_loosened", []):
            lines.append(
                f"| {row['entry_id']} | {row['combined_score']} | "
                f"{row['threshold_margin']} | {row['abstained']} | "
                f"{row['fold_nearest_atlas_tm_score']} | "
                f"{row['geometry_top1_score']} | "
                f"{row['nearest_train_atlas_true_fingerprint_id']} |"
            )
    unscored = audit.get("current_surface_unscored_candidate_rows") or []
    if unscored:
        lines += [
            "",
            "### Current Surface Unscored Candidates",
            "",
            "| entry | accession | geometry status | nearest atlas | nearest fingerprint | tm |",
            "| --- | --- | --- | --- | --- | ---: |",
        ]
        for row in unscored:
            lines.append(
                f"| {row['entry_id']} | {row['accession']} | "
                f"{row['predicted_geometry_status']} | "
                f"{row['nearest_train_atlas_entry_id']} | "
                f"{row['nearest_train_atlas_true_fingerprint_id']} | "
                f"{row['nearest_train_atlas_tm_score']} |"
            )
    lines += [
        "",
        "## Evidence Requests",
        "",
        "| priority | entry | margin | axis | nearest fingerprint | top1 fingerprint |",
        "| --- | --- | ---: | --- | --- | --- |",
    ]
    for row in audit["evidence_request_rows"]:
        lines.append(
            f"| {row['priority']} | {row['entry_id']} | "
            f"{row['threshold_margin']} | {row['axis']} | "
            f"{row['nearest_train_atlas_true_fingerprint_id']} | "
            f"{row['predicted_geometry_top1_fingerprint_id']} |"
        )
    lines += [
        "",
        "## Decision",
        "",
        f"- Apply or change threshold now: {audit['decision']['apply_or_change_threshold_now']}",
        f"- Deployment closed now: {audit['decision']['deployment_closed_now']}",
        "- Evidence extension ready for threshold rerun: "
        f"{audit['decision']['evidence_extension_ready_for_threshold_rerun']}",
        f"- Next gate: {audit['decision']['next_gate']}",
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_fold_augmented_confounded_proxy_evidence_extension_plan(
    *,
    confounded_proxy_operating_point_audit_path: Path,
    confounded_proxy_gap_targets_path: Path,
    confounded_proxy_threshold_stress_path: Path,
    train_cal_oos_surface_path: Path | None = None,
    out_path: Path,
    report_path: Path | None = None,
    artifact_id: str = FOLD_AUGMENTED_CONFOUNDED_PROXY_EVIDENCE_EXTENSION_PLAN_ID,
) -> dict[str, Any]:
    audit = build_fold_augmented_confounded_proxy_evidence_extension_plan(
        confounded_proxy_operating_point_audit_path=(
            confounded_proxy_operating_point_audit_path
        ),
        confounded_proxy_gap_targets_path=confounded_proxy_gap_targets_path,
        confounded_proxy_threshold_stress_path=confounded_proxy_threshold_stress_path,
        train_cal_oos_surface_path=train_cal_oos_surface_path,
        artifact_id=artifact_id,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_fold_augmented_confounded_proxy_evidence_extension_plan(audit),
            encoding="utf-8",
        )
    return audit


def _fold_augmented_confounded_priority_rows(
    fold_channel: dict[str, Any],
) -> list[dict[str, Any]]:
    parsed = fold_channel.get("parsed_foldseek_results") or {}
    priority = parsed.get("priority_cofactor_confounded_oos_vs_atlas") or {}
    hits = priority.get("nearest_atlas_hits") or []
    rows = []
    for hit in hits:
        if not isinstance(hit, dict) or not hit.get("query_entry_id"):
            continue
        rows.append(
            {
                "entry_id": str(hit.get("query_entry_id")),
                "nearest_atlas_entry_id": hit.get("nearest_atlas_entry_id"),
                "nearest_atlas_true_fingerprint_id": (
                    hit.get("nearest_atlas_true_fingerprint_id")
                ),
                "nearest_atlas_tm_score": hit.get("tm_score"),
            }
        )
    return sorted(rows, key=lambda row: _entry_id_sort_key(row["entry_id"]))


def build_fold_augmented_confounded_deployment_closure_audit(
    *,
    predicted_structure_fold_channel_path: Path,
    contract_audit_path: Path,
    oos_calibrated_threshold_contract_path: Path,
    sufficiency_decision_path: Path,
    remaining_blocker_clearance_path: Path,
) -> dict[str, Any]:
    fold_channel = _read_json(predicted_structure_fold_channel_path)
    contract_audit = _read_json(contract_audit_path)
    threshold_contract = _read_json(oos_calibrated_threshold_contract_path)
    sufficiency = _read_json(sufficiency_decision_path)
    clearance = _read_json(remaining_blocker_clearance_path)

    contract_counts = contract_audit.get("counts") or {}
    contract_critical = _contract_critical_violation_total(contract_audit)
    priority_rows = int(contract_counts.get("priority_cofactor_confounded_oos_rows") or 0)
    priority_hits = int(contract_counts.get("priority_nearest_hits") or 0)
    priority_missing = max(0, priority_rows - priority_hits)
    confounded_rows = _fold_augmented_confounded_priority_rows(fold_channel)

    primary = threshold_contract.get("primary_channel_readout") or {}
    selected = (
        primary.get("selected_at_90pct_calibration_in_scope_retention_max_oos_abstain")
        or {}
    )
    heldout = primary.get("heldout_final_eval_at_90pct_oos_calibrated_threshold") or {}
    suff_counts = sufficiency.get("counts") or {}
    clearance_counts = clearance.get("counts") or {}
    blocker_rows = [
        {
            "entry_id": row.get("entry_id"),
            "current_blocker": row.get("current_blocker"),
            "fold_only_evidence_available": bool(row.get("fold_only_evidence_available")),
            "clearance_result": row.get("clearance_result"),
            "next_action": row.get("next_action"),
        }
        for row in clearance.get("row_attempts", [])
        if isinstance(row, dict) and row.get("entry_id")
    ]
    production_blockers = int(
        clearance_counts.get("remaining_blocker_rows") or len(blocker_rows)
    )
    critical_counts = {
        "fold_contract_critical_violations": contract_critical,
        "priority_confounded_missing_hits": priority_missing,
        "production_blocker_rows_remaining": production_blockers,
    }
    heldout_confounded_total = int(
        heldout.get("heldout_confounded_oos_total")
        or threshold_contract.get("counts", {}).get("heldout_confounded_oos")
        or 0
    )
    heldout_confounded_abstained = int(
        heldout.get("heldout_confounded_oos_abstained") or 0
    )
    in_scope_retain = heldout.get("heldout_in_scope_retain_recall")
    confounded_recall = heldout.get("heldout_confounded_oos_abstain_recall")
    confounded_target_met = (
        float(confounded_recall or 0.0) >= 0.80
        and float(in_scope_retain or 0.0) >= 0.85
        and priority_missing == 0
        and contract_critical == 0
    )
    production_closed = (
        production_blockers == 0
        and contract_critical == 0
        and priority_missing == 0
        and sufficiency.get("decision", {}).get("production_surface_sufficient") is True
    )
    status = (
        "confounded_fold_channel_deployment_closed"
        if production_closed
        else "confounded_fold_channel_research_ready_production_blocked"
    )
    return {
        "artifact_id": FOLD_AUGMENTED_CONFOUNDED_DEPLOYMENT_CLOSURE_AUDIT_ID,
        "schema_version": (
            f"{SCHEMA_VERSION}.fold_augmented_confounded_deployment_closure_audit"
        ),
        "created_utc": _utc_now_iso(),
        "status": status,
        "scope": (
            "Validation-only Lever 3 synthesis for the predicted-structure-vs-atlas "
            "fold channel at the fixed OOS-calibrated operating point, focused on "
            "the six cofactor-confounded heldout OOS rows."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "model_weights_fit_or_refit": False,
            "threshold_selected_or_tuned": False,
            "threshold_values_changed": False,
            "heldout_rows_used_for_training_or_threshold_tuning": False,
            "experimental_pdb_metadata_used_as_channel_input": False,
            "foldseek_or_tm_rerun_performed": False,
            "review_only": True,
            "validation_only": True,
        },
        "counts": {
            "priority_confounded_oos_rows": priority_rows,
            "priority_nearest_hits": priority_hits,
            "heldout_confounded_oos_abstained": heldout_confounded_abstained,
            "heldout_confounded_oos_total": heldout_confounded_total,
            "requested_train_cal_oos_rows": suff_counts.get("candidate_ids_requested"),
            "score_complete_train_cal_oos_rows": suff_counts.get("score_complete_rows"),
            "remaining_production_blocker_rows": production_blockers,
            "remaining_blocker_rows_with_fold_only_evidence": clearance_counts.get(
                "rows_with_fold_only_evidence"
            ),
            "critical_counts": critical_counts,
            "critical_violation_total": sum(critical_counts.values()),
        },
        "operating_point": {
            "channel": primary.get("channel"),
            "fixed_threshold": selected.get("threshold"),
            "threshold_source": (
                "selected_at_90pct_calibration_in_scope_retention_max_oos_abstain; "
                "heldout readout copied from existing contract"
            ),
            "calibration_oos_total": selected.get("calibration_oos_total"),
            "calibration_oos_abstained": selected.get("calibration_oos_abstained"),
            "calibration_oos_abstain_recall": selected.get(
                "calibration_oos_abstain_recall"
            ),
            "heldout_in_scope_retain_recall": in_scope_retain,
            "heldout_oos_abstain_recall": heldout.get("heldout_oos_abstain_recall"),
            "heldout_confounded_oos_abstain_recall": confounded_recall,
            "heldout_confounded_oos_abstained": heldout_confounded_abstained,
            "heldout_confounded_oos_total": heldout_confounded_total,
        },
        "predicted_structure_vs_atlas_contract": {
            "fold_channel_status": fold_channel.get("status"),
            "contract_audit_status": contract_audit.get("status"),
            "critical_counts": contract_counts.get("critical_counts") or {},
            "heldout_rows_ok": contract_counts.get("heldout_rows_ok"),
            "all_heldout_nearest_hits": contract_counts.get("all_heldout_nearest_hits"),
            "priority_confounded_oos_rows": priority_rows,
            "priority_nearest_hits": priority_hits,
            "confounded_entry_ids": [row["entry_id"] for row in confounded_rows],
            "confounded_fold_nearest_atlas_rows": confounded_rows,
        },
        "deployment_closure": {
            "research_channel_valid_for_current_diagnostics": bool(
                sufficiency.get("decision", {}).get("research_surface_sufficient")
                and confounded_target_met
            ),
            "production_channel_closed": production_closed,
            "reason_production_not_closed": (
                None
                if production_closed
                else "The fixed threshold is research-sufficient, but disclosed "
                "train/cal OOS surface blockers remain and the sufficiency decision "
                "requires complete coverage for production-like claims."
            ),
            "remaining_blocker_rows": sorted(
                blocker_rows,
                key=lambda row: _entry_id_sort_key(str(row.get("entry_id"))),
            ),
        },
        "decision": {
            "confounded_subset_target_met_for_research": confounded_target_met,
            "in_scope_retention_ok_at_operating_point": float(in_scope_retain or 0.0)
            >= 0.85,
            "deployable_without_production_caveat": production_closed,
            "next_gate": (
                "Clear the five disclosed train/cal OOS surface blockers or "
                "explicitly define a fold-only deployment contract; do not change "
                "the fixed threshold from this artifact."
            ),
        },
        "source_artifacts": {
            "fold_channel": _source_path_record(predicted_structure_fold_channel_path),
            "contract_audit": _source_path_record(contract_audit_path),
            "oos_threshold_contract": _source_path_record(
                oos_calibrated_threshold_contract_path
            ),
            "sufficiency_decision": _source_path_record(sufficiency_decision_path),
            "remaining_blockers": _source_path_record(remaining_blocker_clearance_path),
        },
        "interpretation": {
            "result": (
                "The predicted-structure-vs-atlas fold channel is contract-passing "
                f"and hits the confounded subset research target at the fixed "
                f"operating point: {heldout_confounded_abstained}/"
                f"{heldout_confounded_total} cofactor-confounded heldout OOS rows "
                "abstain while in-scope retention is preserved."
            ),
            "next_action": (
                "For production-like closure, clear m_csa:78, m_csa:204, "
                "m_csa:531, uniprot:P78549, and uniprot:Q3LXA3, or create an "
                "explicit fold-only contract for the rows that already have "
                "Foldseek/TM evidence."
            ),
        },
    }


def _render_fold_augmented_confounded_deployment_closure_audit_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    operating = audit["operating_point"]
    lines = [
        "# Fold-Augmented Confounded Deployment Closure Audit - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Fixed threshold: {operating['channel']} >= {operating['fixed_threshold']}",
        (
            "- Confounded heldout OOS abstained: "
            f"{counts['heldout_confounded_oos_abstained']}/"
            f"{counts['heldout_confounded_oos_total']}"
        ),
        f"- Heldout in-scope retain recall: {operating['heldout_in_scope_retain_recall']}",
        f"- Remaining production blocker rows: {counts['remaining_production_blocker_rows']}",
        "",
        "## Confounded Rows",
        "",
        "| row | nearest atlas | atlas fingerprint | TM |",
        "| --- | --- | --- | ---: |",
    ]
    for row in audit["predicted_structure_vs_atlas_contract"][
        "confounded_fold_nearest_atlas_rows"
    ]:
        lines.append(
            f"| {row['entry_id']} | {row['nearest_atlas_entry_id']} | "
            f"{row['nearest_atlas_true_fingerprint_id']} | "
            f"{row['nearest_atlas_tm_score']} |"
        )
    lines += [
        "",
        "## Production Blockers",
        "",
        "| row | blocker | fold-only evidence | next action |",
        "| --- | --- | ---: | --- |",
    ]
    for row in audit["deployment_closure"]["remaining_blocker_rows"]:
        lines.append(
            f"| {row['entry_id']} | {row['current_blocker']} | "
            f"{row['fold_only_evidence_available']} | {row['next_action']} |"
        )
    lines += [
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['result']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_fold_augmented_confounded_deployment_closure_audit(
    *,
    predicted_structure_fold_channel_path: Path,
    contract_audit_path: Path,
    oos_calibrated_threshold_contract_path: Path,
    sufficiency_decision_path: Path,
    remaining_blocker_clearance_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_fold_augmented_confounded_deployment_closure_audit(
        predicted_structure_fold_channel_path=predicted_structure_fold_channel_path,
        contract_audit_path=contract_audit_path,
        oos_calibrated_threshold_contract_path=oos_calibrated_threshold_contract_path,
        sufficiency_decision_path=sufficiency_decision_path,
        remaining_blocker_clearance_path=remaining_blocker_clearance_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_fold_augmented_confounded_deployment_closure_audit_report(audit),
            encoding="utf-8",
        )
    return audit


def _fold_only_rows_at_threshold(
    rows: list[dict[str, Any]],
    *,
    threshold: float,
) -> list[dict[str, Any]]:
    evaluated = []
    for row in rows:
        score = row.get("nearest_train_atlas_tm_score")
        abstain = score is not None and float(score) < float(threshold)
        evaluated.append(
            {
                "entry_id": row.get("entry_id"),
                "accession": row.get("accession"),
                "predicted_geometry_status": row.get("predicted_geometry_status"),
                "nearest_train_atlas_entry_id": row.get(
                    "nearest_train_atlas_entry_id"
                ),
                "nearest_train_atlas_true_fingerprint_id": row.get(
                    "nearest_train_atlas_true_fingerprint_id"
                ),
                "nearest_train_atlas_tm_score": score,
                "threshold": round(float(threshold), 6),
                "abstains_at_threshold": abstain,
            }
        )
    return evaluated


def build_fold_augmented_fold_only_deployment_contract_decision(
    *,
    oos_calibrated_threshold_contract_path: Path,
    fold_only_surface_path: Path,
    confounded_deployment_closure_path: Path,
) -> dict[str, Any]:
    threshold_contract = _read_json(oos_calibrated_threshold_contract_path)
    fold_only_surface = _read_json(fold_only_surface_path)
    confounded_closure = _read_json(confounded_deployment_closure_path)

    fold_channel = (
        threshold_contract.get("threshold_contract", {}).get(
            "fold_nearest_atlas_tm_score"
        )
        or {}
    )
    selected90 = (
        fold_channel.get(
            "selected_at_90pct_calibration_in_scope_retention_max_oos_abstain"
        )
        or {}
    )
    selected85 = (
        fold_channel.get(
            "selected_at_85pct_calibration_in_scope_retention_max_oos_abstain"
        )
        or {}
    )
    heldout90 = (
        fold_channel.get("heldout_final_eval_at_90pct_oos_calibrated_threshold")
        or {}
    )
    heldout85 = (
        fold_channel.get("heldout_final_eval_at_85pct_oos_calibrated_threshold")
        or {}
    )
    fold_only_rows = [
        row
        for row in fold_only_surface.get("rows", [])
        if isinstance(row, dict) and row.get("entry_id")
    ]
    threshold90 = selected90.get("threshold")
    threshold85 = selected85.get("threshold")
    rows90 = (
        _fold_only_rows_at_threshold(fold_only_rows, threshold=float(threshold90))
        if threshold90 is not None
        else []
    )
    rows85 = (
        _fold_only_rows_at_threshold(fold_only_rows, threshold=float(threshold85))
        if threshold85 is not None
        else []
    )
    abstained90 = sum(1 for row in rows90 if row["abstains_at_threshold"])
    abstained85 = sum(1 for row in rows85 if row["abstains_at_threshold"])
    confounded90 = float(heldout90.get("heldout_confounded_oos_abstain_recall") or 0.0)
    confounded85 = float(heldout85.get("heldout_confounded_oos_abstain_recall") or 0.0)
    retain90 = float(heldout90.get("heldout_in_scope_retain_recall") or 0.0)
    retain85 = float(heldout85.get("heldout_in_scope_retain_recall") or 0.0)
    fold_only_contract_authorized = (
        bool(fold_only_rows)
        and abstained90 == len(fold_only_rows)
        and retain90 >= 0.85
        and confounded90 >= 0.80
    )
    threshold85_rescue_ready = (
        bool(fold_only_rows)
        and abstained85 == len(fold_only_rows)
        and retain85 >= 0.85
        and confounded85 >= 0.80
    )
    critical_counts = {
        "fold_only_rows_not_abstained_at_90pct_threshold": (
            len(fold_only_rows) - abstained90
        ),
        "fold_only_confounded_target_missed_at_90pct_threshold": (
            0 if confounded90 >= 0.80 else 1
        ),
        "fold_only_in_scope_retention_missed_at_90pct_threshold": (
            0 if retain90 >= 0.85 else 1
        ),
    }
    status = (
        "fold_only_deployment_contract_ready_at_fixed_threshold"
        if fold_only_contract_authorized
        else "fold_only_deployment_contract_no_go_fixed_threshold_insufficient"
    )
    return {
        "artifact_id": FOLD_AUGMENTED_FOLD_ONLY_DEPLOYMENT_CONTRACT_DECISION_ID,
        "schema_version": (
            f"{SCHEMA_VERSION}.fold_augmented_fold_only_deployment_contract_decision"
        ),
        "created_utc": _utc_now_iso(),
        "status": status,
        "scope": (
            "Decision audit for the Lever 3 fold-only escape hatch. It copies "
            "the existing OOS-calibrated fold-only operating point and evaluates "
            "only the blocker rows that already have Foldseek/TM evidence; it "
            "does not select or tune thresholds."
        ),
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "model_weights_fit_or_refit": False,
            "threshold_selected_or_tuned": False,
            "threshold_values_changed": False,
            "heldout_rows_used_for_training_or_threshold_tuning": False,
            "foldseek_or_tm_rerun_performed": False,
            "fold_only_blocker_rows_used_for_threshold_selection": False,
            "validation_only": True,
        },
        "counts": {
            "fold_only_blocker_rows": len(fold_only_rows),
            "fold_only_rows_abstained_at_90pct_threshold": abstained90,
            "fold_only_rows_abstained_at_85pct_threshold": abstained85,
            "heldout_confounded_oos_abstain_recall_at_90pct_threshold": confounded90,
            "heldout_confounded_oos_abstain_recall_at_85pct_threshold": confounded85,
            "heldout_in_scope_retain_recall_at_90pct_threshold": retain90,
            "heldout_in_scope_retain_recall_at_85pct_threshold": retain85,
            "remaining_production_blocker_rows": (
                confounded_closure.get("counts", {}).get(
                    "remaining_production_blocker_rows"
                )
            ),
            "critical_counts": critical_counts,
            "critical_violation_total": sum(critical_counts.values()),
        },
        "operating_points": {
            "fold_only_90pct": selected90,
            "fold_only_85pct": selected85,
            "heldout_fold_only_90pct": heldout90,
            "heldout_fold_only_85pct": heldout85,
        },
        "fold_only_blocker_rows_at_90pct_threshold": rows90,
        "fold_only_blocker_rows_at_85pct_threshold": rows85,
        "decision": {
            "fold_only_deployment_contract_authorized": fold_only_contract_authorized,
            "fold_only_85pct_rescue_contract_authorized": threshold85_rescue_ready,
            "deployable_without_production_caveat": False,
            "next_gate": (
                "Do not use a fold-only escape hatch for production-like closure "
                "at the fixed operating point. Clear the geometry/source blockers "
                "for m_csa:204, m_csa:531, uniprot:P78549, and uniprot:Q3LXA3, "
                "and resolve the missing AlphaFoldDB coordinate for m_csa:78."
            ),
        },
        "source_artifacts": {
            "oos_calibrated_threshold_contract": _source_path_record(
                oos_calibrated_threshold_contract_path
            ),
            "fold_only_surface": _source_path_record(fold_only_surface_path),
            "confounded_deployment_closure": _source_path_record(
                confounded_deployment_closure_path
            ),
        },
        "interpretation": {
            "result": (
                "The explicit fold-only contract is a no-go at the fixed "
                f"90% operating point: {abstained90}/{len(fold_only_rows)} "
                "fold-only blocker rows abstain and the heldout fold-only "
                f"confounded abstain recall is {confounded90}."
            ),
            "next_action": (
                "Continue Lever 3 by clearing source-geometry or coordinate "
                "blockers rather than defining a separate fold-only deployment "
                "contract."
            ),
        },
    }


def _render_fold_augmented_fold_only_deployment_contract_decision_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    decision = audit["decision"]
    lines = [
        "# Fold-Augmented Fold-Only Deployment Contract Decision - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        "- Fold-only deployment contract authorized: "
        f"{decision['fold_only_deployment_contract_authorized']}",
        f"- Fold-only blocker rows: {counts['fold_only_blocker_rows']}",
        "- Rows abstained at 90% threshold: "
        f"{counts['fold_only_rows_abstained_at_90pct_threshold']}",
        "- Heldout confounded abstain recall at 90% threshold: "
        f"{counts['heldout_confounded_oos_abstain_recall_at_90pct_threshold']}",
        "- Heldout in-scope retain recall at 90% threshold: "
        f"{counts['heldout_in_scope_retain_recall_at_90pct_threshold']}",
        f"- Critical violations: {counts['critical_violation_total']}",
        "",
        "## Rows At 90% Threshold",
        "",
        "| row | TM score | threshold | abstains | nearest train |",
        "| --- | ---: | ---: | --- | --- |",
    ]
    for row in audit["fold_only_blocker_rows_at_90pct_threshold"]:
        lines.append(
            f"| {row['entry_id']} | {row.get('nearest_train_atlas_tm_score')} | "
            f"{row.get('threshold')} | {row.get('abstains_at_threshold')} | "
            f"{row.get('nearest_train_atlas_entry_id')} |"
        )
    lines += [
        "",
        "## Decision",
        "",
        f"- {decision['next_gate']}",
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['result']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_fold_augmented_fold_only_deployment_contract_decision(
    *,
    oos_calibrated_threshold_contract_path: Path,
    fold_only_surface_path: Path,
    confounded_deployment_closure_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_fold_augmented_fold_only_deployment_contract_decision(
        oos_calibrated_threshold_contract_path=oos_calibrated_threshold_contract_path,
        fold_only_surface_path=fold_only_surface_path,
        confounded_deployment_closure_path=confounded_deployment_closure_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(
        json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_fold_augmented_fold_only_deployment_contract_decision_report(
                audit
            ),
            encoding="utf-8",
        )
    return audit


