def write_mechanism_feature_row_specific_bond_change_p0_oos_augmented_best_token_followup_pair_source_free_pre_threshold_readiness(
    *,
    pair_operating_point_contract_path: Path,
    source_free_application_surface_path: Path,
    event_axis_linker_schema_path: Path,
    locator_rewrite_materialization_gate_path: Path,
    out_path: Path,
    event_axis_linker_materialization_gate_path: Path | None = None,
    locator_rewrite_approval_packet_path: Path | None = None,
    source_free_locator_input_audit_path: Path | None = None,
    report_path: Path | None = None,
) -> dict[str, Any]:
    readiness = build_mechanism_feature_row_specific_bond_change_p0_oos_augmented_best_token_followup_pair_source_free_pre_threshold_readiness(
        pair_operating_point_contract_path=pair_operating_point_contract_path,
        source_free_application_surface_path=source_free_application_surface_path,
        event_axis_linker_schema_path=event_axis_linker_schema_path,
        locator_rewrite_materialization_gate_path=locator_rewrite_materialization_gate_path,
        event_axis_linker_materialization_gate_path=(
            event_axis_linker_materialization_gate_path
        ),
        locator_rewrite_approval_packet_path=locator_rewrite_approval_packet_path,
        source_free_locator_input_audit_path=source_free_locator_input_audit_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(
        json.dumps(readiness, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_mechanism_feature_row_specific_bond_change_p0_oos_augmented_best_token_followup_pair_source_free_pre_threshold_readiness_report(
                readiness
            ),
            encoding="utf-8",
        )
    return readiness


def _predicted_geometry_source_free_anchor_summary(
    row: dict[str, Any],
) -> dict[str, Any]:
    ligand_context = row.get("ligand_context") or {}
    proximal_ligands = [
        item for item in ligand_context.get("proximal_ligands", []) if item
    ]
    ligand_codes = [item for item in ligand_context.get("ligand_codes", []) if item]
    structure_ligands = [
        item for item in ligand_context.get("structure_ligands", []) if item
    ]
    structure_ligand_codes = [
        item for item in ligand_context.get("structure_ligand_codes", []) if item
    ]
    cofactor_families = [
        item for item in ligand_context.get("cofactor_families", []) if item
    ]
    structure_cofactor_families = [
        item
        for item in ligand_context.get("structure_cofactor_families", [])
        if item
    ]
    has_anchor = any(
        (
            proximal_ligands,
            ligand_codes,
            structure_ligands,
            structure_ligand_codes,
            cofactor_families,
            structure_cofactor_families,
        )
    )
    return {
        "has_source_free_ligand_or_cofactor_anchor": has_anchor,
        "proximal_ligand_count": len(proximal_ligands),
        "ligand_codes": sorted(set(str(item) for item in ligand_codes)),
        "structure_ligand_codes": sorted(
            set(str(item) for item in structure_ligand_codes)
        ),
        "cofactor_families": sorted(set(str(item) for item in cofactor_families)),
        "structure_cofactor_families": sorted(
            set(str(item) for item in structure_cofactor_families)
        ),
    }


def build_mechanism_feature_row_specific_bond_change_p0_oos_augmented_best_token_followup_pair_source_free_locator_input_audit(
    *,
    locator_action_queue_path: Path,
    predicted_geometry_retrieval_path: Path,
    source_free_locator_schema_path: Path | None = None,
    coordinate_anchor_candidate_audit_path: Path | None = None,
    coordinate_anchor_priority1_rewrite_preflight_path: Path | None = None,
) -> dict[str, Any]:
    locator_queue = _read_json(locator_action_queue_path)
    predicted_geometry = _read_json(predicted_geometry_retrieval_path)
    locator_schema = (
        _read_json(source_free_locator_schema_path)
        if source_free_locator_schema_path is not None
        and source_free_locator_schema_path.exists()
        else None
    )
    locator_schema_counts = (
        locator_schema.get("counts") if isinstance(locator_schema, dict) else {}
    ) or {}
    locator_schema_summary = (
        {
            "status": locator_schema.get("status"),
            "allowed_locator_evidence_classes": locator_schema_counts.get(
                "allowed_locator_evidence_classes"
            ),
            "forbidden_predictive_fields": locator_schema_counts.get(
                "forbidden_predictive_fields"
            ),
            "required_residue_locator_minimum": locator_schema_counts.get(
                "required_residue_locator_minimum"
            ),
            "residue_locator_required_fields": locator_schema.get(
                "residue_locator_required_fields"
            ),
            "sidecar_required_top_level_fields": locator_schema.get(
                "sidecar_required_top_level_fields"
            ),
        }
        if isinstance(locator_schema, dict)
        else None
    )
    coordinate_anchor_audit = (
        _read_json(coordinate_anchor_candidate_audit_path)
        if coordinate_anchor_candidate_audit_path is not None
        and coordinate_anchor_candidate_audit_path.exists()
        else None
    )
    coordinate_anchor_by_entry = (
        {
            str(row.get("entry_id")): row
            for row in coordinate_anchor_audit.get("row_audits", [])
            if isinstance(row, dict) and row.get("entry_id")
        }
        if isinstance(coordinate_anchor_audit, dict)
        else {}
    )
    coordinate_anchor_preflight = (
        _read_json(coordinate_anchor_priority1_rewrite_preflight_path)
        if coordinate_anchor_priority1_rewrite_preflight_path is not None
        and coordinate_anchor_priority1_rewrite_preflight_path.exists()
        else None
    )
    coordinate_anchor_preflight_by_entry = (
        {
            str(row.get("entry_id")): row
            for row in coordinate_anchor_preflight.get("preflight_rows", [])
            if isinstance(row, dict) and row.get("entry_id")
        }
        if isinstance(coordinate_anchor_preflight, dict)
        else {}
    )
    coordinate_anchor_preflight_counts = (
        coordinate_anchor_preflight.get("counts")
        if isinstance(coordinate_anchor_preflight, dict)
        else {}
    ) or {}
    predicted_by_entry = {
        str(row.get("entry_id")): row
        for row in predicted_geometry.get("results", [])
        if isinstance(row, dict) and row.get("entry_id")
    }
    priority_rows = [
        row
        for row in locator_queue.get("queue_rows", [])
        if isinstance(row, dict)
        and row.get("queue_class")
        == "priority_1_coordinate_ready_locator_candidate"
    ]
    audit_rows = []
    for row in priority_rows:
        entry_id = str(row.get("entry_id") or "")
        predicted_row = predicted_by_entry.get(entry_id, {})
        anchor = _predicted_geometry_source_free_anchor_summary(predicted_row)
        coordinate_anchor_row = coordinate_anchor_by_entry.get(entry_id, {})
        has_coordinate_anchor_candidate = bool(
            coordinate_anchor_row.get(
                "has_source_free_coordinate_local_anchor_candidate"
            )
        )
        coordinate_anchor_preflight_row = coordinate_anchor_preflight_by_entry.get(
            entry_id, {}
        )
        coordinate_anchor_preflight_passed = (
            coordinate_anchor_preflight_row.get("preflight_status")
            == "preflight_passed_pending_explicit_approval"
        )
        blockers: list[str] = []
        if (
            not anchor["has_source_free_ligand_or_cofactor_anchor"]
            and not has_coordinate_anchor_candidate
        ):
            blockers.append("source_free_ligand_or_cofactor_contact_anchor_missing")
        if has_coordinate_anchor_candidate:
            blockers.append(
                "source_free_coordinate_anchor_preflight_passed_requires_explicit_approval"
                if coordinate_anchor_preflight_passed
                else "source_free_coordinate_anchor_candidate_needs_review"
            )
        blockers.append("source_free_event_axis_missing_for_pair_token")
        audit_rows.append(
            {
                "entry_id": entry_id,
                "queue_class": row.get("queue_class"),
                "predicted_geometry_status": predicted_row.get(
                    "status", "missing_predicted_geometry_row"
                ),
                "predicted_model_id": predicted_row.get("pdb_id"),
                "anchor_summary": anchor,
                "coordinate_anchor_candidate_summary": {
                    "has_source_free_coordinate_local_anchor_candidate": (
                        has_coordinate_anchor_candidate
                    ),
                    "candidate_path": coordinate_anchor_row.get("candidate_path"),
                    "selected_structure_id": coordinate_anchor_row.get(
                        "selected_structure_id"
                    ),
                    "selected_ligand_site": coordinate_anchor_row.get(
                        "selected_ligand_site"
                    ),
                    "candidate_residue_locator_count": coordinate_anchor_row.get(
                        "candidate_residue_locator_count"
                    ),
                    "sequence_position_validated_locator_count": (
                        coordinate_anchor_row.get(
                            "sequence_position_validated_locator_count"
                        )
                    ),
                    "candidate_status": coordinate_anchor_row.get("status"),
                    "candidate_blockers": coordinate_anchor_row.get(
                        "candidate_blockers", []
                    ),
                },
                "coordinate_anchor_rewrite_preflight_summary": {
                    "preflight_present": bool(coordinate_anchor_preflight_row),
                    "preflight_status": coordinate_anchor_preflight_row.get(
                        "preflight_status"
                    ),
                    "planned_audited_locator_sidecar_path": (
                        coordinate_anchor_preflight_row.get(
                            "planned_audited_locator_sidecar_path"
                        )
                    ),
                    "coordinate_contact_warnings": (
                        (
                            coordinate_anchor_preflight_row.get(
                                "coordinate_contact_preflight"
                            )
                            or {}
                        ).get("warnings", [])
                    ),
                    "copy_to_audited_locator_dir_allowed_now": False,
                    "explicit_approval_required_before_copy": (
                        bool(coordinate_anchor_preflight_row)
                    ),
                },
                "auto_create_locator_sidecar_allowed": False,
                "blockers": blockers,
            }
        )
    rows_with_anchor = [
        row
        for row in audit_rows
        if row.get("anchor_summary", {}).get(
            "has_source_free_ligand_or_cofactor_anchor"
        )
    ]
    rows_with_coordinate_anchor_candidate = [
        row
        for row in audit_rows
        if row.get("coordinate_anchor_candidate_summary", {}).get(
            "has_source_free_coordinate_local_anchor_candidate"
        )
    ]
    rows_with_coordinate_anchor_preflight_passed = [
        row
        for row in audit_rows
        if row.get("coordinate_anchor_rewrite_preflight_summary", {}).get(
            "preflight_status"
        )
        == "preflight_passed_pending_explicit_approval"
    ]
    rows_with_any_source_free_anchor = [
        row
        for row in audit_rows
        if row.get("anchor_summary", {}).get(
            "has_source_free_ligand_or_cofactor_anchor"
        )
        or row.get("coordinate_anchor_candidate_summary", {}).get(
            "has_source_free_coordinate_local_anchor_candidate"
        )
    ]
    blockers = []
    if len(rows_with_any_source_free_anchor) < len(audit_rows):
        blockers.append("priority1_rows_lack_source_free_contact_or_coordinate_anchor")
    if rows_with_coordinate_anchor_preflight_passed:
        blockers.append(
            "source_free_coordinate_anchor_preflight_passed_requires_explicit_approval"
        )
    if rows_with_coordinate_anchor_candidate:
        rows_still_needing_review = len(rows_with_coordinate_anchor_candidate) - len(
            rows_with_coordinate_anchor_preflight_passed
        )
        if rows_still_needing_review > 0:
            blockers.append("source_free_coordinate_anchor_candidates_need_review")
    blockers.append("source_free_event_axis_missing_for_pair_token")
    return {
        "artifact_id": (
            MECHANISM_FEATURE_ROW_SPECIFIC_BOND_CHANGE_P0_OOS_AUGMENTED_BEST_TOKEN_FOLLOWUP_PAIR_SOURCE_FREE_LOCATOR_INPUT_AUDIT_ID
        ),
        "schema_version": (
            f"{SCHEMA_VERSION}.row_specific_bond_change_p0_oos_augmented_best_token_followup_pair_source_free_locator_input_audit"
        ),
        "created_utc": _utc_now_iso(),
        "status": (
            "p0_oos_augmented_best_token_followup_pair_source_free_locator_input_audit_blocked"
        ),
        "scope": (
            "Input audit for priority-1 source-free locator queue rows. It "
            "checks whether the predicted-geometry artifact already contains "
            "source-free local ligand/cofactor anchors, and whether the "
            "selected-PDB coordinate anchor candidate audit has staged "
            "coordinate-local ligand/metal contact anchors, without M-CSA "
            "heldout mechanism text, heldout labels, source IDs, target names, "
            "or EC/Rhea IDs."
        ),
        "audit_rows": audit_rows,
        "source_free_locator_schema_summary": locator_schema_summary,
        "blockers": blockers,
        "guardrails": {
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "model_weights_fit_or_refit": False,
            "threshold_selected_or_tuned": False,
            "frozen_residual_threshold_applied": False,
            "heldout_rows_used_for_training_or_threshold_tuning": False,
            "heldout_rows_evaluated": False,
            "m_csa_heldout_row_specific_mechanism_text_used": False,
            "m_csa_heldout_active_site_roles_used_as_predictive_features": False,
            "source_text_or_source_ids_used_as_predictive_features": False,
            "event_residue_role_feature_imputed": False,
            "locator_sidecars_created_or_copied": False,
            "auto_locator_creation_allowed": False,
            "review_only": True,
        },
        "counts": {
            "priority1_locator_queue_rows": len(priority_rows),
            "priority1_rows_with_source_free_ligand_or_cofactor_anchor": len(
                rows_with_anchor
            ),
            "priority1_rows_with_source_free_coordinate_local_anchor_candidate": (
                len(rows_with_coordinate_anchor_candidate)
            ),
            "priority1_rows_without_source_free_anchor": len(audit_rows)
            - len(rows_with_any_source_free_anchor),
            "priority1_coordinate_anchor_preflight_rows": (
                coordinate_anchor_preflight_counts.get("priority1_review_rows")
            ),
            "priority1_coordinate_anchor_preflight_passed_pending_explicit_approval": (
                coordinate_anchor_preflight_counts.get(
                    "preflight_passed_pending_explicit_approval"
                )
            ),
            "priority1_coordinate_anchor_preflight_rows_with_warnings": (
                coordinate_anchor_preflight_counts.get("rows_with_preflight_warnings")
            ),
            "priority1_coordinate_anchor_preflight_approved_rewrites": (
                coordinate_anchor_preflight_counts.get(
                    "explicitly_approved_locator_rewrites"
                )
            ),
            "auto_create_locator_sidecar_allowed_rows": 0,
            "source_free_locator_schema_available": (
                1 if locator_schema_summary is not None else 0
            ),
            "source_free_locator_schema_required_residue_locator_minimum": (
                (locator_schema_summary or {}).get("required_residue_locator_minimum")
            ),
            "blockers": len(blockers),
            "critical_violation_total": 0,
        },
        "decision": {
            "auto_create_locator_sidecars_now": False,
            "approved_source_free_locator_surface_ready": False,
            "heldout_safe_pair_application_surface_ready": False,
            "apply_frozen_pair_threshold_now": False,
            "heldout_read_once_performed": False,
            "next_gate": (
                "Use the preflight-passed coordinate-anchor rows as the "
                "explicit-approval queue. Do not copy locator sidecars or "
                "apply the frozen threshold until approved rewrites exist in "
                "the audited locator directory and this audit is rerun."
            ),
        },
        "source_artifacts": {
            "locator_action_queue": _source_path_record(locator_action_queue_path),
            "predicted_geometry_retrieval": _source_path_record(
                predicted_geometry_retrieval_path
            ),
            "source_free_locator_schema": (
                _source_path_record(source_free_locator_schema_path)
                if source_free_locator_schema_path is not None
                else None
            ),
            "coordinate_anchor_candidate_audit": (
                _source_path_record(coordinate_anchor_candidate_audit_path)
                if coordinate_anchor_candidate_audit_path is not None
                else None
            ),
            "coordinate_anchor_priority1_rewrite_preflight": (
                _source_path_record(coordinate_anchor_priority1_rewrite_preflight_path)
                if coordinate_anchor_priority1_rewrite_preflight_path is not None
                else None
            ),
        },
        "interpretation": {
            "result": (
                "The priority-1 queue rows have predicted-geometry coordinates, "
                f"{len(rows_with_coordinate_anchor_candidate)} now expose "
                "review-only coordinate-local anchor candidates, "
                f"{len(rows_with_coordinate_anchor_preflight_passed)} pass "
                "rewrite preflight pending explicit approval, and none are "
                "approved locator sidecars for scoring."
            ),
            "next_action": (
                "Approve only reviewed locator rewrites, copy those sidecars "
                "into the audited locator directory, rerun strict/input/surface "
                "audits, and keep the event-axis blocker separate before any "
                "heldout read."
            ),
        },
    }


