def _embedding_train_cal_stratum(row: dict[str, Any]) -> str:
    fingerprint = row.get("fingerprint_id")
    if fingerprint:
        return f"fingerprint:{fingerprint}"
    return f"label_type:{row.get('label_type') or 'unknown'}"


def build_mechanism_feature_embedding_train_cal_split_manifest(
    *,
    train_cal_input_manifest_path: Path,
    calibration_fraction: float = 0.2,
) -> dict[str, Any]:
    manifest = _read_json(train_cal_input_manifest_path)
    row_records = [
        row
        for row in manifest.get("row_records", [])
        if isinstance(row, dict)
    ]
    ready_rows = [
        row
        for row in row_records
        if row.get("minimal_train_cal_feature_bundle_ready")
        and row.get("split_assignment") == "in_distribution"
    ]
    not_ready_rows = [
        row
        for row in row_records
        if not row.get("minimal_train_cal_feature_bundle_ready")
    ]
    not_ready_reasons: Counter[str] = Counter()
    for row in not_ready_rows:
        if row.get("role_graph_status") != "ok":
            not_ready_reasons[f"role_graph:{row.get('role_graph_status')}"] += 1
        if len(row.get("organic_cofactor_classes_available") or []) < 3:
            not_ready_reasons["organic_cofactor_scores_missing"] += 1

    by_stratum: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for row in ready_rows:
        by_stratum[_embedding_train_cal_stratum(row)].append(row)

    split_records: list[dict[str, Any]] = []
    stratum_counts: dict[str, dict[str, int]] = {}
    for stratum, members in sorted(by_stratum.items()):
        ordered = sorted(
            members,
            key=lambda row: (
                _stable_hash_int(f"{stratum}::{row.get('entry_id')}"),
                str(row.get("entry_id")),
            ),
        )
        if len(ordered) < 2:
            calibration_count = 0
        else:
            calibration_count = max(
                1,
                min(
                    len(ordered) - 1,
                    round(len(ordered) * calibration_fraction),
                ),
            )
        calibration_ids = {
            str(row.get("entry_id")) for row in ordered[:calibration_count]
        }
        counts = {"total": len(ordered), "train": 0, "calibration": 0}
        for row in ordered:
            split = (
                "calibration"
                if str(row.get("entry_id")) in calibration_ids
                else "train"
            )
            counts[split] += 1
            split_records.append(
                {
                    "entry_id": row.get("entry_id"),
                    "assigned_embedding_split": split,
                    "stratum": stratum,
                    "fingerprint_id": row.get("fingerprint_id"),
                    "label_type": row.get("label_type"),
                    "active_site_residue_count": row.get("active_site_residue_count"),
                    "reaction_template_status": row.get("reaction_template_status"),
                    "role_graph_status": row.get("role_graph_status"),
                    "inorganic_locus_statuses": row.get("inorganic_locus_statuses"),
                }
            )
        stratum_counts[stratum] = counts

    split_counts = Counter(row["assigned_embedding_split"] for row in split_records)
    return {
        "artifact_id": "v3_mechanism_feature_embedding_train_cal_split_manifest_current702_20260601",
        "schema_version": f"{SCHEMA_VERSION}.mechanism_feature_embedding_train_cal_split_manifest",
        "created_utc": _utc_now_iso(),
        "status": "mechanism_feature_embedding_train_cal_split_ready_no_model_fit",
        "scope": (
            "Deterministic train/cal split manifest for the no-fit mechanism-feature "
            "embedding pilot. It partitions only in_distribution rows with the "
            "minimal feature bundle ready and carries heldout rows only as an "
            "excluded count."
        ),
        "guardrails": {
            "model_weights_fit_or_refit": False,
            "threshold_selected_or_tuned": False,
            "heldout_rows_used_for_training_or_threshold_tuning": False,
            "heldout_rows_enumerated_only_as_excluded_count": True,
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "review_only": True,
        },
        "counts": {
            "input_train_cal_candidate_rows": manifest.get("counts", {}).get(
                "train_cal_candidate_rows"
            ),
            "minimal_feature_bundle_ready_rows": len(ready_rows),
            "split_rows": len(split_records),
            "train_rows": split_counts.get("train", 0),
            "calibration_rows": split_counts.get("calibration", 0),
            "heldout_excluded_rows": manifest.get("counts", {}).get(
                "heldout_excluded_rows"
            ),
            "not_ready_rows": len(not_ready_rows),
            "strata": len(stratum_counts),
            "not_ready_reason_counts": dict(sorted(not_ready_reasons.items())),
        },
        "stratum_counts": stratum_counts,
        "split_records": sorted(
            split_records,
            key=lambda row: _entry_id_sort_key(str(row.get("entry_id"))),
        ),
        "interpretation": {
            "headline": (
                f"{split_counts.get('train', 0)} train and "
                f"{split_counts.get('calibration', 0)} calibration rows are "
                "ready for an explicitly authorized no-fit embedding pilot."
            ),
            "next_action": (
                "If model fitting is authorized later, fit only on assigned train "
                "rows, select any operating threshold only on calibration rows, "
                "and evaluate heldout once."
            ),
        },
        "source_artifacts": {
            "train_cal_input_manifest": _source_path_record(train_cal_input_manifest_path),
        },
    }


def _render_mechanism_feature_embedding_train_cal_split_manifest_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    lines = [
        "# Mechanism-Feature Embedding Train/Cal Split Manifest - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Train rows: {counts['train_rows']}",
        f"- Calibration rows: {counts['calibration_rows']}",
        f"- Heldout excluded rows: {counts['heldout_excluded_rows']}",
        f"- Not-ready rows: {counts['not_ready_rows']}",
        f"- Strata: {counts['strata']}",
        f"- Not-ready reasons: {counts['not_ready_reason_counts']}",
        "",
        "## Strata",
        "",
        "| stratum | total | train | calibration |",
        "| --- | ---: | ---: | ---: |",
    ]
    for stratum, stratum_count in audit["stratum_counts"].items():
        lines.append(
            f"| `{stratum}` | {stratum_count['total']} | "
            f"{stratum_count['train']} | {stratum_count['calibration']} |"
        )
    lines += [
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_mechanism_feature_embedding_train_cal_split_manifest(
    *,
    train_cal_input_manifest_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_mechanism_feature_embedding_train_cal_split_manifest(
        train_cal_input_manifest_path=train_cal_input_manifest_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_mechanism_feature_embedding_train_cal_split_manifest_report(
                audit
            ),
            encoding="utf-8",
        )
    return audit


def _embedding_feature_contract_row(
    split_record: dict[str, Any],
    input_by_entry: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    entry_id = str(split_record.get("entry_id") or "")
    input_row = input_by_entry.get(entry_id, {})
    return {
        "entry_id": entry_id,
        "assigned_embedding_split": split_record.get("assigned_embedding_split"),
        "active_site_role_graph": {
            "status": split_record.get("role_graph_status"),
            "active_site_residue_count": split_record.get(
                "active_site_residue_count"
            ),
        },
        "reaction_center_template": {
            "status": split_record.get("reaction_template_status"),
            "reaction_chemical_operation": input_row.get(
                "reaction_chemical_operation"
            ),
        },
        "organic_cofactor_scores": {
            "available_classes": input_row.get(
                "organic_cofactor_classes_available", []
            ),
            "score_values_materialized_in_source_sidecar": True,
        },
        "inorganic_cofactor_loci": split_record.get("inorganic_locus_statuses")
        or {},
        "feature_guardrails": {
            "fingerprint_id_excluded_from_features": True,
            "label_type_excluded_from_features": True,
            "stratum_excluded_from_features": True,
            "heldout_row": False,
        },
    }


def build_mechanism_feature_embedding_feature_contract(
    *,
    train_cal_input_manifest_path: Path,
    train_cal_split_manifest_path: Path,
) -> dict[str, Any]:
    input_manifest = _read_json(train_cal_input_manifest_path)
    split_manifest = _read_json(train_cal_split_manifest_path)
    input_by_entry = {
        str(row.get("entry_id")): row
        for row in input_manifest.get("row_records", [])
        if isinstance(row, dict) and row.get("entry_id")
    }
    feature_rows = [
        _embedding_feature_contract_row(row, input_by_entry)
        for row in split_manifest.get("split_records", [])
        if isinstance(row, dict)
    ]
    split_counts = Counter(
        str(row.get("assigned_embedding_split") or "unknown")
        for row in feature_rows
    )
    reaction_status_domain = sorted(
        {
            str(row.get("reaction_center_template", {}).get("status") or "")
            for row in feature_rows
            if row.get("reaction_center_template", {}).get("status")
        }
    )
    locus_domains: dict[str, list[str]] = {}
    for row in feature_rows:
        for locus, status in row.get("inorganic_cofactor_loci", {}).items():
            locus_domains.setdefault(str(locus), [])
            locus_domains[str(locus)].append(str(status))
    locus_domains = {
        locus: sorted(set(statuses))
        for locus, statuses in sorted(locus_domains.items())
    }
    organic_classes = sorted(
        {
            str(cofactor_class)
            for row in feature_rows
            for cofactor_class in row.get("organic_cofactor_scores", {}).get(
                "available_classes", []
            )
        }
    )
    missing_input_records = [
        row["entry_id"]
        for row in feature_rows
        if row["entry_id"] not in input_by_entry
    ]
    return {
        "artifact_id": MECHANISM_FEATURE_EMBEDDING_FEATURE_CONTRACT_ID,
        "schema_version": f"{SCHEMA_VERSION}.mechanism_feature_embedding_feature_contract",
        "created_utc": _utc_now_iso(),
        "status": "mechanism_feature_embedding_feature_contract_ready_no_model_fit",
        "scope": (
            "No-fit feature contract for the mechanism-feature embedding pilot. "
            "It enumerates train/cal feature rows and permitted feature groups "
            "while excluding labels and heldout rows from the feature surface."
        ),
        "guardrails": {
            "model_weights_fit_or_refit": False,
            "threshold_selected_or_tuned": False,
            "heldout_rows_used_for_training_or_threshold_tuning": False,
            "heldout_rows_present_in_feature_rows": False,
            "label_fields_excluded_from_feature_rows": True,
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "review_only": True,
        },
        "counts": {
            "feature_rows": len(feature_rows),
            "train_rows": split_counts.get("train", 0),
            "calibration_rows": split_counts.get("calibration", 0),
            "heldout_excluded_rows": split_manifest.get("counts", {}).get(
                "heldout_excluded_rows"
            ),
            "feature_groups": 4,
            "numeric_feature_fields": 1,
            "categorical_feature_fields": 6,
            "organic_cofactor_classes": len(organic_classes),
            "inorganic_locus_classes": len(locus_domains),
            "missing_input_records": len(missing_input_records),
        },
        "feature_groups": [
            {
                "name": "active_site_role_graph",
                "fields": ["status", "active_site_residue_count"],
                "source": "mechanism_feature_active_site_role_graph_sidecar",
                "notes": (
                    "Ready split rows require role_graph_status=ok; status is "
                    "retained only as a guardrail field."
                ),
            },
            {
                "name": "reaction_center_template",
                "fields": ["status", "reaction_chemical_operation"],
                "source": "mechanism_feature_reaction_center_template_sidecar",
                "notes": (
                    "Fingerprint-template chemistry remains non-row-specific "
                    "and must not be interpreted as source-backed reaction evidence."
                ),
            },
            {
                "name": "organic_cofactor_scores",
                "fields": [f"{cofactor_class}_selected_score" for cofactor_class in organic_classes],
                "source": "selected_organic_cofactor_sidecar",
                "notes": "Scores are materialized in the source sidecar; this contract records availability only.",
            },
            {
                "name": "inorganic_cofactor_loci",
                "fields": sorted(locus_domains),
                "source": "metal/cobalamin/radical-SAM/Fe-S locus sidecars",
                "status_domains": locus_domains,
            },
        ],
        "excluded_fields_as_features": [
            "entry_id",
            "fingerprint_id",
            "label_type",
            "stratum",
            "split_assignment",
            "assigned_embedding_split",
            "source_artifact_paths",
            "heldout_labels_or_outcomes",
        ],
        "categorical_domains": {
            "reaction_template_status": reaction_status_domain,
            "organic_cofactor_classes": organic_classes,
            "inorganic_loci": locus_domains,
        },
        "feature_rows": sorted(
            feature_rows,
            key=lambda row: _entry_id_sort_key(str(row.get("entry_id"))),
        ),
        "blockers_before_model_fit": [
            "explicit_authorization_required_before_model_weights_are_fit",
            "feature_vector_materializer_not_written",
            "directed_electron_or_proton_transfer_edges_not_materialized",
            "row_specific_bond_change_mapping_not_materialized",
            "heldout_final_evaluation_must_remain_once_only",
        ],
        "source_artifacts": {
            "train_cal_input_manifest": _source_path_record(train_cal_input_manifest_path),
            "train_cal_split_manifest": _source_path_record(train_cal_split_manifest_path),
        },
        "interpretation": {
            "headline": (
                f"{len(feature_rows)} train/cal rows have a label-stripped "
                "feature-row contract; no model was fit."
            ),
            "next_action": (
                "If authorized, implement a materializer that consumes only these "
                "feature fields, fits on train rows, selects on calibration rows, "
                "and evaluates heldout once."
            ),
        },
    }


def _render_mechanism_feature_embedding_feature_contract_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    lines = [
        "# Mechanism-Feature Embedding Feature Contract - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Feature rows: {counts['feature_rows']}",
        f"- Train rows: {counts['train_rows']}",
        f"- Calibration rows: {counts['calibration_rows']}",
        f"- Heldout excluded rows: {counts['heldout_excluded_rows']}",
        f"- Missing input records: {counts['missing_input_records']}",
        "",
        "## Feature Groups",
        "",
        "| group | fields | source |",
        "| --- | --- | --- |",
    ]
    for group in audit["feature_groups"]:
        lines.append(
            f"| {group['name']} | {', '.join(group.get('fields', []))} | "
            f"{group.get('source')} |"
        )
    lines += [
        "",
        "## Excluded As Features",
        "",
    ]
    for field in audit["excluded_fields_as_features"]:
        lines.append(f"- {field}")
    lines += [
        "",
        "## Blockers Before Model Fit",
        "",
    ]
    for blocker in audit["blockers_before_model_fit"]:
        lines.append(f"- {blocker}")
    lines += [
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_mechanism_feature_embedding_feature_contract(
    *,
    train_cal_input_manifest_path: Path,
    train_cal_split_manifest_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_mechanism_feature_embedding_feature_contract(
        train_cal_input_manifest_path=train_cal_input_manifest_path,
        train_cal_split_manifest_path=train_cal_split_manifest_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_mechanism_feature_embedding_feature_contract_report(audit),
            encoding="utf-8",
        )
    return audit


MECHANISM_FEATURE_CONTRACT_ALLOWED_ROW_TOP_LEVEL_FIELDS = {
    "active_site_role_graph",
    "assigned_embedding_split",
    "entry_id",
    "feature_guardrails",
    "inorganic_cofactor_loci",
    "organic_cofactor_scores",
    "reaction_center_template",
}
MECHANISM_FEATURE_CONTRACT_FORBIDDEN_FEATURE_KEYS = {
    "fingerprint_id",
    "heldout_labels_or_outcomes",
    "label_type",
    "source_artifact_paths",
    "split_assignment",
    "stratum",
    "true_fingerprint_id",
}


def _forbidden_key_paths(
    value: Any,
    *,
    forbidden_keys: set[str],
    path: str = "$",
) -> list[str]:
    paths: list[str] = []
    if isinstance(value, dict):
        for key, child in value.items():
            child_path = f"{path}.{key}"
            if str(key) in forbidden_keys:
                paths.append(child_path)
            paths.extend(
                _forbidden_key_paths(
                    child,
                    forbidden_keys=forbidden_keys,
                    path=child_path,
                )
            )
    elif isinstance(value, list):
        for index, child in enumerate(value):
            paths.extend(
                _forbidden_key_paths(
                    child,
                    forbidden_keys=forbidden_keys,
                    path=f"{path}[{index}]",
                )
            )
    return paths


def _mechanism_feature_contract_row_audit(
    *,
    row: dict[str, Any],
    split_record: dict[str, Any] | None,
    input_record: dict[str, Any] | None,
    locus_domains: dict[str, list[str]],
    reaction_status_domain: set[str],
    organic_classes: set[str],
) -> dict[str, Any]:
    violations: list[str] = []
    entry_id = str(row.get("entry_id") or "")
    if not entry_id:
        violations.append("entry_id_missing")
    extra_top = sorted(
        set(row) - MECHANISM_FEATURE_CONTRACT_ALLOWED_ROW_TOP_LEVEL_FIELDS
    )
    for field in extra_top:
        violations.append(f"unexpected_top_level_feature_row_field:{field}")
    forbidden_paths = _forbidden_key_paths(
        {
            key: value
            for key, value in row.items()
            if key not in {"entry_id", "assigned_embedding_split"}
        },
        forbidden_keys=MECHANISM_FEATURE_CONTRACT_FORBIDDEN_FEATURE_KEYS,
    )
    for path in forbidden_paths:
        violations.append(f"forbidden_feature_key_present:{path}")
    if split_record is None:
        violations.append("missing_split_record")
    if input_record is None:
        violations.append("missing_input_manifest_record")
    split_assignment = row.get("assigned_embedding_split")
    if split_assignment not in {"train", "calibration"}:
        violations.append("assigned_embedding_split_not_train_or_calibration")
    if (
        split_record is not None
        and split_record.get("assigned_embedding_split") != split_assignment
    ):
        violations.append("assigned_embedding_split_mismatch_split_manifest")
    guardrails = row.get("feature_guardrails") or {}
    expected_true = (
        "fingerprint_id_excluded_from_features",
        "label_type_excluded_from_features",
        "stratum_excluded_from_features",
    )
    for key in expected_true:
        if guardrails.get(key) is not True:
            violations.append(f"feature_guardrail_{key}_not_true")
    if guardrails.get("heldout_row") is not False:
        violations.append("feature_guardrail_heldout_row_not_false")
    role_graph = row.get("active_site_role_graph") or {}
    if role_graph.get("status") != "ok":
        violations.append("role_graph_status_not_ok")
    if not isinstance(role_graph.get("active_site_residue_count"), int):
        violations.append("active_site_residue_count_not_int")
    if split_record is not None:
        if role_graph.get("active_site_residue_count") != split_record.get(
            "active_site_residue_count"
        ):
            violations.append("active_site_residue_count_mismatch_split_manifest")
        if role_graph.get("status") != split_record.get("role_graph_status"):
            violations.append("role_graph_status_mismatch_split_manifest")
    reaction = row.get("reaction_center_template") or {}
    reaction_status = str(reaction.get("status") or "")
    if reaction_status not in reaction_status_domain:
        violations.append("reaction_template_status_outside_domain")
    if split_record is not None and reaction_status != split_record.get(
        "reaction_template_status"
    ):
        violations.append("reaction_template_status_mismatch_split_manifest")
    organic = row.get("organic_cofactor_scores") or {}
    if set(str(value) for value in organic.get("available_classes", [])) != organic_classes:
        violations.append("organic_cofactor_available_classes_mismatch_domain")
    if organic.get("score_values_materialized_in_source_sidecar") is not True:
        violations.append("organic_score_source_sidecar_guardrail_not_true")
    loci = row.get("inorganic_cofactor_loci") or {}
    if set(loci) != set(locus_domains):
        violations.append("inorganic_locus_fields_mismatch_domain")
    for locus, status in loci.items():
        if str(status) not in set(locus_domains.get(str(locus), [])):
            violations.append(f"inorganic_locus_status_outside_domain:{locus}")
    if split_record is not None and loci != (
        split_record.get("inorganic_locus_statuses") or {}
    ):
        violations.append("inorganic_locus_statuses_mismatch_split_manifest")
    return {
        "entry_id": entry_id,
        "assigned_embedding_split": split_assignment,
        "critical_violations": sorted(set(violations)),
        "status": "passed" if not violations else "blocked",
    }


def build_mechanism_feature_embedding_feature_contract_strict_audit(
    *,
    feature_contract_path: Path,
    train_cal_input_manifest_path: Path,
    train_cal_split_manifest_path: Path,
) -> dict[str, Any]:
    contract = _read_json(feature_contract_path)
    input_manifest = _read_json(train_cal_input_manifest_path)
    split_manifest = _read_json(train_cal_split_manifest_path)
    feature_rows = [
        row for row in contract.get("feature_rows", []) if isinstance(row, dict)
    ]
    split_records = [
        row for row in split_manifest.get("split_records", []) if isinstance(row, dict)
    ]
    input_records = [
        row for row in input_manifest.get("row_records", []) if isinstance(row, dict)
    ]
    split_by_entry = {
        str(row.get("entry_id")): row for row in split_records if row.get("entry_id")
    }
    input_by_entry = {
        str(row.get("entry_id")): row for row in input_records if row.get("entry_id")
    }
    reaction_status_domain = set(
        str(value)
        for value in contract.get("categorical_domains", {}).get(
            "reaction_template_status", []
        )
    )
    organic_classes = set(
        str(value)
        for value in contract.get("categorical_domains", {}).get(
            "organic_cofactor_classes", []
        )
    )
    locus_domains = contract.get("categorical_domains", {}).get("inorganic_loci", {})
    if not isinstance(locus_domains, dict):
        locus_domains = {}
    row_audits = [
        _mechanism_feature_contract_row_audit(
            row=row,
            split_record=split_by_entry.get(str(row.get("entry_id") or "")),
            input_record=input_by_entry.get(str(row.get("entry_id") or "")),
            locus_domains=locus_domains,
            reaction_status_domain=reaction_status_domain,
            organic_classes=organic_classes,
        )
        for row in feature_rows
    ]
    critical_counts = Counter(
        violation
        for row in row_audits
        for violation in row.get("critical_violations", [])
    )
    top_level_violations: list[str] = []
    if contract.get("status") != "mechanism_feature_embedding_feature_contract_ready_no_model_fit":
        top_level_violations.append("feature_contract_status_not_ready_no_model_fit")
    if len(feature_rows) != len(split_records):
        top_level_violations.append("feature_row_count_mismatch_split_manifest")
    if set(row.get("entry_id") for row in feature_rows) != set(split_by_entry):
        top_level_violations.append("feature_row_entry_set_mismatch_split_manifest")
    counts = contract.get("counts", {})
    split_counts = Counter(row.get("assigned_embedding_split") for row in feature_rows)
    if counts.get("feature_rows") != len(feature_rows):
        top_level_violations.append("contract_feature_rows_count_mismatch")
    if counts.get("train_rows") != split_counts.get("train", 0):
        top_level_violations.append("contract_train_rows_count_mismatch")
    if counts.get("calibration_rows") != split_counts.get("calibration", 0):
        top_level_violations.append("contract_calibration_rows_count_mismatch")
    if counts.get("heldout_excluded_rows") != split_manifest.get("counts", {}).get(
        "heldout_excluded_rows"
    ):
        top_level_violations.append("heldout_excluded_count_mismatch_split_manifest")
    guardrails = contract.get("guardrails") or {}
    expected_false_guardrails = (
        "model_weights_fit_or_refit",
        "threshold_selected_or_tuned",
        "heldout_rows_used_for_training_or_threshold_tuning",
        "heldout_rows_present_in_feature_rows",
        "labels_registries_ontologies_changed",
        "imports_or_promotions_performed",
        "production_thresholds_changed",
    )
    for key in expected_false_guardrails:
        if guardrails.get(key) is not False:
            top_level_violations.append(f"contract_guardrail_{key}_not_false")
    if guardrails.get("label_fields_excluded_from_feature_rows") is not True:
        top_level_violations.append(
            "contract_guardrail_label_fields_excluded_from_feature_rows_not_true"
        )
    if guardrails.get("review_only") is not True:
        top_level_violations.append("contract_guardrail_review_only_not_true")
    for blocker in (
        "explicit_authorization_required_before_model_weights_are_fit",
        "heldout_final_evaluation_must_remain_once_only",
    ):
        if blocker not in set(contract.get("blockers_before_model_fit", [])):
            top_level_violations.append(f"required_blocker_missing:{blocker}")
    all_critical_counts = critical_counts.copy()
    all_critical_counts.update(top_level_violations)
    passed_rows = [row for row in row_audits if row.get("status") == "passed"]
    status = (
        "mechanism_feature_embedding_feature_contract_strict_audit_passed_no_model_fit"
        if not all_critical_counts and row_audits
        else "mechanism_feature_embedding_feature_contract_strict_audit_blocked"
    )
    return {
        "artifact_id": MECHANISM_FEATURE_EMBEDDING_FEATURE_CONTRACT_STRICT_AUDIT_ID,
        "schema_version": (
            f"{SCHEMA_VERSION}.mechanism_feature_embedding_feature_contract_strict_audit"
        ),
        "created_utc": _utc_now_iso(),
        "status": status,
        "scope": (
            "Strict no-fit audit for the mechanism-feature embedding feature "
            "contract. It validates row alignment, split discipline, forbidden "
            "label/outcome field exclusion, and no-model-fit guardrails."
        ),
        "guardrails": {
            "review_only": True,
            "model_weights_fit_or_refit": False,
            "threshold_selected_or_tuned": False,
            "heldout_rows_used_for_training_or_threshold_tuning": False,
            "heldout_rows_present_in_feature_rows": False,
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
        },
        "counts": {
            "feature_rows": len(feature_rows),
            "split_manifest_rows": len(split_records),
            "input_manifest_rows": len(input_records),
            "row_audits_passed": len(passed_rows),
            "row_audits_blocked": len(row_audits) - len(passed_rows),
            "train_rows": split_counts.get("train", 0),
            "calibration_rows": split_counts.get("calibration", 0),
            "heldout_excluded_rows": counts.get("heldout_excluded_rows"),
            "critical_violation_total": sum(all_critical_counts.values()),
            "critical_counts": dict(sorted(all_critical_counts.items())),
        },
        "row_audits": sorted(
            row_audits,
            key=lambda row: _entry_id_sort_key(str(row.get("entry_id") or "")),
        ),
        "source_artifacts": {
            "feature_contract": _source_path_record(feature_contract_path),
            "train_cal_input_manifest": _source_path_record(train_cal_input_manifest_path),
            "train_cal_split_manifest": _source_path_record(train_cal_split_manifest_path),
        },
        "commands": {
            "rebuild_feature_contract": (
                "PYTHONPATH=src python -m catalytic_earth.cli "
                "build-mechanism-feature-embedding-feature-contract"
            ),
            "rerun_strict_audit": (
                "PYTHONPATH=src python -m catalytic_earth.cli "
                "audit-mechanism-feature-embedding-feature-contract"
            ),
        },
        "interpretation": {
            "headline": (
                f"{len(passed_rows)}/{len(row_audits)} feature rows pass strict "
                "label-exclusion and train/cal alignment checks; no model was fit."
            ),
            "next_action": (
                "Keep model fitting blocked until explicitly authorized; a future "
                "materializer must consume only the audited feature groups, fit on "
                "train rows, select on calibration rows, and evaluate heldout once."
            ),
        },
    }


def _render_mechanism_feature_embedding_feature_contract_strict_audit_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    lines = [
        "# Mechanism-Feature Embedding Feature Contract Strict Audit - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Feature rows: {counts['feature_rows']}",
        f"- Split manifest rows: {counts['split_manifest_rows']}",
        f"- Row audits passed: {counts['row_audits_passed']}",
        f"- Row audits blocked: {counts['row_audits_blocked']}",
        f"- Train rows: {counts['train_rows']}",
        f"- Calibration rows: {counts['calibration_rows']}",
        f"- Heldout excluded rows: {counts['heldout_excluded_rows']}",
        f"- Critical violation total: {counts['critical_violation_total']}",
        f"- Critical counts: {counts['critical_counts']}",
        "",
        "## Commands",
        "",
        "```bash",
        audit["commands"]["rerun_strict_audit"],
        "```",
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_mechanism_feature_embedding_feature_contract_strict_audit(
    *,
    feature_contract_path: Path,
    train_cal_input_manifest_path: Path,
    train_cal_split_manifest_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_mechanism_feature_embedding_feature_contract_strict_audit(
        feature_contract_path=feature_contract_path,
        train_cal_input_manifest_path=train_cal_input_manifest_path,
        train_cal_split_manifest_path=train_cal_split_manifest_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_mechanism_feature_embedding_feature_contract_strict_audit_report(
                audit
            ),
            encoding="utf-8",
        )
    return audit


def _label_by_entry_from_manifest(label_manifest: dict[str, Any]) -> dict[str, str]:
    labels: dict[str, str] = {}
    for row in label_manifest.get("rows", []):
        if not isinstance(row, dict) or not row.get("entry_id"):
            continue
        fingerprint = row.get("fingerprint_id") or row.get("mechanism_fingerprint_id")
        if fingerprint and row.get("label_type") == "seed_fingerprint":
            labels[str(row["entry_id"])] = str(fingerprint)
        else:
            labels[str(row["entry_id"])] = "none_of_above"
    return labels


def _cofactor_scores_by_entry(
    cofactor_sidecar: dict[str, Any],
) -> dict[str, dict[str, float]]:
    scores: dict[str, dict[str, float]] = defaultdict(dict)
    for record in cofactor_sidecar.get("row_class_records", []):
        if not isinstance(record, dict):
            continue
        entry_id = record.get("entry_id")
        cofactor_class = record.get("cofactor_class") or record.get("class")
        if not entry_id or not cofactor_class:
            continue
        score = record.get("selected_score")
        if score is None:
            score = record.get("score")
        try:
            scores[str(entry_id)][str(cofactor_class)] = float(score)
        except (TypeError, ValueError):
            scores[str(entry_id)][str(cofactor_class)] = 0.0
    return scores


def _mechanism_feature_pilot_domains(
    feature_rows: list[dict[str, Any]],
    *,
    include_reaction_template: bool,
) -> dict[str, Any]:
    reaction_statuses = sorted(
        {
            str(row.get("reaction_center_template", {}).get("status") or "missing")
            for row in feature_rows
        }
    )
    reaction_operations = sorted(
        {
            str(
                row.get("reaction_center_template", {}).get(
                    "reaction_chemical_operation"
                )
                or "missing"
            )
            for row in feature_rows
        }
    )
    locus_domains: dict[str, list[str]] = {}
    for row in feature_rows:
        for locus, status in row.get("inorganic_cofactor_loci", {}).items():
            locus_domains.setdefault(str(locus), []).append(str(status))
    return {
        "include_reaction_template": include_reaction_template,
        "reaction_template_status": reaction_statuses
        if include_reaction_template
        else [],
        "reaction_chemical_operation": reaction_operations
        if include_reaction_template
        else [],
        "organic_cofactor_classes": ["flavin", "heme", "plp"],
        "inorganic_loci": {
            locus: sorted(set(statuses))
            for locus, statuses in sorted(locus_domains.items())
        },
    }


def _mechanism_feature_pilot_vector(
    row: dict[str, Any],
    *,
    domains: dict[str, Any],
    cofactor_scores: dict[str, dict[str, float]],
) -> list[float]:
    values: list[float] = []
    role_graph = row.get("active_site_role_graph") or {}
    residue_count = role_graph.get("active_site_residue_count")
    try:
        values.append(math.log1p(float(residue_count)))
    except (TypeError, ValueError):
        values.append(0.0)

    if domains["include_reaction_template"]:
        reaction = row.get("reaction_center_template") or {}
        status = str(reaction.get("status") or "missing")
        operation = str(reaction.get("reaction_chemical_operation") or "missing")
        values.extend(
            1.0 if status == allowed else 0.0
            for allowed in domains["reaction_template_status"]
        )
        values.extend(
            1.0 if operation == allowed else 0.0
            for allowed in domains["reaction_chemical_operation"]
        )

    entry_scores = cofactor_scores.get(str(row.get("entry_id")), {})
    values.extend(
        float(entry_scores.get(cofactor_class, 0.0))
        for cofactor_class in domains["organic_cofactor_classes"]
    )
    loci = row.get("inorganic_cofactor_loci") or {}
    for locus, allowed_statuses in domains["inorganic_loci"].items():
        status = str(loci.get(locus) or "missing")
        values.extend(1.0 if status == allowed else 0.0 for allowed in allowed_statuses)
    return values


def _standardize_train_cal_vectors(
    train_vectors: list[list[float]],
    other_vectors: list[list[float]],
) -> tuple[list[list[float]], list[list[float]], dict[str, list[float]]]:
    if not train_vectors:
        return [], other_vectors, {"mean": [], "scale": []}
    width = len(train_vectors[0])
    means: list[float] = []
    scales: list[float] = []
    for index in range(width):
        column = [vector[index] for vector in train_vectors]
        mean = sum(column) / len(column)
        variance = sum((value - mean) ** 2 for value in column) / len(column)
        scale = math.sqrt(variance) or 1.0
        means.append(mean)
        scales.append(scale)

    def transform(vectors: list[list[float]]) -> list[list[float]]:
        return [
            [
                round((value - means[index]) / scales[index], 8)
                for index, value in enumerate(vector)
            ]
            for vector in vectors
        ]

    return (
        transform(train_vectors),
        transform(other_vectors),
        {
            "mean": [round(value, 8) for value in means],
            "scale": [round(value, 8) for value in scales],
        },
    )


def _centroid(vector_rows: list[list[float]]) -> list[float]:
    if not vector_rows:
        return []
    width = len(vector_rows[0])
    return [
        round(sum(row[index] for row in vector_rows) / len(vector_rows), 8)
        for index in range(width)
    ]


def _euclidean_distance(a: list[float], b: list[float]) -> float:
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))


def _mechanism_feature_pilot_scores(
    vectors: list[list[float]],
    rows: list[dict[str, Any]],
    *,
    labels_by_entry: dict[str, str],
    primary_centroids: dict[str, list[float]],
) -> list[dict[str, Any]]:
    scored: list[dict[str, Any]] = []
    for vector, row in zip(vectors, rows):
        distances = {
            label: _euclidean_distance(vector, centroid)
            for label, centroid in primary_centroids.items()
        }
        if distances:
            nearest_label, nearest_distance = min(
                distances.items(), key=lambda item: (item[1], item[0])
            )
            nearest_score = 1.0 / (1.0 + nearest_distance)
        else:
            nearest_label = None
            nearest_distance = None
            nearest_score = 0.0
        true_label = labels_by_entry.get(str(row.get("entry_id")), "none_of_above")
        scored.append(
            {
                "entry_id": row.get("entry_id"),
                "assigned_embedding_split": row.get("assigned_embedding_split"),
                "true_label": true_label,
                "is_primary": true_label != "none_of_above",
                "nearest_primary_label": nearest_label,
                "nearest_primary_distance": (
                    round(nearest_distance, 8)
                    if nearest_distance is not None
                    else None
                ),
                "nearest_primary_similarity": round(nearest_score, 8),
                "primary_prediction_correct": (
                    bool(true_label != "none_of_above" and nearest_label == true_label)
                    if nearest_label is not None
                    else False
                ),
            }
        )
    return scored


def _select_similarity_threshold(
    scored_rows: list[dict[str, Any]],
    *,
    retention_target: float,
) -> dict[str, Any]:
    primary_rows = [row for row in scored_rows if row["is_primary"]]
    oos_rows = [row for row in scored_rows if not row["is_primary"]]
    if not primary_rows:
        return {
            "retention_target": retention_target,
            "threshold": None,
            "primary_retain_recall": None,
            "oos_abstain_recall": None,
            "primary_rows": 0,
            "oos_rows": len(oos_rows),
        }
    candidates = sorted(
        {float(row["nearest_primary_similarity"]) for row in scored_rows},
        reverse=True,
    )
    selected = candidates[-1]
    selected_primary_retain = 0.0
    selected_oos_abstain = 0.0
    for threshold in candidates:
        primary_retain = sum(
            1
            for row in primary_rows
            if float(row["nearest_primary_similarity"]) >= threshold
        ) / len(primary_rows)
        oos_abstain = (
            sum(
                1
                for row in oos_rows
                if float(row["nearest_primary_similarity"]) < threshold
            )
            / len(oos_rows)
            if oos_rows
            else None
        )
        if primary_retain >= retention_target:
            selected = threshold
            selected_primary_retain = primary_retain
            selected_oos_abstain = oos_abstain if oos_abstain is not None else 0.0
            break
    return {
        "retention_target": retention_target,
        "threshold": round(selected, 8),
        "primary_retain_recall": round(selected_primary_retain, 6),
        "oos_abstain_recall": round(selected_oos_abstain, 6),
        "primary_rows": len(primary_rows),
        "oos_rows": len(oos_rows),
    }


def _classification_summary(scored_rows: list[dict[str, Any]]) -> dict[str, Any]:
    primary_rows = [row for row in scored_rows if row["is_primary"]]
    oos_rows = [row for row in scored_rows if not row["is_primary"]]
    return {
        "rows": len(scored_rows),
        "primary_rows": len(primary_rows),
        "oos_rows": len(oos_rows),
        "primary_nearest_label_accuracy": (
            round(
                sum(1 for row in primary_rows if row["primary_prediction_correct"])
                / len(primary_rows),
                6,
            )
            if primary_rows
            else None
        ),
        "mean_primary_similarity": _mean(
            [float(row["nearest_primary_similarity"]) for row in primary_rows]
        ),
        "mean_oos_similarity": _mean(
            [float(row["nearest_primary_similarity"]) for row in oos_rows]
        ),
        "auc_primary_vs_oos": _auc_in_gt_oos(
            [float(row["nearest_primary_similarity"]) for row in primary_rows],
            [float(row["nearest_primary_similarity"]) for row in oos_rows],
        ),
    }


def _build_mechanism_feature_embedding_pilot_variant(
    *,
    variant_name: str,
    include_reaction_template: bool,
    feature_rows: list[dict[str, Any]],
    labels_by_entry: dict[str, str],
    cofactor_scores: dict[str, dict[str, float]],
) -> dict[str, Any]:
    domains = _mechanism_feature_pilot_domains(
        feature_rows, include_reaction_template=include_reaction_template
    )
    train_rows = [
        row for row in feature_rows if row.get("assigned_embedding_split") == "train"
    ]
    calibration_rows = [
        row
        for row in feature_rows
        if row.get("assigned_embedding_split") == "calibration"
    ]
    train_raw = [
        _mechanism_feature_pilot_vector(
            row, domains=domains, cofactor_scores=cofactor_scores
        )
        for row in train_rows
    ]
    calibration_raw = [
        _mechanism_feature_pilot_vector(
            row, domains=domains, cofactor_scores=cofactor_scores
        )
        for row in calibration_rows
    ]
    train_vectors, calibration_vectors, scaling = _standardize_train_cal_vectors(
        train_raw, calibration_raw
    )
    primary_labels = sorted(
        {
            labels_by_entry.get(str(row.get("entry_id")))
            for row in train_rows
            if labels_by_entry.get(str(row.get("entry_id"))) != "none_of_above"
        }
    )
    primary_centroids: dict[str, list[float]] = {}
    for label in primary_labels:
        label_vectors = [
            vector
            for vector, row in zip(train_vectors, train_rows)
            if labels_by_entry.get(str(row.get("entry_id"))) == label
        ]
        primary_centroids[str(label)] = _centroid(label_vectors)

    train_scored = _mechanism_feature_pilot_scores(
        train_vectors,
        train_rows,
        labels_by_entry=labels_by_entry,
        primary_centroids=primary_centroids,
    )
    calibration_scored = _mechanism_feature_pilot_scores(
        calibration_vectors,
        calibration_rows,
        labels_by_entry=labels_by_entry,
        primary_centroids=primary_centroids,
    )
    selected_threshold = _select_similarity_threshold(
        calibration_scored, retention_target=0.9
    )
    return {
        "variant_name": variant_name,
        "include_reaction_template": include_reaction_template,
        "model_type": "standardized_nearest_primary_centroid",
        "feature_dimension": len(train_vectors[0]) if train_vectors else 0,
        "feature_domains": domains,
        "train_summary": _classification_summary(train_scored),
        "calibration_summary": _classification_summary(calibration_scored),
        "calibration_selected_threshold": selected_threshold,
        "centroid_labels": sorted(primary_centroids),
        "model_parameters": {
            "scaling": scaling,
            "primary_centroids": primary_centroids,
        },
    }


def build_mechanism_feature_embedding_pilot(
    *,
    feature_contract_path: Path,
    feature_contract_strict_audit_path: Path,
    label_manifest_path: Path,
    selected_organic_cofactor_sidecar_path: Path,
) -> dict[str, Any]:
    contract = _read_json(feature_contract_path)
    strict_audit = _read_json(feature_contract_strict_audit_path)
    label_manifest = _read_json(label_manifest_path)
    cofactor_sidecar = _read_json(selected_organic_cofactor_sidecar_path)
    feature_rows = [
        row for row in contract.get("feature_rows", []) if isinstance(row, dict)
    ]
    labels_by_entry = _label_by_entry_from_manifest(label_manifest)
    cofactor_scores = _cofactor_scores_by_entry(cofactor_sidecar)
    train_rows = sum(
        1 for row in feature_rows if row.get("assigned_embedding_split") == "train"
    )
    calibration_rows = sum(
        1
        for row in feature_rows
        if row.get("assigned_embedding_split") == "calibration"
    )
    missing_labels = [
        str(row.get("entry_id"))
        for row in feature_rows
        if str(row.get("entry_id")) not in labels_by_entry
    ]
    missing_cofactor_score_rows = [
        str(row.get("entry_id"))
        for row in feature_rows
        if len(cofactor_scores.get(str(row.get("entry_id")), {})) < 3
    ]
    strict_passed = (
        strict_audit.get("status")
        == "mechanism_feature_embedding_feature_contract_strict_audit_passed_no_model_fit"
        and strict_audit.get("counts", {}).get("critical_violation_total") == 0
    )
    blockers = []
    if not strict_passed:
        blockers.append("feature_contract_strict_audit_not_passed")
    if missing_labels:
        blockers.append("feature_rows_missing_label_manifest_records")
    if missing_cofactor_score_rows:
        blockers.append("feature_rows_missing_three_organic_cofactor_scores")
    if not train_rows or not calibration_rows:
        blockers.append("train_or_calibration_rows_missing")
    variants = []
    if not blockers:
        variants = [
            _build_mechanism_feature_embedding_pilot_variant(
                variant_name="full_contract_with_reaction_template",
                include_reaction_template=True,
                feature_rows=feature_rows,
                labels_by_entry=labels_by_entry,
                cofactor_scores=cofactor_scores,
            ),
            _build_mechanism_feature_embedding_pilot_variant(
                variant_name="no_reaction_template_ablation",
                include_reaction_template=False,
                feature_rows=feature_rows,
                labels_by_entry=labels_by_entry,
                cofactor_scores=cofactor_scores,
            ),
        ]
    best_variant = None
    if variants:
        best_variant = max(
            variants,
            key=lambda variant: (
                variant["calibration_summary"]["auc_primary_vs_oos"] or -1,
                variant["calibration_summary"]["primary_nearest_label_accuracy"] or -1,
                variant["variant_name"],
            ),
        )["variant_name"]
    status = (
        "mechanism_feature_embedding_pilot_fit_train_cal_ready"
        if not blockers
        else "mechanism_feature_embedding_pilot_blocked"
    )
    return {
        "artifact_id": MECHANISM_FEATURE_EMBEDDING_PILOT_ID,
        "schema_version": f"{SCHEMA_VERSION}.mechanism_feature_embedding_pilot",
        "created_utc": _utc_now_iso(),
        "status": status,
        "scope": (
            "Train/cal-only mechanism-feature embedding pilot over the audited "
            "current702 feature contract. It fits standardized nearest-primary "
            "centroids on assigned train rows and selects a review threshold on "
            "assigned calibration rows only."
        ),
        "guardrails": {
            "model_weights_fit_or_refit": not blockers,
            "model_fit_rows": "train_only",
            "threshold_selected_or_tuned": not blockers,
            "threshold_selection_rows": "calibration_only",
            "heldout_rows_used_for_training_or_threshold_tuning": False,
            "heldout_rows_evaluated": False,
            "heldout_feature_surface_available": False,
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "review_only": True,
        },
        "counts": {
            "feature_rows": len(feature_rows),
            "train_rows": train_rows,
            "calibration_rows": calibration_rows,
            "heldout_excluded_rows": contract.get("counts", {}).get(
                "heldout_excluded_rows"
            ),
            "missing_label_rows": len(missing_labels),
            "missing_three_organic_cofactor_score_rows": len(
                missing_cofactor_score_rows
            ),
            "variants": len(variants),
            "primary_label_count": len(
                {
                    label
                    for row in feature_rows
                    for label in [labels_by_entry.get(str(row.get("entry_id")))]
                    if label and label != "none_of_above"
                }
            ),
        },
        "blockers": blockers,
        "best_calibration_variant": best_variant,
        "pilot_variants": variants,
        "heldout_followup": {
            "status": "heldout_not_evaluated_no_feature_surface",
            "required_next_step": (
                "materialize the same allowed feature fields for heldout rows, "
                "then apply the train-fit/cal-selected model exactly once"
            ),
        },
        "source_artifacts": {
            "feature_contract": _source_path_record(feature_contract_path),
            "feature_contract_strict_audit": _source_path_record(
                feature_contract_strict_audit_path
            ),
            "label_manifest": _source_path_record(label_manifest_path),
            "selected_organic_cofactor_sidecar": _source_path_record(
                selected_organic_cofactor_sidecar_path
            ),
        },
        "interpretation": {
            "headline": (
                "A real train/cal mechanism-feature centroid pilot is fit and "
                "calibrated without heldout use."
                if not blockers
                else "The mechanism-feature embedding pilot is blocked before fit."
            ),
            "next_action": (
                "Extend the audited feature materializer to heldout rows and run "
                "a once-only heldout readout; prioritize the no-template ablation "
                "if the full variant wins only by reaction-template leakage."
                if not blockers
                else "Clear the listed blockers, then rerun this pilot builder."
            ),
        },
    }


def _render_mechanism_feature_embedding_pilot_report(audit: dict[str, Any]) -> str:
    counts = audit["counts"]
    lines = [
        "# Mechanism-Feature Embedding Pilot - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Feature rows: {counts['feature_rows']}",
        f"- Train rows: {counts['train_rows']}",
        f"- Calibration rows: {counts['calibration_rows']}",
        f"- Heldout excluded rows: {counts['heldout_excluded_rows']}",
        f"- Variants: {counts['variants']}",
        f"- Best calibration variant: {audit['best_calibration_variant']}",
        "",
        "## Variant Results",
        "",
        "| variant | dim | cal primary acc | cal AUC primary>OOS | cal threshold | cal primary retain | cal OOS abstain |",
        "| --- | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for variant in audit["pilot_variants"]:
        summary = variant["calibration_summary"]
        threshold = variant["calibration_selected_threshold"]
        lines.append(
            f"| {variant['variant_name']} | {variant['feature_dimension']} | "
            f"{summary['primary_nearest_label_accuracy']} | "
            f"{summary['auc_primary_vs_oos']} | "
            f"{threshold['threshold']} | "
            f"{threshold['primary_retain_recall']} | "
            f"{threshold['oos_abstain_recall']} |"
        )
    lines += [
        "",
        "## Heldout Follow-Up",
        "",
        f"- {audit['heldout_followup']['status']}",
        f"- {audit['heldout_followup']['required_next_step']}",
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


def write_mechanism_feature_embedding_pilot(
    *,
    feature_contract_path: Path,
    feature_contract_strict_audit_path: Path,
    label_manifest_path: Path,
    selected_organic_cofactor_sidecar_path: Path,
    out_path: Path,
    report_path: Path | None = None,
) -> dict[str, Any]:
    audit = build_mechanism_feature_embedding_pilot(
        feature_contract_path=feature_contract_path,
        feature_contract_strict_audit_path=feature_contract_strict_audit_path,
        label_manifest_path=label_manifest_path,
        selected_organic_cofactor_sidecar_path=selected_organic_cofactor_sidecar_path,
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(audit, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if report_path is not None:
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(
            _render_mechanism_feature_embedding_pilot_report(audit),
            encoding="utf-8",
        )
    return audit


def _mechanism_feature_heldout_rows_from_sidecars(
    *,
    label_manifest: dict[str, Any],
    active_site_role_graph_sidecar: dict[str, Any],
    reaction_center_template_sidecar: dict[str, Any],
    metal_ion_locus_sidecar: dict[str, Any],
    cobalamin_locus_sidecar: dict[str, Any],
    radical_sam_locus_sidecar: dict[str, Any],
    iron_sulfur_locus_sidecar: dict[str, Any],
    cofactor_scores: dict[str, dict[str, float]],
) -> tuple[list[dict[str, Any]], Counter[str]]:
    role_by_entry = {
        str(row.get("entry_id")): row
        for row in active_site_role_graph_sidecar.get("rows", [])
        if isinstance(row, dict) and row.get("entry_id")
    }
    reaction_by_entry = {
        str(row.get("entry_id")): row
        for row in reaction_center_template_sidecar.get("rows", [])
        if isinstance(row, dict) and row.get("entry_id")
    }
    locus_sidecars = {
        "metal_ion_locus": metal_ion_locus_sidecar,
        "cobalamin_locus": cobalamin_locus_sidecar,
        "radical_sam_locus": radical_sam_locus_sidecar,
        "iron_sulfur_locus": iron_sulfur_locus_sidecar,
    }
    loci_by_entry: dict[str, dict[str, str]] = defaultdict(dict)
    for locus_name, sidecar in locus_sidecars.items():
        for row in sidecar.get("rows", []):
            if isinstance(row, dict) and row.get("entry_id"):
                loci_by_entry[str(row["entry_id"])][locus_name] = str(
                    row.get("sidecar_status") or "unsupported_or_missing_geometry"
                )

    heldout_rows = [
        row
        for row in label_manifest.get("rows", [])
        if isinstance(row, dict) and row.get("split_assignment") == "heldout"
    ]
    blocker_counts: Counter[str] = Counter()
    feature_rows: list[dict[str, Any]] = []
    for manifest_row in heldout_rows:
        entry_id = str(manifest_row.get("entry_id"))
        role_row = role_by_entry.get(entry_id)
        reaction_row = reaction_by_entry.get(entry_id)
        if role_row is None:
            blocker_counts["role_graph_row_missing"] += 1
            continue
        if role_row.get("status") != "ok":
            blocker_counts[f"role_graph:{role_row.get('status')}"] += 1
            continue
        if reaction_row is None:
            blocker_counts["reaction_template_row_missing"] += 1
            continue
        if len(cofactor_scores.get(entry_id, {})) < 3:
            blocker_counts["organic_cofactor_scores_missing"] += 1
            continue
        loci = loci_by_entry.get(entry_id, {})
        required_loci = {
            "metal_ion_locus",
            "cobalamin_locus",
            "radical_sam_locus",
            "iron_sulfur_locus",
        }
        if set(loci) != required_loci:
            blocker_counts["inorganic_locus_status_missing"] += 1
            continue
        reaction_template = reaction_row.get("reaction_center_template") or {}
        feature_rows.append(
            {
                "entry_id": entry_id,
                "assigned_embedding_split": "heldout_final",
                "active_site_role_graph": {
                    "status": role_row.get("status"),
                    "active_site_residue_count": role_row.get(
                        "active_site_residue_count"
                    ),
                },
                "reaction_center_template": {
                    "status": reaction_row.get("status"),
                    "reaction_chemical_operation": reaction_template.get(
                        "chemical_operation_normalized"
                    ),
                },
                "organic_cofactor_scores": {
                    "available_classes": ["flavin", "heme", "plp"],
                    "score_values_materialized_in_source_sidecar": True,
                },
                "inorganic_cofactor_loci": loci,
                "feature_guardrails": {
                    "fingerprint_id_excluded_from_features": True,
                    "label_type_excluded_from_features": True,
                    "stratum_excluded_from_features": True,
                    "heldout_row": True,
                },
            }
        )
    return (
        sorted(feature_rows, key=lambda row: _entry_id_sort_key(str(row["entry_id"]))),
        blocker_counts,
    )


def _apply_pilot_scaling(
    vector: list[float],
    *,
    scaling: dict[str, list[float]],
) -> list[float]:
    means = scaling.get("mean") or []
    scales = scaling.get("scale") or []
    return [
        round((value - means[index]) / (scales[index] or 1.0), 8)
        for index, value in enumerate(vector)
    ]


def _threshold_readout(
    scored_rows: list[dict[str, Any]],
    *,
    threshold: float | None,
) -> dict[str, Any]:
    primary_rows = [row for row in scored_rows if row["is_primary"]]
    oos_rows = [row for row in scored_rows if not row["is_primary"]]
    if threshold is None:
        return {
            "threshold": None,
            "primary_retain_recall": None,
            "oos_abstain_recall": None,
        }
    return {
        "threshold": threshold,
        "primary_retain_recall": (
            round(
                sum(
                    1
                    for row in primary_rows
                    if float(row["nearest_primary_similarity"]) >= threshold
                )
                / len(primary_rows),
                6,
            )
            if primary_rows
            else None
        ),
        "oos_abstain_recall": (
            round(
                sum(
                    1
                    for row in oos_rows
                    if float(row["nearest_primary_similarity"]) < threshold
                )
                / len(oos_rows),
                6,
            )
            if oos_rows
            else None
        ),
    }


def _score_heldout_with_pilot_variant(
    *,
    variant: dict[str, Any],
    heldout_feature_rows: list[dict[str, Any]],
    labels_by_entry: dict[str, str],
    cofactor_scores: dict[str, dict[str, float]],
) -> dict[str, Any]:
    domains = variant["feature_domains"]
    raw_vectors = [
        _mechanism_feature_pilot_vector(
            row, domains=domains, cofactor_scores=cofactor_scores
        )
        for row in heldout_feature_rows
    ]
    scaled_vectors = [
        _apply_pilot_scaling(vector, scaling=variant["model_parameters"]["scaling"])
        for vector in raw_vectors
    ]
    scored_rows = _mechanism_feature_pilot_scores(
        scaled_vectors,
        heldout_feature_rows,
        labels_by_entry=labels_by_entry,
        primary_centroids=variant["model_parameters"]["primary_centroids"],
    )
    threshold = variant.get("calibration_selected_threshold", {}).get("threshold")
    return {
        "variant_name": variant["variant_name"],
        "feature_dimension": variant["feature_dimension"],
        "heldout_summary": _classification_summary(scored_rows),
        "heldout_threshold_readout": _threshold_readout(
            scored_rows, threshold=threshold
        ),
        "calibration_selected_threshold": variant.get(
            "calibration_selected_threshold"
        ),
        "top_non_abstained_oos": [
            {
                "entry_id": row["entry_id"],
                "nearest_primary_label": row["nearest_primary_label"],
                "nearest_primary_similarity": row["nearest_primary_similarity"],
            }
            for row in sorted(
                [
                    row
                    for row in scored_rows
                    if not row["is_primary"]
                    and threshold is not None
                    and float(row["nearest_primary_similarity"]) >= threshold
                ],
                key=lambda item: (
                    -float(item["nearest_primary_similarity"]),
                    str(item["entry_id"]),
                ),
            )[:15]
        ],
    }


def build_mechanism_feature_embedding_heldout_readout(
    *,
    embedding_pilot_path: Path,
    label_manifest_path: Path,
    active_site_role_graph_sidecar_path: Path,
    reaction_center_template_sidecar_path: Path,
    selected_organic_cofactor_sidecar_path: Path,
    metal_ion_locus_sidecar_path: Path,
    cobalamin_locus_sidecar_path: Path,
    radical_sam_locus_sidecar_path: Path,
    iron_sulfur_locus_sidecar_path: Path,
) -> dict[str, Any]:
    pilot = _read_json(embedding_pilot_path)
    label_manifest = _read_json(label_manifest_path)
    cofactor_sidecar = _read_json(selected_organic_cofactor_sidecar_path)
    cofactor_scores = _cofactor_scores_by_entry(cofactor_sidecar)
    heldout_feature_rows, blocker_counts = _mechanism_feature_heldout_rows_from_sidecars(
        label_manifest=label_manifest,
        active_site_role_graph_sidecar=_read_json(active_site_role_graph_sidecar_path),
        reaction_center_template_sidecar=_read_json(reaction_center_template_sidecar_path),
        metal_ion_locus_sidecar=_read_json(metal_ion_locus_sidecar_path),
        cobalamin_locus_sidecar=_read_json(cobalamin_locus_sidecar_path),
        radical_sam_locus_sidecar=_read_json(radical_sam_locus_sidecar_path),
        iron_sulfur_locus_sidecar=_read_json(iron_sulfur_locus_sidecar_path),
        cofactor_scores=cofactor_scores,
    )
    labels_by_entry = _label_by_entry_from_manifest(label_manifest)
    heldout_rows_total = sum(
        1
        for row in label_manifest.get("rows", [])
        if isinstance(row, dict) and row.get("split_assignment") == "heldout"
    )
    variant_readouts = [
        _score_heldout_with_pilot_variant(
            variant=variant,
            heldout_feature_rows=heldout_feature_rows,
            labels_by_entry=labels_by_entry,
            cofactor_scores=cofactor_scores,
        )
        for variant in pilot.get("pilot_variants", [])
        if isinstance(variant, dict)
    ]
    best_variant = pilot.get("best_calibration_variant")
    return {
        "artifact_id": MECHANISM_FEATURE_EMBEDDING_HELDOUT_READOUT_ID,
        "schema_version": f"{SCHEMA_VERSION}.mechanism_feature_embedding_heldout_readout",
        "created_utc": _utc_now_iso(),
        "status": "mechanism_feature_embedding_heldout_readout_applied_once",
        "scope": (
            "Once-only heldout readout for the train/cal-fitted mechanism-feature "
            "embedding pilot. It materializes the same allowed feature fields for "
            "heldout rows from existing sidecars and applies train-fit, "
            "calibration-thresholded pilot variants without refit."
        ),
        "guardrails": {
            "model_weights_fit_or_refit": False,
            "threshold_selected_or_tuned": False,
            "threshold_source": "train_cal_embedding_pilot",
            "heldout_rows_used_for_training_or_threshold_tuning": False,
            "heldout_rows_evaluated_once": True,
            "labels_registries_ontologies_changed": False,
            "imports_or_promotions_performed": False,
            "production_thresholds_changed": False,
            "review_only": True,
        },
        "counts": {
            "heldout_rows_total": heldout_rows_total,
            "heldout_feature_rows": len(heldout_feature_rows),
            "heldout_feature_missing_rows": heldout_rows_total
            - len(heldout_feature_rows),
            "blocker_counts": dict(sorted(blocker_counts.items())),
            "variant_readouts": len(variant_readouts),
        },
        "best_calibration_variant": best_variant,
        "variant_readouts": variant_readouts,
        "heldout_feature_rows": heldout_feature_rows,
        "source_artifacts": {
            "embedding_pilot": _source_path_record(embedding_pilot_path),
            "label_manifest": _source_path_record(label_manifest_path),
            "active_site_role_graph_sidecar": _source_path_record(
                active_site_role_graph_sidecar_path
            ),
            "reaction_center_template_sidecar": _source_path_record(
                reaction_center_template_sidecar_path
            ),
            "selected_organic_cofactor_sidecar": _source_path_record(
                selected_organic_cofactor_sidecar_path
            ),
            "metal_ion_locus_sidecar": _source_path_record(metal_ion_locus_sidecar_path),
            "cobalamin_locus_sidecar": _source_path_record(cobalamin_locus_sidecar_path),
            "radical_sam_locus_sidecar": _source_path_record(
                radical_sam_locus_sidecar_path
            ),
            "iron_sulfur_locus_sidecar": _source_path_record(
                iron_sulfur_locus_sidecar_path
            ),
        },
        "interpretation": {
            "headline": (
                "The train/cal-fitted mechanism-feature pilot has now been "
                "applied to the heldout feature surface once."
            ),
            "next_action": (
                "Use the no-template heldout readout as the honest mechanism "
                "signal floor, and continue row-specific bond-change/proton/"
                "electron-flow materialization before any production claim."
            ),
        },
    }


def _render_mechanism_feature_embedding_heldout_readout_report(
    audit: dict[str, Any],
) -> str:
    counts = audit["counts"]
    lines = [
        "# Mechanism-Feature Embedding Heldout Readout - current702",
        "",
        f"Run: {audit['created_utc']}",
        "",
        audit["scope"],
        "",
        "## Status",
        "",
        f"- {audit['status']}",
        f"- Heldout rows total: {counts['heldout_rows_total']}",
        f"- Heldout feature rows: {counts['heldout_feature_rows']}",
        f"- Missing feature rows: {counts['heldout_feature_missing_rows']}",
        f"- Blocker counts: {counts['blocker_counts']}",
        "",
        "## Variant Readouts",
        "",
        "| variant | rows | primary rows | OOS rows | AUC | threshold | primary retain | OOS abstain |",
        "| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for readout in audit["variant_readouts"]:
        summary = readout["heldout_summary"]
        threshold = readout["heldout_threshold_readout"]
        lines.append(
            f"| {readout['variant_name']} | {summary['rows']} | "
            f"{summary['primary_rows']} | {summary['oos_rows']} | "
            f"{summary['auc_primary_vs_oos']} | {threshold['threshold']} | "
            f"{threshold['primary_retain_recall']} | "
            f"{threshold['oos_abstain_recall']} |"
        )
    lines += [
        "",
        "## Interpretation",
        "",
        f"- {audit['interpretation']['headline']}",
        f"- {audit['interpretation']['next_action']}",
    ]
    return "\n".join(lines) + "\n"


